// Generated by scripts/gen-l10n.mjs (gdetail n1, vi) — 不要手改;改翻譯請改 scripts/out/l10n/vi/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["vi"]=Object.assign(window.GRAMMAR_DETAIL_L10N["vi"]||{},{"n1-8":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ならでは」nghĩa là <b>「chỉ có ở ~ mới có」「đúng là ~ mới làm được」</b>. Ví dụ: 「phong cảnh chỉ có ở Kyoto」, 「hơi ấm chỉ đồ thủ công mới có」. Bạn dùng mẫu này khi muốn nhấn mạnh <b>thứ này nơi khác không có, chỉ ở đây mới có</b>, và thường là để khen.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước nối thẳng với <b>danh từ</b>, phía sau thường nối tiếp bằng「の＋danh từ」.<br><span class='gd-pair'><span class='gd-jp'>職人</span> → <span class='gd-jp'>職人ならではの技術</span></span> (kỹ thuật chỉ người thợ lành nghề mới có)<br><span class='gd-pair'><span class='gd-jp'>地元</span> → <span class='gd-jp'>地元ならではの料理</span></span> (món ăn chỉ ở địa phương đó mới được thưởng thức)<br>Phía trước thường là <b>người, địa điểm, cửa hàng, một cách làm nào đó</b>, tức là những thứ có nét đặc sắc riêng.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ならではの＋danh từ</span>Đây là dạng dùng nhiều nhất, khoảng chín phần mười là dạng này.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもならではの自由な発想に驚いた。</span>(Tôi ngạc nhiên trước ý tưởng tự do chỉ trẻ con mới có)</div><div class='gd-ex-line'>・<span class='gd-jp'>旅館ならではのおもてなしを楽しんだ。</span>(Tôi đã tận hưởng sự đón tiếp chỉ có ở ryokan kiểu Nhật)</div><div class='gd-sec'><span class='gd-tag'>ならではだ</span>Đặt ở cuối câu, nghĩa là 「đây chính là điều chỉ ~ mới làm được」.</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、老舗ならではだ。</span>(Hương vị này chỉ tiệm lâu đời mới làm ra được)</div><div class='gd-sec'><span class='gd-tag'>ならでは〜ない</span>Cách nói thiên về văn viết, hơi cổ, nghĩa là 「nếu không phải ~ thì không thể ~」. Chỉ cần nhìn là hiểu được thôi.</div><div class='gd-ex-line'>・<span class='gd-jp'>この味は、この店ならでは味わえない。</span>(Hương vị này, không phải quán này thì không thưởng thức được)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「なら」ở đây <b>không phải nghĩa 「nếu」</b>, đừng dịch thành 「nếu là ~ thì」.<br>・Chữ「は」trong「では」đọc là <b>わ</b>, cả cụm đọc là ならでわ.<br>・Phía trước nối thẳng với danh từ, <b>đừng thêm の</b>: đúng là <span class='gd-jp'>日本ならではの</span>, không phải 日本のならではの.<br>・Trọng tâm của mẫu này là 「<b>chỉ nó mới có</b>」. Những đặc điểm ai cũng có thì không dùng được, ví dụ nói 「cửa hàng tiện lợi chỉ có ở Tokyo」 nghe rất lạ, vì đâu đâu cũng có cửa hàng tiện lợi.<br>・Phần lớn dùng để khen. Thỉnh thoảng bạn sẽ gặp cách nói trung tính như 「<span class='gd-jp'>都会ならではの悩み</span>」 (nỗi phiền muộn chỉ đô thị mới có), nhưng dùng cho khuyết điểm hay thất bại đơn thuần thì nghe rất kỳ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>らしい</b>＝đúng chất ~, rất ra dáng ~ (nơi khác cũng có thể có thứ tương tự):<br><span class='gd-jp'>京都らしい景色だ。</span>(Phong cảnh đậm chất Kyoto)<br><b>ならでは</b>＝chỉ ở đó mới có, nơi khác tìm không ra:<br><span class='gd-jp'>京都ならではの景色だ。</span>(Phong cảnh chỉ có thể thấy ở Kyoto)</div><div class='gd-sec'><b>をおいて</b>＝nói về <b>người được chọn</b>, ngoài anh ấy ra không còn ai để chọn:<br><span class='gd-jp'>この役ができるのは、彼をおいてほかにいない。</span>(Người đóng được vai này, ngoài anh ấy ra không có ai khác)<br><b>ならでは</b>＝nói về <b>nét đặc sắc</b>, thứ này chỉ anh ấy mới làm được:<br><span class='gd-jp'>この演技は彼ならではだ。</span>(Lối diễn xuất này chỉ anh ấy mới diễn được)</div><div class='gd-warn'>Mẹo phân biệt: 「rất giống ~」dùng らしい; 「nét đặc sắc chỉ ~ mới có」dùng ならでは; 「nếu phải chọn thì chỉ có anh ấy」dùng をおいてほかにない.</div>","n1-33":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とはいうものの」nghĩa là <b>「Nói vậy thì đúng, nhưng…」</b>. Trước tiên bạn thừa nhận một điều là thật, rồi bổ sung ở sau: thực tế lại không diễn ra như thế. Ví dụ 「Tuy đã là mùa xuân rồi mà vẫn lạnh quá」 chính là cảm giác này.<br>Tách ra thì dễ nhớ hơn: <span class='gd-jp'>と</span> (như vậy) ＋ <span class='gd-jp'>いう</span> (nói) ＋ <span class='gd-jp'>ものの</span> (tuy), ghép lại thành 「tuy nói là ~」.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đặt giữa câu</span>A とはいうものの、B。A là sự thật hoặc điều ai cũng nói như vậy; B là 「lẽ ra phải như vậy, nhưng kết quả lại không phải」.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い日が続いている。</span>(Tuy nói là xuân rồi, nhưng những ngày lạnh vẫn kéo dài)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>(Tuy sống ở Nhật mười năm rồi, tôi vẫn kém kính ngữ)</div><div class='gd-ex-line'>・<span class='gd-jp'>便利になったとはいうものの、失われたものも少なくない。</span>(Tuy đã tiện lợi hơn, nhưng những thứ bị mất đi cũng không ít)</div><div class='gd-sec'><span class='gd-tag'>Đặt đầu câu</span>Câu trước đã nói xong, câu sau mở đầu bằng 「<span class='gd-jp'>とはいうものの</span>、」, nghĩa là 「tuy vậy thì…」.</div><div class='gd-ex-line'>・<span class='gd-jp'>今月から節約すると決めた。とはいうものの、コンビニに行くとつい買ってしまう。</span>(Tôi quyết định tiết kiệm từ tháng này. Tuy vậy, hễ vào cửa hàng tiện lợi là lại lỡ mua)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước dùng thể thường, tức là cách nói không có です・ます.<br>Động từ: <span class='gd-pair'><span class='gd-jp'>習った</span> → <span class='gd-jp'>習ったとはいうものの</span></span><br>Tính từ đuôi い: <span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいうものの</span></span><br>Tính từ đuôi な: <span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとはいうものの</span></span>, だ cũng có thể bỏ: <span class='gd-jp'>便利とはいうものの</span><br>Danh từ: <span class='gd-pair'><span class='gd-jp'>春だ</span> → <span class='gd-jp'>春とはいうものの</span></span>, giữ lại だ nói <span class='gd-jp'>春だとはいうものの</span> cũng được</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau nhất định phải là điều 「khác với dự đoán」. <span class='gd-jp'>春とはいうものの、暖かい。</span> nghe rất lạ, vì mùa xuân vốn đã ấm, chẳng có chút trái ngược nào cả.<br>・Giọng văn thiên về văn viết, trang trọng, thường gặp trong bài viết, tin tức, bài phát biểu. Khi nói chuyện với bạn bè thì dùng 「<span class='gd-jp'>けど</span>」 hoặc 「<span class='gd-jp'>とはいっても</span>」 sẽ tự nhiên hơn, còn nói 「とはいうものの」 nghe như đang đọc văn mẫu.<br>・Phía sau thường miêu tả tình hình thực tế hoặc cảm nhận của mình, rất ít khi nối với những câu nhờ vả, rủ rê kiểu 「hãy ~」「~ nhé」.<br>・<span class='gd-jp'>いう</span> khi đọc thực tế là 「ゆう」, nhưng khi viết vẫn viết いう, đừng viết thành ゆう.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một tình huống 「tuy là xuân nhưng vẫn lạnh」:<br><b>とはいえ</b> (N2): <span class='gd-jp'>春とはいえ、まだ寒い。</span> Nghĩa gần như giống hệt, ngắn hơn, cũng thiên về văn viết và cũng đặt được ở đầu câu.<br><b>とはいうものの</b>: <span class='gd-jp'>春とはいうものの、まだ寒い。</span> Nghĩa giống とはいえ, chỉ là dài hơn.<br><b>とはいっても</b>: <span class='gd-jp'>春とはいっても、まだ寒いね。</span> Dạng dùng nhiều nhất khi nói.<br><b>ものの</b> (N2): <span class='gd-jp'>春になったものの、まだ寒い。</span> Nối thẳng với một sự thật, không có lớp nghĩa 「tuy nói là ~」.<br><b>とは言い条</b> (N1): <span class='gd-jp'>春とは言い条、まだ寒い。</span> Nghĩa giống nhưng rất cổ, bây giờ gần như chỉ thấy trong văn viết.</div><div class='gd-warn'>Mẹo phân biệt: khi nói dùng 「とはいっても」, khi viết bài dùng 「とはいえ」「とはいうものの」, còn 「とは言い条」 chỉ cần đọc hiểu là đủ, bạn không cần dùng nó.</div>","n1-14":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なり」nghĩa là <b>“vừa ～ là liền…”</b>, lại kèm chút ngạc nhiên kiểu “ơ, nhanh thế?”. Giống như bạn kể với bạn bè: “Anh ấy vừa bước vào cửa, chưa kịp cởi giày đã lao thẳng vào phòng.” Thường dùng để miêu tả <b>người khác</b> vừa làm xong một hành động thì ngay lập tức làm tiếp một hành động khiến người ta hơi bất ngờ.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thể từ điển của động từ (dạng nguyên mẫu tra được trong từ điển) thêm thẳng「なり」, không cần biến đổi.<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るなり</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くなり</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るなり</span></span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Miêu tả phản ứng của người khác</span>Hành động trước vừa xong, cùng một người đó lập tức có hành động tiếp theo, và hành động này khá đột ngột.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るなり、部屋にこもってしまった。</span>（Anh ấy vừa về đến nhà là nhốt mình trong phòng）</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞くなり、彼女は泣き出した。</span>（Vừa nghe tin đó, cô ấy liền bật khóc）</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は私の顔を見るなり、走って逃げた。</span>（Con trai vừa nhìn thấy mặt tôi là chạy trốn ngay）</div><div class='gd-sec'><span class='gd-tag'>Giọng kể chuyện</span>Phần lớn xuất hiện trong tiểu thuyết, bài viết, hoặc khi bạn “kể lại” một việc cho người khác nghe. Khi nói chuyện thường ngày với nghĩa “vừa ～ là…”, người ta hay dùng「〜たとたん」đã học ở N3 hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Trước và sau phải cùng một người</b>. “Anh ấy vừa về nhà, <b>anh ấy</b> liền nhốt mình trong phòng” thì được; “Chuông vừa reo, học sinh liền lao ra” thì chủ ngữ đã đổi, dùng なり sẽ thấy lạ.<br>・<b>Thường không dùng để nói về bản thân</b>. なり mang cảm giác người ngoài cuộc đang miêu tả, nên nếu muốn nói “tôi vừa về nhà là ngủ luôn” thì nói <span class='gd-jp'>家に帰ってすぐ寝た。</span> sẽ tự nhiên hơn.<br>・Phía sau là <b>việc đã xảy ra</b>, không được nối với mệnh lệnh, lời rủ rê hay dự định:<br>×<span class='gd-jp'>家に帰るなり、宿題をしなさい。</span>（không dùng để bảo người khác làm việc gì）<br>・Phía trước nhất định là thể từ điển. Đổi sang thể た thành「<span class='gd-jp'>〜たなり</span>」thì nghĩa khác hẳn: “sau khi ～ thì cứ thế mãi”, ví dụ <span class='gd-jp'>出かけたなり、帰ってこない。</span>（Ra khỏi nhà rồi là biệt tăm không về）<br>・「<span class='gd-jp'>〜なり〜なり</span>」（～ hay ～ đều được）và「<span class='gd-jp'>私なりに</span>」（theo cách của riêng tôi）trông giống nhau nhưng là ngữ pháp hoàn toàn khác, đừng nhầm lẫn.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>N1 có khá nhiều mẫu “vừa ～ là…”, đều nối với thể từ điển và phía sau đều là việc đã xảy ra, khác nhau ở <b>ai làm, nhấn mạnh gì, dùng ở đâu</b>.<br><br><b>なり</b>：cùng một người, làm một hành động hơi bất ngờ.<br><span class='gd-jp'>部長は会議室に入るなり、大声で怒鳴り始めた。</span>（Trưởng phòng vừa bước vào phòng họp là bắt đầu quát lớn）<br><br><b>や否や</b>：rất văn viết, <b>trước và sau có thể là người hoặc sự việc khác nhau</b>.<br><span class='gd-jp'>ベルが鳴るや否や、学生たちは教室を飛び出した。</span>（Chuông vừa reo, các học sinh liền lao ra khỏi lớp）<br><br><b>が早いか</b>：trọng tâm là <b>nhanh</b>, vừa làm xong việc trước thì gần như cùng lúc đã làm việc sau.<br><span class='gd-jp'>子どもたちは「いただきます」と言うが早いか、料理に手を伸ばした。</span>（Bọn trẻ vừa nói xong “Con xin mời”, tay đã với ngay tới món ăn）<br><br><b>たとたん</b>（N3）：khẩu ngữ hằng ngày, <b>nói về bản thân cũng được</b>, phía sau thường là việc mình không kiểm soát được.<br><span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（Vừa đứng dậy là thấy chóng mặt）</div><div class='gd-warn'>Mẹo phán đoán: cùng một người bất ngờ làm gì đó → なり; hai việc khác nhau nối tiếp nhau, lại là văn viết → や否や; muốn nhấn mạnh tay chân cực nhanh → が早いか; nói về bản thân, trò chuyện thường ngày → たとたん.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo hãy xem「<span class='gd-jp'>〜が早いか</span>」「<span class='gd-jp'>〜や否や</span>」cùng nhóm, rồi đối chiếu với「<span class='gd-jp'>〜そばから</span>」（vừa ～ xong là lại ～ ngay, nói về việc lặp đi lặp lại）. Học các mẫu này cùng nhau thì ít bị nhầm nhất.</div>","n1-15":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜が早いか」 tương đương với <b>「vừa ~ là lập tức …」</b> trong tiếng Việt, và nhanh đến mức <b>khó phân biệt việc nào xảy ra trước</b>. Nghĩa đen là “(việc trước) có nhanh hơn không?”: hành động đầu vừa mới bắt đầu thì hành động sau đã xảy ra rồi. Giống như chuông tan học vừa reo, học sinh đã lao ra hành lang.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Miêu tả cảnh tượng nhìn thấy</span>Dùng để kể việc <b>đã xảy ra</b>, nên cuối câu thường ở thì quá khứ. Mẫu này rất hay gặp trong tiểu thuyết, bài viết, tin tức, còn trong hội thoại hằng ngày hầu như không ai nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>チャイムが鳴るが早いか、子供たちは教室を飛び出した。</span>(Chuông vừa reo, lũ trẻ đã lao ra khỏi lớp)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は家に帰るが早いか、ベッドに倒れ込んだ。</span>(Anh ấy vừa về đến nhà là ngã vật ra giường)</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるが早いか、売り切れてしまった。</span>(Sản phẩm mới vừa mở bán đã hết sạch)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ ở thể từ điển (dạng gốc tra trong từ điển) + 「が早いか」, không cần biến đổi.<br><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るが早いか</span></span><span class='gd-pair'><span class='gd-jp'>発売される</span> → <span class='gd-jp'>発売されるが早いか</span></span><br>Dù cả câu nói về chuyện quá khứ, phần phía trước vẫn dùng thể từ điển, còn thì (tense) để cuối câu lo. Thỉnh thoảng bạn cũng sẽ gặp thể た, ví dụ <span class='gd-jp'>言ったが早いか</span>, nhưng cứ nhớ thể từ điển là đủ dùng rồi.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau <b>không được dùng mệnh lệnh, nhờ vả hay ý định của chính mình</b>: ×<span class='gd-jp'>家に着くが早いか、電話してください。</span> Muốn nói “về đến nhà thì gọi cho mình ngay”, hãy nói <span class='gd-jp'>家に着いたら、すぐ電話してください。</span><br>・Cấu trúc “vừa ~ là ~” trong tiếng Việt dùng rất rộng, ví dụ “cứ xuân đến là hoa nở” là <b>quy luật, điều kiện</b>, không dùng が早いか được, mà phải nói <span class='gd-jp'>春になると、花が咲く。</span><br>・Giọng văn khá cứng. Với bạn bè, nếu muốn nói “mình về đến nhà là ngủ luôn”, chỉ cần nói <span class='gd-jp'>家に帰って、すぐ寝ちゃった。</span> là được, dùng が早いか nghe sẽ như đang đọc tiểu thuyết.<br>・Phía trước đừng thêm ます: ×<span class='gd-jp'>鳴りますが早いか</span>。<br>・「早い」đọc là <b>はやい</b>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một cảnh, cả ba cách nói đều đúng:<br><span class='gd-jp'>息子は帰ってくるが早いか、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるなり、かばんを置いて遊びに行った。</span><br><span class='gd-jp'>息子は帰ってくるや否や、かばんを置いて遊びに行った。</span><br>(Con trai vừa về đến nơi đã quẳng cặp xuống rồi chạy đi chơi)</div><div class='gd-sec'><b>なり</b>: Hai hành động trước sau nhất định do <b>cùng một người</b> làm, và vế sau thường là hành động hơi bất ngờ. Vì vậy câu “chuông vừa reo, học sinh đã lao ra” không dùng なり được: ×<span class='gd-jp'>チャイムが鳴るなり、生徒が飛び出した。</span><br><b>や否や</b>: Hai vế có thể là người hay vật khác nhau, giọng văn <b>mang tính văn viết và trang trọng nhất</b>, báo chí rất hay dùng: <span class='gd-jp'>ドアが開くや否や、客が店内になだれ込んだ。</span> (Cửa vừa mở, khách đã ùa vào trong cửa hàng)<br><b>が早いか</b>: Hai vế cũng có thể khác chủ ngữ, trọng tâm là <b>nhanh đến mức không phân biệt được trước sau</b>, thường gợi cảnh nôn nóng, tranh nhau làm.</div><div class='gd-warn'>Mẹo phân biệt: cùng một người và hành động sau hơi bất ngờ thì dùng なり; muốn nhấn mạnh “nhanh gần như đồng thời” thì dùng が早いか; tin tức, văn viết trang trọng thì dùng や否や. Cả ba mẫu đều không được theo sau bởi mệnh lệnh, nhờ vả hay ý định của bản thân.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜そばから」trông cũng giống “vừa ~ là ~”, nhưng nó diễn tả việc <b>lặp đi lặp lại</b>: “vừa mới ~ thì lại …”: <span class='gd-jp'>覚えるそばから忘れてしまう。</span> (Vừa học thuộc xong là lại quên). Ý của nó là “lần nào cũng thế”, không phải sự “nhanh” của một lần duy nhất.</div>","n1-16":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜や否や」 tương đương với <b>「vừa ~ là ~」</b> trong tiếng Việt, kiểu nhanh <b>vừa làm xong, việc tiếp theo xảy ra ngay</b>. Đây là cách nói <b>văn viết</b> rất trang trọng, hay xuất hiện trong tiểu thuyết, tin tức, bài viết. Bạn có thể xem nó là phiên bản văn viết của <span class='gd-jp'>〜たとたん</span>.</div><div class='gd-h'>Hiểu chữ này trước đã</div><div class='gd-sec'>Đọc là <b>やいなや</b>. 「否」nghĩa là “không” (Hán Việt: phủ). Nghĩa gốc của cả cụm là “rốt cuộc đã làm hay chưa còn chưa rõ”, tức là <b>hành động trước vừa mới xảy ra thì việc sau đã nối tiếp ngay</b>. Nhớ hình ảnh này là bạn sẽ hiểu nó nhấn mạnh sự “nhanh”.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ thể từ điển + や否や<br><span class='gd-pair'><span class='gd-jp'>目を覚ます</span> → <span class='gd-jp'>目を覚ますや否や</span></span>(vừa mở mắt ra là ~)<br><span class='gd-pair'><span class='gd-jp'>ドアが開く</span> → <span class='gd-jp'>ドアが開くや否や</span></span>(cửa vừa mở là ~)<br>Trong văn viết, đôi khi chỉ viết một chữ「や」, nghĩa vẫn vậy: <span class='gd-jp'>家に着くや</span>(vừa đến nhà là ~).</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Miêu tả việc đã xảy ra</span>Dùng khi kể chuyện, đưa tin một sự việc kiểu “A vừa xảy ra thì B xảy ra ngay”. Vế sau thường ở thì quá khứ.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開くや否や、子どもたちが飛び出してきた。</span>(Cửa vừa mở, lũ trẻ đã lao ra)</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品は発売されるや否や、売り切れた。</span>(Sản phẩm mới vừa mở bán đã hết sạch)</div><div class='gd-ex-line'>・<span class='gd-jp'>社長が現れるや否や、会場は静まり返った。</span>(Giám đốc vừa xuất hiện, hội trường lập tức im phăng phắc)</div><div class='gd-sec'>Hai vế có thể là <b>người hay vật khác nhau</b>: ở ví dụ trên, “cửa mở” và “bọn trẻ lao ra” là hai chủ thể khác nhau, dùng như vậy hoàn toàn được.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải dùng <b>thể từ điển</b>, không phải thể た: đúng là <span class='gd-jp'>帰るや否や</span>, không phải 「帰ったや否や」. Tiếng Việt không chia thì, nên nhiều bạn dễ tiện tay viết thành quá khứ.<br>・「否」đọc là <b>いな</b>, không phải ひ.<br>・Vế sau không được đặt những câu như “tôi sẽ ~”, “hãy ~”, “~ nhé” (nhờ vả hoặc ý định).<br>　× 駅に着くや否や、電話してください。<br>　○ <span class='gd-jp'>駅に着いたら、すぐ電話してください。</span>(Đến ga thì hãy gọi cho tôi ngay nhé)<br>・Mẫu này rất cứng và mang tính văn viết. Khi trò chuyện với bạn bè, nếu muốn nói “mình vừa về đến nhà là ngủ luôn”, chỉ cần nói <span class='gd-jp'>家に着いたとたん、寝ちゃった</span> hoặc <span class='gd-jp'>帰ってすぐ寝た</span> là được.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống “anh ấy vừa bước vào phòng là bật khóc”:<br><span class='gd-tag'>や否や</span><span class='gd-jp'>彼は部屋に入るや否や、泣き出した。</span><br>Trang trọng và mang tính văn viết nhất, hai vế có thể khác chủ thể.<br><span class='gd-tag'>なり</span><span class='gd-jp'>彼は部屋に入るなり、泣き出した。</span><br>Hai vế nhất định là <b>cùng một người</b>, thường mang cảm giác bất ngờ kiểu “sao tự nhiên lại thế”.<br><span class='gd-tag'>が早いか</span><span class='gd-jp'>彼は部屋に入るが早いか、泣き出した。</span><br>Nhấn mạnh hơn vào “nhanh gần như đồng thời”, đậm chất tiểu thuyết; phía trước cũng có thể dùng thể た.<br><span class='gd-tag'>たとたん</span><span class='gd-jp'>彼は部屋に入ったとたん、泣き出した。</span><br>Bản dùng hằng ngày, cả nói lẫn viết đều dùng được, phía trước là thể た.</div><div class='gd-sec'>Hai mẫu nữa cũng hay bị nhầm lẫn:<br><b>次第</b> có thể đi với nhờ vả, ý định: <span class='gd-jp'>着き次第、連絡します。</span>(Đến nơi là tôi liên lạc ngay) Câu này đổi sang や否や thì không được.<br><b>そばから</b> nghĩa là “vừa làm xong lại bị xóa sạch ngay, và cứ lặp đi lặp lại”: <span class='gd-jp'>覚えるそばから忘れてしまう。</span>(Vừa nhớ xong lại quên, cứ thế mãi). Đây không phải kiểu “vừa ~ là ~” của một lần duy nhất.</div><div class='gd-warn'>Mẹo phân biệt: muốn nhờ người khác làm gì thì dùng「次第」; công cốc lặp đi lặp lại thì dùng「そばから」; miêu tả một việc đã xảy ra một lần, nói chuyện thì dùng「たとたん」, viết văn thì dùng「や否や」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy xem <span class='gd-jp'>〜なり</span>、<span class='gd-jp'>〜が早いか</span>、<span class='gd-jp'>〜そばから</span> cùng lúc. Nhóm “vừa ~ là ~” này rất hay được đưa ra so sánh với nhau trong đề thi N1.</div>","n1-3":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をものともせず」nghĩa là <b>「bất chấp ~」「không coi ~ ra gì」</b>. Phía trước là khó khăn, nguy hiểm hay trở ngại, phía sau là kết quả \"vậy mà vẫn làm được\". Mẫu câu này dùng để khen ai đó dũng cảm, quyết tâm. Cứ nghĩ đến giọng báo chí kiểu \"bất chấp mưa gió, kiên trì giữ vững vị trí\" là đúng chất của nó.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋<span class='gd-jp'>をものともせず</span> (phía sau có thể thêm に: <span class='gd-jp'>をものともせずに</span>, nghĩa không đổi)<br><span class='gd-pair'><span class='gd-jp'>病気</span> → <span class='gd-jp'>病気をものともせず</span></span>(bất chấp bệnh tật)<br><span class='gd-pair'><span class='gd-jp'>周囲の反対</span> → <span class='gd-jp'>周囲の反対をものともせず</span></span>(bất chấp sự phản đối của xung quanh)<br>Tách ra thì <span class='gd-jp'>もの</span> là \"thứ, vật\", <span class='gd-jp'>せず</span> là \"không làm\". Nghĩa đen là \"không thèm coi nó là một chuyện gì cả\".</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Phía trước đặt khó khăn</span>Những thứ \"chắn đường\" như bệnh đau, chấn thương, thời tiết xấu, nguy hiểm, thất bại, phản đối, áp lực.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は度重なる失敗をものともせず、挑戦し続けた。</span>(Anh ấy bất chấp thất bại liên tiếp, vẫn tiếp tục thử thách)</div><div class='gd-ex-line'>・<span class='gd-jp'>救助隊は激しい雨をものともせず、山へ向かった。</span>(Đội cứu hộ bất chấp mưa lớn, lên đường vào núi)</div><div class='gd-sec'><span class='gd-tag'>Phía sau đặt việc đã làm được</span>Thường là sự thật đã xảy ra, mang giọng khâm phục, khen ngợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は周囲の反対をものともせず、自分の店を開いた。</span>(Cô ấy bất chấp sự phản đối của mọi người xung quanh, mở cửa hàng của riêng mình)</div><div class='gd-ex-line'>・<span class='gd-jp'>その選手は怪我をものともせず、最後まで走り抜いた。</span>(Vận động viên ấy bất chấp chấn thương, chạy hết quãng đường)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này dùng để <b>khen người khác</b>, thường không dùng để nói về mình. <span class='gd-jp'>私は寒さをものともせず</span> nghe như đang tự khen, rất kỳ.<br>・Phía sau không đi với kiểu \"hãy ~\" hay \"cùng ~ nhé\". Những câu như \"bất chấp khó khăn, cố lên nào\" thì đừng dùng mẫu này, nó dùng để <b>miêu tả việc đã làm được</b>.<br>・Phía trước nhất định phải là <b>trở ngại</b>. Những thứ tốt như \"sự cổ vũ\", \"cơ hội\" thì không đặt vào được, vì chẳng có gì để mà \"bất chấp\".<br>・Trợ từ là <b>を</b>, không phải が.<br>・Đây là cách nói cứng, dùng trong văn viết, báo chí, diễn thuyết, nói chuyện với bạn bè gần như không dùng.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>をよそに</b>＝<b>mặc kệ nỗi lo hay kỳ vọng của người khác</b>, cứ tự làm theo ý mình. Phía trước hay là <span class='gd-jp'>心配</span>, <span class='gd-jp'>期待</span>, mang chút sắc thái \"không chịu nghe khuyên\".<br>・<span class='gd-jp'>親の心配をよそに、彼は一人で海外へ行った。</span>(Mặc kệ bố mẹ lo lắng, anh ấy một mình ra nước ngoài)<br><b>をものともせず</b>＝<b>không sợ khó khăn</b>, dũng cảm vượt qua, là lời khen.<br>・<span class='gd-jp'>言葉の壁をものともせず、彼は海外で成功した。</span>(Bất chấp rào cản ngôn ngữ, anh ấy đã thành công ở nước ngoài)<br>\"Nỗi lo của bố mẹ\" không phải cửa ải cần vượt qua, nên nói <span class='gd-jp'>親の心配をものともせず</span> sẽ không tự nhiên.</div><div class='gd-sec'><b>にもかかわらず</b>＝\"dù ~ vẫn ~\" đơn thuần, không khen chê, việc tốt hay xấu đều dùng được.<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>(Dù trời mưa, vẫn có rất nhiều người đến)<br>Chỉ khi muốn nhấn mạnh \"những người này thật đáng nể\" thì mới đổi thành <span class='gd-jp'>雨をものともせず</span>.</div><div class='gd-warn'>Mẹo nhỏ để chọn: phía trước là \"cửa ải khó\" và bạn muốn khen đối phương dũng cảm thì dùng をものともせず; phía trước là \"tâm tình của người khác\" mà đối phương mặc kệ thì dùng をよそに; chỉ đơn giản nói \"dù ~\" thì dùng にもかかわらず.</div>","n1-9":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AはおろかB」nghĩa là <b>「đừng nói A, ngay cả B cũng ~」</b>. A là chuyện \"vốn dĩ đương nhiên\", chẳng buồn nhắc tới; B là chuyện bất ngờ hơn, dùng để nhấn mạnh \"tình trạng đã đến mức quá đáng như vậy\". Thứ tự cũng giống tiếng Việt, cứ theo trật tự của câu \"đừng nói A, đến B cũng ~\" mà áp vào là được.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Cơ bản là <b>danh từ＋はおろか</b>: <span class='gd-pair'><span class='gd-jp'>漢字</span> → <span class='gd-jp'>漢字はおろか</span></span><br>Nếu A là hành động, hãy thêm 「こと」 sau động từ để biến nó thành danh từ: <span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることはおろか</span></span><br>Vế sau thường đi với <b>も、さえ、すら、まで</b>, những từ này mang nghĩa \"ngay cả ~ cũng\".</div><div class='gd-h'>Sắp xếp A và B thế nào</div><div class='gd-sec'>Cách xác định: A đặt chuyện \"vốn dĩ đương nhiên\", B đặt chuyện cực đoan hơn, bất ngờ hơn.</div><div class='gd-sec'><span class='gd-tag'>Câu phủ định (phổ biến nhất)</span>A là việc khó hơn, B là việc cơ bản hơn. \"Việc khó không làm được thì bình thường, nhưng đến việc dễ cũng không làm được\" mới tạo được hiệu quả nhấn mạnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はおろか、ひらがなさえまだ読めない。</span>(Đừng nói Hán tự, đến hiragana mình cũng chưa đọc được)</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、休みはおろか、昼ご飯を食べる時間もない。</span>(Bận đến mức đừng nói nghỉ ngơi, đến thời gian ăn trưa cũng không có)</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがして、走ることはおろか、歩くこともできない。</span>(Bị thương ở chân, đừng nói chạy, đến đi bộ cũng không được)</div><div class='gd-sec'><span class='gd-tag'>Câu khẳng định</span>Ngược lại, A là việc bình thường hơn, B là việc có phạm vi rộng hơn, ấn tượng hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は国内はおろか、海外でも人気がある。</span>(Bài hát này đừng nói trong nước, ngay cả nước ngoài cũng nổi tiếng)</div><div class='gd-warn'>Đừng đảo ngược thứ tự: <span class='gd-jp'>ひらがなはおろか、漢字も読めない。</span> là vô lý. Người đến hiragana còn không đọc được thì không đọc được Hán tự là chuyện đương nhiên, chẳng cần nhấn mạnh.<br>Câu phủ định hay khẳng định đều giống nhau: A là \"vốn dĩ như vậy\", B là \"đến cả cái này cũng như vậy\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau <b>không được đặt mệnh lệnh, yêu cầu hay dự định của bản thân</b>. <span class='gd-jp'>漢字はおろか、ひらがなも覚えなさい。</span> là sai, lúc này phải đổi sang <span class='gd-jp'>はもちろん</span>.<br>・は đã nằm sẵn trong mẫu rồi, phía trước đừng thêm を hay が. Cũng không nối thẳng với động từ được, nhớ thêm 「こと」 trước.<br>・おろか ở đây không liên quan đến 「愚か」 (ngu ngốc), đừng hiểu thành \"ngốc\".<br>・Giọng khá cứng, thường mang sắc thái bất mãn hoặc ngạc nhiên kiểu \"quá đáng thật\", \"thảm quá\", hay dùng trong văn viết hoặc hoàn cảnh trang trọng. Khi nói chuyện với bạn bè, người Nhật hay dùng <span class='gd-jp'>どころか</span> hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một tình huống, so sánh thử nhé:<br><b>はおろか</b>＝nhấn mạnh \"đến cả B cũng\" kèm cảm thán hoặc bất mãn, vế sau chỉ có thể là câu trần thuật: <span class='gd-jp'>漢字はおろか、ひらがなも書けない。</span>(Đừng nói Hán tự, đến hiragana cũng không viết được)<br><b>はもちろん</b>＝\"A thì đương nhiên rồi, B cũng\" đơn thuần, giọng trung tính, phía sau có thể đi với yêu cầu: <span class='gd-jp'>漢字はもちろん、ひらがなもちゃんと書いてください。</span>(Hán tự thì đương nhiên phải viết cho chuẩn, hiragana cũng hãy viết cho đàng hoàng)<br><b>どころか</b>＝nghĩa gần với はおろか, mang tính khẩu ngữ hơn. Ngoài ra nó còn có thể diễn tả \"không những không A, mà ngược lại còn B\": <span class='gd-jp'>安いどころか、すごく高かった。</span>(Đã không rẻ thì chớ, còn đắt kinh khủng). はおろか không có cách dùng \"ngược lại\" này.</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn nhờ người khác làm gì thì dùng はもちろん; nói chuyện với bạn bè thì dùng どころか; viết văn, muốn nhấn mạnh sự cảm thán kiểu \"quá đáng đến mức ngay cả cái này cũng\" thì dùng はおろか.</div><div class='gd-h'>Học tiếp sau khi nắm xong</div><div class='gd-sec'>Bạn có thể học tiếp <span class='gd-jp'>すら</span> (ngay cả ~ cũng), từ thường đi cùng ở vế sau.</div>","n1-40":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にひきかえ」gần giống với <b>\"ngược lại với…\", \"trái ngược hẳn với…\"</b> trong tiếng Việt. Bạn nói về một bên trước, rồi nói về bên hoàn toàn đối lập. Thường thì một bên tốt, một bên không tốt, và người nói có cảm xúc riêng trong đó. Ví dụ: \"Anh trai người ta chăm chỉ thế, <b>ngược lại</b> em trai thì……\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b> nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>去年</span> → <span class='gd-jp'>去年にひきかえ</span></span><br><b>Cả một câu</b> thì phải thêm「の」để biến thành danh từ trước, rồi mới nối にひきかえ:<br><span class='gd-pair'><span class='gd-jp'>兄はよく勉強する</span> → <span class='gd-jp'>兄がよく勉強するのにひきかえ</span></span><br><span class='gd-pair'><span class='gd-jp'>姉は明るい</span> → <span class='gd-jp'>姉が明るいのにひきかえ</span></span><br>Từ như「社交的」(đuôi な) phải thêm な thì mới nối được の: <span class='gd-pair'><span class='gd-jp'>社交的</span> → <span class='gd-jp'>社交的なのにひきかえ</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Hai bên chênh lệch rất lớn</span>Đem hai người, hai thời kỳ hoặc hai nơi ra đối chiếu để nhấn mạnh sự khác biệt lớn.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の猛暑にひきかえ、今年の夏は過ごしやすい。</span>（So với cái nóng khủng khiếp năm ngoái thì mùa hè năm nay dễ chịu hơn nhiều）</div><div class='gd-ex-line'>・<span class='gd-jp'>前の部長にひきかえ、今度の部長はとても話しやすい。</span>（So với trưởng phòng trước thì trưởng phòng lần này dễ nói chuyện hơn nhiều）</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が社交的なのにひきかえ、弟は人見知りだ。</span>（Anh trai thì hướng ngoại, ngược lại em trai lại rất nhút nhát với người lạ）</div><div class='gd-sec'><span class='gd-tag'>それにひきかえ</span>Đặt ở đầu câu, nghĩa là \"ngược lại thì…\". Câu trước nói người khác tốt thế nào, câu sau nói đến bản thân hoặc người nhà mình, thường mang ý than phiền hoặc tự giễu.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の子は毎日勉強している。それにひきかえ、うちの子はゲームばかりだ。</span>（Con nhà hàng xóm ngày nào cũng học bài. Ngược lại, con nhà mình suốt ngày chỉ chơi game）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi nối với cả câu, 「の」ở giữa không được thiếu: phải nói <span class='gd-jp'>社交的なのにひきかえ</span>, không được nói 社交的にひきかえ. 「のに」ở đây là「の＋に」, không phải のに kiểu \"rõ ràng… vậy mà…\".<br>・Mẫu này mang đánh giá của người nói, nên <b>không hợp để so sánh số liệu thuần túy</b>. Với câu chỉ nêu con số như \"nam chiếm 30%, nữ chiếm 50%\" thì dùng にひきかえ nghe rất lạ.<br>・Sắc thái thiên về văn viết, trang trọng. Trong hội thoại hằng ngày, bạn hay nghe <span class='gd-jp'>それにひきかえ</span> ở đầu câu hơn.<br>・Đừng nhầm với <span class='gd-jp'>〜と引き換えに</span>, nghĩa là \"đổi lấy ~\": <span class='gd-jp'>代金と引き換えに商品を渡す。</span>（Tiền trao cháo múc）. Nghĩa hoàn toàn khác nhau.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng nói anh trai hướng ngoại, em trai hướng nội:<br><b>に対して</b>＝liệt kê khách quan hai bên khác nhau, không mang cảm xúc: <span class='gd-jp'>兄は社交的なのに対して、弟は内向的だ。</span>（Anh trai hướng ngoại, còn em trai thì hướng nội）<br><b>にひきかえ</b>＝mang cảm giác \"sao khác nhau đến thế\" hoặc bất mãn: <span class='gd-jp'>兄が社交的なのにひきかえ、弟は内向的だ。</span>（Anh trai thì hướng ngoại đến vậy, ngược lại em trai lại hướng nội thế này）<br><b>に比べて</b>＝chỉ đơn thuần so sánh mức độ cao thấp: <span class='gd-jp'>去年に比べて、今年は暑い。</span>（Năm nay nóng hơn năm ngoái）</div><div class='gd-warn'>Mẹo nhận biết: nếu trong lòng bạn có cảm giác \"ngược lại thì…\", \"người ta thì… còn mình lại…\" thì dùng にひきかえ; nếu chỉ khách quan nói hai bên khác nhau thì dùng に対して; nếu chỉ so ai nhiều ai ít thì dùng に比べて.</div>","n1-2":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をもって」giống cách nói <b>\"bằng ~\", \"lấy ~ làm…\"</b> trong văn bản hành chính tiếng Việt. Một nghĩa là <b>\"dùng ~ để làm\"</b> (thông báo bằng văn bản, xử lý bằng sự thành ý), nghĩa còn lại là <b>\"lấy ~ làm mốc\"</b> (đến hết hôm nay, kể từ ngày này). Bạn hay gặp nó nhất trong thông báo, thư thông báo, hoặc lời MC ở buổi lễ; trò chuyện hằng ngày gần như không dùng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đặt danh từ ở phía trước, rồi thêm をもって: <span class='gd-pair'><span class='gd-jp'>書面</span> → <span class='gd-jp'>書面をもって</span></span><br>Phần đứng trước thường là danh từ trang trọng hoặc trừu tượng, ví dụ 書面, 誠意, 拍手, hoặc từ chỉ thời gian như 本日, 3月.<br>Khi muốn nói lịch sự hơn, bạn sẽ dùng <span class='gd-jp'>をもちまして</span>, nghĩa vẫn như nhau.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bằng cách nào</span>\"Dùng ~ để làm việc gì đó\", giống「で」trong hoàn cảnh trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>合否は書面をもってお知らせします。</span>（Kết quả đỗ hay không sẽ được thông báo bằng văn bản）</div><div class='gd-ex-line'>・<span class='gd-jp'>誠意をもって対応いたします。</span>（Chúng tôi sẽ xử lý bằng tất cả thành ý）</div><div class='gd-ex-line'>・<span class='gd-jp'>盛大な拍手をもってお迎えください。</span>（Xin hãy chào đón bằng một tràng pháo tay thật nhiệt liệt）</div><div class='gd-sec'><span class='gd-tag'>Mốc thời gian</span>Lấy một thời điểm làm ranh giới, thường là \"đến ngày này thì kết thúc\", cũng có thể là \"từ ngày này bắt đầu có hiệu lực\".</div><div class='gd-ex-line'>・<span class='gd-jp'>本日をもって、閉店いたします。</span>（Cửa hàng chúng tôi mở cửa đến hết hôm nay）</div><div class='gd-ex-line'>・<span class='gd-jp'>以上をもちまして、本日の会議を終了いたします。</span>（Đến đây là hết, cuộc họp hôm nay xin được kết thúc）</div><div class='gd-ex-line'>・<span class='gd-jp'>4月1日をもって、社名を変更いたします。</span>（Kể từ ngày 1 tháng 4, công ty sẽ đổi tên）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>本日をもって閉店</span> nghĩa là <b>hôm nay vẫn còn mở, và hôm nay là ngày cuối</b>, không phải hôm nay đã đóng cửa rồi. Nếu dịch thành \"kể từ hôm nay ngừng kinh doanh\" thì rất dễ gây hiểu lầm.<br>・Đây là cách nói rất cứng, thuộc văn viết, đừng dùng bừa trong đời sống hằng ngày. Với bạn bè, \"viết bằng bút\" thì nói <span class='gd-jp'>ペンで書く</span>; nói ペンをもって書く nghe sẽ rất kỳ.<br>・Nó khác với <span class='gd-jp'>持って</span> nghĩa là \"cầm\". <span class='gd-jp'>傘を持って出かける</span> là thật sự cầm ô trên tay ra ngoài; còn <span class='gd-jp'>書面をもって</span> là \"bằng hình thức văn bản\", không có ai cầm vật gì cả. Vì vậy khi dùng như mẫu ngữ pháp, nó thường được viết bằng hiragana.<br>・<span class='gd-jp'>以上をもちまして</span> là câu cố định để kết thúc sự kiện, buổi lễ; nghe câu này là biết sắp kết thúc rồi.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>で</b>＝\"bằng ~\" trong cách nói đời thường: <span class='gd-jp'>結果はメールで知らせるね。</span>（Kết quả mình sẽ báo cho bạn qua email nhé）<br><b>をもって</b>＝\"bằng ~\" trong thông báo chính thức: <span class='gd-jp'>結果は書面をもってお知らせします。</span>（Kết quả sẽ được thông báo bằng văn bản）<br>Hai câu nghĩa gần giống nhau, khác ở hoàn cảnh: một câu là nói tự nhiên với người quen, một câu là thông báo chính thức của công ty hay trường học.</div><div class='gd-sec'><b>を限りに</b> cũng có thể nói \"đến ~ là hết\", nhưng nó nhấn mạnh <b>\"đây là lần cuối, sau này không làm nữa\"</b>, thường mang cảm giác cá nhân đã hạ quyết tâm: <span class='gd-jp'>今日を限りにタバコをやめる。</span>（Từ hôm nay tôi không hút thuốc nữa）<br><b>をもって</b> thì giống <b>thông báo chính thức</b> của cơ quan, công ty hơn, và còn có thể nói \"từ ngày này bắt đầu có hiệu lực\", là cách dùng mà を限りに không có: <span class='gd-jp'>本日をもって受付を締め切ります。</span>（Việc tiếp nhận sẽ khép lại vào hôm nay）</div><div class='gd-warn'>Mẹo nhận biết: bình thường nói \"bằng ~\" thì dùng で; \"bằng ~\" trong thông báo, thư thông báo, buổi lễ thì dùng をもって; còn tự hạ quyết tâm \"đến hôm nay là thôi không ~ nữa\" thì dùng を限りに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>をもってしても</span>＝\"cho dù dùng đến ~ thì cũng…\", phía sau là việc không làm được: <span class='gd-jp'>最新の技術をもってしても、完全には防げない。</span>（Cho dù dùng đến công nghệ mới nhất cũng không thể ngăn chặn hoàn toàn）</div>","n1-10":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ないまでも」nghĩa là <b>“dù chưa được đến mức ～, thì ít nhất cũng phải ～”</b>. Bạn đặt tiêu chuẩn cao sang một bên trước (điểm tuyệt đối, ngày nào cũng làm, giỏi như người bản xứ), rồi nêu một mục tiêu <b>lùi một bước, ở mức tối thiểu</b>. Giống như bạn tự nhủ: “Không cần ngày nào cũng tập thể dục, ít nhất mỗi tuần một lần”, chính là giọng điệu này.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ thể ない + までも. Vế đầu đặt “tiêu chuẩn cao”, vế sau đặt “mức ít nhất phải đạt được”.<br><span class='gd-pair'><span class='gd-jp'>取れない</span> → <span class='gd-jp'>取れないまでも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ネイティブのようには話せないまでも、日常会話はこなしたい。</span>(Dù không nói được như người bản xứ, ít nhất mình cũng muốn xoay xở được trong giao tiếp hằng ngày)</div><div class='gd-sec'>Thực tế, hai cụm cố định dưới đây còn gặp nhiều hơn, danh từ đặt thẳng phía trước. Bạn nên học thuộc cả cụm:</div><div class='gd-sec'><span class='gd-tag'>とは言わないまでも</span>“Không đòi hỏi đến mức ～”, hay dùng khi nói về mong muốn, yêu cầu.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日とは言わないまでも、週に一度は運動したい。</span>(Không dám nói là mỗi ngày, nhưng ít nhất mình muốn tập thể dục mỗi tuần một lần)</div><div class='gd-sec'><span class='gd-tag'>とはいかないまでも</span>“Tuy chưa đạt đến ～”, hay dùng để nói về kết quả đã có.</div><div class='gd-ex-line'>・<span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>(Tuy không được điểm tuyệt đối, nhưng ít nhất cũng đạt điểm đỗ)</div><div class='gd-h'>Vế sau thường trông thế nào</div><div class='gd-sec'>Vế sau thường là “muốn ～”, “nên ～”, “mong đối phương ～”, hoặc một kết quả đã làm được. Nó cũng hay đi với <b>「は」「くらいは」「せめて」</b> để nhấn mạnh “ít nhất là điều này”.</div><div class='gd-ex-line'>・<span class='gd-jp'>謝罪とは言わないまでも、せめて一言説明してほしい。</span>(Không đòi xin lỗi, nhưng ít nhất cũng hãy giải thích một câu)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Hai vế phải là <b>cao và thấp trên cùng một thước đo</b>: điểm tuyệt đối so với điểm đỗ, mỗi ngày so với mỗi tuần một lần. Vế trước cao, vế sau thấp. Nếu vế sau cao hơn vế trước, hoặc hai việc chẳng liên quan gì nhau thì không dùng được.<br>・Vế sau là ý <b>khẳng định</b>: “ít nhất cũng làm được / muốn làm được”. Nếu muốn nói “đến mức tối thiểu cũng không làm được”, phải đổi sang mẫu khác (xem はおろか ở dưới).<br>・Đừng nhầm với「〜までもない」: <span class='gd-jp'>言うまでもない</span> là “khỏi cần nói cũng biết”, đi với thể từ điển, nghĩa là “không cần thiết phải làm”; còn <span class='gd-jp'>言わないまでも</span> là “dù không nói đến mức đó”. Chỉ khác một chữ ない mà nghĩa hoàn toàn khác.<br>・Nhìn chung mẫu này thiên về văn viết, trang trọng, nhưng「とは言わないまでも」cũng khá hay nghe trong hội thoại hằng ngày.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Dễ lẫn nhất là <b>〜はおろか</b>. Cả hai đều có nghĩa “tiêu chuẩn cao không đạt được”, nhưng hướng ở vế sau thì ngược nhau. Cùng nói về thi cử:<br><span class='gd-jp'>満点とはいかないまでも、合格点は取れた。</span>(Tuy không được điểm tuyệt đối, nhưng ít nhất cũng đạt điểm đỗ) → mức thấp <b>có đạt</b>, câu khép lại theo hướng tốt.<br><span class='gd-jp'>満点はおろか、合格点も取れなかった。</span>(Điểm tuyệt đối thì khỏi nói, đến điểm đỗ cũng không đạt) → mức thấp cũng <b>không đạt</b>, câu nhấn mạnh theo hướng xấu.</div><div class='gd-warn'>Mẹo phân biệt: “cái cao thì không có, <b>nhưng cái thấp thì có</b>” dùng ないまでも; “cái cao không có, <b>đến cái thấp cũng không có</b>” dùng はおろか.</div>","n1-22":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜べく」nghĩa là <b>“để ～, nhằm ～”</b>, nhưng đây là cách nói văn viết, trang trọng, giống kiểu “nhằm…”, “với mục đích…” trong báo chí hay văn bản hành chính tiếng Việt. Nghĩa gần giống「ために」, chỉ là cứng hơn, trang trọng hơn, và khi trò chuyện bình thường gần như không ai dùng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tin tức・phóng sự</span>Thuật lại việc ai đó hành động vì mục đích gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>真相を確かめるべく、記者は現地へ向かった。</span>(Để làm rõ sự thật, phóng viên đã đến hiện trường)</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格すべく、毎日10時間勉強した。</span>(Để thi đỗ, mỗi ngày mình đã học 10 tiếng)</div><div class='gd-sec'><span class='gd-tag'>Bày tỏ quyết tâm trong dịp trang trọng</span>Trong bài phát biểu, họp báo, thông báo của công ty, khi nói “để ～, chúng tôi sẽ nỗ lực”.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご期待に応えるべく、全力を尽くします。</span>(Để không phụ lòng mong đợi của quý vị, chúng tôi sẽ dốc toàn lực)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thêm「べく」thẳng vào <b>thể từ điển</b> (dạng gốc tra được trong từ điển) của động từ:<br><span class='gd-pair'><span class='gd-jp'>確かめる</span> → <span class='gd-jp'>確かめるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なるべく</span></span><br><span class='gd-pair'><span class='gd-jp'>応える</span> → <span class='gd-jp'>応えるべく</span></span></div><div class='gd-sec'><b>する</b> hơi đặc biệt, cả hai dạng đều dùng được, nhưng <b>すべく</b> phổ biến hơn:<br><span class='gd-pair'><span class='gd-jp'>達成する</span> → <span class='gd-jp'>達成すべく</span></span> (cũng có thể nói <span class='gd-jp'>達成するべく</span>)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước <b>không được dùng phủ định</b>: không có cách nói「遅刻しないべく」. Muốn nói “để không ～” hãy dùng <span class='gd-jp'>遅刻しないように</span>.<br>・Phía sau <b>không được nhờ/yêu cầu người khác làm gì</b> (nhờ vả, mệnh lệnh, rủ rê): <span class='gd-jp'>合格すべく、毎日勉強してください</span> là sai, phải sửa thành <span class='gd-jp'>合格するために、毎日勉強してください</span>.<br>・<b>Danh từ không nối thẳng được</b>: nói được <span class='gd-jp'>健康のために</span>, nhưng không có「健康のべく」. Muốn dùng べく thì phải nối với động từ: <span class='gd-jp'>健康を維持すべく</span>.<br>・Hai vế thường có <b>cùng một chủ thể</b>, và là việc <b>làm có chủ đích</b>. Những việc con người không kiểm soát được như “trời mưa” thì không đặt trước べく được.<br>・Coi chừng nhầm với phó từ <span class='gd-jp'>なるべく</span> (cố gắng hết mức có thể): <span class='gd-jp'>なるべく早く来てください</span> là “hãy đến sớm hết mức có thể”; còn <span class='gd-jp'>医者になるべく</span> mới là “để trở thành bác sĩ”. Nhìn phía trước có từ nào nối vào hay không là phân biệt được.<br>・Nếu nói chuyện với bạn bè mà dùng「〜べく」thì nghe như đang đọc công văn, trong văn nói hãy dùng ために.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Cùng là “cố gắng để thi đỗ”:<br><b>ために</b> = cách nói thông thường, nói hay viết đều dùng được: <span class='gd-jp'>合格するために、毎日勉強している。</span> (Để thi đỗ, ngày nào mình cũng học)<br><b>べく</b> = văn viết, trang trọng: <span class='gd-jp'>合格すべく、毎日勉強した。</span> (Nhằm thi đỗ, mình đã học miệt mài mỗi ngày)<br><b>んがため(に)</b> = cổ hơn, cứng hơn, mang sắc thái mạnh “phải đạt bằng được, bất chấp”, cách nối cũng khác (<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span>): <span class='gd-jp'>合格せんがため、寝る間も惜しんで勉強した。</span> (Để thi đỗ, tiếc cả thời gian ngủ, mình đã học điên cuồng)</div><div class='gd-warn'>Mẹo phân biệt: bình thường dùng ために; báo chí, diễn văn, văn bản trang trọng dùng べく; chỉ khi muốn nhấn mạnh “dù thế nào cũng phải đạt cho bằng được” mới dùng んがため.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>・<span class='gd-jp'>べくして</span>: “vốn dĩ đã định sẵn là sẽ ～”, nghĩa khác với “để”. <span class='gd-jp'>起こるべくして起こった事故だ。</span> (Đây là vụ tai nạn sớm muộn gì cũng xảy ra)<br>・Cùng họ còn có <span class='gd-jp'>べき</span> (nên) và <span class='gd-jp'>べからず</span> (không được), nghĩa đều không phải “để”, đừng lẫn lộn.</div>","n1-23":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ゆえ（に）」tương đương với <b>「do ～」「bởi ～」「vì lẽ ～」</b> trong văn viết tiếng Việt. Nghĩa giống「から」「ので」là “vì, bởi vì”, chỉ là nó mặc vest vào và nói năng trang trọng hơn. Bạn hay gặp nó trong bình luận báo chí, tiểu thuyết, bài diễn văn. Bạn bè nói chuyện với nhau gần như không dùng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Phổ biến nhất là nối trực tiếp, ở giữa cũng có thể thêm「の」.<br><span class='gd-pair'><span class='gd-jp'>若さ</span> → <span class='gd-jp'>若さゆえ</span></span><span class='gd-pair'><span class='gd-jp'>貧しさ</span> → <span class='gd-jp'>貧しさのゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>Động từ・tính từ い</span>Dùng thể thường (dạng từ điển, không có ます), phía sau nối「がゆえ」hoặc「ゆえ」đều được, trong đó「がゆえ」nghe cứng hơn.<br><span class='gd-pair'><span class='gd-jp'>人気がある</span> → <span class='gd-jp'>人気があるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いがゆえに</span></span></div><div class='gd-sec'><span class='gd-tag'>Tính từ な・danh từ làm vị ngữ</span>Đổi「だ」thành <b>である</b> rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>真面目だ</span> → <span class='gd-jp'>真面目であるがゆえに</span></span><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるがゆえに</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ゆえに、〜</span>Phía sau là cả một câu nêu kết quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>人気があるがゆえに、予約がなかなか取れない。</span>（Do quá được ưa chuộng nên mãi vẫn không đặt được chỗ）</div><div class='gd-ex-line'>・<span class='gd-jp'>責任ある立場ゆえに、軽率な発言は許されない。</span>（Vì đang ở vị trí có trách nhiệm nên không được phát ngôn tùy tiện）</div><div class='gd-sec'><span class='gd-tag'>ゆえの＋danh từ</span>Bổ nghĩa trực tiếp cho danh từ phía sau, nghĩa là “… xuất phát từ ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>経験不足ゆえの失敗だった。</span>（Đó là thất bại do thiếu kinh nghiệm）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しさゆえの嘘もある。</span>（Cũng có những lời nói dối xuất phát từ lòng tốt）</div><div class='gd-sec'><span class='gd-tag'>ゆえに đứng đầu câu</span>Đặt riêng ở đầu câu, nó có nghĩa là “vì vậy, do đó”, rất hay gặp trong chứng minh toán học và lập luận triết học.</div><div class='gd-ex-line'>・<span class='gd-jp'>我思う、ゆえに我あり。</span>（Tôi tư duy, vậy nên tôi tồn tại）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な <b>không được nối với「だ」</b>: không nói「学生だがゆえに」, mà phải nói <span class='gd-jp'>学生であるがゆえに</span>。<br>・Dùng trong hội thoại hằng ngày nghe như đang diễn phim cổ trang hay đọc thoại. Nói với bạn “vì bận quá” thì cứ nói <span class='gd-jp'>忙しいから</span> là đủ, nói「忙しいがゆえに」sẽ làm người ta bật cười.<br>・Chữ Hán viết là「故」. Gặp <span class='gd-jp'>若さ故に</span> đừng tưởng là mẫu ngữ pháp khác, vẫn đọc là ゆえに.<br>・Phía sau thường là kết quả khá tiêu cực, hoặc kiểu “ngược lại lại ～”, mang chút cảm khái “chính vì đặc điểm này nên mới ra thế”, ví dụ <span class='gd-jp'>真面目であるがゆえに、かえって批判されることもある。</span>（Chính vì nghiêm túc nên đôi khi lại bị chỉ trích）</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>から／ので</b>＝“vì, bởi vì” thông thường, dùng được cả khi nói lẫn khi viết: <span class='gd-jp'>子どもを愛しているから、厳しくする。</span>（Vì yêu con nên tôi nghiêm khắc）<br><b>がゆえに</b>＝cùng nghĩa, nhưng mang giọng văn viết, nêu nguyên nhân một cách khách quan: <span class='gd-jp'>子どもを愛するがゆえに、厳しくする。</span>（Do yêu con nên tôi nghiêm khắc với con）<br><b>ばこそ</b>＝nhấn mạnh rất mạnh “<b>chính</b> vì điều này, chứ không phải gì khác”, thường là người nói đang biện hộ cho cách làm của mình, cuối câu hay đi với のだ: <span class='gd-jp'>子どもを愛すればこそ、厳しくするのだ。</span>（Chính vì yêu con nên tôi mới nghiêm khắc với con）</div><div class='gd-warn'>Mẹo phân biệt: chỉ muốn nói “vì” theo cách trang trọng hơn thì dùng ゆえに; muốn nhấn mạnh “chính là lý do này, hãy hiểu cho tôi” thì dùng ばこそ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu N1 khác cũng nói về nguyên nhân là <span class='gd-jp'>〜とあって</span>（vì là tình huống đặc biệt như ～）, bạn có thể đặt cạnh ゆえに để so sánh và nhớ cùng nhau.</div>","n1-27":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たところで」nghĩa là <b>「dù có ～ thì cũng vô ích」「～ thì được gì chứ」</b>. Giống như khi người Việt nói “bây giờ khóc thì được gì”, “bạn có giải thích thế nào anh ấy cũng không tin đâu”, giọng hơi buông xuôi, hơi dội gáo nước lạnh: việc ở phía trước có làm cũng uổng công.</div><div class='gd-ex-line'>・<span class='gd-jp'>今さら謝ったところで、関係は戻らないだろう。</span>（Đến nước này dù có xin lỗi thì quan hệ cũng không quay lại được đâu nhỉ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đầu tiên chuyển động từ sang thể た (thể quá khứ), rồi thêm「ところで」ngay phía sau.<br><b>Nhóm 1 (động từ ngũ đoạn)</b>：<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いだ</span> → <span class='gd-jp'>急いだところで</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったところで</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>：<br><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てた</span> → <span class='gd-jp'>慌てたところで</span></span><br><b>Nhóm 3 (する・来る)</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したところで</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たところで</span></span></div><div class='gd-h'>Những dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Làm cũng công cốc</span>Cách dùng phổ biến nhất. Phía trước thường đi với「<span class='gd-jp'>いくら</span>」「<span class='gd-jp'>どんなに</span>」「<span class='gd-jp'>今さら</span>」, phía sau là những kết quả vô ích như「～ない」「無駄だ」「仕方がない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに急いだところで、最終便には間に合わない。</span>（Dù có vội thế nào cũng không kịp chuyến cuối）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら説明したところで、わかってもらえないだろう。</span>（Dù có giải thích bao nhiêu, chắc anh ấy cũng không hiểu đâu）</div><div class='gd-sec'><span class='gd-tag'>Cùng lắm cũng chỉ ～</span>Phía sau đi với「<span class='gd-jp'>せいぜい</span>」, nghĩa là “dù có làm thì kết quả cũng chẳng đáng là bao”.</div><div class='gd-ex-line'>・<span class='gd-jp'>今から急いだところで、せいぜい5分早く着くくらいだ。</span>（Bây giờ có vội thì cùng lắm cũng chỉ đến sớm được 5 phút）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tuy dùng thể た nhưng đây là nói về <b>giả định</b>, không phải việc đã xảy ra. 「謝ったところで」là “dù (có đi) xin lỗi”, chứ không phải “đã xin lỗi”.<br>・Phía sau phải là kết quả vô ích, chẳng ra sao. Muốn nói một kết quả tốt kiểu “cố gắng thì sẽ đỗ” thì không thể nói 頑張ったところで合格できる, mà phải dùng <span class='gd-jp'>頑張れば合格できる</span>。<br>・Phía sau là nhận định hoặc suy đoán của chính bạn, thường kết thúc bằng「～だろう」「～わけではない」, và không đi với những câu nhờ người khác làm gì như「～てください」.<br>・Cũng có một「たところで」khác nghĩa là “vào lúc ～, khi vừa xong một đoạn”, phía sau nối hành động tiếp theo: <span class='gd-jp'>話が一段落したところで、休憩しましょう。</span>（Câu chuyện đã tạm xong một đoạn, mình nghỉ giải lao nhé）. Hãy nhìn phía sau: nếu là “vô ích” thì là nghĩa của bài này, nếu là “rồi làm việc gì đó tiếp” thì là mốc thời gian.<br>・Giọng điệu hơi lạnh nhạt, mang cảm giác bỏ cuộc. Nói thẳng với người khác “bạn làm cũng vô ích” sẽ rất phũ, tùy hoàn cảnh mà dùng.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>ても</b>＝“dù” thông thường, trung tính, phía sau là kết quả tốt hay xấu đều được: <span class='gd-jp'>彼に説明しても、わかってもらえないだろう。</span>（Dù có giải thích với anh ấy, chắc anh ấy cũng không hiểu đâu）<br><b>たところで</b>＝đặc biệt nhấn mạnh “làm cũng uổng công”, buông xuôi hơn ても: <span class='gd-jp'>彼に説明したところで、わかってもらえないだろう。</span>（Dù có giải thích với anh ấy cũng vô ích, anh ấy sẽ không hiểu đâu）<br><b>ようと</b>＝“dù ～ thì tôi vẫn ～”, trọng tâm là phía sau không bị ảnh hưởng, có thể nối với quyết tâm của chính mình: <span class='gd-jp'>みんなが反対しようと、私はこの計画を進める。</span>（Dù mọi người phản đối thế nào, tôi vẫn sẽ thúc đẩy kế hoạch này）<br>Cũng nói về chuyện phản đối, nếu dùng たところで thì thành: <span class='gd-jp'>みんなが反対したところで、社長の考えは変わらない。</span>（Mọi người có phản đối cũng vô ích, suy nghĩ của giám đốc sẽ không thay đổi）</div><div class='gd-warn'>Mẹo phân biệt: muốn nói “làm cũng công cốc” thì dùng たところで; muốn nói “dù thế nào tôi cũng sẽ làm” thì dùng ようと; chỉ là “dù” thông thường thì dùng ても.</div>","n1-28":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようが／〜ようと」nghĩa là <b>「mặc kệ ~, tôi vẫn cứ…」</b>. Dù phía trước xảy ra chuyện gì, người khác thế nào, kết luận phía sau cũng không đổi. Giọng điệu <b>cứng và mạnh</b> hơn 「〜ても」 thông thường, mang thái độ \"tôi quyết rồi, không ngán ai\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đi với từ nghi vấn</span>Phía trước đặt 「何・どこ・誰・どんなに・いくら」, nghĩa là \"dù gì / dù ở đâu / dù ai / dù ~ đến mức nào\".</div><div class='gd-ex-line'>・<span class='gd-jp'>何を言われようが、気にしない。</span>(Dù bị nói gì, tôi cũng không bận tâm)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこへ行こうと、あなたの自由です。</span>(Bạn đi đâu cũng là tự do của bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が反対しようと、私はやる。</span>(Dù ai phản đối, tôi vẫn làm)</div><div class='gd-sec'><span class='gd-tag'>Dùng một mình</span>Khi không có từ nghi vấn, nghĩa là \"cho dù ~ thì vẫn cứ…\".</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが行く。</span>(Cho dù trời mưa, tôi vẫn đi)</div><div class='gd-sec'><span class='gd-tag'>Hai vế song song</span>「AようがBようが」＝ dù A hay B; 「Aようが Aまいが」＝ dù làm hay không làm. 「まい」ở đây mang nghĩa phủ định \"không ~\"; với nhóm 1 (động từ ngũ đoạn) thì nối vào dạng từ điển: <span class='gd-jp'>行くまい</span>; còn <span class='gd-jp'>する</span> thường nói thành <span class='gd-jp'>しまい</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降ろうが風が吹こうが、試合は行われる。</span>(Dù mưa hay gió, trận đấu vẫn diễn ra như thường)</div><div class='gd-ex-line'>・<span class='gd-jp'>参加しようがしまいが、あなたの自由だ。</span>(Tham gia hay không là tùy bạn)</div><div class='gd-sec'>Vế sau rất hay đi với「<span class='gd-jp'>自由だ</span>」「<span class='gd-jp'>関係ない</span>」「<span class='gd-jp'>構わない</span>」「<span class='gd-jp'>気にしない</span>」, hoặc thể hiện quyết tâm \"tôi nhất định sẽ làm\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: đổi sang thể ý chí (dạng 「行こう」「食べよう」), rồi thêm が hoặc と.<br>Nhóm 1 (động từ ngũ đoạn): <span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành こ → <span class='gd-jp'>行こうが</span></span><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうが</span></span><br>Nhóm 2 (động từ nhất đoạn): bỏ る rồi thêm よう　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べようが</span></span>, thể bị động cũng biến đổi như vậy: <span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われようが</span></span><br>Nhóm 3 (する・来る): <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようが</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようが</span></span></div><div class='gd-sec'><b>Tính từ い</b>: bỏ「い」ở cuối, thêm「かろう」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かろうが</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろうと</span></span><br>「いい」phải biến đổi theo「よい」: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろうが</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに暑かろうと、毎朝のランニングは欠かさない。</span>(Nóng đến đâu, tôi cũng không bỏ buổi chạy bộ mỗi sáng)</div><div class='gd-sec'><b>Tính từ な・Danh từ</b>: thêm「だろう」hoặc 「であろう」trang trọng hơn.<br><span class='gd-pair'><span class='gd-jp'>不便だ</span> → <span class='gd-jp'>不便だろうが</span></span><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもであろうと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>相手が子どもだろうが、ルールはルールだ。</span>(Dù đối phương là trẻ con, luật vẫn là luật)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Thể ý chí ở đây <b>không</b> mang nghĩa \"cùng làm nhé\" hay rủ rê ai cả, chỉ là mượn hình thức đó để diễn đạt \"mặc kệ\".<br>・Nhóm 1 không nối trực tiếp được: phải là <span class='gd-jp'>行こうが</span>, không phải「行くようが」.<br>・<span class='gd-jp'>来ようが</span> đọc là「こようが」, không phải「きようが」.<br>・<span class='gd-jp'>降ろうが</span> chỉ có nghĩa \"cho dù trời mưa\"; muốn nói \"mưa hay không mưa thì cũng…\" phải nói <span class='gd-jp'>降ろうが降るまいが</span>.<br>・「ようが」và「ようと」về cơ bản nghĩa giống nhau, dùng thay cho nhau được.<br>・Giọng điệu rất cứng và mạnh; trò chuyện hằng ngày nói「<span class='gd-jp'>暑くても</span>」tự nhiên hơn; dạng かろう như「<span class='gd-jp'>暑かろうが</span>」thiên về văn viết hoặc khi cần nhấn mạnh.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: dù có vội đến đâu.<br><b>ても</b>＝ \"dù ~ cũng\" thông thường, trung tính nhất: <span class='gd-jp'>いくら急いでも、間に合わない。</span>(Vội đến đâu cũng không kịp)<br><b>ようが</b>＝ vế sau là \"tôi vẫn cứ / chẳng khác gì\", mang thái độ mạnh: <span class='gd-jp'>いくら急がされようが、手は抜かない。</span>(Bị giục thế nào đi nữa, tôi cũng không làm ẩu)<br><b>たところで</b>＝ vế sau là \"cũng vô ích, kết quả không tốt đâu\": <span class='gd-jp'>いくら急いだところで、もう間に合わない。</span>(Dù có vội đến đâu thì cũng đã không kịp rồi)</div><div class='gd-sec'>Ngoài ra, với danh từ còn có thể dùng「<b>であれ</b>」để diễn đạt cùng nghĩa \"dù là ~\": <span class='gd-jp'>理由が何であれ、遅刻はだめだ。</span> và <span class='gd-jp'>理由が何であろうと、遅刻はだめだ。</span> nghĩa gần như giống nhau (dù lý do là gì, đi trễ vẫn không được).</div><div class='gd-warn'>Mẹo chọn nhanh: vế sau là \"tôi vẫn làm / tùy bạn / không sao\" thì dùng ようが; vế sau là \"làm cũng vô ích\" thì dùng たところで; nói chuyện hằng ngày, không muốn nói quá gay gắt thì dùng ても.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là \"dù A hay B\", bạn có thể xem tiếp「<span class='gd-jp'>〜にせよ〜にせよ</span>」: <span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>(Dù đi hay không đi, cũng hãy liên lạc cho tôi)</div>","n1-29":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AにせよBにせよ」tương đương với <b>\"dù là A hay B thì đều ~\"</b> trong tiếng Việt. Bạn đưa ra hai khả năng trước, rồi nói: khả năng nào cũng như nhau, kết luận không đổi. Giọng khá trang trọng, hay gặp trong bài viết, tin tức, phát biểu trong cuộc họp.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối thẳng với thể thường (cách nói không có ます、です).<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにせよ行かないにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ安いにせよ</span></span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: nối thẳng, ở thì hiện tại <b>không thêm だ</b>. Muốn trang trọng hơn thì thêm「である」.<br><span class='gd-pair'><span class='gd-jp'>大人</span> → <span class='gd-jp'>大人にせよ子どもにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きにせよ嫌いにせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにせよ</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Một cặp trái nghĩa</span>Đi / không đi, tán thành / phản đối, bên nào cũng như nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してください。</span>(Dù đi hay không đi, cũng hãy báo sớm cho tôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>好きにせよ嫌いにせよ、この仕事は誰かがやらなければならない。</span>(Dù thích hay không thích, công việc này vẫn phải có người làm)</div><div class='gd-sec'><span class='gd-tag'>Hai thứ cùng loại</span>Nêu hai ví dụ để đại diện cho \"cả loại này đều như nhau\".</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にせよ子どもにせよ、ルールは守らなければならない。</span>(Dù là người lớn hay trẻ em, đều phải tuân thủ luật lệ)</div><div class='gd-sec'>Vế sau thường là nhận định kiểu \"nên ~\", \"đều phải ~\", \"không khác gì nhau\", tức là <b>đúng với cả hai bên</b>.</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Cách nói cố định</span>Không nêu ví dụ, dùng một từ để bao trọn tất cả, rất phổ biến cả khi nói lẫn khi viết.</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、結果が出たら連絡します。</span>(Dù thế nào đi nữa, có kết quả tôi sẽ báo bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>何にせよ、無事でよかった。</span>(Tóm lại, bình an là tốt rồi)</div><div class='gd-sec'><span class='gd-tag'>Chỉ dùng một lần</span>Một「にせよ」đứng riêng ＝ \"cho dù ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にせよ、そんなことを言ってはいけない。</span>(Cho dù là đùa, cũng không được nói những lời như thế)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ, tính từ な ở thì hiện tại không thêm だ: không phải 学生だにせよ mà là <span class='gd-jp'>学生にせよ</span> hoặc <span class='gd-jp'>学生であるにせよ</span>.<br>・「せよ」trông giống mệnh lệnh (\"hãy làm đi!\"), nhưng ở đây chỉ là cách nói cố định, <b>không có nghĩa ra lệnh</b>.<br>・Vế sau nhất định phải đúng với cả hai trường hợp. Nếu kết luận chỉ áp dụng cho một bên thì không dùng được.<br>・Rất văn viết. Nói chuyện với bạn bè thì <span class='gd-jp'>行っても行かなくても</span> tự nhiên hơn; dùng にせよ nghe hơi giống đang đọc công văn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>にしろ…にしろ</b>: nghĩa hoàn toàn giống, giọng mềm hơn một chút, văn nói vẫn dùng được.<br><span class='gd-jp'>行くにしろ行かないにしろ、連絡してください。</span>(Dù đi hay không đi, cũng hãy liên lạc)<br><b>であれ…であれ</b>: chủ yếu đi với danh từ, cứng và trang trọng hơn にせよ.<br><span class='gd-jp'>大人であれ子どもであれ、ルールは守るべきだ。</span>(Dù người lớn hay trẻ em, đều nên tuân thủ luật lệ)<br><b>ようが…まいが</b>: mang cảm xúc mạnh kiểu \"tùy bạn, dù sao cũng như nhau\".<br><span class='gd-jp'>行こうが行くまいが、私には関係ない。</span>(Bạn đi hay không đi cũng chẳng liên quan đến tôi)</div><div class='gd-warn'>Mẹo chọn nhanh: nói bình tĩnh \"dù A hay B\" thì dùng にせよ／にしろ; chỉ đi với danh từ và cần trang trọng hơn thì dùng であれ; mang cảm xúc \"kệ đi, dù sao cũng không đổi\" thì dùng ようが.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói \"bất kể nội dung ra sao thì đều ~\", bạn có thể học <span class='gd-jp'>いかんにかかわらず</span>: <span class='gd-jp'>理由のいかんにかかわらず、遅刻は認めません。</span>(Bất kể lý do là gì, đi trễ đều không được chấp nhận)</div>","n1-30":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜と思いきや」nghĩa là <b>“cứ tưởng là ～, ai ngờ lại…”</b>. Vế trước nói điều bạn dự đoán ban đầu, vế sau nói điều thực sự xảy ra, và kết quả <b>hoàn toàn ngược</b> với dự đoán, tạo cảm giác bất ngờ kiểu “bị vả mặt”.</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れると思いきや、午後から急に雨が降り出した。</span>（Cứ tưởng trời sẽ nắng, ai ngờ chiều đến bỗng mưa ập xuống）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước dùng <b>thể thường</b> (dạng không có ます、です), phía sau thêm thẳng「と思いきや」.<br><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したと思いきや</span></span><br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単だと思いきや</span></span></div><div class='gd-sec'><span class='gd-tag'>かと思いきや</span>Ở giữa thường có thêm một chữ「か」, giọng như “mình còn tưởng liệu có phải ～ không”, dạng này rất hay gặp. Khi thêm「か」bạn cần lưu ý:<br><b>Động từ, tính từ い</b>: thêm か trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>終わった</span> → <span class='gd-jp'>終わったかと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかと思いきや</span></span><br><b>Danh từ, tính từ な</b>: bỏ「だ」trước, rồi mới thêm か.<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → bỏ だ → <span class='gd-jp'>簡単かと思いきや</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → bỏ だ → <span class='gd-jp'>雨かと思いきや</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もう帰ったかと思いきや、まだ会社にいた。</span>（Cứ tưởng anh ấy về rồi, ai ngờ vẫn còn ở công ty）</div><div class='gd-ex-line'>・<span class='gd-jp'>高いかと思いきや、意外と安かった。</span>（Cứ tưởng đắt, không ngờ lại khá rẻ）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は怒るかと思いきや、笑って許してくれた。</span>（Cứ tưởng anh ấy sẽ nổi giận, ai ngờ anh ấy cười rồi tha thứ cho mình）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'>Chủ yếu xuất hiện trong văn viết, báo chí, lời dẫn trên TV, bài đăng mạng xã hội, tức là những lúc “kể chuyện”, mang chút ngạc nhiên hoặc hài hước. Trên mạng người ta còn chỉ viết「〜と思いきや…」rồi dừng lại, cố tình úp mở để câu sau tiết lộ.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi thêm か vào danh từ, tính từ な thì <b>không được giữ だ</b>: đúng là <span class='gd-jp'>簡単かと思いきや</span>, không phải「簡単だかと思いきや」.<br>・「思いきや」là một khối cố định, <b>không chia được</b>, không có cách nói như「思いましたきや」.<br>・Đọc là <b>おもいきや</b>, đừng nhầm với <span class='gd-jp'>思い切り</span> (hết sức, thoải mái) hay <span class='gd-jp'>思い切って</span> (quyết tâm làm), nhìn na ná nhưng nghĩa hoàn toàn khác.<br>・Vế sau là <b>sự thật đã xảy ra</b>, thường dùng thì quá khứ. Không đi với ý định “sẽ làm gì”, mệnh lệnh hay lời rủ rê: 「雨だと思いきや、傘を持っていこう」là sai.<br>・Kết quả nhất định phải <b>ngược</b> với dự đoán. Nếu kết quả đúng như bạn nghĩ thì không dùng được.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Trong giao tiếp hằng ngày người ta hay nói <b>と思ったら</b> hơn. Nó cũng diễn đạt “cứ tưởng ～, ai ngờ…”, lúc này có thể thay cho と思いきや, chỉ là giọng khẩu ngữ hơn:<br><span class='gd-jp'>簡単かと思ったら、意外と難しかった。</span>（Cứ tưởng dễ, hóa ra lại khó bất ngờ）<br>Nhưng と思ったら còn một nghĩa khác: <b>“vừa mới ～ thì ngay lập tức…”</b>, nói về việc diễn ra nối tiếp rất nhanh. Nghĩa này と思いきや không có:<br><span class='gd-jp'>子どもは泣いたと思ったら、もう笑っている。</span>（Đứa bé vừa mới khóc đó mà đã lại cười rồi）<br>Câu này đổi sang と思いきや là sai, vì trọng tâm là “thay đổi quá nhanh”, không phải “dự đoán bị phá vỡ”.</div><div class='gd-warn'>Mẹo nhỏ: nếu là “dự đoán bị lật ngược” thì dùng cái nào cũng được, viết văn dùng と思いきや, nói chuyện dùng と思ったら; còn nếu là “vừa mới ～ đã…” thì chỉ dùng được と思ったら.</div>","n1-31":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ものを」mang giọng kiểu <b>“Biết thế nói sớm có phải xong rồi không!”</b>. Lẽ ra chỉ cần làm như vậy là ổn, thế mà lại không làm, kết quả mọi chuyện tệ đi. Câu mang cảm xúc <b>tiếc nuối, trách móc</b>, có khi trách người khác, có khi trách chính mình.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước dùng thể thường (dạng từ điển, không có ます), thường gặp nhất là đứng sau「〜ばいい」「〜ばよかった」:<br><span class='gd-pair'><span class='gd-jp'>言えばいい</span> → <span class='gd-jp'>言えばいいものを</span></span><br><span class='gd-pair'><span class='gd-jp'>聞けばよかった</span> → <span class='gd-jp'>聞けばよかったものを</span></span><br>Tính từ な phải nối bằng「な」: <span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なものを</span></span>, không nói「便利だものを」.</div><div class='gd-h'>Ba dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>〜ばいいものを</span>Rõ ràng làm vậy là xong, thế mà lại không làm. Hay dùng nhất để cằn nhằn người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>謝ればすむものを、意地を張るから話がややこしくなる。</span>（Rõ ràng xin lỗi một câu là xong, cứ cố chấp nên chuyện mới rắc rối thế này）</div><div class='gd-ex-line'>・<span class='gd-jp'>黙っていればいいものを、余計な一言で彼を怒らせてしまった。</span>（Cứ im lặng là yên chuyện, vậy mà lại nói thêm một câu thừa làm anh ấy giận）</div><div class='gd-sec'><span class='gd-tag'>〜ば〜たものを</span>“Nếu mà ～ thì lẽ ra đã ～ rồi”, nhưng thực tế không xảy ra, thật đáng tiếc.</div><div class='gd-ex-line'>・<span class='gd-jp'>言ってくれれば手伝ったものを。</span>（Giá bạn nói sớm thì mình đã giúp rồi mà）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し早く家を出ていれば間に合ったものを。</span>（Giá ra khỏi nhà sớm thêm chút nữa thì đã kịp rồi）</div><div class='gd-sec'><span class='gd-tag'>Dừng ở cuối câu</span>Vế sau “vậy mà bạn lại không làm” được nuốt luôn không nói, chỉ còn lại tiếng thở dài. Câu thứ ba ở trên chính là kiểu này, rất hay gặp trong phim truyền hình và tiểu thuyết Nhật.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng nhầm với「danh từ もの＋を」: ở <span class='gd-jp'>おいしいものを食べた</span>, もの nghĩa là “đồ vật/món”, theo sau là động từ ngay; còn「〜ものを」thường có dấu phẩy phía sau, nối với ý “vậy mà…”, hoặc thậm chí không nói tiếp.<br>・Nó nói về việc <b>đã xảy ra và không thể thay đổi</b>, nên phía sau không đi với yêu cầu hay mệnh lệnh: không nói「早く言えばいいものを、言ってください」.<br>・Giọng thiên về văn viết, hơi văn chương và mang ý trách móc. Hằng ngày người ta thường nói「〜ばよかったのに」; dùng「ものを」để trách sếp hay khách sẽ rất thiếu lịch sự.<br>・Vế sau là than thở, phàn nàn chứ không phải thuật lại sự thật đơn thuần, nên phía trước hầu như luôn là cách nói giả định kiểu “lẽ ra làm vậy là ổn”.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>のに</b>: nghĩa gần nhất, dùng nhiều nhất trong khẩu ngữ hằng ngày.<br><span class='gd-jp'>早く言えばよかったのに。</span>（Nói sớm có phải tốt hơn không）<br><b>ものを</b>: cũng là phàn nàn, nhưng thiên về văn viết hơn và cảm xúc nặng hơn.<br><span class='gd-jp'>早く言えばよかったものを。</span>（Biết thế nói sớm có phải xong rồi không, haizz）<br>Ngoài ra, のに còn dùng để nói đơn thuần sự thật “rõ ràng ～ mà lại ～” (<span class='gd-jp'>雨なのに出かけた。</span>Trời mưa mà vẫn đi ra ngoài), còn ものを rất ít dùng như vậy.</div><div class='gd-sec'><b>ものの</b> (N2): chỉ khác một chữ, nghĩa là “tuy ～ nhưng ～”, bình tĩnh nêu sự thật, không có ý trách ai.<br><span class='gd-jp'>先生に相談しようと思ったものの、言い出せなかった。</span>（Tuy định bàn với thầy cô nhưng không mở lời được）<br><span class='gd-jp'>先生に相談すればよかったものを、一人で悩んでいた。</span>（Rõ ràng bàn với thầy cô là xong, vậy mà lại một mình phiền muộn）</div><div class='gd-warn'>Mẹo nhỏ: phía trước có「〜ばいい／〜ばよかった」, lại kèm tiếng thở dài kiểu “biết thế thì…”, đó là ものを; còn chỉ nói bình thường “tuy… nhưng…” thì là ものの.</div>","n1-43":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とは」tương đương với <b>「không ngờ lại～」「thật không ngờ～」</b>. Khi gặp một chuyện hoàn toàn bất ngờ, bạn giật mình, cảm khái, thậm chí hơi đứng hình hoặc thất vọng, thì đặt chuyện đó trước とは. Giống phản ứng của người Việt khi nói: \"Hả? Hóa ra anh ta là thủ phạm á!\"</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Ngạc nhiên・bất ngờ</span>Sự việc diễn ra hoàn toàn khác với những gì bạn nghĩ.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな所で君に会うとは。</span>(Không ngờ lại gặp cậu ở nơi thế này)</div><div class='gd-ex-line'>・<span class='gd-jp'>まさか一回で合格するとは思わなかった。</span>(Không ngờ lại đỗ ngay trong một lần)</div><div class='gd-sec'><span class='gd-tag'>Đứng hình・thất vọng</span>Không chỉ ngạc nhiên mà còn kèm chút bất mãn kiểu \"sao lại thế được\".</div><div class='gd-ex-line'>・<span class='gd-jp'>大人がこんな簡単なルールも守れないとは、情けない。</span>(Người lớn mà ngay cả quy định đơn giản thế này cũng không làm được, thật xấu hổ)</div><div class='gd-sec'><span class='gd-tag'>Nói lửng</span>Phần sau như 「驚いた」「思わなかった」 thường bị lược luôn, chỉ để lại dư âm \"không ngờ là...\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が犯人だったとは……。</span>(Không ngờ anh ta lại là thủ phạm...)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước dùng <b>thể thường</b>, tức là cách nói không có です・ます, rồi thêm とは.<br>Động từ:<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うとは</span></span><span class='gd-pair'><span class='gd-jp'>負けた</span> → <span class='gd-jp'>負けたとは</span></span><br>Tính từ đuôi い:<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>こんなに高いとは</span></span><br>Tính từ đuôi な:<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>こんなに簡単だとは</span></span><br>Danh từ:<span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人だとは</span></span>, chữ だ này đôi khi được lược đi, thành <span class='gd-jp'>犯人とは</span>.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Phía trước thường đi với <span class='gd-jp'>まさか</span> (không bao giờ ngờ tới), phía sau thường nối với <span class='gd-jp'>思わなかった</span>, <span class='gd-jp'>思いもよらなかった</span>, <span class='gd-jp'>夢にも思わなかった</span>, <span class='gd-jp'>信じられない</span>, <span class='gd-jp'>驚きだ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>自分が日本で働くことになるとは、夢にも思わなかった。</span>(Có mơ cũng không ngờ mình lại phải đi làm ở Nhật)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・は trong とは đọc là 「わ」, cả cụm đọc là とわ.<br>・Phía trước phải dùng thể thường, không được nối với thể ます. <span class='gd-jp'>会いますとは</span> là sai.<br>・Chuyện chỉ là giả định, chưa chắc chắn thì không dùng とは được (ví dụ 「もし合格するとは」 là sai). Nhưng tin chưa xảy ra mà đã chắc chắn thì dùng được: <span class='gd-jp'>彼女が来月結婚するとは、驚いた。</span>(Không ngờ tháng sau cô ấy lại kết hôn, ngạc nhiên thật)<br>・とは nghe khá trang trọng, thiên về văn viết. Khi trò chuyện với bạn bè, người Nhật hay nói なんて hơn. Dùng とは cũng được, chỉ là nghe sẽ hơi phóng đại, có chút kịch tính.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>なんて</b>: nghĩa cũng là \"không ngờ lại\", chỉ là khẩu ngữ hơn.<br><span class='gd-jp'>こんな所で会うなんて！</span>(Không ngờ lại gặp ở đây! Giữa bạn bè)<br><span class='gd-jp'>こんな所でお会いするとは。</span>(Không ngờ lại gặp ở nơi này, trang trọng hơn)</div><div class='gd-sec'><b>とは mang nghĩa \"cái gọi là～\"</b>: cũng viết là とは, nhưng đây là để định nghĩa một từ, phía sau là lời giải thích hoặc câu hỏi, hoàn toàn không có ý ngạc nhiên.<br><span class='gd-jp'>幸せとは何だろう。</span>(Hạnh phúc là gì nhỉ)<br><span class='gd-jp'>彼が幸せだったとは。</span>(Không ngờ anh ấy lại hạnh phúc)</div><div class='gd-sec'><b>と思いきや</b>: \"Cứ tưởng là～, ai ngờ lại...\", phía sau phải nói ra <b>kết quả thực sự</b>.<br><span class='gd-jp'>晴れると思いきや、雨が降ってきた。</span>(Cứ tưởng trời sẽ nắng, ai ngờ lại mưa)<br><span class='gd-jp'>こんなに雨が降るとは。</span>(Không ngờ mưa to thế này)</div><div class='gd-warn'>Mẹo phân biệt: nếu trước とは là cả một sự việc khiến bạn ngạc nhiên, phía sau là cảm nghĩ thì đó là \"không ngờ lại\". Nếu trước chỉ có một danh từ và phía sau giải thích nó thì đó là \"cái gọi là\". Nếu viết điều mình dự đoán trước rồi mới đến kết quả thật thì đó là と思いきや.</div>","n1-47":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ともなると」tương đương với <b>「đã đến mức ～ thì đương nhiên ～」</b>. Khi địa vị đã lên cao, tuổi đã đến, hoặc một thời điểm đặc biệt đã tới, tình hình tự nhiên sẽ khác thường ngày. Giống như người Việt nói \"làm đến trưởng phòng rồi thì trách nhiệm đương nhiên nặng\", tiếng Nhật là <span class='gd-jp'>部長ともなると、責任も重くなる。</span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thân phận・địa vị</span>Khi lên một vị trí cao hơn, bạn sẽ gặp những tình huống tương ứng.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長ともなると、毎日会議ばかりだ。</span>(Đã lên đến trưởng phòng thì ngày nào cũng chỉ toàn họp)</div><div class='gd-sec'><span class='gd-tag'>Tuổi tác・giai đoạn</span>Con người đến một giai đoạn nào đó thì tự nhiên sẽ khác đi.</div><div class='gd-ex-line'>・<span class='gd-jp'>高校生ともなると、親とあまり話さなくなる。</span>(Lên cấp ba rồi thì không còn nói chuyện nhiều với bố mẹ nữa)</div><div class='gd-sec'><span class='gd-tag'>Thời kỳ</span>Cứ đến một thời điểm đặc biệt nào đó là lần nào cũng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、どこの店も人でいっぱいだ。</span>(Cứ đến cuối năm là cửa hàng nào cũng chật kín người)</div><div class='gd-sec'><span class='gd-tag'>Quy mô của sự việc</span>Khi làm một việc lớn, có tầm cỡ, thì tình hình đi kèm cũng lớn theo.</div><div class='gd-ex-line'>・<span class='gd-jp'>家を建てるともなると、決めることが山ほどある。</span>(Đã xây nhà thì có cả núi việc phải quyết định)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋ともなると:<span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長ともなると</span></span><br>Động từ thể từ điển (dạng nguyên mẫu tra trong từ điển)＋ともなると:<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するともなると</span></span><br>Phía trước thường là thân phận, độ tuổi, thời kỳ hoặc sự việc <b>cao hơn bình thường một bậc, có tầm cỡ</b>. Phía sau là tình huống hoặc nhận định mà khi đến giai đoạn đó thì <b>đương nhiên</b> sẽ xuất hiện.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này mang sắc thái \"đã đến mức này rồi\". Nếu chỉ nói về một sự thay đổi thông thường, như \"cứ đến mùa xuân là hoa nở\", thì dùng <span class='gd-jp'>春になると</span> sẽ tự nhiên hơn.<br>・Phía sau thường là tình huống chung hoặc nhận định, ví dụ trách nhiệm nặng, rất đông, phải chuẩn bị nhiều. Rất ít khi nối với dự định của bản thân kiểu \"tôi sẽ ～\" hay yêu cầu người khác kiểu \"hãy ～\".<br>・「とも」ở đây không phải nghĩa \"cũng\", và cũng hoàn toàn khác với <span class='gd-jp'>ともなく</span> (vô tình ～). Đừng thấy とも là gộp chung lại.<br>・Mẫu này thiên về trang trọng, văn viết. Khi trò chuyện với bạn bè, nói <span class='gd-jp'>部長になると</span> hoặc <span class='gd-jp'>部長にもなると</span> sẽ nhẹ nhàng hơn.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>ともなれば</b>: nghĩa gần như giống hệt, hầu hết trường hợp có thể thay thế cho nhau.<br><span class='gd-jp'>部長ともなれば、責任も重くなる。</span>(Đã lên đến trưởng phòng thì trách nhiệm đương nhiên nặng hơn)</div><div class='gd-sec'><b>とあって</b>: nói rằng \"vì gặp tình huống đặc biệt lần này nên trước mắt đang xảy ra ～\", tức là việc đã nhìn thấy, đã thực sự xảy ra. Còn <b>ともなると</b> nói về xu hướng chung: \"cứ đến mức này thì xưa nay vẫn ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>連休とあって、高速道路はどこも渋滞している。</span>(Vì là kỳ nghỉ liên tiếp nên đường cao tốc chỗ nào cũng đang kẹt)</div><div class='gd-ex-line'>・<span class='gd-jp'>連休ともなると、高速道路はどこも渋滞する。</span>(Hễ đến kỳ nghỉ liên tiếp là đường cao tốc chỗ nào cũng kẹt)</div><div class='gd-warn'>Mẹo phân biệt: nói \"lần này vì ～ nên ～\" thì dùng とあって. Nói \"cứ đến mức ～ thì tự nhiên đều ～\" thì dùng ともなると.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>〜たる</span> cũng hay đi cùng thân phận, nhưng nó nói về \"đã là thân phận này thì phải có dáng vẻ như thế\": <span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>(Đã là giáo viên thì phải là tấm gương cho học sinh). ともなると nói về <b>kết quả tự nhiên</b> mà thân phận mang lại, còn たる nói về <b>biểu hiện đáng có</b> của thân phận đó. Bạn có thể đối chiếu để nhớ.</div>","n1-72":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を余儀なくされる」chính là cách nói quen thuộc trên báo chí, nghĩa là <b>“bị buộc phải ~”</b>. Ví dụ như “do bão nên sự kiện buộc phải hủy”: không phải bạn muốn làm vậy, mà là <b>hoàn cảnh, bối cảnh chung ép đến mức bạn không còn đường nào khác</b>. <span class='gd-jp'>余儀</span> nghĩa là “cách khác”, nên <span class='gd-jp'>余儀ない</span> nghĩa là “không còn cách nào khác”.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Tin tức・báo chí</span>Những sự kiện lớn như thiên tai, dịch bệnh, kinh tế khiến một người hay một tổ chức đành phải làm gì đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨で、試合は中止を余儀なくされた。</span>（Vì mưa lớn, trận đấu buộc phải hủy）</div><div class='gd-ex-line'>・<span class='gd-jp'>地震で、多くの住民が避難生活を余儀なくされている。</span>（Vì động đất, nhiều người dân buộc phải sống trong cảnh sơ tán）</div><div class='gd-sec'><span class='gd-tag'>Nói về hoàn cảnh của mình trong tình huống trang trọng</span>Bạn cũng sẽ dùng khi viết báo cáo hoặc kể về kinh nghiệm của mình trong phỏng vấn.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の倒産で、退職を余儀なくされました。</span>（Vì công ty phá sản, tôi buộc phải nghỉ việc）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>danh từ</b>, và là danh từ chỉ “một hành động”. Hay gặp nhất là <span class='gd-jp'>中止</span>, <span class='gd-jp'>延期</span>, <span class='gd-jp'>変更</span>, <span class='gd-jp'>撤退</span>, <span class='gd-jp'>入院</span>, <span class='gd-jp'>移転</span>, tức là những từ có thể thêm する phía sau.<br>Nếu trong tay bạn là động từ, hãy bỏ する và giữ lại danh từ: <span class='gd-pair'><span class='gd-jp'>延期する</span> → <span class='gd-jp'>延期を余儀なくされた</span></span><br>Chủ ngữ của câu (từ đứng trước は／が) là <b>bên chịu ảnh hưởng, bên bị ép</b>: trận đấu, tiệm lâu đời, người dân, tôi.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>余儀なくされた</span>Việc đã xảy ra, đây là dạng phổ biến nhất.<br><span class='gd-tag'>余儀なくされている</span>Hiện vẫn đang bị ép như vậy, như cuộc sống sơ tán ở ví dụ trên.<br><span class='gd-tag'>余儀なくさせる</span>Ngược lại, đứng về phía “nguyên nhân” để nói, chủ ngữ thường là chính sự kiện đó:</div><div class='gd-ex-line'>・<span class='gd-jp'>円安が、計画の見直しを余儀なくさせた。</span>（Đồng yên mất giá buộc kế hoạch phải được xem xét lại）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đọc là <b>よぎなく</b>, không phải よぎむなく。<br>・Phía trước không đặt động từ trực tiếp: nói <span class='gd-jp'>中止を余儀なくされた</span>, không nói 「中止するを余儀なくされた」。<br>・Việc do bạn tự chọn, tự muốn làm thì không dùng được. Đổi việc vì muốn thử thách điều mới thì không phải “bị buộc”.<br>・Sắc thái rất nặng và trang trọng, dùng cho chuyện nhỏ nhặt sẽ nghe rất phóng đại. 「宿題を余儀なくされた」nghe như đang đùa.<br>・Tiếng Việt nói “bị buộc phải”, nên nhiều bạn phản xạ viết thành させられる, nhưng hai cách này khác nghĩa nhau, xem phần dưới.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng là “nghỉ việc”:<br><b>を余儀なくされる</b>＝do <b>hoàn cảnh</b> ép, không có ai đích danh ép bạn, trang trọng, thiên về văn viết:<br><span class='gd-jp'>会社の倒産で、退職を余儀なくされた。</span>（Vì công ty phá sản, tôi bị buộc phải nghỉ việc）<br><b>させられる</b>＝do <b>một người nào đó</b> ép bạn làm, thường mang chút không cam lòng, cũng hay dùng trong khẩu ngữ:<br><span class='gd-jp'>上司に無理やり退職させられた。</span>（Bị sếp ép nghỉ việc）<br><b>ざるを得ない</b>＝<b>chính mình</b> cân nhắc rồi đành làm vậy, trọng tâm là phán đoán của bản thân:<br><span class='gd-jp'>体調が悪くて、退職せざるを得なかった。</span>（Sức khỏe yếu nên tôi đành phải nghỉ việc）</div><div class='gd-warn'>Mẹo phán đoán: có một “người” ép bạn thì dùng させられる; tự nghĩ kỹ rồi đành làm thì dùng ざるを得ない; bị bối cảnh lớn như thiên tai, kinh tế, thời cuộc ép đến hết đường, lại trong tình huống trang trọng thì dùng を余儀なくされる。</div>","n1-77":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜んばかりに」nghĩa là <b>“cứ như sắp ~ đến nơi”, “với vẻ như muốn ~”</b>. Đây là cách nói phóng đại để miêu tả mức độ của một trạng thái: <b>chỉ thiếu chút nữa là</b> làm hành động đó, nhưng thường <b>chưa thật sự làm</b>. Giống như tiếng Việt nói “cô ấy sốt ruột đến mức sắp khóc”: trọng tâm là miêu tả cô ấy sốt ruột thế nào, chứ không phải cô ấy đã khóc thật.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang thể ない, bỏ 「ない」 đi, rồi thêm 「んばかり」.<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span> → <span class='gd-jp'>泣かんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わんばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>あふれる</span> → <span class='gd-jp'>あふれない</span> → <span class='gd-jp'>あふれんばかり</span></span><br><b>する là ngoại lệ</b>: không phải しんばかり, mà dùng cách nói cổ <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかり</span></span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>んばかりに＋hành động</span>Miêu tả một hành động được làm “như thế nào”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は泣かんばかりに頼んできた。</span>（Cô ấy nhờ tôi như sắp bật khóc）</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が飛びつかんばかりに喜んで走ってきた。</span>（Con chó mừng đến mức như sắp nhảy bổ vào người, chạy lao tới）</div><div class='gd-sec'><span class='gd-tag'>んばかりの＋danh từ</span>Bổ nghĩa trực tiếp cho danh từ phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>会場は割れんばかりの拍手に包まれた。</span>（Cả hội trường vang lên tràng pháo tay như muốn vỡ tung）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「お前のせいだ」と言わんばかりの顔で私を見た。</span>（Anh ấy nhìn tôi với vẻ mặt như muốn nói “tại mày cả”）</div><div class='gd-sec'><span class='gd-tag'>んばかりだ</span>Đặt ở cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の喜びようは、今にも踊り出さんばかりだった。</span>（Anh ấy vui đến mức như sắp nhảy múa ngay lúc này）</div><div class='gd-sec'>Trong đó <span class='gd-jp'>言わんばかり</span>, <span class='gd-jp'>割れんばかり</span>, <span class='gd-jp'>あふれんばかり</span>, <span class='gd-jp'>泣かんばかり</span> xuất hiện đặc biệt nhiều, bạn có thể nhớ cả cụm. Nhìn chung nó mang sắc thái văn viết, tiểu thuyết, nhưng「<span class='gd-jp'>〜と言わんばかりの顔</span>」thì trong lúc nói chuyện bình thường cũng hay nghe.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ 「ん」 ở đây <b>không phải “không”</b>. <span class='gd-jp'>泣かん</span> trông rất giống “không khóc” kiểu giọng Kansai, nhưng trong mẫu ngữ pháp này nó là ん của văn cổ, mang nghĩa “sắp ~”. <span class='gd-jp'>泣かんばかり</span> là “sắp khóc”, không phải “không khóc”.<br>・する phải đổi thành <b>せんばかり</b>, viết しんばかり là sai.<br>・Đây là cách miêu tả phóng đại, dùng để tả <b>dáng vẻ, mức độ</b>. Nếu chỉ đơn giản nói “trông như sắp khóc”, trong hội thoại hằng ngày dùng <span class='gd-jp'>泣きそうな顔</span> là đủ, dùng <span class='gd-jp'>泣かんばかり</span> sẽ nghe rất kịch tính.<br>・Thường chỉ là “chỉ thiếu chút nữa”, chứ chưa thật sự xảy ra. <span class='gd-jp'>あふれんばかり</span> là “đầy đến mức sắp tràn ra”, nước chưa thật sự tràn.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Trước <b>とばかりに</b> là một câu “lời thoại”, nghĩa là “với vẻ như đang nói ~”. Nó có nghĩa gần như giống <span class='gd-jp'>と言わんばかりに</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」と言わんばかりに時計を見た。</span>（Cửa hàng trưởng liếc đồng hồ với vẻ như muốn nói “về nhanh đi”）</div><div class='gd-ex-line'>・<span class='gd-jp'>店長は「早く帰れ」とばかりに時計を見た。</span>（Như trên）</div><div class='gd-sec'>Khác biệt nằm ở thứ được đặt phía trước. Trước <b>んばかりに</b> là <b>hành động suýt nữa được làm</b>, như khóc, tràn ra, nhảy lên; trước <b>とばかりに</b> là <b>lời trong lòng</b>. Vì vậy “như sắp bật khóc” chỉ có thể nói <span class='gd-jp'>泣かんばかりに</span>, không nói 泣くとばかりに。</div><div class='gd-warn'>Mẹo phán đoán: phía trước là “một câu nói” thì dùng とばかりに hoặc と言わんばかりに đều được; phía trước là “hành động suýt làm” thì chỉ dùng thể ない thêm んばかりに。</div>","n1-89":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Nhóm ngữ pháp này giống kiểu <b>“không có ～ mà vẫn ～ / không có ～ thì không thể ～”</b> trong tiếng Việt, và chia làm hai cách nói:<br><span class='gd-jp'>なしに</span>: “không chào một tiếng <b>mà</b> đã lấy đi”, miêu tả ai đó <b>không làm việc đáng ra phải làm mà cứ thế làm luôn</b>.<br><span class='gd-jp'>なしには</span>: “không có bạn <b>thì không thể</b> thành công”, nghĩa là <b>thiếu A thì B hoàn toàn không làm được</b>.<br>Hai cái chỉ khác nhau một chữ「は」, nhưng cách dùng khác nhau rất nhiều.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>なしに</span>Đáng ra phải có một thứ gì đó nhưng không có, vậy mà vẫn làm luôn. Thường mang chút ý không hài lòng kiểu “làm vậy đâu có được”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は連絡なしに会社を休んだ。</span>（Anh ấy nghỉ làm mà không báo một tiếng）</div><div class='gd-ex-line'>・<span class='gd-jp'>断りなしに、人の物を使ってはいけない。</span>（Không được dùng đồ của người khác khi chưa được cho phép）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一言の断りもなしに帰ってしまった。</span>（Anh ấy về luôn, đến một lời chào cũng không có）</div><div class='gd-sec'>Chen thêm 「も」 ở giữa thành <span class='gd-jp'>もなしに</span> thì giọng mạnh hơn, mang cảm giác “thậm chí ～ cũng không có”.</div><div class='gd-sec'><span class='gd-tag'>なしには</span>A là điều kiện không thể thiếu, không có A thì B không làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、涙なしには見られない。</span>（Bộ phim này xem kiểu gì cũng phải khóc）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功できなかった。</span>（Không có sự giúp đỡ của mọi người thì tôi đã không thể thành công）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの協力なしには、成功しなかったでしょう。</span>（Nếu không có mọi người giúp, chắc là đã không thành công đâu）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b> nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>許可</span> → <span class='gd-jp'>許可なしに</span></span><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なしには</span></span><br><b>Động từ</b> phải thêm 「こと」 trước, thành 「thể từ điển＋ことなしに（は）」. Đây là cách nói thiên về văn viết:</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は休むことなしに働き続けた。</span>（Anh ấy làm việc liên tục, không nghỉ phút nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>努力することなしには、夢はかなわない。</span>（Không nỗ lực thì ước mơ sẽ không thành hiện thực）</div><div class='gd-sec'><b>Vế sau của なしには nhất định phải ở dạng phủ định</b>. Thường gặp <span class='gd-jp'>〜できない</span>, <span class='gd-jp'>〜られない</span>, <span class='gd-jp'>〜ありえない</span>, cũng có thể dùng <span class='gd-jp'>〜ない</span>, <span class='gd-jp'>〜なかった（でしょう）</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Sau なしに không nhất thiết phải là phủ định</b>: <span class='gd-jp'>連絡なしに休んだ</span> chính là câu khẳng định. Chỉ có <b>なしには</b> mới bắt buộc vế sau phủ định.<br>・Sau なしには không thể dùng câu khẳng định: ×<span class='gd-jp'>協力なしには成功した</span>, câu này nghĩa không ăn khớp.<br>・Động từ không nối trực tiếp được: ×<span class='gd-jp'>連絡しなしに</span>. Phải viết <span class='gd-jp'>連絡なしに</span> (dùng danh từ), hoặc <span class='gd-jp'>連絡することなしに</span>.<br>・Đây là cách nói khá trang trọng, thiên về văn viết. Khi nói chuyện hằng ngày thường dùng <b>なしで</b>: <span class='gd-jp'>予約なしで入れますか。</span>（Không đặt trước có vào được không?）</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'>Cùng nói về chuyện “không đặt trước”:<br><span class='gd-jp'>予約なしに店に入った。</span>（Không đặt trước mà vào quán luôn: cho biết người đó <b>làm bằng cách nào</b>）<br><span class='gd-jp'>予約なしには入れない。</span>（Không đặt trước thì không vào được: nói về <b>điều kiện cần thiết</b>）</div><div class='gd-sec'><b>なくして（は）</b>: nghĩa gần như giống なしには, nhưng cứng hơn, thường dùng trong diễn văn, bài viết.<br><span class='gd-jp'>皆さんの協力なくしては、成功はありえなかった。</span>（Không có sự hỗ trợ của quý vị thì không thể thành công）</div><div class='gd-sec'><b>あっての</b>: cùng một việc nhưng nói từ chiều ngược lại, “có A mới có B”.<br><span class='gd-jp'>お客様あっての店だ。</span>（Có khách hàng thì mới có cửa hàng）<br>＝<span class='gd-jp'>お客様なしには、店は成り立たない。</span>（Không có khách thì cửa hàng không thể tồn tại）</div><div class='gd-warn'>Mẹo nhỏ để chọn: “không ～ mà cứ làm” dùng なしに; “không ～ thì không thể” dùng なしには (vế sau nhất định phủ định); muốn nói trang trọng hơn thì đổi sang なくしては; muốn nói theo hướng “có A mới có B” thì dùng あっての.</div>","n1-91":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に足る」 giống kiểu <b>“đủ để ～”, “đáng để ～”</b> trong tiếng Việt, nghĩa là người hay việc này <b>đủ tư cách</b> để người ta tin cậy, kính trọng, hài lòng. Ngược lại, 「〜に足りない」 giống như <b>“không đáng sợ”, “không đáng nhắc đến”</b>, tức là không đáng, không cần thiết. 「足る」 đọc là <b>たる</b>, là cách nói văn viết rất cứng, thường xuất hiện trong báo chí, bình luận, tiểu thuyết.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ thể từ điển＋に足る</b>: <span class='gd-pair'><span class='gd-jp'>信頼する</span> → <span class='gd-jp'>信頼するに足る</span></span><span class='gd-pair'><span class='gd-jp'>満足する</span> → <span class='gd-jp'>満足するに足る</span></span><br><b>Với động từ「〜する」, bỏ する đi, dùng danh từ phía trước nối trực tiếp</b>: <span class='gd-pair'><span class='gd-jp'>信頼</span> → <span class='gd-jp'>信頼に足る</span></span><span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に足る</span></span><br>Phần lớn đặt trước danh từ để bổ nghĩa, như 「<span class='gd-jp'>信頼に足る人物</span>」, cũng có thể đặt cuối câu làm kết luận.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>に足る</span>Đánh giá một cách trang trọng rằng người, tài liệu, lý do, kết quả “đủ tư cách, đạt tiêu chuẩn”. Thường đi với các động từ mang tính “đánh giá” như <span class='gd-jp'>信頼する・尊敬する・満足する・納得する・信じる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は尊敬に足る先輩だ。</span>（Chị ấy là một đàn chị đáng kính trọng）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、納得するに足るものだった。</span>（Lời giải thích của anh ấy đủ để thuyết phục người nghe）</div><div class='gd-ex-line'>・<span class='gd-jp'>この報告書には、信頼に足るデータがない。</span>（Trong báo cáo này không có số liệu nào đáng tin cậy）</div><div class='gd-sec'><span class='gd-tag'>に足りない</span>Nói rằng việc nào đó hoàn toàn không quan trọng, không cần sợ. Phần lớn chỉ dùng trong vài cách nói cố định, <span class='gd-jp'>に足らない</span> cũng hay gặp, nghĩa giống nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなのは取るに足りない問題だ。</span>（Đó chỉ là vấn đề nhỏ không đáng nhắc đến）</div><div class='gd-ex-line'>・<span class='gd-jp'>相手は新人ばかりだ。恐れるに足りない。</span>（Đối thủ toàn là người mới, không đáng sợ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>取るに足りない</span> không có nghĩa là “không đủ để lấy”, mà là cả cụm cần học thuộc với nghĩa “nhỏ nhặt, không đáng kể”. Nó khác hẳn với “không đủ” trong <span class='gd-jp'>お金が足りない</span> (không đủ tiền).<br>・Phía trước chỉ nối được với <b>thể từ điển</b> hoặc “danh từ của động từ する”, không nối với thể た hay thể ます: <span class='gd-jp'>信頼したに足る</span> là sai. Cũng không nối tùy tiện với danh từ thông thường, ví dụ <span class='gd-jp'>彼に足る</span> là không thông.<br>・Dạng phủ định <span class='gd-jp'>に足りない</span> chủ yếu dùng trong các cách nói cố định như <span class='gd-jp'>取るに足りない</span>, <span class='gd-jp'>恐れるに足りない</span>. Muốn nói “không đáng tin” nói chung thì dùng <span class='gd-jp'>信頼できない</span> hoặc <span class='gd-jp'>信頼に値しない</span> sẽ tự nhiên hơn.<br>・Đây là văn viết. Khi trò chuyện với bạn bè và muốn nói “người đó rất đáng tin”, chỉ cần nói <span class='gd-jp'>あの人は信頼できる</span>; dùng に足る nghe sẽ giống đang đọc công văn.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'>Cùng là đánh giá một cuốn sách:<br><b>に足る</b>＝đủ tư cách, đạt tiêu chuẩn: <span class='gd-jp'>これは読むに足る本だ。</span>（Đây là cuốn sách đáng đọc）<br><b>に値する</b>＝có giá trị đó, nghĩa rất gần, nhiều khi dùng thay nhau được. Điểm khác là dạng phủ định <span class='gd-jp'>に値しない</span> có thể dùng thoải mái: <span class='gd-jp'>この本は一読に値しない。</span>（Cuốn sách này không đáng đọc một lần）<br><b>に堪えない</b>（n1-36）＝tệ đến mức <b>không chịu nổi</b>, mang cảm xúc mạnh: <span class='gd-jp'>読むに堪えない文章だ。</span>（Đó là bài viết tệ đến mức không đọc nổi）<br>Vì vậy 「<span class='gd-jp'>取るに足りない</span>」 là “không quan trọng, không cần bận tâm”, còn 「<span class='gd-jp'>見るに堪えない</span>」 là “quá tệ, không xem nổi”, hai cái hướng nghĩa hoàn toàn khác nhau.</div><div class='gd-warn'>Mẹo nhỏ để chọn: “đủ để ～ / không đáng nhắc đến” dùng に足る・に足りない; muốn thoải mái nói “không đáng ～” thì dùng に値しない; “tệ đến mức không chịu nổi” dùng に堪えない.</div>","n1-19":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に至るまで」nghĩa là <b>「từ ～ đến tận ～」「từ lớn đến nhỏ, tất cả đều ～」</b>. Ví dụ \"từ sếp đến nhân viên part-time, ai cũng tham gia\". Trọng tâm không nằm ở chuyện \"dừng ở đâu\", mà là nhấn mạnh <b>ngay cả nơi xa như vậy, chi tiết nhỏ như vậy cũng nằm trong phạm vi</b>, tức là phạm vi rất rộng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋に至るまで, hay đi cùng 「から」 nhất:<br><b>Aから Bに至るまで</b>＝từ A cho đến tận B (cũng đều...)<br><span class='gd-pair'><span class='gd-jp'>子供から高齢者</span> → <span class='gd-jp'>子供から高齢者に至るまで</span></span> (từ trẻ em đến người cao tuổi)<br>B thường là <b>đầu bên kia</b> của phạm vi, và hay là đầu mà bạn không ngờ cũng được tính vào. Phía sau thường có các từ mang nghĩa \"tất cả\" như <span class='gd-jp'>全員</span>, <span class='gd-jp'>すべて</span>, <span class='gd-jp'>誰もが</span>, <span class='gd-jp'>細かく</span>.</div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Phạm vi con người</span>Từ trên xuống dưới, từ già đến trẻ, bao gồm tất cả mọi người.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長から新入社員に至るまで、全員が会議に参加した。</span> (Từ giám đốc đến nhân viên mới, tất cả mọi người đều tham dự cuộc họp)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供から高齢者に至るまで、誰もが楽しめるイベントだ。</span> (Đây là sự kiện mà từ trẻ em đến người cao tuổi, ai cũng có thể vui chơi)</div><div class='gd-sec'><span class='gd-tag'>Phạm vi chi tiết</span>Từ hướng lớn đến chi tiết nhỏ, đều được lo hết.</div><div class='gd-ex-line'>・<span class='gd-jp'>服装から髪型に至るまで、細かく決められている。</span> (Từ trang phục đến kiểu tóc, đều có quy định chi tiết)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋の隅々に至るまで、きれいに掃除した。</span> (Dọn sạch sẽ đến từng ngóc ngách trong phòng)</div><div class='gd-sec'><span class='gd-tag'>Phạm vi thời gian</span>Từ rất lâu về trước kéo dài đến hiện tại, nhấn mạnh quãng thời gian dài.</div><div class='gd-ex-line'>・<span class='gd-jp'>創業から現在に至るまで、この味を守り続けている。</span> (Từ lúc thành lập đến nay, vẫn luôn giữ gìn hương vị này)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ \"đến\" trong tiếng Việt dễ khiến bạn nghĩ cấu trúc này <b>vạch ranh giới, đặt giới hạn</b>, nhưng thật ra ngược lại: nó không phải \"chỉ tới đây thôi\" mà là \"<b>ngay cả chỗ này cũng bao gồm</b>\", trọng tâm là phạm vi rộng.<br>・A và B phải là hai đầu của <b>cùng một loại</b>: người với người, vật với vật, thời gian với thời gian.<br>・Với điểm cuối bình thường như \"đợi đến mấy giờ\", \"đi bộ đến ga\" thì dùng <span class='gd-jp'>まで</span> là đủ, dùng に至るまで sẽ nghe rất lạ.<br>・Đây là cách nói <b>trang trọng, văn viết</b>, hay xuất hiện trong tin tức, thông báo, giới thiệu công ty. Khi nói chuyện với bạn bè, chỉ cần nói <span class='gd-jp'>おじいちゃんまでみんなスマホ持ってるよ</span> (đến ông cũng có điện thoại luôn đó) là đủ.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là 「至る」, ở N1 có ba mẫu rất dễ lẫn. Hãy so sánh trong cùng một tình huống \"gia đình và điện thoại thông minh\":<br><b>に至るまで</b>＝phạm vi rất rộng, <b>bao gồm tất cả</b>:<br><span class='gd-jp'>祖父母から孫に至るまで、家族全員がスマホを持っている。</span> (Từ ông bà đến cháu, cả nhà ai cũng có điện thoại thông minh)<br><b>に至っては</b>＝<b>chọn ra trường hợp quá đáng nhất</b> trong cả nhóm để nói, phần nhiều mang chút chê trách:<br><span class='gd-jp'>うちの家族は機械に弱い。祖母に至っては、電話のかけ方も知らない。</span> (Nhà mình ai cũng kém khoản máy móc. Còn bà thì đến cách gọi điện cũng không biết)<br><b>に至る</b>＝sự việc phát triển từng bước, <b>cuối cùng đi đến một kết quả</b>:<br><span class='gd-jp'>何度も話し合って、ようやく祖母もスマホを買うに至った。</span> (Bàn bạc nhiều lần, cuối cùng bà cũng đã mua điện thoại thông minh)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"từ ～ đến ～, tất cả đều\" thì dùng に至るまで; muốn nói \"trong số đó, quá đáng nhất là ～\" thì dùng に至っては; muốn nói \"cuối cùng dẫn đến ～\" thì dùng に至る。</div>","n1-20":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を経て」nghĩa là <b>「trải qua ～」「qua ～」「thông qua ～」</b>. Trọng tâm là ở giữa có <b>một quá trình, một giai đoạn đã đi qua, hoặc đi ngang qua một nơi nào đó</b>, rồi mới đến kết quả phía sau. Giọng văn trang trọng, rất hay gặp trong tin tức, báo cáo, tiểu sử, bài diễn thuyết; nói chuyện với bạn bè thì ít dùng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋を経て　<span class='gd-pair'><span class='gd-jp'>長い議論</span> → <span class='gd-jp'>長い議論を経て</span> (sau cuộc thảo luận dài)</span><br>Phía trước chỉ nối với <b>danh từ</b>, không nối trực tiếp với động từ. Muốn nói việc \"chuẩn bị\" thì viết <span class='gd-jp'>準備を経て</span>, không viết 「準備するを経て」.<br>「経て」đọc là <b>へて</b>, dạng gốc là <span class='gd-jp'>経る</span> (へる), nghĩa là \"trải qua\".</div><div class='gd-sec'>Khi phía sau cần nối danh từ, đổi thành <b>を経た＋danh từ</b>:<br><span class='gd-pair'><span class='gd-jp'>厳しい訓練</span> → <span class='gd-jp'>厳しい訓練を経た選手</span> (vận động viên đã trải qua huấn luyện khắc nghiệt)</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trải qua một quá trình</span>Những việc tốn thời gian, công sức như thảo luận, thẩm định, đàm phán, chuẩn bị, làm xong rồi mới có kết quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い議論を経て、ようやく結論が出た。</span> (Sau cuộc thảo luận dài, cuối cùng cũng có kết luận)</div><div class='gd-ex-line'>・<span class='gd-jp'>厳しい審査を経て、新しい薬が発売された。</span> (Sau khi trải qua thẩm định nghiêm ngặt, loại thuốc mới đã được tung ra thị trường)</div><div class='gd-sec'><span class='gd-tag'>Trải qua một khoảng thời gian</span>Hay đi cùng 「歳月」「年月」, mang cảm giác \"trải qua bao nhiêu năm\".</div><div class='gd-ex-line'>・<span class='gd-jp'>10年の歳月を経て、橋が完成した。</span> (Sau mười năm ròng, cây cầu đã hoàn thành)</div><div class='gd-sec'><span class='gd-tag'>Từng trải qua một vai trò</span>Rất hay gặp trong tiểu sử, kể một người đã đi qua những giai đoạn nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社員を経て、作家になった。</span> (Anh ấy từng là nhân viên công ty, rồi trở thành nhà văn)</div><div class='gd-sec'><span class='gd-tag'>Đi qua một địa điểm</span>Nơi đi ngang qua giữa lộ trình di chuyển.</div><div class='gd-ex-line'>・<span class='gd-jp'>香港を経て、日本に着いた。</span> (Qua Hồng Kông, đã đến Nhật Bản)</div><div class='gd-ex-line'>・<span class='gd-jp'>台北から台中を経て、高雄へ向かう。</span> (Từ Đài Bắc qua Đài Trung, đi đến Cao Hùng)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「経て」đọc là <b>へて</b>, không phải けいて, cũng không phải たって.<br>・Cùng chữ 「経」 còn có <span class='gd-jp'>経つ</span> (たつ), nghĩa là \"thời gian trôi qua\": <span class='gd-jp'>3年経って</span> đọc là さんねんたって, là cách nói khẩu ngữ thông thường cho \"đã ba năm trôi qua\". Hai cái nhìn rất giống nhau, nhưng cách đọc và sắc thái đều khác.<br>・Đây là cách nói trang trọng. Khi nói với bạn bè \"quá cảnh qua Hồng Kông\", dùng <span class='gd-jp'>香港経由で</span> hoặc <span class='gd-jp'>香港で乗り換えて</span> sẽ tự nhiên hơn; dùng 「を経て」 cho chuyện nhỏ hằng ngày nghe như đang đọc bản tin.<br>・Phía trước phải là <b>quá trình đáng nhắc đến</b>. Những việc nhỏ như ăn cơm, tắm rửa thì chỉ cần dùng 「〜てから」, không dùng 「を経て」.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>を経て vs 経って</b>: đều có thể nói \"đã qua một khoảng thời gian\".<br><span class='gd-jp'>3年経って、やっと仕事に慣れた。</span> (Ba năm trôi qua, cuối cùng cũng quen công việc): khẩu ngữ, sau từ chỉ thời gian nối thẳng 「経って」, không thêm を.<br><span class='gd-jp'>3年の歳月を経て、作品が完成した。</span> (Sau ba năm ròng, tác phẩm đã hoàn thành): trang trọng, phần nhiều gợi cảm giác \"bỏ ra rất nhiều công sức mới có thành quả\".</div><div class='gd-sec'><b>を経て vs に至る</b>: thường xuất hiện cùng nhau, nhưng vị trí khác nhau.<br><span class='gd-jp'>何度もの交渉を経て、合意に至った。</span> (Sau nhiều lần đàm phán, cuối cùng đã đạt được thỏa thuận)<br>「を経て」nói về <b>con đường đã đi qua ở giữa</b>, 「に至る」nói về <b>điểm đến cuối cùng</b>.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói ở giữa đã trải qua những gì thì dùng 「を経て」; muốn nói cuối cùng đi đến đâu thì dùng 「に至る」; chỉ là buột miệng nói \"mấy năm trôi qua\" thì dùng 「経って」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>〜に至る</span> và <span class='gd-jp'>〜に至るまで</span> cùng cấp độ có thể nhớ chung với 「を経て」, rất hữu ích khi viết bài về \"từ quá trình đến kết quả\".</div>","n1-93":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たが最後」nghĩa là <b>「một khi đã ... là coi như xong」「dính vào là không quay đầu được」</b>. Chỉ cần làm việc ở vế trước, vế sau chắc chắn sẽ thành một tình huống tệ, không cứu vãn được hoặc không dừng lại được. Giống như câu 「Mở gói snack khoai tây là xong, thế nào cũng ăn sạch cả gói」, đúng cái cảm giác đó.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chia động từ sang thể た (dạng quá khứ「〜た」), rồi thêm trực tiếp「が最後」.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝た</span> → <span class='gd-jp'>寝たが最後</span></span><br><span class='gd-pair'><span class='gd-jp'>見つかる</span> → <span class='gd-jp'>見つかった</span> → <span class='gd-jp'>見つかったが最後</span></span><br>「最後」đọc là <b>さいご</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nói về thói quen của ai đó</span>Người nào đó hễ làm việc gì thì chắc chắn sẽ thành ra thế nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一度寝たが最後、朝まで何をしても起きない。</span>(Anh ấy mà đã ngủ là coi như xong, làm gì cũng không dậy cho đến sáng)</div><div class='gd-sec'><span class='gd-tag'>Không dừng lại được</span>Đã bắt đầu là không thể dừng tay.</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは見始めたが最後、止まらなくなる。</span>(Bộ phim này đã xem là không dừng lại được)</div><div class='gd-sec'><span class='gd-tag'>Cảnh báo hậu quả</span>Nhắc rằng「tuyệt đối đừng làm vậy, không thì hậu quả rất thảm」.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長に見つかったが最後、一時間は説教される。</span>(Bị trưởng phòng phát hiện là coi như xong, ít nhất cũng bị giảng đạo một tiếng)</div><div class='gd-sec'>Khi nói chuyện, người ta hay đổi thành <b>「〜たら最後」</b>, nghĩa giống hệt nhưng khẩu ngữ hơn:</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと言ったら最後、絶交されるよ。</span>(Đã lỡ nói câu đó ra là coi như xong, sẽ bị cắt đứt quan hệ đấy)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau <b>chỉ được là kết quả xấu</b>. Chuyện tốt như 「trúng số là có cuộc sống sung sướng」 thì không dùng được が最後.<br>・Vế trước luôn là thể た, kể cả khi nói về chuyện chưa xảy ra. Không thể nói「食べるが最後」.<br>・「最後」ở đây không phải nghĩa 「cuối cùng, rốt cuộc」 như trong tiếng Việt, mà có nghĩa 「đến đây là hết, xong đời」. Đừng dịch thành kiểu 「sau khi ăn thì cuối cùng...」.<br>・Vế sau thường là mô tả hoặc nhận định kiểu 「chắc chắn sẽ như vậy」, rất ít khi đi với lời yêu cầu như「請～」hay quyết tâm như「我要～」.<br>・Vế sau hay đi cùng những cách nói kiểu 「không quay lại được」 như <span class='gd-jp'>二度と〜ない</span>、<span class='gd-jp'>止まらない</span>、<span class='gd-jp'>終わりだ</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>〜が早いか</b>: cũng hay được dịch là 「vừa ... là liền」, nhưng nó chỉ nói <b>thời gian rất nhanh</b>, không phân biệt tốt xấu.<br>・<span class='gd-jp'>彼は布団に入るが早いか、眠ってしまった。</span>(Anh ấy vừa chui vào chăn là ngủ ngay)<br>・<span class='gd-jp'>彼は布団に入ったが最後、昼まで出てこない。</span>(Anh ấy đã chui vào chăn là coi như xong, đến trưa cũng không chịu ra)<br>Câu trước nhấn mạnh 「tốc độ nhanh」, câu sau nhấn mạnh 「từ đó không cứu vãn được nữa」.</div><div class='gd-sec'><b>〜たところで</b>: cũng nối sau thể た, nhưng nghĩa là <b>「có làm cũng vô ích」</b>.<br>・<span class='gd-jp'>彼に話したが最後、みんなに知られてしまう。</span>(Đã nói với anh ấy là coi như xong, mọi người sẽ biết hết)<br>・<span class='gd-jp'>今さら彼に話したところで、何も変わらない。</span>(Bây giờ mới nói với anh ấy thì cũng chẳng thay đổi được gì)</div><div class='gd-warn'>Mẹo phân biệt: 「làm rồi là không quay đầu được, hậu quả rất thảm」 là が最後; 「vừa ... là liền」 là が早いか; 「có làm cũng vô ích」 là たところで.</div>","n1-18":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に至る」giống như cách nói hay gặp trên báo chí: <b>「diễn biến thành ~」「cuối cùng đi đến bước ~」</b>. Sự việc trải qua một thời gian, một chuỗi diễn biến, rồi đến một kết quả nào đó. Kết quả này thường là việc có trọng lượng, ví dụ kiện tụng, phá sản, hòa giải, đưa ra kết luận. Mẫu này rất văn viết, rất trang trọng, hay xuất hiện nhất trong tin tức, báo cáo, họp báo và thông báo của công ty.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: thêm thẳng に至る, ở giữa không thêm の.<br><span class='gd-pair'><span class='gd-jp'>訴訟</span> → <span class='gd-jp'>訴訟に至る</span></span><span class='gd-pair'><span class='gd-jp'>和解</span> → <span class='gd-jp'>和解に至る</span></span><br><b>Động từ</b>: dùng thể từ điển (dạng gốc ghi trong từ điển) rồi thêm に至る.<br><span class='gd-pair'><span class='gd-jp'>中止する</span> → <span class='gd-jp'>中止するに至る</span></span><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えるに至る</span></span></div><div class='gd-sec'>Bản thân <span class='gd-jp'>至る</span> là <b>động từ nhóm 1 (động từ ngũ đoạn)</b>, chia giống <span class='gd-jp'>帰る</span>:<br><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至った</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至っていない</span></span><span class='gd-pair'><span class='gd-jp'>至る</span> → <span class='gd-jp'>至らなかった</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Cuối cùng đi đến một kết quả</span>Hay dùng nhất là thì quá khứ「〜に至った」, phía trước thường có <span class='gd-jp'>ついに</span>、<span class='gd-jp'>〜の末</span>、<span class='gd-jp'>〜結果</span> để cho biết đã trải qua một quá trình.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、両社は合併に至った。</span>(Sau thời gian thương lượng dài, cuối cùng hai công ty đã đi đến quyết định sáp nhập)</div><div class='gd-ex-line'>・<span class='gd-jp'>留学を通して、日本で働きたいと考えるに至った。</span>(Qua việc du học, dần dần mình có suy nghĩ muốn làm việc ở Nhật)</div><div class='gd-sec'><span class='gd-tag'>Chưa đến bước đó</span>Phủ định thường viết là「〜には至っていない」, nói rằng sự việc vẫn chưa phát triển đến giai đoạn đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>この技術は、まだ実用化には至っていない。</span>(Công nghệ này vẫn chưa đến giai đoạn ứng dụng thực tế)</div><div class='gd-sec'><span class='gd-tag'>Cách nói cố định</span>Ba câu dưới đây rất thường gặp, bạn có thể học thuộc cả câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>幸い、大事には至らなかった。</span>(May mà không gây ra chuyện lớn)</div><div class='gd-ex-line'>・<span class='gd-jp'>中止に至った経緯をご説明します。</span>(Xin giải thích đầu đuôi việc đi đến quyết định hủy)</div><div class='gd-ex-line'>・<span class='gd-jp'>1990年に創業し、現在に至る。</span>(Thành lập năm 1990 và hoạt động cho đến nay)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ phải dùng thể từ điển, đừng dùng thể た: đúng là <span class='gd-jp'>中止するに至った</span>, không phải「中止したに至った」. Nghĩa quá khứ chỉ cần đặt ở <span class='gd-jp'>至った</span> là đủ.<br>・Mẫu này rất văn viết. Khi trò chuyện với bạn bè và muốn nói 「cuối cùng tụi mình chia tay rồi」, chỉ cần nói <span class='gd-jp'>結局別れることになった</span>. Nói thành「別れるに至った」nghe như đang đọc thông cáo báo chí.<br>・Kết quả phải có trọng lượng, và phía trước thường là cả một quá trình. Chuyện nhỏ như đói bụng đi mua bánh mì thì không dùng được「パンを買うに至った」.<br>・Dù nghĩa chữ là 「đến」, nhưng trong đời thường, khi nói 「đến một nơi nào đó」 thì phải dùng <span class='gd-jp'>着く</span>.<br>・Khi <span class='gd-jp'>至らない</span> dùng đứng riêng, thường mang nghĩa khác là 「chưa chu đáo」: <span class='gd-jp'>至らない点もありますが、よろしくお願いします。</span>(Có thể còn chỗ chưa chu đáo, mong bạn giúp đỡ nhiều)</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>N1 có ba mẫu trong họ「至る」trông rất giống nhau. Hãy so sánh trong cùng một tình huống 「công ty đang rất tệ」:<br><b>に至る</b> = sự việc <b>cuối cùng diễn biến thành</b> một kết quả nào đó:<br><span class='gd-jp'>赤字が続き、ついに倒産に至った。</span>(Thua lỗ liên tục, cuối cùng đi đến phá sản)<br><b>に至るまで</b> = nói về phạm vi, <b>từ A cho đến tận B, ngay cả B cũng</b>:<br><span class='gd-jp'>社長から新入社員に至るまで、全員が毎日残業している。</span>(Từ giám đốc cho đến nhân viên mới, tất cả mọi người ngày nào cũng tăng ca)<br><b>に至っては</b> = <b>còn về B thì càng quá đáng</b>, nêu ra ví dụ cực đoan nhất:<br><span class='gd-jp'>どの部署も業績が悪いが、営業部に至っては目標の半分にも届いていない。</span>(Phòng ban nào cũng làm ăn tệ, riêng phòng kinh doanh còn tệ hơn, ngay cả một nửa chỉ tiêu cũng không đạt)</div><div class='gd-warn'>Mẹo phân biệt: đặt ở cuối câu để nói 「cuối cùng thành ra thế nào」 là に至る; phía trước có 「từ A đến B」, đang nói về phạm vi là に至るまで; đặt giữa câu làm chủ đề, dẫn ra 「trường hợp còn quá đáng hơn」 là に至っては.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể học tiếp <span class='gd-jp'>〜に至るまで</span> và <span class='gd-jp'>〜に至っては</span>, nhớ cả ba mẫu cùng lúc thì sẽ ít bị lẫn nhất. Bạn cũng có thể học <span class='gd-jp'>〜を経て</span> (trải qua ~), mẫu này hay xuất hiện cùng に至る: <span class='gd-jp'>何度もの議論を経て、合意に至った。</span>(Sau nhiều lần thảo luận, cuối cùng đã đạt được đồng thuận)</div>","n1-38":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に難くない」 tương đương với <b>“không khó để tưởng tượng”, “không khó hiểu”, “có thể đoán được”</b> trong tiếng Việt. Cách dùng là từ một chút manh mối, bạn có thể suy ra tình huống hay tâm trạng đằng sau. Cách đọc là <b>かたくない</b>, thiên về văn viết, trang trọng, rất hay gặp trong tin tức, bài bình luận và bài viết.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước hầu như luôn là những từ mang nghĩa “suy nghĩ trong đầu”, chỉ có vài từ cố định, nên học thuộc cả cụm là nhanh nhất:<br><span class='gd-jp'>想像に難くない</span>（không khó tưởng tượng）<br><span class='gd-jp'>理解に難くない</span>（không khó hiểu）<br><span class='gd-jp'>予想に難くない</span>（không khó dự đoán）<br><span class='gd-jp'>推測に難くない</span>（không khó suy đoán）<br><span class='gd-jp'>察するに難くない</span>（không khó nhận ra, đoán ra）<br>Những từ như 想像、理解 thường là danh từ nối thẳng với 「に」. <span class='gd-jp'>察する</span> bản thân là động từ nên dùng thể nguyên dạng (thể từ điển) để nối.</div><div class='gd-sec'>Nội dung bạn suy ra được đặt ở phía trước, thường có ba dạng: 「〜は」「〜ことは」「〜のは」.</div><div class='gd-ex-line'>・<span class='gd-jp'>親を亡くした彼の悲しみは想像に難くない。</span>（Nỗi buồn của anh ấy khi mất cha mẹ thì không khó để tưởng tượng）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画に反対の声が上がることは予想に難くない。</span>（Không khó để đoán trước là kế hoạch này sẽ vấp phải làn sóng phản đối）</div><div class='gd-ex-line'>・<span class='gd-jp'>物価がこれだけ上がれば、生活が苦しくなるのは想像に難くない。</span>（Giá cả tăng đến mức này thì cuộc sống trở nên khó khăn là điều dễ hiểu）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の表情から、何があったかは察するに難くない。</span>（Nhìn vẻ mặt cô ấy thì không khó để đoán ra đã xảy ra chuyện gì）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・「難くない」 đọc là <b>かたくない</b>, đừng đọc thành むずかしくない.<br>・Mẫu này nói rằng “<b>suy đoán</b> trong đầu không khó”, chứ không phải “<b>làm</b> thì dễ”. Muốn nói “bài này dễ giải” thì phải nói <span class='gd-jp'>この問題は簡単だ</span>, không dùng に難くない.<br>・Đừng ghép bừa động từ ở phía trước, chỉ cần dùng 想像、理解、予想、推測、察する là đủ.<br>・Mẫu này rất cứng, giao tiếp hằng ngày không ai nói vậy. Nói với bạn bè kiểu “cũng dễ hiểu thôi” thì dùng <span class='gd-jp'>想像できる</span> hoặc <span class='gd-jp'>想像がつく</span> mới tự nhiên.<br>・Thấy 「ない」 đừng vội nghĩ là phủ định. 「難くない」＝không khó＝<b>rất dễ</b>, cả câu mang sắc thái khẳng định.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>N1 có khá nhiều mẫu câu dạng 「〜に＋phủ định」 nhìn rất giống nhau nhưng nghĩa lại khác xa. Hãy so sánh trong cùng một tình huống: một người bạn bị công ty cho thôi việc.<br><b>に難くない</b>＝không khó để suy ra: <span class='gd-jp'>彼のショックは想像に難くない。</span>（Không khó để tưởng tượng anh ấy đã sốc đến mức nào）<br><b>には当たらない</b>＝không cần phản ứng như vậy: <span class='gd-jp'>この不景気だから、リストラされても驚くには当たらない。</span>（Kinh tế ảm đạm thế này thì bị cho thôi việc cũng không cần ngạc nhiên）<br><b>に堪えない</b>＝tệ đến mức không nhìn nổi, không nghe nổi: <span class='gd-jp'>会社の説明は聞くに堪えない言い訳ばかりだった。</span>（Lời giải thích của công ty toàn là những lời bao biện nghe không nổi）</div><div class='gd-warn'>Mẹo phân biệt nhanh: “có thể đoán được” là に難くない; “không cần phải ～” là には当たらない; “tệ đến mức không chịu nổi” là に堪えない.</div>","n1-37":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を禁じ得ない」 tương đương với <b>“không kìm được…”, “không khỏi cảm thấy…”</b> trong tiếng Việt. Khi nhìn thấy hay nghe thấy chuyện gì đó, những cảm xúc như thương cảm, ngạc nhiên, tức giận tự trào lên, muốn nén cũng không nén được. Mẫu này rất trang trọng, chủ yếu xuất hiện trong bình luận báo chí, bài viết, bài phát biểu, còn trò chuyện thường ngày hầu như không dùng.</div><div class='gd-h'>Tách ra là hiểu ngay</div><div class='gd-sec'><span class='gd-jp'>禁じる</span> nghĩa là “cấm”, <span class='gd-jp'>得ない</span> nghĩa là “không thể ～”. Ghép lại thành “muốn cấm cũng không cấm được”, tức là cảm xúc không ngăn nổi, tự trào ra.<br>Cách đọc là <b>きんじえない</b>, chữ 「得」 ở đây đọc là 「え」.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước đặt <b>danh từ chỉ cảm xúc</b>, rồi thêm 「を禁じ得ない」. Khi nói chuyện đã xảy ra trong quá khứ thì chuyển thành 「を禁じ得なかった」.<br><span class='gd-pair'><span class='gd-jp'>同情</span> → <span class='gd-jp'>同情を禁じ得ない</span></span>（không khỏi thương cảm）<br><span class='gd-pair'><span class='gd-jp'>驚き</span> → <span class='gd-jp'>驚きを禁じ得なかった</span></span>（lúc đó không khỏi kinh ngạc）<br>Các danh từ hay đi cùng: <span class='gd-jp'>同情</span>、<span class='gd-jp'>驚き</span>、<span class='gd-jp'>怒り</span>、<span class='gd-jp'>憤り</span>、<span class='gd-jp'>涙</span>、<span class='gd-jp'>戸惑い</span>、<span class='gd-jp'>疑問</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Bị một việc làm xúc động</span> Phía trước thường nói trước là “đã thấy gì, nghe gì, nghĩ đến gì”, rồi phía sau mới nói cảm xúc không kìm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>その知らせを聞いて、驚きを禁じ得なかった。</span>（Nghe tin đó, tôi không khỏi kinh ngạc）</div><div class='gd-ex-line'>・<span class='gd-jp'>被害者の話を聞き、涙を禁じ得なかった。</span>（Nghe người bị hại kể lại, tôi không cầm được nước mắt）</div><div class='gd-sec'><span class='gd-tag'>Bày tỏ quan điểm trang trọng</span> Trong bình luận, xã luận, mẫu này dùng để thể hiện quan điểm mạnh mẽ và rất hay gặp.</div><div class='gd-ex-line'>・<span class='gd-jp'>政府の対応には、怒りを禁じ得ない。</span>（Trước cách xử lý của chính phủ, tôi không khỏi phẫn nộ）</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には疑問を禁じ得ない。</span>（Đối với kế hoạch này, tôi không khỏi nghi ngờ）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>danh từ</b>, không đặt trực tiếp động từ: phải nói <span class='gd-jp'>涙を禁じ得ない</span>、<span class='gd-jp'>驚きを禁じ得ない</span>, không thể nói 「泣くを禁じ得ない」「驚くを禁じ得ない」.<br>・Mẫu này nói về cảm xúc <b>của chính mình</b> tự trào lên, không dùng để miêu tả tâm trạng của người khác.<br>・Giọng văn rất cứng. Nói chuyện với bạn bè mà dùng 「感動を禁じ得なかった」 thì nghe như đang đọc diễn văn, trong khẩu ngữ chỉ cần nói <span class='gd-jp'>思わず泣いちゃった</span>（tôi bật khóc lúc nào không hay）là đủ.<br>・「得ない」 đọc là <b>えない</b>, đừng đọc thành うない.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống: nghe câu chuyện của anh ấy và thấy rất thương cảm.<br><b>を禁じ得ない</b>＝cảm xúc <b>trào lên, không nén được</b>, rất trang trọng, phía trước là danh từ:<br><span class='gd-jp'>彼の話を聞いて、同情を禁じ得なかった。</span>（Nghe anh ấy kể, tôi không khỏi thương cảm）<br><b>ずにはいられない</b>（N2）＝“không thể không ～”, phía trước là động từ, cũng có thể nói về hành động, dùng phổ biến hơn và không cứng bằng:<br><span class='gd-jp'>彼の話を聞いて、同情せずにはいられなかった。</span>（Nghe anh ấy kể, tôi không thể không thương cảm）<br><span class='gd-jp'>あまりにおかしくて、笑わずにはいられなかった。</span>（Buồn cười quá, tôi không nhịn được cười）<br><b>に堪えない</b> khi đi với danh từ chỉ cảm xúc có nghĩa là “～ đến cực điểm, vô cùng ～”, hay gặp như <span class='gd-jp'>感謝に堪えない</span>（vô cùng biết ơn）、<span class='gd-jp'>遺憾に堪えない</span>、<span class='gd-jp'>同情に堪えない</span>、<span class='gd-jp'>憤慨に堪えない</span>, thường dùng trong lời phát biểu hoặc bài viết trang trọng. Sắc thái thiên về “cảm xúc mạnh đến mức không chịu nổi”:<br><span class='gd-jp'>被災された方々のことを思うと、同情に堪えない。</span>（Nghĩ đến những người bị thiên tai, tôi thật sự vô cùng thương cảm）<br>Ngoài ra, khi に堪えない đi với động từ thì mang nghĩa khác: <span class='gd-jp'>見るに堪えない</span> là “thảm đến mức không nhìn nổi”, không liên quan đến を禁じ得ない, đừng nhầm lẫn.</div><div class='gd-warn'>Mẹo phân biệt nhanh: cảm xúc “tự trào lên, không nén được” dùng を禁じ得ない; cảm xúc “mạnh đến mức không chịu nổi, ～ đến cực điểm” dùng に堪えない; nói chung “không nhịn được mà làm gì đó” dùng ずにはいられない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng nhóm ngữ pháp N1 diễn tả cảm xúc mạnh còn có <span class='gd-jp'>〜て止まない</span>（luôn ～ từ tận đáy lòng）, ví dụ <span class='gd-jp'>皆様のご健康を願って止みません。</span>（Xin chân thành chúc sức khỏe tất cả mọi người）, thường xuất hiện trong lời phát biểu và phần kết thư.</div>","n1-34":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜極まりない」giống kiểu nói <b>「~ hết sức」「~ vô cùng」「~ đến cực điểm」</b> trong tiếng Việt, ví dụ \"vô lễ hết sức\", \"nguy hiểm vô cùng\". Mẫu này dùng để <b>chê trách rất nặng</b> một việc nào đó, giọng cứng như trong tin tức, bình luận hay thư phản đối chính thức. 「〜極まる」có nghĩa y hệt, chỉ là mang màu sắc văn ngữ hơn một chút.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Phê phán gay gắt</span>Đưa ra nhận xét rất nặng về thái độ, hành vi của người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店員の対応は失礼極まりない。</span>（Cách ứng xử của nhân viên đó vô lễ hết sức）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に大声で騒ぐなんて、迷惑極まりない。</span>（Nửa đêm mà la hét ầm ĩ, đúng là phiền phức hết mức）</div><div class='gd-sec'><span class='gd-tag'>Mô tả tình huống rất tệ</span>Dùng trong tin tức, báo cáo khi nói về những việc nguy hiểm, rắc rối.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の夜に無灯火で走るのは危険極まりない。</span>（Đêm mưa mà chạy xe không bật đèn thì nguy hiểm vô cùng）</div><div class='gd-sec'><span class='gd-tag'>Đặt trước danh từ</span>Dùng trực tiếp để bổ nghĩa cho danh từ đứng sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>退屈極まりない会議が三時間も続いた。</span>（Cuộc họp chán không chịu nổi kéo dài tận ba tiếng）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Với tính từ đuôi な, bỏ 「な」 rồi nối thẳng vào:<br><span class='gd-pair'><span class='gd-jp'>失礼な</span> → <span class='gd-jp'>失礼極まりない</span></span><span class='gd-pair'><span class='gd-jp'>危険な</span> → <span class='gd-jp'>危険極まる</span></span><br>Những từ hay đi cùng nhất: <span class='gd-jp'>失礼、無礼、危険、迷惑、不快、不愉快、退屈、非常識、無責任</span>. Hầu hết là từ có từ hai chữ Hán trở lên và tự nó đã mang nghĩa tiêu cực.<br><br>Vì đuôi của 「極まりない」là 「ない」 nên bạn có thể chia quá khứ như tính từ đuôi い:<span class='gd-pair'><span class='gd-jp'>失礼極まりない</span> → <span class='gd-jp'>失礼極まりなかった</span></span><br>Tính từ đuôi い thì không nối trực tiếp được, phải thêm 「こと」 trước:<span class='gd-pair'><span class='gd-jp'>情けない</span> → <span class='gd-jp'>情けないこと極まりない</span></span>（đáng xấu hổ hết sức）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「ない」 trong 「極まりない」<b>không phải phủ định</b>. 「極まり」 là \"điểm tận cùng\", nên 「極まりない」 = \"không có điểm tận cùng\", tức là \"cực kỳ ~\". <span class='gd-jp'>失礼極まりない</span> nghĩa là \"vô lễ hết sức\", chứ không phải \"không vô lễ\".<br>・Đừng chèn な vào giữa: đúng là <span class='gd-jp'>失礼極まりない</span>, không phải 「失礼な極まりない」.<br>・Hầu như chỉ dùng cho chuyện xấu. Muốn khen món ăn ngon hay đồ dùng tốt thì hãy chọn cách nói khác, đừng gượng ép dùng mẫu này.<br>・Giọng rất nặng và rất cứng. Than phiền với bạn bè thì chỉ cần nói <span class='gd-jp'>本当に失礼だよね</span>; còn nói thẳng 「失礼極まりない」 vào mặt người ta thì coi như trở mặt chính thức.<br>・Cách đọc: 極まりない đọc là きわまりない, 極まる đọc là きわまる.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là chuyện bị nhân viên đối xử vô lễ:<br><b>極まりない</b>＝bình tĩnh đưa ra một <b>nhận xét</b> rất nặng: <span class='gd-jp'>あの店員の態度は失礼極まりない。</span>（Thái độ của nhân viên đó vô lễ hết sức）<br><b>といったらない</b>＝câu cảm thán, <b>cảm xúc tràn ra</b> hết cỡ, khẩu ngữ hơn, và tính từ đuôi い nối trực tiếp được: <span class='gd-jp'>あの店員の態度、腹が立つといったらない。</span>（Thái độ của nhân viên đó làm mình tức không chịu nổi）</div><div class='gd-sec'><b>の至り</b> cũng có nghĩa gần như \"~ vô cùng\", nhưng hướng ngược lại: nói về cảm xúc của <b>chính mình</b>, phần lớn là chuyện tốt như vinh dự, biết ơn, dùng trong lời phát biểu hay các dịp lịch sự.<br><span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>（Được nhận giải thưởng thế này, tôi vô cùng vinh dự）</div><div class='gd-warn'>Mẹo phân biệt nhanh: chê một việc xấu thì dùng 「極まりない」; lịch sự nói mình rất vinh dự, rất biết ơn thì dùng 「の至り」; còn cảm thán khi giận, xấu hổ hay vui đến mức cảm xúc bùng nổ thì dùng 「といったらない」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng một chữ Hán còn có hai cách nói thường gặp khác:<br>Danh từ＋の極み：<span class='gd-jp'>こんな料理を毎日食べるなんて、贅沢の極みだ。</span>（Ngày nào cũng ăn món thế này, đúng là xa xỉ hết mức）<br>Cách nói cố định 「感極まる」：<span class='gd-jp'>優勝が決まった瞬間、感極まって泣き出した。</span>（Khoảnh khắc xác định đã vô địch, cô ấy xúc động đến bật khóc）</div>","n1-52":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜まじき」nghĩa là <b>\"Đã là ~ mà sao lại làm thế được!\"</b>. Dùng để chê trách ai đó làm việc <b>không xứng với thân phận của mình</b>, kiểu như \"mất tư cách\", \"không xứng đáng\". Giọng rất nặng và trang trọng, phần lớn xuất hiện trong tin tức, bài xã luận, phát biểu chính thức.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ dạng từ điển (dạng gốc tra trong từ điển)＋まじき＋danh từ<br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまじき行為</span></span>（hành vi không được phép có）<br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許すまじき犯罪</span></span>（tội ác không thể tha thứ）<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うまじきこと</span></span>（điều không nên nói）<br>Với 「する」, ngoài <span class='gd-jp'>するまじき</span> bạn cũng sẽ gặp dạng cổ hơn là <span class='gd-jp'>すまじき</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Thân phận＋にあるまじき</span>Hơn chín phần mười là cụm cố định này: 「người hoặc thân phận＋に（hoặc として）＋あるまじき＋danh từ」, nghĩa là \"với thân phận này thì không được phép có ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にあるまじき行為だ。</span>（Đó là hành vi không thể có ở một bác sĩ）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロにあるまじきミスだ。</span>（Đây là lỗi mà dân chuyên nghiệp không được phép mắc）</div><div class='gd-ex-line'>・<span class='gd-jp'>社会人としてあるまじき態度だと叱られた。</span>（Tôi bị mắng là có thái độ không thể chấp nhận ở một người đi làm）</div><div class='gd-sec'><span class='gd-tag'>許すまじき</span>Không nhắc đến thân phận, nói thẳng rằng \"việc này tuyệt đối không thể tha thứ\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもを狙った許すまじき犯罪だ。</span>（Đây là tội ác nhắm vào trẻ em, không thể tha thứ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・まじき<b>phía sau nhất định phải có danh từ</b>, không thể kết thúc câu ngay:<br>　×<span class='gd-jp'>教師にあるまじきだ。</span><br>　○<span class='gd-jp'>教師にあるまじき発言だ。</span><br>・Nghĩa là「<b>không nên</b>」, không phải 「<b>không thể, không làm được</b>」. Đây là sự phê phán về đạo đức, không liên quan đến năng lực.<br>・Chữ 「許す」 trong 「許すまじき」 là <b>người ngoài</b> tha thứ hay không. Vì vậy 「政治家として許すまじき発言」 dễ bị hiểu thành \"chúng tôi, với tư cách chính trị gia, không thể tha thứ\". Muốn nói \"chính trị gia đó không được nói câu như vậy\" thì dùng <span class='gd-jp'>政治家としてあるまじき発言</span> là rõ nhất.<br>・Rất cứng, nói trong trò chuyện hằng ngày sẽ nghe lạ. Khẩu ngữ chỉ cần nói <span class='gd-jp'>先生なのに、ありえない。</span>（Là giáo viên mà vậy, thật quá đáng）là đủ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là chê một giáo viên phạt thể xác học sinh:<br><b>べきではない</b>＝\"không nên\" thông thường, dùng được ở mọi hoàn cảnh và đặt được ở cuối câu: <span class='gd-jp'>教師は体罰をするべきではない。</span>（Giáo viên không nên phạt thể xác học sinh）<br><b>まじき</b>＝cũng là \"không nên\" nhưng nặng hơn, mang tính văn viết hơn, và chỉ đặt được trước danh từ: <span class='gd-jp'>体罰は教師にあるまじき行為だ。</span>（Phạt thể xác là hành vi không thể có ở người làm giáo viên）<br><b>べからざる</b>＝trọng tâm là \"không được phép, không thể thiếu\", thường nói về quy tắc hoặc sự cần thiết, không nhất thiết liên quan đến thân phận: <span class='gd-jp'>水は生活に欠くべからざるものだ。</span>（Nước là thứ không thể thiếu trong cuộc sống）</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước có 「thân phận＋に／として」 và bạn đang chê ai đó không xứng với vai trò thì là まじき; nói về quy tắc hoặc \"không thể thiếu\" thì là べからざる.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜たる」＝là người như thế này (đã là ~), thường đi cùng nghĩa với まじき: <span class='gd-jp'>教師たる者、生徒の手本でなければならない。</span>（Đã là giáo viên thì phải làm tấm gương cho học sinh）</div>","n1-36":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に堪えない」có hai nghĩa gần như trái ngược nhau, nhưng tiếng Việt đều có cách nói tương ứng:<br>①<b>「không nỡ nhìn, không nỡ nghe」</b>: thứ gì đó tệ hoặc thảm đến mức không thể nhìn nổi, nghe nổi.<br>②<b>「vô cùng cảm kích, xiết bao cảm khái」</b>: cảm xúc trong lòng đầy đến mức không chứa hết, tức là「rất ～」.<br>Cả hai đều rất văn viết, rất trang trọng, hầu như không dùng khi trò chuyện hằng ngày.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>①<b>Động từ thể từ điển＋に堪えない</b>: phía trước hầu như chỉ đặt ba hành động「nhìn, nghe, đọc」.<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くに堪えない</span></span><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに堪えない</span></span><br>②<b>Danh từ chỉ cảm xúc＋に堪えない</b>: hay gặp nhất là các từ <span class='gd-jp'>感謝</span>、<span class='gd-jp'>感激</span>、<span class='gd-jp'>感慨</span>、<span class='gd-jp'>遺憾</span>、<span class='gd-jp'>痛恨</span>.<br><span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝に堪えません</span></span><span class='gd-pair'><span class='gd-jp'>遺憾</span> → <span class='gd-jp'>遺憾に堪えない</span></span><br>「堪えない」đọc là <b>たえない</b>, và cũng thường được viết thẳng bằng hiragana「たえない」.</div><div class='gd-h'>Cách dùng ①: tệ đến mức không nhìn nổi</div><div class='gd-sec'><span class='gd-tag'>Chê bai, phê phán</span>Dùng khi nội dung quá tệ, quá khó nghe, quá thảm, không đáng để xem, nghe, đọc. Phía sau thường nối thẳng danh từ, ví dụ「聞くに堪えない悪口」.</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くに堪えない悪口だった。</span>(Những lời nói xấu đó khó nghe đến mức không thể lọt tai)</div><div class='gd-ex-line'>・<span class='gd-jp'>この翻訳はひどくて、読むに堪えない。</span>(Bản dịch này dở đến mức không đọc nổi)</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の現場は見るに堪えない状態だった。</span>(Hiện trường vụ tai nạn thảm đến mức không nỡ nhìn)</div><div class='gd-h'>Cách dùng ②: cảm xúc đầy đến mức không chứa hết</div><div class='gd-sec'><span class='gd-tag'>Phát biểu trang trọng</span>Thường xuất hiện trong diễn văn, thư cảm ơn, thông cáo xin lỗi, điếu văn, nói về cảm xúc mãnh liệt của <b>chính mình</b>. Khi nói trực tiếp với người khác thì thường dùng「〜に堪えません」.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様の温かいご支援に、感謝の念に堪えません。</span>(Trước sự ủng hộ ấm áp của quý vị, chúng tôi vô cùng cảm kích)</div><div class='gd-ex-line'>・<span class='gd-jp'>このような事態となり、誠に遺憾に堪えません。</span>(Sự việc diễn biến đến mức này, chúng tôi vô cùng lấy làm tiếc)</div><div class='gd-ex-line'>・<span class='gd-jp'>二十年ぶりに母校を訪れ、感慨に堪えない。</span>(Hai mươi năm mới quay lại trường cũ, lòng xiết bao cảm khái)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・②<b>không mang nghĩa tiêu cực</b>. 「<span class='gd-jp'>感謝に堪えない</span>」không phải là「biết ơn đến phát chán, thấy phiền」, mà là「biết ơn đến mức lòng không chứa hết」, tương đương「vô cùng cảm ơn」.<br>・Không dùng để nói về sự chịu đựng của cơ thể. Muốn nói nóng không chịu nổi thì phải nói <span class='gd-jp'>暑くてたまらない</span> hoặc <span class='gd-jp'>暑さに耐えられない</span>, không thể nói 暑さに堪えない.<br>・①là chê bản thân thứ đó quá tệ hoặc quá thảm, không phải kiểu「tôi không có thời gian xem」「tôi không muốn xem」.<br>・②rất trang trọng, nói「感謝に堪えない」với bạn bè sẽ nghe như đang đọc diễn văn, bình thường chỉ cần nói <span class='gd-jp'>本当にありがとう</span> là đủ.<br>・②phía trước phải là danh từ cảm xúc gốc Hán như「感謝, 遺憾」, không thể nối thẳng với tính từ, ví dụ không thể nói 悲しいに堪えない.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là「một vụ tai nạn」, nhưng ba cách nói cho cảm giác khác nhau:<br><b>に堪えない</b>＝trong dịp trang trọng, bày tỏ cảm xúc <b>rất sâu sắc</b> của mình, giống thông cáo chính thức:<br><span class='gd-jp'>このような事故が起きたことは、誠に遺憾に堪えません。</span>(Việc xảy ra tai nạn như thế này, chúng tôi vô cùng lấy làm tiếc)<br><b>を禁じ得ない</b>＝một việc nào đó khiến cảm xúc <b>trào ra không kìm được</b>, trọng tâm là「không kiềm chế nổi」:<br><span class='gd-jp'>遺族の話を聞いて、涙を禁じ得なかった。</span>(Nghe thân nhân người mất kể, tôi không cầm được nước mắt)<br><b>てたまらない</b>＝cách nói khẩu ngữ kiểu「～không chịu nổi / ～kinh khủng」, nói về cảm giác cá nhân hoặc cảm giác của cơ thể:<br><span class='gd-jp'>あの映像を思い出すと、つらくてたまらない。</span>(Cứ nhớ lại hình ảnh đó là tôi đau khổ không chịu nổi)</div><div class='gd-warn'>Mẹo phân biệt nhanh: phát biểu thông cáo, diễn văn nói「vô cùng ～」thì dùng に堪えない; 「không nhịn được ～」thì dùng を禁じ得ない; nói với bạn bè kiểu「～chết đi được」thì dùng てたまらない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi sang dạng khẳng định「〜に堪える」thì nghĩa trở thành「chịu được ～, xứng đáng ～」: <span class='gd-jp'>大人の鑑賞に堪える作品だ。</span>(Đây là tác phẩm xứng đáng để người lớn thưởng thức). Mẫu「〜に足る」có nghĩa gần giống, bạn học cùng luôn nhé.</div>","n1-39":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てやまない」tương đương <b>「tha thiết ～」「～ khôn nguôi」</b> trong tiếng Việt. <span class='gd-jp'>やむ</span> nghĩa là「dừng lại」, như <span class='gd-jp'>雨がやむ</span> (mưa tạnh). Vì vậy <span class='gd-jp'>願ってやまない</span> dịch sát là「mong ước không ngừng lại được」, tức là một tình cảm sâu đậm, mãnh liệt luôn được giữ trong lòng. Đây là cách nói văn viết, trang trọng, thường gặp trong diễn văn, lời chúc, bài viết.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ thể て＋やまない. Thường viết bằng hiragana <span class='gd-jp'>やまない</span>, ít khi viết bằng kanji.<br><span class='gd-pair'><span class='gd-jp'>願う</span> → <span class='gd-jp'>願って</span> → <span class='gd-jp'>願ってやまない</span></span><br><span class='gd-pair'><span class='gd-jp'>期待する</span> → <span class='gd-jp'>期待して</span> → <span class='gd-jp'>期待してやまない</span></span><br>Khi nói trang trọng với người khác thì dùng thể lịch sự <span class='gd-jp'>やみません</span>; nói chuyện đã qua thì dùng <span class='gd-jp'>やまなかった</span>.<br>Phía trước hầu như luôn là động từ diễn tả tâm trạng: <span class='gd-jp'>願う</span>、<span class='gd-jp'>祈る</span>、<span class='gd-jp'>望む</span>、<span class='gd-jp'>期待する</span>、<span class='gd-jp'>愛する</span>、<span class='gd-jp'>尊敬する</span>、<span class='gd-jp'>信じる</span>、<span class='gd-jp'>憧れる</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Diễn văn・lời chúc</span>Chúc phúc người khác, đây là cách dùng điển hình nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご健康を祈ってやみません。</span>(Xin chân thành chúc sức khỏe tất cả quý vị)</div><div class='gd-sec'><span class='gd-tag'>Niềm tin của bản thân</span>Viết bài để bày tỏ suy nghĩ đã giữ từ lâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は彼の才能を信じてやまない。</span>(Tôi luôn tin tưởng tài năng của anh ấy)</div><div class='gd-sec'><span class='gd-tag'>Khiến người ta say mê</span>Chủ ngữ là sự vật, cho thấy nó luôn thu hút con người sâu sắc.</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の景色は、今も多くの人を魅了してやまない。</span>(Phong cảnh của thị trấn này đến nay vẫn khiến nhiều người say mê không thôi)</div><div class='gd-sec'><span class='gd-tag'>Bổ nghĩa cho danh từ</span>Khi nói về tình cảm của người khác, thường đặt trước danh từ như một định ngữ.</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父が愛してやまなかった海</span>(Biển cả mà ông nội yêu thương suốt cuộc đời)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Dù nghĩa gốc là「không ngừng」, mẫu này <b>không</b> dùng để nói hành động cứ tiếp diễn. <span class='gd-jp'>雨が降ってやまない</span> và <span class='gd-jp'>走ってやまない</span> đều sai; mưa cứ rơi mãi thì nói thẳng <span class='gd-jp'>雨がやまない</span>. Mẫu này chỉ dùng cho <b>tâm trạng, mong ước</b>.<br>・Chỉ nối với động từ, không nối với tính từ. 「Vui không chịu nổi」không thể nói 嬉しくてやまない, mà phải nói <span class='gd-jp'>嬉しくてたまらない</span>.<br>・Đây là cách nói rất trang trọng, nếu nói <span class='gd-jp'>君を愛してやまない</span> khi trò chuyện với bạn bè thì nghe như đang đọc kịch bản.<br>・Khi nói trang trọng với người khác, dùng <span class='gd-jp'>願ってやみません</span>, đừng nói thành 願ってやまないです.<br>・Khi đặt ở cuối câu, chủ ngữ thường là「tôi」. Nói về tình cảm của người khác thì phần lớn gặp trong văn viết, hoặc đặt trước danh từ như ví dụ trên.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng nói về「quê hương」, nhưng ba loại tình cảm khác nhau:<br><b>てやまない</b>＝tình cảm sâu đậm giữ trong lòng từ lâu, văn viết: <span class='gd-jp'>故郷を愛してやまない。</span>(Yêu quê hương tha thiết)<br><b>てたまらない</b>(N2)＝cảm giác ngay lúc này mạnh đến mức không chịu nổi, khẩu ngữ cũng dùng được: <span class='gd-jp'>故郷に帰りたくてたまらない。</span>(Muốn về quê quá, nhớ không chịu nổi)<br><b>を禁じ得ない</b>＝thấy một việc nào đó mà cảm xúc trào lên không kìm được: <span class='gd-jp'>故郷の変わりように驚きを禁じ得ない。</span>(Thấy quê hương đổi thay như vậy, tôi không khỏi ngạc nhiên)</div><div class='gd-warn'>Mẹo phân biệt nhanh: tâm nguyện, tình yêu, niềm tin lâu năm dùng <span class='gd-jp'>てやまない</span>; khó chịu hay muốn gì đó ngay lúc này dùng <span class='gd-jp'>てたまらない</span>; phản ứng không kìm được khi bị một việc chạm đến thì dùng <span class='gd-jp'>を禁じ得ない</span>.</div>","n1-53":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜べからず」chính là kiểu chữ trên biển báo: <b>「cấm ～」「không được ～」「xin đừng ～」</b>. Đây là cách nói của văn ngôn Nhật, nghe giống những dòng như \"Cấm vào\", \"Cấm hút thuốc\", \"Không phận sự miễn vào\" trong tiếng Việt: cứng và rất trang trọng. Ngày thường gần như không ai dùng khi nói chuyện, bạn sẽ gặp nó nhiều nhất trong <b>biển báo, khẩu hiệu, châm ngôn</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Biển báo</span>Quy định cấm viết cho tất cả mọi người đọc, đặt ở cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに入るべからず。</span>(Cấm vào khu vực này)</div><div class='gd-ex-line'>・<span class='gd-jp'>ここにごみを捨てるべからず。</span>(Cấm xả rác ở đây)</div><div class='gd-sec'><span class='gd-tag'>Châm ngôn・khẩu hiệu</span>Rất nhiều câu nói xưa, danh ngôn có dạng này, bạn cứ nhớ nguyên cả câu nhé.</div><div class='gd-ex-line'>・<span class='gd-jp'>働かざる者食うべからず。</span>(Người không làm việc thì không đáng được ăn)</div><div class='gd-ex-line'>・<span class='gd-jp'>初心忘るべからず。</span>(Đừng bao giờ quên初tâm ban đầu)</div><div class='gd-sec'><span class='gd-tag'>べからざる＋danh từ</span>Khi phía sau cần nối với danh từ, ta đổi thành <b>べからざる</b>, nghĩa là 「～ mà không thể/không được (làm)」, thường gặp trong văn viết và báo chí.</div><div class='gd-ex-line'>・<span class='gd-jp'>水は生活に欠くべからざるものだ。</span>(Nước là thứ không thể thiếu trong cuộc sống)</div><div class='gd-ex-line'>・<span class='gd-jp'>それは許すべからざる行為だ。</span>(Đó là hành vi không thể tha thứ)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ dùng <b>thể từ điển</b> (dạng gốc bạn tra trong từ điển), gắn thẳng vào:<br><span class='gd-pair'><span class='gd-jp'>入る</span> → <span class='gd-jp'>入るべからず</span></span><span class='gd-pair'><span class='gd-jp'>捨てる</span> → <span class='gd-jp'>捨てるべからず</span></span><br><b>する</b> thường đổi thành <b>す</b> rồi mới nối: <span class='gd-pair'><span class='gd-jp'>駐車する</span> → <span class='gd-jp'>駐車すべからず</span></span> (viết するべからず cũng có gặp, nhưng すべからず mới là cách nói chuẩn hơn)<br>Khi cần bổ nghĩa cho danh từ, đổi ず thành ざる: <span class='gd-pair'><span class='gd-jp'>欠くべからず</span> → <span class='gd-jp'>欠くべからざるもの</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Cuối câu dùng <b>べからず</b>, trước danh từ dùng <b>べからざる</b>, đừng viết thành 「べからずもの」.<br>・Nó là kiểu chữ viết trên biển, trong văn bản, <b>không dùng để nói thẳng với ai đó là đừng làm gì</b>. Nói với bạn bè 「吸うべからず」 nghe sẽ rất kỳ, khi nói chuyện hãy dùng <span class='gd-jp'>吸わないで</span> hoặc <span class='gd-jp'>吸っちゃだめ</span>.<br>・Phía trước không được dùng thể ない, 「行かないべからず」 là sai. Bản thân nó đã mang nghĩa \"không được\" rồi.<br>・「忘る」 trong <span class='gd-jp'>初心忘るべからず</span> là dạng gốc cổ của <span class='gd-jp'>忘れる</span>, đây là cách nói cố định, cứ thuộc nguyên văn, đừng tự sửa.<br>・<span class='gd-jp'>すべからく</span> trông na ná nhưng là một từ khác, nghĩa là \"đáng lẽ phải, nhất định phải\", không phải phủ định.</div><div class='gd-h'>Phân biệt với những mẫu trông giống</div><div class='gd-sec'>Cùng tình huống \"hút thuốc\":<br><b>べからず</b> = <b>quy định cấm</b> trên biển báo: <span class='gd-jp'>ここでたばこを吸うべからず。</span>(Cấm hút thuốc ở đây)<br><b>べきではない</b> = <b>khuyên</b> rằng \"không nên\", dùng được cả khi nói lẫn khi viết: <span class='gd-jp'>ここでたばこを吸うべきではない。</span>(Không nên hút thuốc ở đây)<br><b>まじき</b> = điều không nên có đối với <b>tư cách, vai trò</b> đó: <span class='gd-jp'>患者の前でたばこを吸うなんて、医者にあるまじき行為だ。</span>(Hút thuốc trước mặt bệnh nhân là hành vi không thể chấp nhận ở một bác sĩ)</div><div class='gd-sec'>Ngoài ra <b>べく</b> chỉ giống về hình thức, nghĩa hoàn toàn khác, là 「để ～」: <span class='gd-jp'>合格すべく、毎日勉強している。</span>(Để đậu, ngày nào tôi cũng học)</div><div class='gd-warn'>Mẹo phân biệt: \"cấm\" trên biển báo, châm ngôn thì dùng べからず; khuyên \"không nên\" thì dùng べきではない; nói đến \"với tư cách là ～\" thì dùng まじき; còn \"để ～\" là べく.</div>","n1-55":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たる」nghĩa là <b>「với tư cách là ～」「đã là ～」</b>, giọng giống kiểu \"đã là thầy giáo thì…\", \"làm cha làm mẹ thì phải…\" trong tiếng Việt. Trước hết nêu ra một vai trò có sức nặng, rồi nói \"vai trò này <b>thì phải</b> thế nào\".<br><span class='gd-jp'>たる</span> là cách nói rất cổ, nghĩa tương đương <span class='gd-jp'>である</span>, chuyên đặt trước danh từ, nên nghe rất trang trọng, có phần \"lên mặt dạy đời\", thường xuất hiện trong văn viết, diễn văn, lời huấn thị.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Danh từ＋たる＋danh từ. Phổ biến nhất là phía sau nối với <span class='gd-jp'>者</span> (cũng hay viết là <span class='gd-jp'>もの</span>, vẫn nghĩa là \"người\"):<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者たる者</span></span> (người đã làm bác sĩ)<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親たるもの</span></span> (người đã làm cha mẹ)</div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Nói về điều nên làm</span>Phổ biến nhất. Phía sau hay đi với <span class='gd-jp'>べきだ</span>, <span class='gd-jp'>なければならない</span>, <span class='gd-jp'>てはならない</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者たる者、患者の話をよく聞くべきだ。</span>(Đã là bác sĩ thì phải lắng nghe bệnh nhân cho kỹ)</div><div class='gd-ex-line'>・<span class='gd-jp'>プロたる者、言い訳はしない。</span>(Đã là dân chuyên nghiệp thì không viện cớ)</div><div class='gd-sec'><span class='gd-tag'>Phê phán việc không làm được</span>Nêu vai trò ra trước, rồi nói người đó lại làm điều không ra gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師たる者が生徒にうそをつくなんて、許されることではない。</span>(Là giáo viên mà lại nói dối học sinh thì không thể tha thứ)</div><div class='gd-sec'><span class='gd-tag'>Nối với danh từ khác</span>Phía sau không nhất thiết là 者, cũng có thể nối với danh từ như 「資格」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に代表たる資格はない。</span>(Anh ấy không đủ tư cách làm đại diện)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước chỉ nối với <b>danh từ</b>, và thường là những từ chỉ vai trò, chức vụ, lập trường, tức là những vị trí \"có trách nhiệm phải làm tròn\". Không nối với động từ hay tính từ.<br>・Nó không phải 「た」 của quá khứ cộng thêm 「る」; <span class='gd-jp'>たる</span> là một từ nguyên khối, đừng tách ra mà hiểu.<br>・Nghe rất cứng, trò chuyện hằng ngày mà nói vậy sẽ như đang lên lớp. Khi nói, muốn diễn đạt \"đã là ～ thì phải ～\" cứ dùng <span class='gd-jp'>〜なんだから</span> là đủ: <span class='gd-jp'>先生なんだから、ちゃんとしてよ。</span>(Cậu là thầy giáo mà, nghiêm túc một chút đi)<br>・Đừng nhầm với <span class='gd-jp'>足る</span> (đủ tư cách, đáng) cùng cách đọc, phần dưới sẽ so sánh.</div><div class='gd-h'>Phân biệt với những mẫu trông giống</div><div class='gd-sec'>Cùng nói về giáo viên:<br><b>たる者</b> = nêu vai trò trước, rồi nói điều nên làm (hoặc phê phán việc không làm được): <span class='gd-jp'>教師たる者、生徒の手本であるべきだ。</span>(Đã là giáo viên thì phải là tấm gương cho học sinh)<br><b>にあるまじき</b> = đánh giá trực tiếp một <b>hành vi, phát ngôn</b> là \"điều không nên có ở vai trò này\", phía sau nối danh từ như <span class='gd-jp'>行為</span>, <span class='gd-jp'>発言</span>: <span class='gd-jp'>教師にあるまじき発言だ。</span>(Đây là phát ngôn không thể chấp nhận ở một giáo viên)<br><b>ともなれば</b> = đạt đến cấp độ đó thì <b>đương nhiên</b> sẽ ～, nói về kết quả hiển nhiên chứ không phải nghĩa vụ: <span class='gd-jp'>ベテラン教師ともなれば、生徒の顔を見ただけで悩みに気づく。</span>(Đến trình độ giáo viên kỳ cựu thì chỉ nhìn mặt học sinh là biết em đang có chuyện lo)<br><b>に足る</b> = <b>đáng</b> ～, phía trước nối với những từ như <span class='gd-jp'>信頼</span>, <span class='gd-jp'>尊敬</span>, và có thêm một chữ <span class='gd-jp'>に</span>: <span class='gd-jp'>彼は信頼に足る教師だ。</span>(Anh ấy là một giáo viên đáng tin cậy)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"đã là ～ thì phải thế nào\" hoặc \"đã là ～ mà lại…\", nêu vai trò ra trước thì dùng たる(者); muốn đánh giá thẳng một hành vi là \"điều không nên có ở người ～\" thì dùng 「～にあるまじき＋行為／発言」; nói \"đến cấp độ đó thì đương nhiên ～\" dùng ともなれば; nói \"đáng ～\" dùng に足る.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>〜まじき</span> (điều không nên có ở ～) cũng dùng để đánh giá theo vai trò, và <span class='gd-jp'>〜ともなれば</span> nói về \"đến mức độ đó thì…\", bạn có thể nhớ cùng lúc.</div>","n1-56":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なくして（は）」nghĩa là <b>「nếu không có ～ thì không thể…」</b>. Phía trước đặt một thứ rất quan trọng, phía sau nói \"thiếu nó thì việc đó căn bản không làm được\", để nhấn mạnh <b>thứ này tuyệt đối không thể thiếu</b>. Giọng văn rất trang trọng, thường gặp trong bài viết, diễn văn, lời phát biểu khi nhận giải.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ + なくして trực tiếp, <b>ở giữa không thêm「が」hay「を」</b>:<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力なくして</span></span><span class='gd-pair'><span class='gd-jp'>協力</span> → <span class='gd-jp'>協力なくしては</span></span><br>Phía sau nhất định phải là cách nói \"không thể, không làm được\", thường gặp nhất là <span class='gd-jp'>あり得ない</span> (không thể có), <span class='gd-jp'>できない</span>, <span class='gd-jp'>語れない</span> (không thể nói tới).<br>Khi phía trước là một hành động, dùng「thể từ điển + ことなくして」: <span class='gd-pair'><span class='gd-jp'>苦労する</span> → <span class='gd-jp'>苦労することなくして</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Giải thích lý lẽ</span>Nói về những điều kiện không thể thiếu đằng sau thành công, thành quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>日々の努力なくして成功はあり得ない。</span>(Không có nỗ lực mỗi ngày thì không thể thành công)</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼関係なくして、いいチームは作れない。</span>(Không có sự tin tưởng lẫn nhau thì không xây dựng được một đội nhóm tốt)</div><div class='gd-ex-line'>・<span class='gd-jp'>苦労することなくして、本当の喜びは味わえない。</span>(Không chịu khổ thì không nếm được niềm vui thật sự)</div><div class='gd-sec'><span class='gd-tag'>Lời cảm ơn</span>Nhìn lại và nói \"nếu lúc đó không có mọi người thì đã không làm được\", phía sau thường dùng thì quá khứ.</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様のご協力なくしては、このプロジェクトは成功しませんでした。</span>(Nếu không có sự hỗ trợ của mọi người, dự án này đã không thể thành công)</div><div class='gd-sec'><span class='gd-tag'>Đánh giá</span>Nói rằng vị trí của một người hay một sự vật quan trọng đến mức không thể không nhắc tới.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の存在なくして、日本のサッカーの歴史は語れない。</span>(Khi nói về lịch sử bóng đá Nhật Bản, không thể không nhắc đến anh ấy)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau nhất định là \"không thể, không làm được\". <b>Không thể</b> nói「努力なくして成功した」vì như vậy là tự mâu thuẫn.<br>・Đừng thêm「を」: <span class='gd-jp'>財布をなくして困った</span> nghĩa là \"làm mất ví nên gặp rắc rối\", đó là động từ <span class='gd-jp'>なくす</span> (làm mất), không liên quan đến mẫu ngữ pháp này.<br>・Phía trước phải là thứ <b>thật sự quan trọng</b>, như nỗ lực, tình yêu, sự hỗ trợ, sự tin tưởng. Nếu đem chuyện nhỏ như cái ô ra nói thì nghe sẽ rất phóng đại, ngày thường chỉ cần nói <span class='gd-jp'>傘がないと出かけられない</span> là đủ.<br>・Mẫu này rất cứng, nói chuyện với bạn bè sẽ không dùng. Văn nói chỉ cần「〜がなかったら、〜できない」là được.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là cảm ơn mọi người đã giúp đỡ:<br><b>なくしては</b>＝không có ～ thì không làm được (trang trọng nhất): <span class='gd-jp'>皆様の協力なくしては、成功できませんでした。</span><br><b>なしには</b>＝ý nghĩa gần như giống hệt, hơi bớt cứng một chút: <span class='gd-jp'>皆様の協力なしには、成功できませんでした。</span><br><b>あっての</b>＝nói theo chiều ngược lại, \"có A mới có B\": <span class='gd-jp'>皆様の協力あっての成功でした。</span>(Nhờ mọi người giúp đỡ mới có được thành công lần này)</div><div class='gd-sec'>Lưu ý, 「なしに」khi không có は còn có thể đơn giản mang nghĩa \"không làm ～ mà cứ thế làm luôn\": <span class='gd-jp'>連絡なしに休んだ。</span>(Nghỉ mà không báo trước một tiếng)<br>なくして không có cách dùng này, nó chỉ dùng cho nghĩa \"thiếu nó thì không thể\".</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu phía sau là \"không thể, không làm được\" thì なくして và なしには đều dùng được, なくして trang trọng hơn; nếu phía sau là \"cứ thế làm luôn\" thì chỉ dùng được なしに; muốn nói từ góc độ \"có\" thì dùng あっての.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜あっての」(có A mới có B) chính là mặt đối lập của なくして, nhớ cả hai cùng lúc là tiện nhất: <span class='gd-jp'>お客様あっての商売だ。</span>(Có khách hàng thì mới có việc kinh doanh)</div>","n1-57":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「にして」là một mẫu <b>văn viết</b> rất cứng, hơi giống lối nói trang trọng, đậm chất Hán Việt trong tiếng Việt như \"tuổi ngoài năm mươi mới…\", \"chỉ trong một đêm\", \"vừa là… vừa là…\". Có ba nghĩa thường gặp: <b>「đến ～ mới」</b> (bao gồm cả \"chỉ có ～ mới\"), <b>「trong nháy mắt」</b>, <b>「vừa là ～ vừa là」</b>. Hai nghĩa đầu thường mang sắc thái cảm thán kiểu \"thật không đơn giản / thật không ngờ\"; còn \"vừa là ～ vừa là\" chỉ là đặt song song hai thân phận hoặc hai tính chất, giọng trang trọng, chỉnh tề, không nhất thiết có ý ngạc nhiên.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Về cơ bản ghép với danh từ: <span class='gd-pair'><span class='gd-jp'>50歳</span> → <span class='gd-jp'>50歳にして</span></span><br>Cách dùng \"vừa là ～ vừa là\" cũng hay ghép với tính từ đuôi な (như <span class='gd-jp'>簡潔な</span>, tính từ có な đi sau), bỏ な đi rồi ghép: <span class='gd-pair'><span class='gd-jp'>簡潔な</span> → <span class='gd-jp'>簡潔にして</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đến ～ mới</span>Phía trước đặt một \"giai đoạn\" như tuổi tác, lần thứ mấy, năm thứ mấy; phía sau thường đi với <span class='gd-jp'>初めて</span>, <span class='gd-jp'>ようやく</span>, diễn tả \"phải đến bước này mới cuối cùng…\".</div><div class='gd-ex-line'>・<span class='gd-jp'>三度目の挑戦にして、ようやく合格した。</span>(Thử đến lần thứ ba, cuối cùng cũng đỗ)</div><div class='gd-ex-line'>・<span class='gd-jp'>50歳にして初めて海外に行った。</span>(Đến 50 tuổi mới lần đầu ra nước ngoài)</div><div class='gd-sec'>Phía sau đi với <span class='gd-jp'>なお</span> thì thành nghĩa \"đã đến giai đoạn này rồi mà vẫn…\":</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は90歳にしてなお現役の医者だ。</span>(Ông ấy đã 90 tuổi mà vẫn còn khám bệnh ở tuyến đầu)</div><div class='gd-sec'><span class='gd-tag'>Chỉ có ～ mới</span>Phía trước đặt người, diễn tả \"phải là người như vậy mới làm được\", thường viết thành「〜にして初めて」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは彼にして初めてできる仕事だ。</span>(Đây là công việc chỉ có anh ấy mới làm được)</div><div class='gd-ex-line'>・<span class='gd-jp'>この親にしてこの子あり。</span>(Cha nào con nấy)</div><div class='gd-sec'><span class='gd-tag'>Trong nháy mắt</span>Đi sau những từ chỉ thời gian rất ngắn như <span class='gd-jp'>一瞬</span>, <span class='gd-jp'>一夜</span>, diễn tả \"chỉ trong chớp mắt đã…\". Văn nói thì nói thẳng là <span class='gd-jp'>一瞬で</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>町は一瞬にして炎に包まれた。</span>(Cả thị trấn trong chớp mắt bị biển lửa nuốt chửng)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は一夜にしてスターになった。</span>(Chỉ sau một đêm, cô ấy đã trở thành ngôi sao)</div><div class='gd-sec'><span class='gd-tag'>Vừa là ～ vừa là</span>「AにしてB」＝có đồng thời cả A và B. Ý nghĩa giống「で」: <span class='gd-jp'>医者で作家</span> là cách nói bình thường, <span class='gd-jp'>医者にして作家</span> là cách viết trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者にして作家でもある。</span>(Anh ấy vừa là bác sĩ, vừa là nhà văn)</div><div class='gd-ex-line'>・<span class='gd-jp'>説明は簡潔にして明快だった。</span>(Lời giải thích vừa ngắn gọn vừa rõ ràng)</div><div class='gd-sec'>Ngoài ra, <span class='gd-jp'>幸いにして</span> (may mắn là) và <span class='gd-jp'>不幸にして</span> (không may là) là cách nói cố định, cứ học thuộc như một từ là được:<br><span class='gd-jp'>幸いにして、けが人はいなかった。</span>(May mắn là không có ai bị thương)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Với nghĩa「đến ～ mới」, phía trước phải là <b>giai đoạn cuộc đời hoặc số lần</b> (tuổi tác, lần thứ mấy, năm thứ mấy), không thể tùy tiện đặt một mốc giờ giấc, ví dụ「3時にして」là sai.<br>・Đây là văn phong của bài viết, diễn văn, tin tức; dùng khi nói chuyện với bạn bè sẽ rất gượng gạo, văn nói chỉ cần dùng「で」「〜歳で初めて」là được.<br>・Khi ghép với tính từ đuôi な phải bỏ な: là <span class='gd-jp'>簡潔にして</span>, không phải「簡潔なにして」.<br>・Đừng nhầm với thể て của「〜にする」: <span class='gd-jp'>ジュースにして飲む</span> nghĩa là \"làm thành nước ép rồi uống\", không liên quan đến mẫu ngữ pháp này, cần dựa vào ngữ cảnh trước sau để phán đoán.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>にして</b>＝đến giai đoạn này <b>mới</b> xảy ra một việc nào đó:<br><span class='gd-jp'>50歳にして初めてパソコンを買った。</span>(Đến 50 tuổi mới lần đầu mua máy tính)<br><b>にしては</b>＝\"xét theo ～ thì khá là…\", dùng để nhận xét điều khác với ấn tượng thông thường:<br><span class='gd-jp'>50歳にしては体力がある。</span>(Xét ở tuổi 50 thì thể lực khá tốt)</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía sau đi với「初めて／ようやく／なお」, nói về một việc cuối cùng cũng xảy ra hoặc vẫn như cũ, thì là にして; phía sau đang đánh giá \"so với thông thường thì thế nào\", thì là にしては. Chỉ thêm một chữ「は」mà ý nghĩa đã khác hẳn.</div>","n1-59":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜には当たらない」 nghĩa là <b>「không cần phải ～」「chẳng đáng phải ～」</b>. Mẫu này dùng để bình luận một cách bình tĩnh: chuyện này không nghiêm trọng đến thế, <b>phản ứng như vậy là quá đà</b>. Ví dụ: không cần ngạc nhiên, không cần buồn, không cần mắng ai. Nó giống kiểu nói \"có gì mà phải ngạc nhiên đến thế\" trong tiếng Việt, chỉ là giọng trang trọng hơn và hay gặp trong bài viết, bài bình luận hoặc phát biểu chính thức.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ thể từ điển (dạng gốc tra được trong từ điển) ＋には当たらない<br><span class='gd-pair'><span class='gd-jp'>驚く</span> → <span class='gd-jp'>驚くには当たらない</span></span> (không cần ngạc nhiên)<br><span class='gd-pair'><span class='gd-jp'>悲観する</span> → <span class='gd-jp'>悲観するには当たらない</span></span> (không cần bi quan)<br>Muốn nói lịch sự hơn thì dùng <span class='gd-jp'>〜には当たりません</span>. 「は」 đôi khi được lược bỏ, viết thành <span class='gd-jp'>驚くに当たらない</span>, nghĩa vẫn y nguyên.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Bình luận phản ứng quá đà</span>Phía trước thường nêu lý do trước, kiểu \"vì vốn dĩ là vậy\" hoặc \"mới có chút này thôi\", rồi phía sau mới kết luận: \"nên không cần ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はずっと努力してきたのだから、合格したのも驚くには当たらない。</span> (Anh ấy luôn nỗ lực, nên chuyện anh ấy đỗ cũng không có gì phải ngạc nhiên)</div><div class='gd-ex-line'>・<span class='gd-jp'>一度失敗したくらいで、悲観するには当たらない。</span> (Mới thất bại một lần thôi, không cần bi quan)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが言ったことだから、そんなに責めるには当たらない。</span> (Đó là lời của trẻ con, không cần trách móc đến thế)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Phía trước thường là các động từ chỉ \"phản ứng\": <span class='gd-jp'>驚く</span>, <span class='gd-jp'>嘆く</span>, <span class='gd-jp'>悲観する</span>, <span class='gd-jp'>責める</span>, <span class='gd-jp'>非難する</span>, <span class='gd-jp'>褒める</span>, <span class='gd-jp'>感心する</span>.<br>Phần lý do thường đi với <span class='gd-jp'>〜くらいで</span> (chỉ cỡ này mà đã ～), <span class='gd-jp'>〜からといって</span> (dù là vì ～ đi nữa), <span class='gd-jp'>〜のだから</span> (đã là ～ thì).</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ <span class='gd-jp'>当たる</span> ở đây không liên quan gì đến \"trúng thưởng\" hay \"trúng đích\". Hãy nhớ cả câu như một cách nói cố định.<br>・Phía trước là <b>phản ứng hoặc đánh giá đối với một việc</b>. Còn kiểu \"không cần đích thân chạy một chuyến\", tức \"không cần mất công làm một hành động nào đó\", tiếng Nhật thường dùng <span class='gd-jp'>〜には及ばない</span>, không dùng mẫu này (so sánh ở dưới).<br>・Danh từ ＋ <span class='gd-jp'>に当たらない</span> thường mang nghĩa khác: \"không tính là ～, không cấu thành ～\". Ví dụ <span class='gd-jp'>これは違反には当たらない。</span> (Cái này không tính là vi phạm). Lúc mới học, bạn chỉ cần nhớ <b>động từ thể từ điển＋には当たらない＝không cần ～</b> là đủ.<br>・Dịch thành \"không đáng ～\" dễ khiến bạn hiểu nhầm là \"thứ này không có giá trị\". Nghĩa thật của nó là \"phản ứng đó không cần thiết, không hợp lý\", nên dịch là \"không cần ～\" sẽ chính xác hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>には及ばない</b>＝không cần mất công làm (thường mang sự quan tâm, nói với đối phương)<br>Tình huống: cấp dưới mắc một lỗi nhỏ.<br>Sếp nói với cấp dưới: <span class='gd-jp'>わざわざ謝りに来るには及ばないよ。</span> (Không cần cất công đến xin lỗi đâu)<br>Đồng nghiệp bình luận về chuyện này: <span class='gd-jp'>一度のミスで、そこまで彼を責めるには当たらない。</span> (Mới sai một lần, không cần trách cậu ấy đến mức đó)</div><div class='gd-sec'><b>に足りない</b>＝bản thân đối tượng chưa đủ \"tầm\", không đáng để ～<br>Tình huống: ngày mai có trận đấu.<br><span class='gd-jp'>あんな相手は恐れるに足りない。</span> (Đối thủ như thế không đáng sợ: trọng tâm là đối thủ quá yếu)<br><span class='gd-jp'>初めての試合だからといって、恐れるには当たらない。</span> (Dù là trận đầu tiên cũng không cần sợ: trọng tâm là nỗi sợ này không cần thiết)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"phản ứng đó không cần thiết\" thì dùng には当たらない; muốn nói \"không cần mất công làm\" thì dùng には及ばない; muốn nói \"bản thân đối tượng chẳng có tầm cỡ gì\" thì dùng に足りない.</div>","n1-62":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜がてら」 nghĩa là <b>「nhân tiện ～」「kết hợp ～」</b>. Bạn ra ngoài một chuyến mà làm xong hai việc cùng lúc: đi dạo kết hợp mua bánh mì, tiễn bạn ra ga kết hợp trò chuyện. Điểm mấu chốt là <b>một hành động mang hai mục đích cùng lúc</b>, cảm giác \"một công đôi việc\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋がてら</span>Phổ biến nhất. Phía trước là danh từ chỉ \"hành động\", như <span class='gd-jp'>散歩</span>, <span class='gd-jp'>買い物</span>, <span class='gd-jp'>見物</span> (tham quan), <span class='gd-jp'>運動</span>, <span class='gd-jp'>ドライブ</span>.<br><span class='gd-pair'><span class='gd-jp'>散歩</span> → <span class='gd-jp'>散歩がてら</span></span> (đi dạo nhân tiện)</div><div class='gd-ex-line'>・<span class='gd-jp'>散歩がてら、パンを買ってきた。</span> (Đi dạo, nhân tiện mua bánh mì về)</div><div class='gd-ex-line'>・<span class='gd-jp'>花見がてら、久しぶりに実家に帰った。</span> (Lâu rồi mới về quê một chuyến, nhân tiện ngắm hoa)</div><div class='gd-sec'><span class='gd-tag'>Thể ます＋がてら</span>Với động từ, bỏ 「ます」 rồi thêm がてら trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>送ります</span> → bỏ ます → <span class='gd-jp'>送りがてら</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで送りがてら、ちょっと話そうか。</span> (Mình tiễn bạn ra ga, nhân tiện nói chuyện một chút nhé)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Vế sau thường là hành động <b>di chuyển, ra ngoài</b>, như <span class='gd-jp'>行く</span>, <span class='gd-jp'>来る</span>, <span class='gd-jp'>寄る</span> (ghé qua), <span class='gd-jp'>歩く</span>, <span class='gd-jp'>出かける</span>. Vì \"nhân tiện\" vốn là \"dù sao cũng phải ra ngoài rồi, thì làm luôn một thể\".</div><div class='gd-ex-line'>・<span class='gd-jp'>運動がてら、一駅歩いて帰った。</span> (Coi như tập thể dục, đi bộ thêm một ga rồi về nhà)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>hành động</b>. <span class='gd-jp'>散歩がてら</span> thì được, còn những từ không phải hành động như 「雨がてら」「休みがてら」 thì không dùng được.<br>・Hai việc trước và sau phải do <b>cùng một người</b> làm.<br>・Mẫu này không phải văn viết, trong hội thoại hằng ngày cũng nghe rất nhiều, chỉ hơi chững chạc hơn <span class='gd-jp'>ついでに</span> một chút thôi.<br>・Nó nói về việc làm nhân tiện trong <b>lần này</b>, không phải làm song song hai việc trong thời gian dài. Trường hợp dài hạn thì dùng <span class='gd-jp'>かたわら</span>.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là \"đi mua đồ, nhân tiện ghé bưu điện\":<br><b>ついでに</b>＝khẩu ngữ nhất, dễ dùng nhất, việc chính là đi mua đồ, bưu điện chỉ là việc phụ: <span class='gd-jp'>買い物のついでに、郵便局に寄った。</span><br><b>がてら</b>＝một chuyến ra ngoài có hai mục đích: <span class='gd-jp'>買い物がてら、郵便局に寄った。</span></div><div class='gd-sec'><b>かたがた</b>＝rất trang trọng, hay dùng khi đến thăm hỏi, chào hỏi, thường gặp trong môi trường công việc hoặc thư từ: <span class='gd-jp'>お礼かたがた、ご挨拶に伺いました。</span> (Tôi đến để cảm ơn, nhân tiện xin chào hỏi anh/chị)<br><b>かたわら</b>＝trong thời gian dài vừa làm công việc chính, vừa làm việc khác: <span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span> (Vừa đi làm công ty, vừa viết tiểu thuyết)<br><b>ながら</b>＝hai hành động diễn ra cùng lúc: <span class='gd-jp'>歩きながら電話する。</span> (Vừa đi vừa nói điện thoại)</div><div class='gd-warn'>Mẹo phân biệt: nói \"nhân tiện\" bình thường thì dùng ついでに hoặc がてら; đến thăm hỏi, chào hỏi khách hàng hay bề trên thì dùng かたがた; làm cả hai việc trong thời gian dài thì dùng かたわら; cơ thể làm hai hành động cùng lúc thì dùng ながら.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn hãy xem tiếp <span class='gd-jp'>〜かたがた</span> và <span class='gd-jp'>〜かたわら</span>. Nhớ ba mẫu này cùng nhau thì câu trắc nghiệm trong kỳ thi sẽ rất dễ phân biệt.</div>","n1-64":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ずくめ」giống như các cách nói <b>「toàn thân đen」「toàn là ～」「một màu ～」</b> trong tiếng Việt. Nhìn từ đầu đến cuối, tổng thể toàn là cùng một loại thứ, ví dụ mặc đồ đen từ đầu đến chân, cả năm toàn chuyện tốt nối tiếp nhau, hay quy định nhiều đến mức đâu cũng bị quản.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ + ずくめ, đơn giản vậy thôi.<br><span class='gd-pair'><span class='gd-jp'>黒</span> → <span class='gd-jp'>黒ずくめ</span></span><span class='gd-pair'><span class='gd-jp'>いいこと</span> → <span class='gd-jp'>いいことずくめ</span></span><span class='gd-pair'><span class='gd-jp'>規則</span> → <span class='gd-jp'>規則ずくめ</span></span><br>Ghép xong thì dùng giống một danh từ bình thường:<br>Đứng trước danh từ thì thêm 「の」：<span class='gd-jp'>黒ずくめの男</span>（người đàn ông mặc đồ đen từ đầu đến chân）<br>Đứng cuối câu thì thêm 「だ」：<span class='gd-jp'>いいことずくめだ</span><br>Khi câu chưa kết thúc thì dùng 「で」：<span class='gd-jp'>規則ずくめで、疲れる</span></div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'>ずくめ<b>không ghép được với mọi danh từ</b>. Người Nhật thường chỉ dùng vài cụm cố định, nên bạn học thuộc những cụm dưới đây trước là thiết thực nhất.</div><div class='gd-sec'><span class='gd-tag'>Màu sắc, trang phục</span>Cả người toàn một màu.</div><div class='gd-ex-line'>・<span class='gd-jp'>黒ずくめの男が店に入ってきた。</span>（Một người đàn ông mặc đồ đen từ đầu đến chân bước vào cửa hàng）</div><div class='gd-sec'><span class='gd-tag'>Chuyện tốt</span>Chuyện tốt đến hết việc này đến việc khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>今年は結婚に昇進に、いいことずくめだった。</span>（Năm nay vừa kết hôn vừa được thăng chức, toàn là chuyện tốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行中はごちそうずくめで、3キロも太った。</span>（Trong chuyến du lịch bữa nào cũng toàn món ngon, tăng hẳn 3 ký）</div><div class='gd-sec'><span class='gd-tag'>Quy định, hạn chế</span>Đâu đâu cũng bị quản lý, thường mang cảm giác khó chịu vì bị bó buộc.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの会社は規則ずくめで、息が詰まる。</span>（Công ty mình quy định cả đống, ngột ngạt đến khó thở）</div><div class='gd-sec'><span class='gd-tag'>Hay thấy trên báo chí</span>Dùng để nói một sự việc có rất nhiều điểm khác thường.</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の大会は異例ずくめだった。</span>（Giải đấu lần này chỗ nào cũng là ngoại lệ）</div><div class='gd-sec'>Từ các ví dụ trên bạn thấy đấy: ずくめ<b>bản thân không phân tốt hay xấu</b>, điểm mấu chốt chỉ là «tổng thể đồng nhất một kiểu». <span class='gd-jp'>黒ずくめ</span> là trung tính, <span class='gd-jp'>いいことずくめ</span> là tích cực, còn <span class='gd-jp'>規則ずくめ</span> thì nghiêng về tiêu cực.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chỉ ghép được với <b>danh từ</b>. Muốn nói «toàn món ngon» thì nói <span class='gd-jp'>美味しいものずくめ</span> hoặc <span class='gd-jp'>ごちそうずくめ</span>, không thể gắn thẳng tính từ vào thành 美味しいずくめ.<br>・<b>Đồ bẩn dính trên người</b> thì không dùng ずくめ: «lấm lem bùn» là <span class='gd-jp'>泥まみれ</span>, không nói 泥ずくめ; «ướt đẫm mồ hôi» là <span class='gd-jp'>汗まみれ</span>.<br>・<span class='gd-jp'>結構ずくめ</span>（điều kiện tốt đến mức không chê vào đâu được）thường mang chút giọng nghi ngờ: <span class='gd-jp'>結構ずくめの話には気をつけたほうがいい。</span>（Chuyện nào toàn điều kiện có lợi thì nên cẩn thận một chút）<br>・Đôi khi bạn sẽ thấy viết là 「づくめ」, đó là cùng một từ, hiện nay thường viết ずくめ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về một bộ quần áo, hãy xem ba cách nói khác nhau chỗ nào:<br><b>ずくめ</b>＝tổng thể đồng nhất một kiểu: <span class='gd-jp'>黒ずくめの服</span>（đồ đen từ trên xuống dưới）<br><b>まみれ</b>＝bề mặt dính đầy chất lỏng hoặc bột, hầu như luôn mang nghĩa tiêu cực: <span class='gd-jp'>泥まみれの服</span>（quần áo dính đầy bùn）<br><b>だらけ</b>＝một thứ nào đó nhiều đến mức đâu cũng có, phần lớn là thứ không tốt: <span class='gd-jp'>しわだらけの服</span>（quần áo nhăn nhúm khắp nơi）</div><div class='gd-warn'>Mẹo phán đoán: tổng thể đồng nhất một kiểu (trang phục, chuyện tốt, quy định… các cụm cố định) dùng ずくめ; dính trên bề mặt, bám đầy người dùng まみれ; số lượng nhiều đến mức đâu đâu cũng có dùng だらけ.</div>","n1-63":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜まみれ」giống như các cách nói <b>「lấm lem bùn」「ướt đẫm mồ hôi」「dính đầy máu」</b> trong tiếng Việt. Điểm mấu chốt là bùn, mồ hôi, máu, bụi… <b>dính trên bề mặt, bám khắp một vùng</b>, và thường là thứ bẩn, khiến người ta khó chịu.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Người hoặc đồ vật dính đầy thứ bẩn</span>Cách dùng cơ bản nhất. Những từ hay đi cùng: <span class='gd-jp'>泥</span>、<span class='gd-jp'>汗</span>、<span class='gd-jp'>血</span>、<span class='gd-jp'>ほこり</span>（bụi）、<span class='gd-jp'>油</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>泥まみれになって、子供と遊んだ。</span>（Chơi với bọn trẻ đến lấm lem bùn）</div><div class='gd-ex-line'>・<span class='gd-jp'>汗まみれで家に帰ってきた。</span>（Về nhà mà mồ hôi ướt đẫm người）</div><div class='gd-ex-line'>・<span class='gd-jp'>倉庫からほこりまみれのアルバムが出てきた。</span>（Lục trong kho ra một cuốn album phủ đầy bụi）</div><div class='gd-sec'><span class='gd-tag'>Nghĩa bóng: bị chuyện xấu quấn lấy</span>Cũng có thể dùng cho những thứ trừu tượng, như bị nợ nần hay lời nói dối bao trùm hết, không gỡ ra được.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は借金まみれだ。</span>（Anh ấy nợ nần chồng chất）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人の話は嘘まみれだ。</span>（Chuyện người đó kể toàn là dối trá）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản, <b>danh từ + まみれ</b>：<span class='gd-pair'><span class='gd-jp'>泥</span> → <span class='gd-jp'>泥まみれ</span></span><br>Ghép xong thì xem nó như một danh từ. Các dạng hay gặp nhất:<br>・<span class='gd-jp'>〜まみれになる</span>：trở nên dính đầy ～<br>・<span class='gd-jp'>〜まみれだ</span>：（hiện tại）người đầy ～<br>・<span class='gd-jp'>〜まみれで</span>：trong tình trạng dính đầy ～（mà làm việc gì đó）<br>・<span class='gd-jp'>〜まみれの＋名詞</span>：（thứ）dính đầy ～　Ví dụ: <span class='gd-jp'>血まみれのシャツ</span>（chiếc áo sơ mi dính đầy máu）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・まみれ mang cảm giác «<b>dính lên, bám trên bề mặt</b>», nên với thứ chỉ là «số lượng nhiều» thì đừng dùng. Nói đông người thì dùng <span class='gd-jp'>人でいっぱい</span> hoặc <span class='gd-jp'>人だらけ</span>, không nói 人まみれ.<br>・Vết thương, lỗi sai… những thứ không phải «dính lên» thì thường dùng <span class='gd-jp'>だらけ</span>：<span class='gd-jp'>傷だらけ</span>、<span class='gd-jp'>間違いだらけ</span>。<br>・Nó mang nghĩa tiêu cực. Chuyện tốt, thứ đẹp đẽ thường không dùng まみれ; nghĩa tích cực như «toàn hoa» hay «ngập tràn hạnh phúc» phải dùng cách nói khác.<br>・Đứng trước danh từ thì thêm 「の」: là <span class='gd-jp'>血まみれのシャツ</span>, không phải 血まみれシャツ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>だらけ</b>＝<b>nhiều, đâu đâu cũng có</b>（trọng tâm là số lượng nhiều, rải rác khắp nơi）：<span class='gd-jp'>この作文は間違いだらけだ。</span>（Bài văn này sai lỗi đầy rẫy）<br><b>まみれ</b>＝<b>dính đầy, bám kín cả một vùng trên bề mặt</b>（trọng tâm là bị chất lỏng hoặc bột phủ lên）：<span class='gd-jp'>顔が汗まみれだ。</span>（Mặt ướt đẫm mồ hôi）<br>Với bùn, mồ hôi, máu thì dùng được cả hai: <span class='gd-jp'>泥だらけ</span> và <span class='gd-jp'>泥まみれ</span> đều được, chỉ là まみれ gợi hình ảnh «dính kín mít» rõ hơn.</div><div class='gd-sec'><b>ずくめ</b>＝<b>từ đầu đến cuối đồng nhất một kiểu</b>（không nhất thiết tiêu cực, cũng có thể là chuyện tốt）：<span class='gd-jp'>黒ずくめの服</span>（trang phục đen từ đầu đến chân）、<span class='gd-jp'>いいことずくめ</span>（toàn chuyện tốt）<br><b>まみれ</b> thì là bị thứ bẩn dính đầy: <span class='gd-jp'>泥まみれの服</span>（quần áo dính đầy bùn）</div><div class='gd-warn'>Mẹo phán đoán: dính trên người, phủ đầy → まみれ; số lượng nhiều, đâu đâu cũng có → だらけ; đồng nhất một kiểu, toàn là → ずくめ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu hay được đem ra so sánh cùng nhóm là <span class='gd-jp'>〜ずくめ</span>（một màu, toàn là ～）, bạn nên xem tiếp. Học hai mẫu cùng lúc là cách khó bị lẫn nhất.</div>","n1-69":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を皮切りに」nghĩa là <b>“mở màn bằng ~”, “lấy ~ làm điểm xuất phát”</b>. Giống như concert thông báo “bắt đầu từ show ở Hà Nội, sau đó lưu diễn khắp cả nước”: show ở Hà Nội chính là 「皮切り」, tức là người chạy đầu tiên. Điểm quan trọng là <b>phía sau còn cả một chuỗi việc nối tiếp nhau</b>.</div><div class='gd-sec'>「皮切り」vốn chỉ mồi cứu ngải đầu tiên, mồi nóng nhất, đau nhất. Về sau nghĩa mở rộng thành “việc đầu tiên trong một chuỗi sự việc”.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Sự kiện, lưu diễn</span>Bắt đầu từ điểm dừng đầu tiên, rồi lần lượt đi tiếp từng nơi.</div><div class='gd-ex-line'>・<span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まった。</span>（Mở màn bằng buổi diễn ở Tokyo, chuyến lưu diễn toàn quốc đã bắt đầu）</div><div class='gd-sec'><span class='gd-tag'>Mở rộng kinh doanh</span>Từ cửa hàng đầu tiên, sản phẩm đầu tiên, rồi ngày càng nhiều thêm.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は渋谷店を皮切りに、各地に店舗を増やしている。</span>（Cửa hàng này khởi đầu từ chi nhánh Shibuya, rồi lần lượt mở thêm ở nhiều nơi）</div><div class='gd-sec'><span class='gd-tag'>Một người dẫn đầu, những người khác theo sau</span>Có người lên tiếng trước, mọi người liền nối tiếp theo.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言を皮切りに、次々と意見が出た。</span>（Anh ấy vừa lên tiếng là ý kiến của mọi người liên tục xuất hiện）</div><div class='gd-sec'>Vế sau thường đi kèm các từ như <span class='gd-jp'>次々と</span>（liên tiếp）、<span class='gd-jp'>相次いで</span>（nối tiếp nhau）、<span class='gd-jp'>各地で</span>（ở nhiều nơi）, để diễn tả “tiếp theo còn rất nhiều nữa”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Nối thẳng với danh từ：<span class='gd-pair'><span class='gd-jp'>東京公演</span> → <span class='gd-jp'>東京公演を皮切りに</span></span><br>Nếu là một hành động, thường dùng dạng danh từ hóa：<span class='gd-jp'>発売</span>（bắt đầu bán）、<span class='gd-jp'>開店</span>（khai trương）、<span class='gd-jp'>発言</span>（phát biểu）。<br>Thêm「して」phía sau thì nghĩa vẫn vậy, dùng cách nào cũng được. Tuy nhiên「を皮切りに」không có「して」gọn hơn và thường gặp hơn trong văn viết：<span class='gd-jp'>東京公演を皮切りにして</span>。<br>Ngoài ra bạn cũng sẽ gặp<span class='gd-jp'>を皮切りとして</span>, nghĩa tương tự.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Phía sau nhất định phải có “một chuỗi” sự việc</b>. Nếu chỉ xảy ra một việc thì không dùng được：<span class='gd-jp'>入学を皮切りに、一人暮らしを始めた</span>là sai, vì phía sau chỉ có một việc, phải đổi thành<span class='gd-jp'>入学をきっかけに</span>。<br>・Nó không đơn thuần là “bắt đầu từ ~”. Nếu chỉ nói mốc thời gian thì dùng「から」là đủ：<span class='gd-jp'>月曜日から仕事が始まる</span>, đừng nói thành 月曜日を皮切りに。<br>・<b>Ít dùng cho chuỗi việc xấu</b>. Những chuyện như động đất, tai nạn xảy ra liên tiếp thì người Nhật thường không dùng 皮切り, mà chủ yếu dùng cho những việc “diễn ra nối tiếp” như sự kiện, kinh doanh, giải đấu.<br>・Sắc thái khá trang trọng, rất hay gặp trong tin tức, bài báo, bài giới thiệu; nói chuyện với bạn bè thì ít dùng.</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Cùng là một buổi concert, nhưng dùng ngữ pháp khác nhau thì nghĩa khác hẳn nhau：<br><b>を皮切りに</b>＝buổi này là <b>điểm dừng đầu tiên</b>, phía sau còn nhiều buổi nữa：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブを皮切りに、彼らは全国を回った。</span>（Mở màn bằng buổi concert đó, họ đã đi khắp cả nước）</div><div class='gd-sec'><b>をきっかけに</b>＝nhờ việc này mà <b>có một thay đổi</b> (không nhất thiết có cả chuỗi)：</div><div class='gd-ex-line'>・<span class='gd-jp'>そのライブをきっかけに、彼らは有名になった。</span>（Nhờ buổi concert đó, họ trở nên nổi tiếng）</div><div class='gd-sec'><b>を限りに</b>＝hoàn toàn ngược lại, là <b>lần cuối cùng</b>, đến đây là hết：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日のライブを限りに、活動を休止する。</span>（Buổi concert hôm nay là buổi cuối, sau đó sẽ tạm ngừng hoạt động）</div><div class='gd-warn'>Mẹo phân biệt nhanh: “điểm đầu tiên, phía sau một chuỗi việc nối tiếp” dùng を皮切りに; “vì việc đó mà có thay đổi” dùng をきっかけに; “lần cuối, kết thúc tại đây” dùng を限りに.</div>","n1-75":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜きらいがある」nghĩa là <b>“có tật ~”, “có khuynh hướng ~”</b>, và nhất định là khuynh hướng <b>không tốt</b>. Giọng điệu giống cô giáo ghi vào sổ liên lạc “em này làm việc có khuynh hướng hấp tấp”: rõ ràng đang nói khuyết điểm, nhưng nói rất lịch sự và tế nhị. Phần lớn xuất hiện trong bài viết, bình luận, hoặc những cuộc nói chuyện khá trang trọng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ dạng từ điển＋きらいがある　<span class='gd-pair'><span class='gd-jp'>抱え込む</span> → <span class='gd-jp'>抱え込むきらいがある</span></span><br>Động từ dạng ない＋きらいがある　<span class='gd-pair'><span class='gd-jp'>聞かない</span> → <span class='gd-jp'>聞かないきらいがある</span></span><br>Danh từ＋の＋きらいがある　<span class='gd-pair'><span class='gd-jp'>独断</span> → <span class='gd-jp'>独断のきらいがある</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何でも一人で抱え込むきらいがある。</span>（Anh ấy có tật việc gì cũng ôm hết một mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は人の話を最後まで聞かないきらいがある。</span>（Cô ấy có tật không nghe người khác nói hết câu）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のやり方は独断のきらいがある。</span>（Cách làm của anh ấy hơi độc đoán）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>〜すぎるきらいがある</span>Đặc biệt hay dùng khi phê bình việc “làm quá mức”.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長は細かいことを気にしすぎるきらいがある。</span>（Trưởng phòng bên mình có tật quá để ý chuyện vụn vặt）</div><div class='gd-sec'><span class='gd-tag'>Nói về một nhóm người</span>Bình luận phong cách chung của một nhóm, một tổ chức hay xã hội.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近のニュースは話題性を重視しすぎるきらいがある。</span>（Tin tức dạo này có khuynh hướng quá coi trọng tính thời sự gây chú ý）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ Hán viết là「嫌い」, nhưng ở đây <b>không liên quan gì đến “ghét”</b>, nghĩa là “khuynh hướng, tật xấu”. Hiện nay thường viết thẳng bằng hiragana<span class='gd-jp'>きらい</span>。<br>・Chỉ dùng cho khuynh hướng <b>không tốt</b>. Muốn nói ai đó “chu đáo” thì không dùng được, phải nói<span class='gd-jp'>優しいところがある</span>。<br>・Mẫu này nói về <b>phong cách, tính cách thường ngày</b> của một người (hoặc nhóm), không phải một việc xảy ra một lần. “Hôm qua anh ấy đến muộn” thì không dùng きらいがある được.<br>・Khi nối với danh từ nhất định phải thêm「の」: đúng là<span class='gd-jp'>独断のきらいがある</span>, không phải「独断きらいがある」。<br>・Sắc thái khá cứng. Khi nói với bạn bè kiểu “anh ấy hay nghĩ quá nhiều” thì dùng<span class='gd-jp'>考えすぎるところがある</span>hoặc<span class='gd-jp'>考えすぎがちだ</span>sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Cùng nói về việc một người hay nghĩ theo hướng xấu：<br><b>がち</b>＝“thường hay ~, dễ ~”, trọng tâm là <b>tần suất nhiều</b>, dùng được trong hội thoại hằng ngày：<span class='gd-jp'>彼は物事を悲観的に考えがちだ。</span>（Anh ấy hay nghĩ sự việc theo hướng bi quan）<br><b>きらいがある</b>＝“có tật ~”, mang sắc thái <b>nhận xét tế nhị</b> về tính cách đối phương, thiên về văn viết：<span class='gd-jp'>彼は物事を悲観的に考えるきらいがある。</span>（Anh ấy có khuynh hướng nghĩ sự việc theo hướng bi quan）<br><b>気味</b>＝“hơi có cảm giác ~”, nói về <b>trạng thái nhẹ ngay lúc này</b>, không phải tính cách：<span class='gd-jp'>最近、ちょっと疲れ気味だ。</span>（Dạo này hơi mệt mệt）<br>Ngoài ra, がち còn dùng được cho thời tiết, hiện tượng tự nhiên（<span class='gd-jp'>冬は空気が乾燥しがちだ</span>, mùa đông không khí dễ bị khô）, còn きらいがある về cơ bản chỉ dùng để bình luận phong cách của người hoặc nhóm người.</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói chuyện thường ngày “hay ~” dùng がち; “hơi có cảm giác ~” dùng 気味; viết bình luận, lịch sự chỉ ra “thói xấu” của một người hay một nhóm thì dùng きらいがある.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thường đi cùng「ともすると・ともすれば」（hơi một chút là ~）：<span class='gd-jp'>人はともすると、楽な方を選ぶきらいがある。</span>（Con người hơi một chút là có xu hướng chọn con đường dễ dàng hơn）</div>","n1-80":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にとどまらず」chính là cách nói quen thuộc trên báo chí tiếng Việt: <b>「không chỉ giới hạn ở ～, mà còn lan sang ～」</b>. <span class='gd-jp'>とどまる</span> nghĩa là \"dừng lại tại chỗ\", nên <span class='gd-jp'>とどまらず</span> là \"không dừng lại ở đó\". Vế trước nêu một phạm vi nhỏ hơn, vế sau nối với phạm vi lớn hơn, giống như gợn sóng lan ra từng vòng.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Phạm vi mở rộng</span>Hay dùng nhất với những thứ có thể \"lan rộng\" như ảnh hưởng, thiệt hại thiên tai, độ nổi tiếng, hoạt động. Rất thường gặp trong tin tức, báo cáo, bài phát biểu; đây là cách nói mang tính văn viết và trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の人気は日本にとどまらず、アジア全体に広がっている。</span>（Độ nổi tiếng của cô ấy không chỉ ở Nhật Bản mà còn lan ra khắp châu Á）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は一つの会社にとどまらず、業界全体に関わる。</span>（Vấn đề này không chỉ liên quan đến một công ty mà còn ảnh hưởng đến toàn ngành）</div><div class='gd-sec'><span class='gd-tag'>Hành động tiến thêm một bước</span>Phía trước cũng có thể đặt một hành động, nghĩa là \"không chỉ làm đến mức ～, mà còn tiến xa hơn nữa ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>ボランティアたちは物資を届けるにとどまらず、被災者の話にも耳を傾けた。</span>（Các tình nguyện viên không chỉ chuyển hàng cứu trợ mà còn lắng nghe tâm sự của người bị nạn）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>国内</span> → <span class='gd-jp'>国内にとどまらず</span></span><br>Động từ thể từ điển (dạng nguyên mẫu tra trong từ điển)＋にとどまらず：<span class='gd-pair'><span class='gd-jp'>届ける</span> → <span class='gd-jp'>届けるにとどまらず</span></span><br>Bạn cũng hay thấy dạng thêm 「だけ」: <span class='gd-jp'>国内だけにとどまらず</span>, nghĩa giống nhau nhưng nhấn mạnh hơn một chút.</div><div class='gd-sec'>Khi đặt ở cuối câu hoặc bổ nghĩa cho danh từ, đổi thành <b>にとどまらない</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は音楽にとどまらない。</span>（Tài năng của anh ấy không chỉ giới hạn ở âm nhạc）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Là <span class='gd-jp'>とどまる</span>, không phải <span class='gd-jp'>とまる</span>. <span class='gd-jp'>涙が止まらない</span> nghĩa là \"nước mắt không ngừng rơi\", hoàn toàn không liên quan đến mẫu ngữ pháp này, đừng bỏ sót 「とど」 nhé.<br>・Phía sau nhất định phải nối với <b>phạm vi lớn hơn</b>, thường đi với 「も」「まで」「へと」: <span class='gd-jp'>海外にも</span>、<span class='gd-jp'>全国へと</span>. Nếu chỉ nói nửa câu đầu thì câu sẽ bị lửng, chưa trọn ý.<br>・Mẫu này rất trang trọng, đừng dùng cho chuyện nhỏ hằng ngày. Muốn nói \"mình không chỉ ăn ramen mà còn ăn cả sushi\" thì chỉ cần <span class='gd-jp'>ラーメンだけじゃなくて、寿司も食べた</span>; dùng にとどまらず sẽ nghe như đang đọc thông cáo báo chí.<br>・Dạng không phủ định <span class='gd-jp'>にとどまる</span> cũng rất hay gặp, nghĩa ngược lại là \"chỉ dừng ở ～\": <span class='gd-jp'>今回の値上げは一部の商品にとどまる。</span>（Đợt tăng giá lần này chỉ giới hạn ở một số mặt hàng）</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng nói về một bộ anime nổi tiếng:<br><b>だけでなく</b>＝cách nói \"không chỉ ～ mà còn ～\" thông dụng nhất, dùng được mọi hoàn cảnh: <span class='gd-jp'>このアニメは子どもだけでなく、大人にも人気だ。</span>（Bộ anime này không chỉ trẻ em mà người lớn cũng thích）<br><b>に限らず</b>＝không giới hạn ở một nhóm nào, <b>thay bằng nhóm khác cũng vậy</b>: <span class='gd-jp'>このアニメは子どもに限らず、大人にも人気だ。</span>（Không riêng trẻ em, người lớn cũng thích＝ai cũng thích）<br><b>にとどまらず</b>＝phạm vi <b>lan rộng ra ngoài</b>: <span class='gd-jp'>このアニメの人気は日本にとどまらず、世界中に広がっている。</span>（Độ nổi tiếng không chỉ ở Nhật mà còn lan ra khắp thế giới）<br><b>はおろか</b>＝vế trước thì khỏi phải nói, <b>đến cả trường hợp cực đoan nhất</b> cũng ～: <span class='gd-jp'>このアニメは、子どもはおろか、お年寄りまで知っている。</span>（Trẻ em thì khỏi nói, đến cả người già cũng biết）</div><div class='gd-warn'>Mẹo phân biệt: ảnh hưởng, phạm vi \"càng lúc càng rộng\" thì dùng にとどまらず; \"không giới hạn nhóm nào\" thì dùng に限らず; \"đến cả trường hợp cực đoan nhất cũng…\" thì dùng はおろか; không chắc thì dùng だけでなく, an toàn nhất.</div>","n1-81":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜すら」tương đương với <b>「đến cả ～ cũng…」</b> trong tiếng Việt. Bạn nêu ra một ví dụ cơ bản nhất, ít có khả năng xảy ra vấn đề nhất, để làm nổi bật mức độ nghiêm trọng của tình huống: <span class='gd-jp'>名前すら知らない</span>, đến cả tên cũng không biết, thì những chuyện khác càng khỏi phải nói. Nghĩa gần giống 「さえ」, nhưng <b>giọng cứng hơn, mang tính văn viết hơn</b>, thường xuất hiện trong bài viết, tin tức, bình luận.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋すら</span>Cách nối cơ bản nhất. Trợ từ 「が」「を」 gốc được thay trực tiếp bằng すら.<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間すらない</span></span>（đến cả thời gian cũng không có）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、食事する時間すらない。</span>（Bận đến mức đến cả thời gian ăn cơm cũng không có）</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋ですら</span>Rất hay dùng khi phía trước là \"người\" và người đó là chủ thể của hành động. 「で」 ở đây không mang nghĩa \"ở\", bạn cứ nhớ nguyên cụm 「ですら」 là được.</div><div class='gd-ex-line'>・<span class='gd-jp'>専門家ですら答えられない問題だ。</span>（Đây là vấn đề mà đến cả chuyên gia cũng không trả lời được）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもですら知っていることだ。</span>（Đây là chuyện mà đến cả trẻ con cũng biết）</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋に・と v.v.＋すら</span>Các trợ từ như 「に」「と」 phải giữ lại, すら thêm vào phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>このことは親にすら話していない。</span>（Chuyện này mình chưa nói với ai, đến cả bố mẹ cũng không）</div><div class='gd-sec'><span class='gd-tag'>Thể て＋すらいない</span>Nhấn mạnh vào <b>chính hành động</b>: đến cả bước \"làm\" cũng chưa làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はメールを読んですらいない。</span>（Email đó anh ấy đến đọc cũng chưa đọc）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・すら<b>không chỉ đi với phủ định</b>. Phần lớn phía sau là 「ない」, nhưng câu khẳng định như <span class='gd-jp'>子どもですら知っている</span> cũng rất tự nhiên.<br>・「に」「と」 không được bỏ: phải nói <span class='gd-jp'>親にすら</span>, không thể nói 親すら話していない.<br>・<span class='gd-jp'>メールすら読んでいない</span> là \"đến cả email cũng chưa đọc\" (trọng tâm ở email), còn <span class='gd-jp'>メールを読んですらいない</span> là \"đến đọc cũng chưa đọc\" (trọng tâm ở hành động đọc). すら đặt ở vị trí khác nhau thì phần được nhấn mạnh cũng khác.<br>・すら có giọng khá cứng, khi trò chuyện với bạn bè thì nói <span class='gd-jp'>名前も知らない</span> hoặc <span class='gd-jp'>名前さえ知らない</span> sẽ tự nhiên hơn.<br>・すら thường mang cảm giác \"ngạc nhiên, sững sờ, chê trách\", ít khi dùng để khen ai.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>すら</b> và <b>さえ</b> với nghĩa \"đến cả ～ cũng\" gần như có thể thay thế cho nhau:<br><span class='gd-jp'>名前すら知らない。</span>／<span class='gd-jp'>名前さえ知らない。</span>（đến cả tên cũng không biết）<br>Khác biệt là すら mang tính văn viết hơn, và さえ còn có một cách dùng mà すら <b>không có</b>: 「〜さえ〜ば」＝chỉ cần ～ là được.<br><span class='gd-jp'>時間さえあれば行ける。</span>（Chỉ cần có thời gian là đi được）<br>Câu này <b>không thể</b> đổi sang すら.</div><div class='gd-warn'>Mẹo phân biệt: nghĩa \"đến cả ～ cũng\" thì dùng cái nào cũng được, viết văn thì すら nghe mạnh mẽ hơn; nghĩa \"chỉ cần ～ là\" thì chỉ dùng được さえ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>すら rất hay đi cùng 「<span class='gd-jp'>〜はおろか</span>」 (đừng nói ～, ngay cả...), vế trước nói chuyện khó, vế sau nói chuyện dễ:<br><span class='gd-jp'>漢字はおろか、ひらがなすら書けない。</span>（Chữ Hán thì khỏi nói, đến cả hiragana cũng không viết được）</div>","n1-1":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に至っては」nghĩa là <b>\"riêng về ~ thì còn quá đáng hơn, thậm chí còn…\"</b>. Trước tiên bạn nói tình hình chung của cả nhóm hoặc cả sự việc, rồi chọn ra <b>trường hợp quá đáng nhất</b> để nhấn mạnh.<br>Giống như khi bạn than: \"Nhà mình ai cũng hay nướng giường, <b>riêng ba mình thì còn quá đáng hơn</b>, ngủ tới trưa vẫn không chịu dậy.\"</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋に至っては。<br><span class='gd-pair'><span class='gd-jp'>父</span> → <span class='gd-jp'>父に至っては</span></span><span class='gd-pair'><span class='gd-jp'>数学</span> → <span class='gd-jp'>数学に至っては</span></span><br>Cả câu thường có dạng: <b>nói tình hình chung → 〇〇に至っては → chuyện cực đoan nhất</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの家族はみんな朝が弱い。父に至っては、昼まで起きてこない。</span>（Nhà mình ai cũng sáng ra là không dậy nổi, riêng ba mình còn quá đáng hơn, ngủ đến trưa vẫn không chịu dậy.）</div><div class='gd-ex-line'>・<span class='gd-jp'>成績が悪く、数学に至っては赤点だ。</span>（Điểm số tệ, riêng môn Toán thậm chí còn bị rớt.）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議では誰も意見を言わなかった。部長に至っては、最初から最後まで寝ていた。</span>（Trong cuộc họp không ai phát biểu ý kiến, riêng trưởng phòng còn quá đáng hơn, ngủ từ đầu đến cuối.）</div><div class='gd-sec'>Vế sau thường đi với những cách nói nhấn mạnh như 「<span class='gd-jp'>さえ</span>」「<span class='gd-jp'>まで</span>」「<span class='gd-jp'>一度も〜ない</span>」 để cảm giác \"quá đáng\" rõ hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định phải có một <b>tổng thể</b> (một nhóm người, vài môn học, cả sự việc) thì mới \"chọn ra cái quá đáng nhất\" được. Nếu tự nhiên nói một câu 「父に至っては…」 mà trước đó chưa nói gì, người Nhật sẽ không hiểu bạn đang so sánh với cái gì.<br>・Hầu như chỉ dùng cho <b>chuyện xấu, chuyện khiến người ta cạn lời</b>. Dùng để khen kiểu \"cậu ấy còn giỏi hơn, được điểm tuyệt đối\" nghe sẽ rất lạ.<br>・Điều nói ở vế sau phải thật sự ở mức <b>cực đoan nhất</b>; nếu chỉ ở mức bình thường thì dùng mẫu câu này sẽ nghe như làm quá lên.<br>・Đây là cách nói thiên về văn viết, trang trọng. Khi trò chuyện với bạn bè, người ta hay nói 「<span class='gd-jp'>父なんか、昼まで寝てるよ</span>」 hơn.<br>・Cách đọc là <b>いたっては</b>, chữ 「至」 đọc là いた.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>に至っては</b>＝trong tổng thể, <b>chọn ra một trường hợp quá đáng nhất</b> (phần lớn mang nghĩa tiêu cực):<br>・<span class='gd-jp'>部屋はどこも汚かった。台所に至っては、足の踏み場もなかった。</span>（Phòng nào cũng bẩn, riêng nhà bếp còn tệ hơn, đến chỗ đặt chân cũng không có.）<br><b>に至るまで</b>＝từ A đến B, <b>bao gồm tất cả</b>, nhấn mạnh phạm vi rộng, tốt hay xấu đều dùng được:<br>・<span class='gd-jp'>リビングから台所に至るまで、全部きれいに掃除した。</span>（Từ phòng khách đến nhà bếp, tất cả đều đã được dọn sạch sẽ.）</div><div class='gd-sec'><b>ときたら</b>＝đơn giản là lôi một người ra để <b>phàn nàn</b>, phía trước không cần nói về cả một nhóm người, giọng khẩu ngữ hơn và mang sự bất mãn:<br>・<span class='gd-jp'>うちの父ときたら、毎晩飲んで帰ってくる。</span>（Nói đến ba mình thì tối nào cũng nhậu xong mới về.）<br>・<span class='gd-jp'>家族はみんなお酒好きだが、父に至っては毎晩飲んで帰ってくる。</span>（Cả nhà ai cũng thích uống rượu, riêng ba mình còn quá đáng hơn, tối nào cũng nhậu xong mới về.）</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói \"ai cũng ~\" rồi mới nói \"trong đó, người nào đó còn quá đáng hơn\" → に至っては; \"từ A đến B, tất cả\" → に至るまで; chỉ đơn giản là \"nhắc đến người nào đó là thấy bó tay\" → ときたら.</div>","n1-4":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たりとも…ない」nghĩa là <b>\"đến một ~ cũng không…\"</b>, và là phiên bản nhấn mạnh hơn. Giống như có người đập bàn nói \"Một xu cũng không đưa!\", \"Một phút cũng không được lãng phí!\" — giọng <b>dứt khoát, tuyệt đối không nhượng bộ</b> đó, tiếng Nhật dùng たりとも.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Công thức rất cố định: <b>「一」＋ lượng từ ＋たりとも＋ phủ định</b>.<br><span class='gd-pair'><span class='gd-jp'>一日</span> → <span class='gd-jp'>一日たりとも</span></span>（đến một ngày cũng）<br><span class='gd-pair'><span class='gd-jp'>一円</span> → <span class='gd-jp'>一円たりとも</span></span>（đến một yên cũng）<br><span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>一人たりとも</span></span>（đến một người cũng）<br>Phía sau <b>nhất định phải là phủ định</b>: như <span class='gd-jp'>〜ない</span>、<span class='gd-jp'>〜ません</span>、<span class='gd-jp'>〜できない</span>、<span class='gd-jp'>許されない</span>、<span class='gd-jp'>〜するな</span>.<br>Các cặp hay gặp nhất: <span class='gd-jp'>一秒</span>、<span class='gd-jp'>一瞬</span>、<span class='gd-jp'>一日</span>、<span class='gd-jp'>一円</span>、<span class='gd-jp'>一人</span>、<span class='gd-jp'>一歩</span>、<span class='gd-jp'>一滴</span>、<span class='gd-jp'>一度</span>, đều là \"đơn vị nhỏ nhất\", nhấn mạnh rằng dù chỉ một chút như vậy cũng không được.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Quyết tâm mạnh mẽ</span>Bản thân tuyệt đối không muốn, không định làm việc gì đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>残り時間、一秒たりとも無駄にしたくない。</span>（Thời gian còn lại, mình không muốn lãng phí dù chỉ một giây）</div><div class='gd-sec'><span class='gd-tag'>Quy định, mệnh lệnh</span>Cấm, không cho phép; cấp trên, huấn luyện viên, thông báo rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合が終わるまで、一瞬たりとも気を抜くな。</span>（Cho đến khi trận đấu kết thúc, không được lơ là dù chỉ một khoảnh khắc）</div><div class='gd-ex-line'>・<span class='gd-jp'>医療ミスは一件たりとも許されない。</span>（Sai sót y khoa thì dù chỉ một vụ cũng không được phép xảy ra）</div><div class='gd-sec'><span class='gd-tag'>Cảm xúc mãnh liệt</span>Thường đi với 「〜たことはない」, diễn tả \"chưa từng có lần nào\".</div><div class='gd-ex-line'>・<span class='gd-jp'>君のことを一日たりとも忘れたことはない。</span>（Anh chưa từng quên em dù chỉ một ngày）</div><div class='gd-h'>Một cách nói cố định đặc biệt</div><div class='gd-sec'><span class='gd-jp'>何人たりとも</span>＝\"bất kể là ai cũng không được ~\". Ở đây 何人 đọc là <b>なんぴと</b>, là văn viết rất cứng, hay xuất hiện trong thông báo, tiểu thuyết, lời thoại anime.</div><div class='gd-ex-line'>・<span class='gd-jp'>何人たりとも、ここに立ち入ることは許さない。</span>（Bất kể là ai, cũng không được phép bước vào đây）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước chỉ có thể là <b>「一」</b>: <span class='gd-jp'>二日たりとも</span>、<span class='gd-jp'>三人たりとも</span> đều sai. Điều cần nhấn mạnh chính là \"lượng nhỏ nhất\".<br>・Phía sau <b>nhất định là phủ định</b>, không thể nói câu khẳng định kiểu 「一日たりとも休む」.<br>・Sau lượng từ thì nối thẳng たりとも, đừng thêm 「も」 hay 「の」: nói 「一日もたりとも」 là sai.<br>・Giọng rất nặng, thiên về văn viết. Trong giao tiếp hằng ngày, nói <span class='gd-jp'>一円も払わない</span> là đủ rồi, đổi sang たりとも sẽ nghe như đang thề thốt hay tuyên bố.<br>・Nếu chỉ mô tả sự thật (ví dụ \"trong lớp không có một học sinh nào\") thì dùng <span class='gd-jp'>一人もいなかった</span> tự nhiên hơn; たりとも hợp với quyết tâm, quy định, cảm xúc mạnh.<br>・何人たりとも thì 何人 đọc là なんぴと, không phải なんにん.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về \"tiền\", hãy xem ba cách nói:<br><b>一〜も…ない</b>＝chỉ đơn giản nói \"không có lấy một cái\", trung tính, dùng trong đời sống: <span class='gd-jp'>財布には一円もない。</span>（Trong ví không có lấy một yên）<br><b>一〜たりとも…ない</b>＝mang quan điểm mạnh mẽ, tuyệt đối không nhượng bộ: <span class='gd-jp'>税金は一円たりとも無駄にできない。</span>（Tiền thuế thì dù chỉ một yên cũng không thể lãng phí）<br><b>すら</b>＝đưa ra một \"thứ cơ bản nhất\" để nhấn mạnh, phía trước không cần là \"一＋lượng từ\": <span class='gd-jp'>今月は電車代すらない。</span>（Tháng này đến tiền đi tàu điện cũng không có）</div><div class='gd-warn'>Mẹo phân biệt nhanh: chỉ đơn thuần nói \"không có lấy một cái\" thì dùng も; \"一＋lượng từ\" cộng thêm giọng quyết tâm, cấm đoán, tuyệt đối không cho phép thì dùng たりとも; nêu ra \"đến cả thứ cơ bản như vậy mà cũng ~\" thì dùng すら.</div>","n1-12":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AこそあれB（ない）」nghĩa là <b>\"A thì có, còn B thì không\"</b>. Nói đời thường hơn là <b>\"chỉ có A, không có B\"</b>, kiểu như \"Với anh ấy tôi chỉ có biết ơn, không có oán hận\". Đây là văn viết rất cứng. Khi trò chuyện hằng ngày, bạn chỉ cần nói「<span class='gd-jp'>Aはあっても、Bはない</span>」là đủ.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chỉ có A, không có B</span>Đặt hai thứ <b>trái ngược hoặc đối lập</b> ở hai vế, ví dụ biết ơn và oán hận, chê bai và khen ngợi. Bạn thừa nhận A có thật, rồi nhấn mạnh B ở vế sau \"hoàn toàn không có\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には感謝こそあれ、恨みは少しもない。</span>(Với anh ấy chỉ có biết ơn, một chút oán hận cũng không có)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の行動には批判こそあれ、賞賛の声はほとんど聞かれない。</span>(Hành động của anh ta chỉ có chỉ trích, hầu như không nghe thấy lời khen nào)</div><div class='gd-sec'><span class='gd-tag'>Cách nói cố định</span><span class='gd-jp'>程度の差こそあれ</span>、<span class='gd-jp'>多少の違いこそあれ</span>＝\"Tuy mức độ có khác nhau, nhưng……\". Lúc này vế sau <b>không nhất thiết là phủ định</b>, thường dùng để nói \"thật ra ai cũng như nhau\".</div><div class='gd-ex-line'>・<span class='gd-jp'>程度の差こそあれ、誰にでも悩みはある。</span>(Tuy mức độ khác nhau, nhưng ai cũng có nỗi phiền muộn)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ + こそあれ, nối thẳng: <span class='gd-pair'><span class='gd-jp'>感謝</span> → <span class='gd-jp'>感謝こそあれ</span></span><span class='gd-pair'><span class='gd-jp'>批判</span> → <span class='gd-jp'>批判こそあれ</span></span><br>Vế sau thường kết thúc bằng「<span class='gd-jp'>〜はない</span>」「<span class='gd-jp'>ほとんど〜ない</span>」「<span class='gd-jp'>〜ことはない</span>」.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>danh từ</b>. Không nối trực tiếp với động từ dạng từ điển, nói「批判するこそあれ」là sai. Muốn dùng động từ, hãy dùng「こそすれ」ở bên dưới, và nối bằng <b>thể ます bỏ ます</b>.<br>・Nghĩa của nó <b>không phải</b> \"chính vì có ～\". Đây là hiểu lầm hay gặp trong giáo trình cũ, còn \"chính vì\" là một mẫu ngữ pháp khác.<br>・Hai vế phải là cặp đối lập trong cùng một chủ đề. Nếu hai vế chẳng liên quan gì nhau, ví dụ \"lễ hội có nét giản dị nhưng không có dấu hiệu suy tàn\", người Nhật nghe sẽ thấy kỳ.<br>・Giọng văn rất trang trọng, hay xuất hiện trong bài viết, bài bình luận, bài diễn thuyết. Nói với bạn bè nghe sẽ như đang đọc công văn.</div><div class='gd-h'>Phân biệt với mẫu giống nhau</div><div class='gd-sec'><b>こそすれ</b>cũng là \"chỉ có A, không có B\", khác ở chỗ phía trước là <b>hành động</b>.<br>Cách nối: <b>động từ thể ます (bỏ ます) ＋ こそすれ</b><br><span class='gd-pair'><span class='gd-jp'>上がります</span> → bỏ ます → <span class='gd-jp'>上がりこそすれ</span></span><br><span class='gd-pair'><span class='gd-jp'>褒められます</span> → bỏ ます → <span class='gd-jp'>褒められこそすれ</span></span><br>Động từ する có thể dùng「danh từ＋こそすれ」hoặc「し＋こそすれ」: <span class='gd-pair'><span class='gd-jp'>感謝します</span> → <span class='gd-jp'>感謝こそすれ</span>／<span class='gd-jp'>感謝しこそすれ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がりこそすれ、下がることはないだろう。</span>(Giá cả chỉ có tăng, chắc sẽ không giảm đâu)</div><div class='gd-ex-line'>・<span class='gd-jp'>褒められこそすれ、叱られる理由はない。</span>(Đáng được khen mới đúng, không có lý do gì bị mắng)</div><div class='gd-sec'>So sánh trong cùng một tình huống:<br><span class='gd-jp'>彼女には感謝こそあれ、恨みはない。</span>(Trong lòng tôi <b>có</b> lòng biết ơn: nói về \"sự tồn tại\")<br><span class='gd-jp'>彼女には感謝こそすれ、恨むことはない。</span>(Điều tôi <b>làm</b> là cảm ơn cô ấy: nói về \"hành động\")<br>Nghĩa của hai câu trong tiếng Việt gần như giống nhau.</div><div class='gd-sec'>Ngoài ra, \"chính vì ～ nên mới ～\" là <span class='gd-jp'>〜ばこそ</span>; \"chỉ khi ～ mới ～\" là <span class='gd-jp'>〜てこそ</span>, ví dụ <span class='gd-jp'>努力してこそ成功できる</span> (chỉ khi nỗ lực mới thành công được). Đừng thấy cùng có こそ mà lẫn với こそあれ nhé.</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước là <b>danh từ</b> (感謝、批判、差) thì dùng こそあれ; phía trước là <b>động từ</b> thì dùng こそすれ, và động từ phải chuyển sang thể ます rồi bỏ ます, ví dụ「上がり（こそすれ）」「褒められ（こそすれ）」「感謝し（こそすれ）」. Tuyệt đối đừng viết thành「褒められるこそすれ」.</div>","n1-13":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜まで（のこと）だ」giống cách nói <b>\"cùng lắm thì ～ thôi\"</b> và <b>\"tôi chỉ ～ thôi mà\"</b>. <span class='gd-jp'>まで</span> vốn là \"đến\", ở đây bạn có thể hiểu là <b>\"sự việc cùng lắm chỉ đến bước này thôi, không có gì to tát\"</b>. Phía trước là dạng từ điển hay thể た thì nghĩa khác nhau, mình sẽ nói riêng bên dưới.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Dạng từ điển: cùng lắm thì ～</span>Khi kế hoạch không suôn sẻ, bạn đã nghĩ sẵn đường lui và có thái độ \"không sao, cứ làm vậy thôi\". Phía trước hay có「〜なら」「〜ば」「〜ても」, nêu trước trường hợp không thuận lợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>だめなら、また一からやり直すまでだ。</span>(Nếu không được thì cùng lắm làm lại từ đầu)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も手伝ってくれないなら、一人でやるまでだ。</span>(Nếu không ai giúp thì tôi tự làm một mình thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が動かなければ、歩いて帰るまでのことだ。</span>(Nếu tàu điện ngừng chạy thì cùng lắm đi bộ về)</div><div class='gd-sec'><span class='gd-tag'>Thể た: chỉ là ～ thôi</span>Dùng để giải thích việc mình đã làm, với ý \"không có ý gì khác\", \"chẳng có gì ghê gớm\". Rất hay dùng khi được người khác cảm ơn, nghe khiêm tốn.</div><div class='gd-ex-line'>・<span class='gd-jp'>当然のことをしたまでです。</span>(Tôi chỉ làm việc đương nhiên phải làm thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>念のため、確認したまでです。</span>(Tôi chỉ kiểm tra lại cho chắc thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったことを言ったまでだ。</span>(Tôi chỉ nói ra điều mình nghĩ thôi)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ dạng từ điển＋までだ／までのことだ: <span class='gd-pair'><span class='gd-jp'>やり直す</span> → <span class='gd-jp'>やり直すまでだ</span></span><br>Động từ thể た＋までだ／までのことだ: <span class='gd-pair'><span class='gd-jp'>した</span> → <span class='gd-jp'>したまでです</span></span><br>Có hay không có「<span class='gd-jp'>のこと</span>」thì nghĩa vẫn như nhau, thêm vào thì càng có cảm giác \"chỉ có vậy thôi\". Muốn nói lịch sự, chỉ cần đổi <span class='gd-jp'>だ</span> thành <span class='gd-jp'>です</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>まで</span> ở đây không phải \"cho đến khi\". <span class='gd-jp'>帰るまで</span> đứng một mình có nghĩa là \"cho đến khi về nhà\", nên hãy xem phía sau có kết thúc bằng <span class='gd-jp'>だ</span> hay không.<br>・Đừng nối nhầm dạng từ điển và thể た: <span class='gd-jp'>やり直すまでだ</span> là \"cùng lắm làm lại\" (chưa làm), còn <span class='gd-jp'>やり直したまでだ</span> là \"tôi chỉ làm lại thôi\" (đã làm rồi).<br>・Cách dùng dạng từ điển mang giọng \"liều thì liều\", thường nói về quyết tâm của <b>chính mình</b>, không dùng để bảo người khác làm.<br>・Phía trước thường là phương án dự phòng \"vốn không phải lựa chọn đầu tiên nhưng cũng không sao\", chứ không phải chuyện đáng mừng.</div><div class='gd-h'>Phân biệt với mẫu giống nhau</div><div class='gd-sec'><b>〜までだ</b>＝cùng lắm thì làm: <span class='gd-jp'>聞かれたら、説明するまでだ。</span>(Nếu bị hỏi thì giải thích là xong)<br><b>〜までもない</b>＝hoàn toàn không cần làm: <span class='gd-jp'>簡単だから、説明するまでもない。</span>(Đơn giản nên không cần giải thích)</div><div class='gd-sec'><b>〜までだ</b>＝còn đường lui, lạc quan: <span class='gd-jp'>失敗したら、またやるまでだ。</span>(Thất bại thì cùng lắm làm lại)<br><b>〜ばそれまでだ</b>＝hễ thế là xong hết, bi quan: <span class='gd-jp'>一度失敗すれば、それまでだ。</span>(Chỉ cần thất bại một lần là hết)</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"động từ＋までだ\" là vẫn còn đường đi; \"それまでだ\" là đường đã cụt; \"までもない\" là không cần đi đường này.</div>","n1-5":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜であれ」nghĩa là <b>“dù là ~ thì cũng…”, “cho dù là ~ cũng…”</b>. Ví dụ: “dù là ai cũng phải xếp hàng”, “cho dù là giám đốc cũng phải tuân thủ quy tắc”. Phần phía trước thay bằng gì cũng được, kết luận phía sau vẫn không đổi. Mẫu này rất trang trọng, thường xuất hiện trong tin tức, bài diễn thuyết và văn viết.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước là <b>danh từ</b>, thêm であれ trực tiếp: <span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長であれ</span></span><br>Tính từ đuôi な thì bỏ 「な」, rồi thêm であれ: <span class='gd-pair'><span class='gd-jp'>有名な</span> → <span class='gd-jp'>有名であれ</span></span><br>Cũng có thể đặt các từ nghi vấn như 「誰、何、どんな～」 ở phía trước: <span class='gd-pair'><span class='gd-jp'>誰</span> → <span class='gd-jp'>誰であれ</span></span><span class='gd-pair'><span class='gd-jp'>どう</span> → <span class='gd-jp'>どうであれ</span></span><br>Thực ra 「であれ」 là thể mệnh lệnh của 「である」 (cách nói văn viết của 「だ」, hay dùng trong bài viết). Nhưng ở đây nó <b>không có nghĩa bảo ai làm gì</b>; đây là cách dùng nhượng bộ kiểu “là gì cũng như nhau”, nghĩa là “cho dù là ~”.</div><div class='gd-h'>Ba dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>たとえ＋名詞＋であれ</span>Dù là một thân phận hay hoàn cảnh đặc biệt nào đó thì cũng vậy. Phía trước hay thêm 「たとえ」 (cho dù) để nhấn mạnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ子供であれ、自分のしたことには責任がある。</span>（Cho dù là trẻ con thì cũng phải chịu trách nhiệm về việc mình đã làm）</div><div class='gd-sec'><span class='gd-tag'>誰／何／どんな～＋であれ</span>Dù là ai, dù là cái gì, tất cả đều như nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰であれ、許可なく入ることはできない。</span>（Dù là ai, không có phép cũng không được vào）</div><div class='gd-ex-line'>・<span class='gd-jp'>理由はどうであれ、約束を破ったのは事実だ。</span>（Dù lý do là gì, việc đã thất hứa vẫn là sự thật）</div><div class='gd-sec'><span class='gd-tag'>AであれBであれ</span>Dù là A hay B, kết quả đều như nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>男であれ女であれ、能力があれば評価される。</span>（Dù là nam hay nữ, có năng lực thì sẽ được công nhận）</div><div class='gd-ex-line'>・<span class='gd-jp'>晴れであれ雨であれ、試合は予定どおり行う。</span>（Dù trời nắng hay mưa, trận đấu vẫn diễn ra đúng kế hoạch）</div><div class='gd-sec'>Vế sau thường là <b>một kết luận không vì thế mà thay đổi</b>, hay gặp 「〜できない」「許されない」「〜べきだ」「変わりはない」.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là danh từ hoặc thân của tính từ đuôi な, động từ không nối trực tiếp được: <b>không thể nói</b> 「行くであれ」. Muốn đặt động từ ở phía trước thì đổi sang 「〜ようが」 hoặc 「〜にせよ」.<br>・Mẫu này khá cứng, dùng khi nói chuyện thường ngày sẽ nghe lạ. Trong khẩu ngữ hãy đổi sang 「でも」, ví dụ: <span class='gd-jp'>誰でも許可が必要だよ。</span>（Ai cũng cần có giấy phép đấy）<br>・Muốn nói “không ai được vào” thì dùng <span class='gd-jp'>誰も入れない</span>, đừng nói <span class='gd-jp'>誰でも入れない</span> (nghe rất không tự nhiên). Nếu muốn nói “không phải ai cũng vào được” thì nói <span class='gd-jp'>誰でも入れるわけではない</span>.<br>・<span class='gd-jp'>であれ</span> và <span class='gd-jp'>であれば</span> chỉ khác nhau một chữ, nhưng nghĩa hoàn toàn khác. であれば là “nếu là ~”: <span class='gd-jp'>社長であれば決められる。</span>（Nếu là giám đốc thì có thể quyết định）; còn であれ là “cho dù là ~ cũng”: <span class='gd-jp'>社長であれ、勝手には決められない。</span>（Cho dù là giám đốc cũng không được tự ý quyết định）</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng nói “dù lý do là gì, đi trễ là không được”:<br><b>であれ</b>: phía trước là danh từ hoặc thân tính từ đuôi な, trang trọng nhất.<br><span class='gd-jp'>どんな理由であれ、遅刻は許されない。</span><br><b>にせよ</b>: phía trước có thể là danh từ hoặc động từ, bớt cứng hơn một chút.<br><span class='gd-jp'>どんな理由にせよ、遅刻はよくない。</span><br><span class='gd-jp'>行くにせよ行かないにせよ、連絡してください。</span>（Dù đi hay không đi, cũng hãy liên lạc cho tôi）<br><b>ようが／ようと</b>: phía trước là thể ý chí của động từ (dạng 〜う／〜よう), sắc thái là “dù ~ thế nào đi nữa cũng mặc”.<br><span class='gd-jp'>どんな理由があろうと、遅刻は許されない。</span></div><div class='gd-warn'>Mẹo nhỏ để chọn: phía trước là danh từ và hoàn cảnh rất trang trọng thì dùng であれ; phía trước muốn đặt động từ thì dùng にせよ hoặc ようが.</div><div class='gd-h'>Sau khi học xong, bạn có thể học tiếp</div><div class='gd-sec'>Mẫu cùng kiểu “dù A hay B” còn có 「〜にせよ…にせよ」, và các cách nói cố định 「〜かれ〜かれ」: <span class='gd-jp'>多かれ少なかれ</span> (ít nhiều), <span class='gd-jp'>遅かれ早かれ</span> (sớm muộn gì).</div>","n1-6":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とあれば」nghĩa là <b>“nếu là ~ thì (tôi) sẽ…”</b>. Phía trước là <b>một lý do đặc biệt, có sức nặng</b>, như “vì con cái”, “lệnh của sếp”, “bạn thân nhờ”; phía sau là “vậy thì tôi sẵn lòng làm” hoặc “vậy thì đành làm”. Giống như trong tiếng Việt ta nói “vì con thì khổ mấy cũng cam lòng” vậy.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>子供のため</span> → <span class='gd-jp'>子供のためとあれば</span></span><br>Tính từ đuôi な cũng nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>必要</span> → <span class='gd-jp'>必要とあれば</span></span><br>Động từ dùng thể thường (dạng từ điển, thể ない hoặc thể た): <span class='gd-pair'><span class='gd-jp'>社長が来る</span> → <span class='gd-jp'>社長が来るとあれば</span></span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Sẵn lòng hy sinh</span>Vì người hoặc việc quan trọng, việc gì cũng sẵn sàng làm. Hay đi cùng 「のため」 nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のためとあれば、親はどんな苦労も厭わない。</span>（Hễ là vì con, cha mẹ vất vả đến mấy cũng cam lòng）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のためとあれば、どんな仕事でもする。</span>（Hễ là vì gia đình, công việc gì tôi cũng làm）</div><div class='gd-sec'><span class='gd-tag'>Đành chấp nhận</span>Thân phận hoặc hoàn cảnh của đối phương đặc biệt, không làm thì khó coi.</div><div class='gd-ex-line'>・<span class='gd-jp'>親友の頼みとあれば、断るわけにはいかない。</span>（Đã là bạn thân nhờ thì không thể từ chối được）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（Đã là lệnh của giám đốc thì chỉ còn cách làm theo）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Trong môi trường công sở, bạn sẽ rất hay nghe hai câu cố định này:</div><div class='gd-ex-line'>・<span class='gd-jp'>必要とあれば、いつでもご連絡ください。</span>（Nếu cần thì xin cứ liên lạc với tôi bất cứ lúc nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>お客様のご希望とあれば、できる限り対応いたします。</span>（Nếu là mong muốn của quý khách, chúng tôi sẽ cố gắng đáp ứng hết mức có thể）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>một lý do có sức nặng</b>. Điều kiện thường ngày thì không dùng: “nếu trời mưa thì mang ô” nói là <span class='gd-jp'>雨なら傘を持っていく</span>, nói thành 「雨とあれば」 nghe rất lạ.<br>・Phía sau thường là <b>quyết tâm hoặc phán đoán</b>, như <span class='gd-jp'>何でもする</span>、<span class='gd-jp'>喜んで</span>、<span class='gd-jp'>しかない</span>、<span class='gd-jp'>わけにはいかない</span>, chứ không phải chỉ đơn thuần miêu tả một sự việc đã xảy ra.<br>・Sau danh từ nối thẳng とあれば, không cần thêm だ.<br>・Giọng văn trang trọng, thiên về văn viết. Khi nói chuyện với bạn bè chỉ cần nói <span class='gd-jp'>子供のためなら</span>, nghĩa gần như nhau mà nhẹ nhàng hơn.<br>・Nghĩa “vì” là từ <span class='gd-jp'>のため</span> ở phía trước mà ra; bản thân とあれば chỉ là “nếu là ~”, không phải câu nào cũng mang nghĩa “vì”.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>「とあれば」「とあって」đều bắt đầu bằng 「と＋あ…」, chỉ khác nhau một chút ở phía sau; 「ともなれば」cũng bắt đầu bằng と nên nhìn rất giống. Cùng so sánh qua tình huống “giám đốc”:<br><b>とあれば</b>＝<b>nếu là</b> ~ thì… (giả định, phía sau là quyết tâm): <span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（Nếu là lệnh của giám đốc thì chỉ còn cách làm theo）<br><b>とあって</b>＝<b>vì là</b> ~ nên… (sự thật đã xảy ra, phía sau miêu tả tình trạng): <span class='gd-jp'>社長の命令とあって、みんな必死に働いている。</span>（Vì là lệnh của giám đốc nên mọi người đều đang làm việc hết sức）<br><b>ともなれば</b>＝<b>một khi đã đến mức</b> thân phận hay trình độ ~ thì đương nhiên…: <span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（Một khi đã làm giám đốc thì trách nhiệm đương nhiên cũng nặng hơn）</div><div class='gd-warn'>Mẹo nhỏ để chọn: “nếu là ~ thì tôi sẵn lòng／đành làm” dùng とあれば; “vì là ~ nên bây giờ mới như vậy” dùng とあって; “đã đến mức ~ thì đương nhiên sẽ” dùng ともなれば.</div>","n1-7":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をおいて」 tương đương với <b>“không ai ngoài ～”, “ngoài ～ ra thì còn ai nữa”</b>. Người nói đã cân nhắc một loạt người hoặc vật có thể chọn, rồi đi đến kết luận: <b>thật sự chỉ có cái này là phù hợp nhất</b>. Nó không chỉ nói “chỉ có”, mà còn mang theo một đánh giá rất cao.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋<span class='gd-jp'>をおいて</span>＋<span class='gd-jp'>ほかに</span>〜<span class='gd-jp'>ない</span>／<span class='gd-jp'>いない</span><br>Nói về người thì dùng <span class='gd-jp'>いない</span>, nói về đồ vật, thời gian, địa điểm thì dùng <span class='gd-jp'>ない</span>.<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼をおいてほかにいない</span></span>(ngoài anh ấy ra không có ai khác)<br><span class='gd-pair'><span class='gd-jp'>今</span> → <span class='gd-jp'>今をおいてほかにない</span></span>(ngoài lúc này ra không có thời cơ nào khác)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Nói về người</span>Hay dùng nhất khi đề cử người phù hợp hoặc khen ai đó là lựa chọn duy nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>次のリーダーにふさわしいのは、山田さんをおいてほかにいない。</span>(Người phù hợp làm đội trưởng tiếp theo thì không ai ngoài Yamada)</div><div class='gd-sec'><span class='gd-tag'>Nói về thời cơ</span><span class='gd-jp'>今をおいてほかにない</span> là cách nói cố định, nghĩa là “chính là bây giờ, bỏ lỡ là hết”.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学するなら、今をおいてほかにない。</span>(Muốn đi du học thì chính là bây giờ)</div><div class='gd-sec'><span class='gd-tag'>Câu hỏi tu từ</span>Phía sau không nhất thiết phải là 「ない」, bạn cũng có thể dùng giọng hỏi tu từ kiểu “còn ai nữa chứ?”, nghĩa vẫn là “chỉ có anh ấy”.</div><div class='gd-ex-line'>・<span class='gd-jp'>この役を演じられるのは、彼をおいて誰がいるだろうか。</span>(Người có thể diễn vai này, ngoài anh ấy ra còn ai nữa chứ?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không dùng để nói một sự thật đơn thuần</b>. “Trong phòng ngoài anh ấy không có ai khác” chỉ là tình trạng khách quan, phải nói <span class='gd-jp'>部屋には彼以外誰もいなかった</span>, không dùng をおいて được.<br>・Mẫu này thường dùng cho <b>đánh giá tốt</b>, như “phù hợp nhất”, “giỏi nhất”, “chỉ có anh ấy làm được”. Dùng cho chuyện xấu sẽ nghe rất lạ.<br>・<span class='gd-jp'>をおいて</span> và <span class='gd-jp'>において</span> chỉ khác nhau một chữ nhưng nghĩa hoàn toàn khác: <span class='gd-jp'>会議室において</span> là “tại phòng họp”, chỉ địa điểm hoặc bối cảnh.<br>・Đây là cách nói khá trang trọng, thiên về văn viết, hay gặp trong bài viết, diễn văn, tin tức. Nói chuyện với bạn bè thì cứ nói <span class='gd-jp'>彼しかいないよ</span> là được.<br>・<span class='gd-jp'>何をおいても</span> là một cách nói quen dùng khác, nghĩa là “dù thế nào cũng ưu tiên trước hết”: <span class='gd-jp'>何をおいても駆けつける</span>(dù thế nào cũng sẽ chạy đến ngay). Đừng nhầm với nghĩa “ngoài ～ ra không có cái nào khác”.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng là nói về một quán lâu đời rất giỏi:<br><b>をおいて</b>＝trong một loạt ứng viên, <b>chọn ra duy nhất một</b>: <span class='gd-jp'>この味を出せるのは、あの店をおいてほかにない。</span>(Làm ra được vị này thì không đâu ngoài quán đó)<br><b>ならでは</b>＝một nét đặc sắc nào đó <b>chỉ riêng nó mới có</b>: <span class='gd-jp'>これはあの店ならではの味だ。</span>(Đây là hương vị chỉ quán đó mới có)<br><b>以外</b>＝chỉ đơn thuần nói <b>“ngoài ～”</b>, không kèm đánh giá: <span class='gd-jp'>あの店以外で食べたことがない。</span>(Ngoài quán đó ra, tôi chưa từng ăn ở nơi nào khác)</div><div class='gd-warn'>Mẹo phân biệt: khi nói “chọn ai / chọn cái nào thì đáp án chỉ có cái này” thì dùng をおいて; khi nói “nét đặc trưng này là của riêng nó” thì dùng ならでは; chỉ nói khách quan “ngoài ～” thì dùng 以外.</div>","n1-11":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ならまだしも」 tương đương với <b>“nếu là ～ thì còn tạm chấp nhận, nhưng…”</b>. Trước tiên bạn lùi một bước: “nếu chỉ thế này thì mình còn chịu được”, rồi chỉ ra: “nhưng mức độ bây giờ thì thật sự không được”. Trọng tâm của cả câu nằm ở vế sau: <b>bạn đang phàn nàn, đang bày tỏ rằng mình không thể chấp nhận</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>一度ならまだしも、三度も遅刻するなんて。</span>(Một lần thì còn tạm, vậy mà lại đi trễ tận ba lần)</div><div class='gd-h'>Tách ra để xem</div><div class='gd-sec'><span class='gd-jp'>まだしも</span> có thể hiểu là 「<span class='gd-jp'>まだ</span>」(còn)＋「<span class='gd-jp'>しも</span>」(nhấn mạnh), nghĩa là “còn tạm chấp nhận được”. Vì vậy cấu trúc câu luôn cố định như sau:<br><b>tình huống nhẹ hơn, còn chịu được</b>＋ならまだしも、<b>tình huống nghiêm trọng hơn, không thể chấp nhận</b>.<br>Tình huống nhẹ ở vế trước thường là điều “thực tế không phải như vậy”, chỉ dùng để đối chiếu. Ví dụ <span class='gd-jp'>冗談ならまだしも</span> ngầm có nghĩa là “bạn đâu có đùa”.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b>: nối trực tiếp. <span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談ならまだしも</span></span><br><b>Tính từ な</b>: không thêm だ, nối trực tiếp. <span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手ならまだしも</span></span><br><b>Động từ, tính từ い</b>: dùng thể thường (tức là dạng bình thường, không có ます、です). <span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないならまだしも</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bất mãn với việc đã xảy ra</span></div><div class='gd-ex-line'>・<span class='gd-jp'>知らないならまだしも、知っていて黙っていたのは許せない。</span>(Không biết thì còn tạm, biết rõ mà vẫn im lặng thì mình không tha thứ được)</div><div class='gd-sec'><span class='gd-tag'>Đánh giá tình huống chưa xảy ra</span>Vế sau không nhất thiết là chuyện đã qua, cũng có thể là nhận định về một giả định hay tương lai.</div><div class='gd-ex-line'>・<span class='gd-jp'>夏はまだしも、冬はこの部屋じゃ無理だ。</span>(Mùa hè thì còn tạm được, chứ mùa đông ở phòng này thì không thể nào)</div><div class='gd-sec'><span class='gd-tag'>Nhờ đối phương đừng làm vậy nữa</span>Vế sau cũng có thể là lời nhờ vả hoặc ngăn cấm.</div><div class='gd-ex-line'>・<span class='gd-jp'>一日ならまだしも、毎日来るのはやめてほしい。</span>(Một ngày thì còn tạm, chứ ngày nào cũng đến thì thật lòng xin đừng)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Sau danh từ, người ta cũng hay dùng thẳng <span class='gd-jp'>はまだしも</span>, như <span class='gd-jp'>夏はまだしも</span> ở trên, nghĩa vẫn như vậy.<br>Ngoài ra còn có mẫu nghĩa rất gần là <span class='gd-jp'>ならともかく</span>, nhiều khi có thể thay thế cho nhau.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không được đảo thứ tự</b>: vế trước đặt cái nhẹ, vế sau đặt cái nghiêm trọng. Nếu nói <span class='gd-jp'>三度ならまだしも、一度遅刻するなんて</span> thì sẽ vô lý.<br>・Sau danh từ và tính từ な đừng thêm だ: đúng là <span class='gd-jp'>冗談ならまだしも</span>, không phải 冗談だならまだしも.<br>・Vế sau phải là đánh giá tiêu cực (như <span class='gd-jp'>ありえない</span>、<span class='gd-jp'>許せない</span>、<span class='gd-jp'>無理だ</span>、<span class='gd-jp'>やめてほしい</span>), không dùng để khen hay nói chuyện tốt.<br>・Giọng điệu là phàn nàn, trách móc, nên nói thẳng như vậy với bề trên hoặc khách sẽ nghe như chỉ trích, bạn nhớ cẩn thận với hoàn cảnh.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng là thấy một người lớn khóc vì chuyện nhỏ:<br><b>ならまだしも</b>: <span class='gd-jp'>子どもならまだしも、大人がこんなことで泣くなんて。</span>(Trẻ con thì còn tạm, người lớn mà lại khóc vì chuyện thế này)<br><b>ではあるまいし</b>: <span class='gd-jp'>子どもではあるまいし、こんなことで泣かないで。</span>(Có phải trẻ con đâu, đừng khóc vì chuyện này)<br>Trọng tâm của <b>ならまđしも</b> nằm ở <b>độ chênh</b>: “vế trước còn chấp nhận được, nhưng mức độ ở vế sau thì không”, hay dùng để phàn nàn hoặc bày tỏ không thể chấp nhận. Trọng tâm của <b>ではあるまいし</b> nằm ở “đâu phải ～”, tức là <b>phủ định tiền đề phía trước</b>, rồi yêu cầu đối phương nên làm gì hoặc đưa ra nhận định.</div><div class='gd-warn'>Mẹo phân biệt: khi muốn nói kiểu “A thì còn tạm, B thì quá đáng rồi” thì dùng ならまだしも; khi muốn nói “đâu phải A, bạn phải…” thì dùng ではあるまいし.</div>","n1-24":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜とあって」là mẫu câu báo chí rất hay dùng, nghĩa là <b>“vì là tình huống đặc biệt như thế này nên đúng là…”</b>. Giống như tin tức tiếng Việt hay viết “Nhân dịp ngày đầu kỳ nghỉ lễ, sân bay đông nghẹt khách”, cảm giác của “nhân dịp~” chính là nó. Vế trước nêu một ngày hoặc dịp đặc biệt, vế sau nói về cảnh tượng và phản ứng của mọi người vì dịp đó.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Ngày・dịp đặc biệt</span>Kỳ nghỉ dài, đợt giảm giá, lễ hội pháo hoa… là những chuyện không ngày nào cũng có, nên người đông và không khí náo nhiệt hơn hẳn.</div><div class='gd-ex-line'>・<span class='gd-jp'>連休初日とあって、空港は大混雑だった。</span>（Đúng ngày đầu kỳ nghỉ dài, sân bay đông kinh khủng）</div><div class='gd-ex-line'>・<span class='gd-jp'>年に一度のセールとあって、店の前には朝から長い列ができていた。</span>（Vì là đợt giảm giá mỗi năm một lần, từ sáng sớm trước cửa tiệm đã xếp hàng dài）</div><div class='gd-sec'><span class='gd-tag'>Phản ứng của con người</span>Vì tình huống hiếm có nên người trong cuộc hồi hộp, phấn khích, đặc biệt nghiêm túc.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての海外旅行とあって、娘はずいぶん張り切っている。</span>（Vì là chuyến du lịch nước ngoài đầu tiên, con gái mình háo hức cực kỳ）</div><div class='gd-ex-line'>・<span class='gd-jp'>人気歌手が来るとあって、会場には若い人が大勢集まった。</span>（Vì có ca sĩ nổi tiếng đến, rất đông bạn trẻ đã tụ tập ở hội trường）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b>: ghép trực tiếp, thường không thêm「だ」.<br><span class='gd-pair'><span class='gd-jp'>連休</span> → <span class='gd-jp'>連休とあって</span></span><span class='gd-pair'><span class='gd-jp'>花火大会</span> → <span class='gd-jp'>花火大会とあって</span></span><br><b>Động từ, tính từ い</b>: dùng thể thường (tức là dạng không có ます、です; thì quá khứ cũng được).<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るとあって</span></span><span class='gd-pair'><span class='gd-jp'>優勝した</span> → <span class='gd-jp'>優勝したとあって</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとあって</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau chỉ được viết <b>kết quả, tình huống thực tế quan sát được</b>, không được đặt dự định, lời mời hay lời nhờ của bản thân.<br>×<span class='gd-jp'>連休とあって、旅行に行こう。</span><br>○<span class='gd-jp'>連休だから、旅行に行こう。</span>（Vì được nghỉ dài, mình đi du lịch nhé）<br>・Vế trước phải là chuyện <b>đặc biệt, hiếm có</b>. Lý do quá bình thường nghe sẽ rất gượng, ví dụ “đói bụng nên mua bánh mì” thì cứ dùng「から」「ので」là được.<br>・Sau danh từ thường không thêm だ: phải nói <span class='gd-jp'>連休とあって</span>, không nói 連休だとあって.<br>・Đây là giọng văn viết, giọng báo chí; khi nói chuyện với bạn bè thì dùng「〜から」「〜ので」sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là tình huống liên quan đến「社長」(giám đốc):<br><b>とあって</b>＝vì là ~, <b>nên có kết quả như thế này</b> (việc đã xảy ra)<br><span class='gd-jp'>社長が来るとあって、社員はみんな緊張している。</span>（Vì giám đốc sắp đến, nhân viên ai cũng căng thẳng）<br><b>とあれば</b>＝<b>nếu là ~ thì</b> (sẵn sàng) làm… (giả định, điều kiện)<br><span class='gd-jp'>社長の頼みとあれば、断るわけにはいかない。</span>（Nếu là lời nhờ của giám đốc thì không thể từ chối được）<br><b>にあって</b>＝<b>đang ở trong lập trường, hoàn cảnh ~</b><br><span class='gd-jp'>社長という立場にあって、そんな発言は許されない。</span>（Ở cương vị giám đốc thì không được phép phát ngôn như vậy）</div><div class='gd-warn'>Mẹo phân biệt nhanh: “vì là ~ nên (mọi người) đúng là…” là とあって; “nếu là ~ thì” là とあれば; “đang ở trong ~” là にあって.</div>","n1-25":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜ばこそ」nghĩa là <b>“chính vì ~ mà mới…”</b>, ý gần giống「からこそ」nhưng trang trọng hơn, giống cách nói trong văn viết hoặc diễn văn. Mẫu này hay dùng khi “việc nghe có vẻ không hay nhưng phía sau lại có lý do tốt”, ví dụ “chính vì thương con nên mới mắng con”.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nói ra lý do thật sự</span>Người khác có thể hiểu lầm hành động của bạn, và bạn muốn nhấn mạnh “mình làm vậy là vì ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたを思えばこそ、厳しく言うのです。</span>（Chính vì nghĩ cho bạn nên tôi mới nói nặng lời）</div><div class='gd-ex-line'>・<span class='gd-jp'>信頼していればこそ、この仕事を任せたのです。</span>（Chính vì tin tưởng bạn nên tôi mới giao công việc này）</div><div class='gd-sec'><span class='gd-tag'>Có điều kiện này mới làm được</span>Nhấn mạnh một điều kiện tốt là mấu chốt.</div><div class='gd-ex-line'>・<span class='gd-jp'>若ければこそ、失敗を恐れずに挑戦できる。</span>（Chính vì còn trẻ nên mới có thể thử thách mà không sợ thất bại）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康であればこそ、好きなことに挑戦できる。</span>（Chính vì khỏe mạnh nên mới có thể thử sức với điều mình thích）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Trước hết đổi từ phía trước sang dạng「〜ば」, rồi thêm <b>こそ</b>.<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng「え」cùng cột, rồi thêm ば.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → đổi う thành え → <span class='gd-jp'>思えばこそ</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ る, thêm れば.<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じればこそ</span></span><br><b>Nhóm 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればこそ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ればこそ</span>（くればこそ）</span><br>Với「〜ている」thì đổi いる thành いれば: <span class='gd-pair'><span class='gd-jp'>案じている</span> → <span class='gd-jp'>案じていればこそ</span></span></div><div class='gd-sec'><b>Tính từ い</b>: đổi い thành ければ. <span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若ければこそ</span></span><br><b>Danh từ, tính từ な</b>: thêm であれば phía sau. <span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親であればこそ</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康であればこそ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>親であればこそ、子どもの幸せを願うのだ。</span>（Chính vì là cha mẹ nên mới mong con hạnh phúc）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「ば」ở đây <b>không phải “nếu”</b> mà là “vì”. <span class='gd-jp'>思えばこそ</span> không có nghĩa là “nếu nghĩ”, mà là “chính vì đang nghĩ đến (bạn)”. Đây là cách dùng còn sót lại từ văn cổ, nên trông giống hệt thể điều kiện.<br>・Danh từ, tính từ な không ghép trực tiếp được: phải nói <span class='gd-jp'>健康であればこそ</span>, không phải「健康ばこそ」.<br>・Giọng rất trang trọng, khi trò chuyện hiếm khi dùng. Nói với bạn bè thì dùng <span class='gd-jp'>からこそ</span> là đủ, dùng ばこそ nghe như đang đọc bài phát biểu.<br>・Lý do ở vế trước thường mang nghĩa tích cực, chân thành (yêu thương, tin tưởng, sức khỏe, nỗ lực), ít dùng để nói về nguyên nhân xui xẻo hay tiêu cực.<br>・Vế sau hay kết thúc bằng <span class='gd-jp'>のだ／のです</span>, tạo cảm giác “thật ra là như vậy”, bạn thử để ý trong các câu ví dụ nhé.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>からこそ</b>＝chính vì ~ nên mới…, dùng được cả khi nói lẫn khi viết: <span class='gd-jp'>好きだからこそ、厳しく言うんだよ。</span>（Chính vì thích bạn nên mình mới nói nặng lời đấy）<br><b>ばこそ</b>＝nghĩa giống nhau nhưng trang trọng hơn, thường dùng trong văn viết, diễn văn: <span class='gd-jp'>愛すればこそ、厳しく言うのである。</span>（Chính vì yêu thương nên mới nói nghiêm khắc）<br><b>あっての</b>＝“có ~ thì mới có…”, ghép sau danh từ, trọng tâm là “thiếu nó thì không thành”: <span class='gd-jp'>健康あっての人生だ。</span>（Có sức khỏe thì mới có cuộc sống）</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói chuyện hằng ngày dùng からこそ; viết văn, phát biểu muốn trang trọng hơn thì dùng ばこそ; muốn nói “thiếu nó thì chẳng còn gì” thì dùng あっての.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng là cách nói chỉ nguyên nhân ở N1, bạn có thể xem tiếp <span class='gd-jp'>〜ゆえ（に）</span> (vì ~, thiên về văn viết hơn) và <span class='gd-jp'>〜あっての</span>.</div>","n1-42":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「Aと言わずBと言わず」nghĩa là <b>「dù là A hay B thì đều ～」</b>. Bạn nêu ra hai phần tiêu biểu để người nghe cảm nhận được rằng <b>toàn bộ đều như vậy</b>. Giống như trong tiếng Việt, khi nói «tay chân dính đầy bùn», thật ra là muốn nói cả người lem luốc.</div><div class='gd-ex-line'>・<span class='gd-jp'>手と言わず足と言わず、泥だらけになった。</span>（Dù là tay hay chân, tất cả đều dính đầy bùn）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋と言わず＋danh từ＋と言わず, <b>sau mỗi danh từ đều phải có một「と言わず」</b>.<br>「言わず」là cách nói mang tính văn viết, cổ hơn của「言わない」. Nghĩa đen là «không nói là A, cũng không nói là B», tức là «không phân biệt A hay B». Cụm này cũng hay được viết bằng hiragana là <span class='gd-jp'>といわず</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cơ thể</span>Từ đầu đến chân, khắp người đều như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>顔と言わず腕と言わず、蚊に刺されてしまった。</span>（Mặt cũng như tay, chỗ nào cũng bị muỗi đốt）</div><div class='gd-sec'><span class='gd-tag'>Địa điểm</span>Cả không gian, cả nơi đó đều như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>壁と言わず床と言わず、部屋中に落書きがしてあった。</span>（Tường cũng như sàn, khắp phòng đều bị vẽ bậy）</div><div class='gd-sec'><span class='gd-tag'>Thời gian</span>Không phân biệt thời điểm, lúc nào cũng vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>昼と言わず夜と言わず、工事の音が響いている。</span>（Dù ngày hay đêm, tiếng thi công vẫn vang lên không ngừng）</div><div class='gd-ex-line'>・<span class='gd-jp'>平日と言わず週末と言わず、この店はいつも行列ができている。</span>（Dù ngày thường hay cuối tuần, quán này lúc nào cũng có hàng người xếp hàng）</div><div class='gd-sec'>Bạn sẽ thấy vế sau thường có những từ mang nghĩa «tất cả» như <span class='gd-jp'>部屋中</span>, <span class='gd-jp'>町中</span>, <span class='gd-jp'>いつも</span>, <span class='gd-jp'>だらけ</span>, hô ứng với ý «không phân biệt A, B» ở phía trước.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cả hai「と言わず」đều phải viết. <span class='gd-jp'>手と足と言わず</span> là sai, phải nói <span class='gd-jp'>手と言わず足と言わず</span>.<br>・A và B phải là <b>cùng một loại</b> và là các phần của một tổng thể (tay và chân＝cả người, ngày và đêm＝cả ngày). Ghép hai thứ không liên quan với nhau sẽ nghe rất kỳ.<br>・Mẫu này dùng để <b>miêu tả tình trạng thực tế đang thấy</b>, và thường là tình trạng gây ngạc nhiên hoặc không mấy tốt đẹp (người đầy bùn, khắp nơi đầy vết thương, ồn ào không dứt).<br>・Đây là cách nói văn viết, khá cứng, hay gặp trong tiểu thuyết và báo chí. Khi trò chuyện bình thường, người Nhật thường nói <span class='gd-jp'>手も足も</span>, <span class='gd-jp'>どこもかしこも</span>.<br>・Đừng nhầm với「と言わず」đứng một mình: <span class='gd-jp'>明日と言わず、今すぐ行こう。</span>（Đừng nói là ngày mai, đi ngay bây giờ đi）Câu này mang nghĩa «không cần đợi đến A», khác với mẫu ngữ pháp này.<br>・「言わず」trong <span class='gd-jp'>何も言わずに帰った</span>（về mà không nói gì cả）là «không nói» theo đúng nghĩa đen, không liên quan đến mẫu câu này.</div><div class='gd-h'>Phân biệt với mẫu dễ nhầm</div><div class='gd-sec'>Cùng mang nghĩa «dù A hay B», nhưng <span class='gd-jp'>Aであれ Bであれ</span> có sắc thái khác:<br><b>と言わず</b>＝<b>miêu tả tình trạng thực tế trước mắt</b>, đâu đâu cũng như vậy:<br><span class='gd-jp'>駅前と言わず住宅街と言わず、どこも観光客であふれている。</span>（Dù là trước ga hay khu dân cư, đâu đâu cũng đông nghẹt khách du lịch）<br><b>であれ</b>＝<b>dù là cái nào thì cũng áp dụng cùng một quy định hay một nhận định</b>:<br><span class='gd-jp'>駅前であれ住宅街であれ、ごみを捨ててはいけない。</span>（Dù là trước ga hay khu dân cư, đều không được vứt rác bừa bãi）<br>Câu thứ hai nói về quy định, nên nếu đổi sang と言わず sẽ không tự nhiên.</div><div class='gd-warn'>Mẹo phân biệt: khi bạn đang miêu tả cảnh «nhìn đâu cũng thấy như vậy», dùng と言わず; khi nói về quy định hay nhận định kiểu «loại nào cũng phải ～», dùng であれ.</div>","n1-44":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「Danh từ＋ったら」giống như câu <b>«Cái người nhà mình ấy mà, thật là…»</b> trong tiếng Việt. Bạn nhắc đến một người thân quen trước, rồi kể chuyện khiến mình vừa bực vừa buồn cười. Trọng tâm là sắc thái <b>bất lực, phàn nàn nhưng đầy thân mật</b>, không phải đang mắng thật.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thêm thẳng「ったら」sau danh từ, không cần biến đổi.<br><span class='gd-pair'><span class='gd-jp'>弟</span> → <span class='gd-jp'>弟ったら</span></span><span class='gd-pair'><span class='gd-jp'>お母さん</span> → <span class='gd-jp'>お母さんったら</span></span><span class='gd-pair'><span class='gd-jp'>あなた</span> → <span class='gd-jp'>あなたったら</span></span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Than phiền với người khác</span>Khi trò chuyện với bạn bè về người nhà, đồng nghiệp, thú cưng, dùng để mở đầu câu chuyện kiểu «lại nữa rồi».</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの猫ったら、また私の椅子で寝てる。</span>（Con mèo nhà mình thật là, lại ngủ trên ghế của mình rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>父ったら、また眼鏡をなくしたの。</span>（Bố mình thật là, lại làm mất kính rồi）</div><div class='gd-sec'><span class='gd-tag'>Trách trực tiếp người đối diện</span>Gọi thẳng người đó, mang nghĩa «Trời ơi, thật là!», thường đi với「もう」.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう、お母さんったら！その話はしないでって言ったでしょ。</span>（Trời ơi, mẹ! Con đã bảo mẹ đừng nhắc chuyện đó rồi mà）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんったら、冗談ばっかり。</span>（Anh Tanaka thật là, suốt ngày đùa）</div><div class='gd-sec'>Vế sau thường nói dở rồi bỏ lửng, như <span class='gd-jp'>弟ったら、また忘れ物して…。</span>（Em trai mình thật là, lại bỏ quên đồ nữa rồi…）. Phần không nói hết chính là tiếng thở dài ấy.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nó <b>không phải nghĩa «nếu»</b>. Trong <span class='gd-jp'>雨が降ったら</span>, たら mang nghĩa «nếu ～ thì», còn danh từ＋ったら là «nói đến ～ thì thật là…», hai cái hoàn toàn khác nhau.<br>・Giọng điệu rất khẩu ngữ, thân mật, dùng với người nhà, bạn bè, thú cưng. Nói thẳng với cấp trên, khách hàng hoặc trong hoàn cảnh trang trọng đều không phù hợp.<br>・Phía sau thường là chuyện khiến bạn cạn lời, bất lực, hoặc hơi ngượng. Nếu chỉ muốn khen hay cảm ơn ai đó, dùng「は」bình thường là được. Dù đi với chuyện tốt, sắc thái vẫn là kiểu ngại ngùng hay bất lực như «Anh ấy khách sáo quá đi, thật là».<br>・Trước ったら có một「っ」nhỏ, phải ngắt một nhịp khi đọc thành「ったら」, đừng đọc thành「たら」.<br>・Bạn cũng sẽ nghe thấy <span class='gd-jp'>お母さんってば</span>, sắc thái gần giống ったら, đều là khẩu ngữ.</div><div class='gd-h'>Phân biệt với mẫu dễ nhầm</div><div class='gd-sec'><b>ったら</b>＝bất lực xen lẫn thương yêu, cũng có thể gọi thẳng người đối diện:<br><span class='gd-jp'>うちの子ったら、またゲームばっかり。</span>（Con nhà mình thật là, lại chơi game suốt）<br><b>ときたら</b>＝phàn nàn nghiêm túc hơn, sắc thái tiêu cực nặng hơn, phần lớn là nói với người khác, không dùng để gọi thẳng người đối diện:<br><span class='gd-jp'>うちの子ときたら、毎日ゲームばっかりで全然勉強しない。</span>（Nói đến con nhà mình thì, ngày nào cũng chỉ chơi game, chẳng học hành gì cả）<br><b>ったらない</b>＝phía trước thường là tính từ, nghĩa là «cực kỳ ～», không liên quan đến việc phàn nàn về một người nào đó:<br><span class='gd-jp'>あの時は恥ずかしいったらなかった。</span>（Lúc đó xấu hổ không chịu nổi）</div><div class='gd-warn'>Mẹo phân biệt: nói «thật là…» với khóe miệng đang cười là ったら; cau mày trách móc là ときたら; nếu sau ったら còn có「ない」và phía trước là tính từ, đó là «cực kỳ ～».</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Hãy học tiếp <span class='gd-jp'>～ときたら</span> để phân biệt rõ hai sắc thái «phàn nàn thân mật» và «trách móc nghiêm túc».</div>","n1-35":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜の至り」tương đương với cách nói <b>「…vô cùng」「…hết sức」</b> trong tiếng Việt, như \"vinh dự vô cùng\", \"cảm kích vô cùng\". Người Nhật nói <span class='gd-jp'>光栄の至りです</span>, nghĩa là \"tôi thật sự vinh dự đến cực điểm\". Đây là cách nói rất trang trọng, thường xuất hiện trong bài phát biểu ở buổi lễ, lời cảm ơn khi nhận giải, thư từ thương mại. Bình thường nói chuyện với bạn bè thì sẽ không ai nói như vậy.</div><div class='gd-h'>「至り」là gì</div><div class='gd-sec'><span class='gd-jp'>至り</span>là danh từ được tạo từ động từ <span class='gd-jp'>至る</span> (đi đến, đạt tới), mang nghĩa \"đi đến điểm cao nhất\". Vì vậy <span class='gd-jp'>光栄の至り</span> = vinh dự đạt đến đỉnh điểm = vinh dự hết sức.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ + の至り, cuối câu thường đi với です hoặc でございます.<br><span class='gd-pair'><span class='gd-jp'>光栄</span> → <span class='gd-jp'>光栄の至りです</span></span><br><span class='gd-pair'><span class='gd-jp'>感激</span> → <span class='gd-jp'>感激の至りでございます</span></span><br>Bạn cần đặc biệt lưu ý: danh từ đứng trước <b>gần như chỉ là một nhóm cố định</b>, không phải danh từ nào cũng đặt vào được.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Cảm ơn・Vinh dự</span>Phổ biến nhất là <span class='gd-jp'>光栄の至り</span>、<span class='gd-jp'>感激の至り</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>このような賞をいただき、光栄の至りです。</span>(Được nhận giải thưởng như thế này, tôi vô cùng vinh dự)</div><div class='gd-ex-line'>・<span class='gd-jp'>皆様から温かいお言葉をいただき、感激の至りです。</span>(Nhận được những lời ấm áp từ mọi người, tôi vô cùng cảm kích)</div><div class='gd-sec'><span class='gd-tag'>Áy náy・Xấu hổ</span>Thường gặp là <span class='gd-jp'>恐縮の至り</span> (vô cùng áy náy), <span class='gd-jp'>赤面の至り</span> (xấu hổ đến đỏ mặt).</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところお越しいただき、恐縮の至りでございます。</span>(Anh/chị bận rộn như vậy mà vẫn đến tham dự, tôi thật sự rất áy náy)</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな初歩的なミスをしてしまい、赤面の至りです。</span>(Mắc lỗi cơ bản thế này, tôi xấu hổ vô cùng)</div><div class='gd-sec'><span class='gd-tag'>Một trường hợp đặc biệt</span><span class='gd-jp'>若気の至り</span> có nghĩa hơi khác, chỉ \"lỗi lầm do còn trẻ, chưa hiểu chuyện\". Ở đây 至り gần với nghĩa \"kết quả gây ra\". Câu này hay dùng để nhớ lại những việc dại dột đã làm ngày xưa, mang chút tự giễu, không nhất thiết phải là dịp trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は若気の至りで、ずいぶん無茶をした。</span>(Thời sinh viên còn trẻ người non dạ, tôi đã làm khá nhiều chuyện liều lĩnh)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>danh từ + の</b>, không thể nối trực tiếp với tính từ. <span class='gd-jp'>嬉しいの至り</span>、<span class='gd-jp'>ありがたいの至り</span> đều sai. Muốn diễn đạt vui mừng, biết ơn thì dùng các cụm cố định như <span class='gd-jp'>光栄</span>、<span class='gd-jp'>感激</span>.<br>・Đừng tự ý thay danh từ khác, thuộc lòng 光栄・感激・恐縮・赤面・若気 là an toàn nhất.<br>・Cách nói này chủ yếu diễn tả tâm trạng của <b>chính mình</b>, mang sắc thái khiêm tốn. Nếu dùng để nói về cảm xúc của người khác, ví dụ \"Trưởng phòng vô cùng vinh dự\", nghe sẽ rất kỳ.<br>・Sắc thái của nó cực kỳ trang trọng. Nói với bạn bè <span class='gd-jp'>ケーキありがとう、感激の至り！</span> thì nghe như đang đùa, cố tình làm bộ làm tịch.<br>・<span class='gd-jp'>若気</span> đọc là <span class='gd-jp'>わかげ</span>, không phải わかき.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>の至り</b> = cảm xúc biết ơn hay xấu hổ của bản thân đạt đến cực điểm, giọng khiêm tốn: <span class='gd-jp'>お招きいただき、光栄の至りです。</span>(Được mời tham dự, tôi vô cùng vinh dự)<br><b>極まりない</b> = một việc hay thái độ nào đó \"cực kỳ…\", phần lớn dùng để phê bình, phàn nàn: <span class='gd-jp'>連絡もなく欠席するなんて、失礼極まりない。</span>(Vắng mặt mà không báo một tiếng, thật là cực kỳ thất lễ)<br><b>に至る</b> = động từ, diễn tả việc \"phát triển đến một kết quả hay mức độ nào đó\": <span class='gd-jp'>何度も話し合った結果、ようやく合意に至った。</span>(Sau nhiều lần thảo luận, cuối cùng cũng đạt được sự đồng thuận)</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói về cảm xúc của mình kiểu \"…vô cùng\" thì dùng の至り; chê trách hay phàn nàn \"cực kỳ…\" thì dùng 極まりない; nói sự việc \"diễn biến đến mức…\" thì dùng に至る.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>〜に堪えない</span> cũng là cách diễn đạt cảm xúc mãnh liệt trong hoàn cảnh trang trọng: <span class='gd-jp'>皆様のご支援には感謝に堪えません。</span>(Tôi biết ơn vô cùng trước sự ủng hộ của mọi người)</div>","n1-41":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜といったらない」tương đương với <b>「…không thể tả nổi」「…kinh khủng」「…hết sức」「…không chịu được」</b> trong tiếng Việt. Nghĩa đen là \"nói về mức độ… thì không biết lấy lời nào để diễn tả\", dùng để nhấn mạnh một cách phóng đại rằng cảm giác nào đó mạnh đến cực điểm. Cả chuyện tốt lẫn xấu đều nói được: vui không tả nổi, lạnh kinh khủng, xấu hổ chết đi được, đều dùng được.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b> + といったらない (phổ biến nhất là biến tính từ thành danh từ dạng 「～さ」)<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い換成さ → <span class='gd-jp'>寒さといったらない</span></span><br><b>Tính từ đuôi い</b>: nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>うれしい</span> → <span class='gd-jp'>うれしいといったらない</span></span><br><b>Tính từ đuôi な</b>: không thêm な, nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>退屈</span> → <span class='gd-jp'>退屈といったらない</span></span></div><div class='gd-sec'>Khi nói về việc đã xảy ra trong <b>quá khứ</b>, đổi thành 「といったら<b>なかった</b>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて富士山を見た時の感動といったらなかった。</span>(Lần đầu nhìn thấy núi Phú Sĩ, nỗi xúc động ấy thật không thể diễn tả bằng lời)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日同じ作業ばかりで、退屈といったらない。</span>(Ngày nào cũng làm đúng một việc, chán không chịu nổi)</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ったらない</span>Dạng rút gọn khẩu ngữ của 「といったらない」, rất hay nghe khi tán gẫu với bạn bè hoặc than phiền, phía trước phần lớn nối thẳng với tính từ đuôi い.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の工事、うるさいったらないよ。</span>(Nhà bên cạnh đang thi công, ồn kinh khủng luôn)</div><div class='gd-sec'><span class='gd-tag'>ったらありゃしない</span>Cách nói còn khẩu ngữ hơn, nhiều cảm xúc hơn, phần lớn dùng khi phàn nàn, xấu hổ, tức giận.</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの前で転ぶなんて、恥ずかしいったらありゃしない。</span>(Ngã trước mặt mọi người, xấu hổ chết đi được)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・「ない」ở đây <b>không phải phủ định</b>. <span class='gd-jp'>うれしいといったらない</span> nghĩa là \"vui không tả nổi\", không phải \"không vui\".<br>・Tính từ đuôi な không thêm な: nói <span class='gd-jp'>退屈といったらない</span>, không nói 退屈なといったらない.<br>・Việc đã qua thì phải dùng 「といったらなかった」, nếu không nghe như vẫn đang xảy ra.<br>・Phía trước thường là tính từ hoặc danh từ, nhất là dạng 「～さ」; động từ rất ít khi nối trực tiếp như vậy.<br>・「ったらない」「ったらありゃしない」rất khẩu ngữ, trong hoàn cảnh trang trọng hoặc khi nói với cấp trên thì đừng dùng.<br>・Đừng nhầm với 「といったら (nói đến…)」: <span class='gd-jp'>日本といったら、やっぱり寿司だ。</span>(Nhắc đến Nhật Bản thì đúng là phải có sushi) Phía sau không có ない, nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>〜ったら（n1-44）</b>: phía trước là <b>người</b>, nghĩa là \"cái người này thật là…\", mang chút bất lực hoặc phàn nàn, phía sau đi với một câu hoàn chỉnh.<br><span class='gd-jp'>うちの母ったら、また夜中に電話してきた。</span>(Mẹ mình thật là, lại gọi điện giữa đêm nữa rồi)<br><span class='gd-jp'>うちの母、心配性ったらない。</span>(Mẹ mình hay lo lắng hết chỗ nói)</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu sau 「ったら」 là 「ない」 ngay, phía trước là tính từ hoặc 「～さ」 thì đang nói về mức độ; nếu phía trước là người, phía sau là cả một câu thì đang phàn nàn về người đó.</div><div class='gd-sec'><b>〜極まりない（n1-34）</b>: cũng là \"…đến cực điểm\", nhưng cứng hơn, thiên về văn viết, phần lớn dùng để đánh giá tiêu cực, như trong tin tức, thư khiếu nại. 「といったらない」 giống nói về cảm nhận trực tiếp của bản thân hơn, cả tích cực lẫn tiêu cực đều dùng được.<br><span class='gd-jp'>あの店員の態度は失礼極まりない。</span>(Thái độ của nhân viên đó cực kỳ thất lễ: giống một lời khiếu nại chính thức)<br><span class='gd-jp'>あの店員の態度の悪さといったらなかった。</span>(Thái độ của nhân viên đó tệ không thể tả: giống đang kể trải nghiệm cho bạn bè)</div><div class='gd-warn'>Mẹo phân biệt nhanh: viết văn trang trọng, phê bình nghiêm khắc thì dùng 「極まりない」; nói về cảm nhận của mình, có chút cảm xúc phóng đại thì dùng 「といったらない」.</div>","n1-26":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜手前」tương đương với kiểu nói trong tiếng Việt: <b>「Đã lỡ nói ra rồi thì đâu thể…」「Người ta đang nhìn thế này, ngại quá không dám…」</b>. Vì bạn đã nói hay đã làm điều gì đó, hoặc vì có người đang nhìn, nên để giữ <b>thể diện và lập trường của chính mình</b>, bạn đành phải làm như vậy, hoặc không thể làm như thế.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đã nói ra rồi</span>Phía trước là động từ, thường là việc chính bạn đã nói hoặc đã làm. Vì đã nói rồi nên bây giờ không thể tự vả vào mặt mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた手前、途中でやめるわけにはいかない。</span>（Đã nhận lời rồi thì không thể bỏ ngang giữa chừng）</div><div class='gd-ex-line'>・<span class='gd-jp'>「絶対合格する」と言った手前、遊んでいられない。</span>（Đã nói chắc như đinh「nhất định sẽ đậu」rồi thì làm sao mà chơi bời được）</div><div class='gd-sec'><span class='gd-tag'>Có người đang nhìn</span>Phía trước là người, nghĩa là 「trước mặt ～」「ngại bị ～ nghĩ về mình」. Điều bạn quan tâm là hình ảnh của <b>chính mình</b> trong mắt những người đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>みんなの手前、そんなことは言えない。</span>（Trước mặt mọi người, tôi không thể nói những lời như thế）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの手前、夫婦げんかはしないようにしている。</span>（Vì ngại con nhìn thấy, vợ chồng tôi cố gắng không cãi nhau trước mặt con）</div><div class='gd-sec'><span class='gd-tag'>Thân phận của mình</span>Dùng 「〜である手前」 để nói về thân phận của bản thân, nghĩa là 「đã là ～ thì đâu thể…」.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である手前、生徒の前でたばこは吸えない。</span>（Đã là giáo viên thì không thể hút thuốc trước mặt học sinh）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ: nối trực tiếp với thể thường (tức là cách nói không có ます). Hay gặp nhất là thể た, thể từ điển và thể ている cũng dùng được.<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した手前</span></span><span class='gd-pair'><span class='gd-jp'>言っている</span> → <span class='gd-jp'>言っている手前</span></span><br>Danh từ: thêm「の」rồi mới nối. <span class='gd-pair'><span class='gd-jp'>部下</span> → <span class='gd-jp'>部下の手前</span></span><br>Vế sau thường là cách nói mang nghĩa 「buộc phải」 hoặc 「không thể」, ví dụ <span class='gd-jp'>〜わけにはいかない</span>、<span class='gd-jp'>〜しかない</span>、<span class='gd-jp'>〜られない</span>、<span class='gd-jp'>〜ないといけない</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này nói về thể diện và lập trường của <b>chính mình (hoặc chủ ngữ của câu)</b>, chứ không phải đang giữ thể diện cho đối phương. <span class='gd-jp'>部長は部下の手前、ミスを認めにくかった。</span> nghĩa là trưởng phòng ngại không dám nhận lỗi trước mặt cấp dưới, điều ông ấy lo là hình ảnh của chính mình, không phải thể diện của cấp dưới.<br>・Vế sau gần như luôn mang cảm giác bị ép buộc kiểu 「đành phải ～」「không thể ～」, nên không thể đi với những việc vui vẻ, mong chờ. Câu như 「約束した手前、楽しみだ」 nghe rất kỳ.<br>・<span class='gd-jp'>手前</span> đọc là <b>てまえ</b>. Vốn dĩ nó có nghĩa là 「phía này, phía trước một chút」, ví dụ <span class='gd-jp'>駅の手前で降りる</span> (xuống ở chỗ gần tới ga). Khi gặp 「danh từ＋の手前」 hãy xem ngữ cảnh: nếu phía trước là người, phía sau là việc không thể làm hoặc đành phải làm thì đó là mẫu ngữ pháp này, không phải đang nói về vị trí.<br>・Đây là cách nói khá trang trọng, thiên về văn viết. Trong hội thoại hằng ngày, bạn sẽ nghe cách nói như 「言っちゃったし…」 nhiều hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><span class='gd-jp'>〜からには</span>、<span class='gd-jp'>〜以上</span> cũng được dịch là 「đã ～ thì」, nhưng trọng tâm khác nhau:<br><b>からには／以上</b> = đã ～ rồi thì nên, thì phải chịu trách nhiệm đến cùng. Trọng tâm là <b>lẽ phải và quyết tâm</b>.<br><b>手前</b> = đã ～ rồi mà không làm vậy thì <b>rất mất mặt</b>. Trọng tâm là <b>người khác sẽ nhìn mình thế nào</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず行く。</span>（Đã hứa rồi thì nhất định tôi sẽ đi: nói về quyết tâm）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束した手前、行かないわけにはいかない。</span>（Đã hứa với người ta rồi, không đi thì thật khó coi: nói về thể diện）</div><div class='gd-sec'>Sau からには và 以上 có thể đặt việc bản thân muốn làm, còn 手前 thì không:<br><span class='gd-jp'>日本に来たからには、富士山に登りたい。</span>（Đã đến Nhật rồi thì tôi muốn leo núi Phú Sĩ）<br>Câu này mà đổi sang 手前 thì không ổn, vì leo hay không leo núi Phú Sĩ chẳng liên quan gì đến thể diện.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu phía sau bạn có thể bổ sung thêm câu 「không thì rất xấu hổ, không biết ăn nói sao」 thì dùng 手前. Nếu chỉ là 「đã ～ thì nên ～」 thì dùng からには hoặc 以上.</div>","n1-32":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ところを」hay gặp nhất tương đương với kiểu nói trong tiếng Việt: <b>「Đang lúc bận rộn mà còn làm phiền anh/chị」「Xin lỗi đã làm phiền lúc anh/chị đang nghỉ ngơi」</b>. Trước hết bạn nêu ra việc <b>đối phương đang ở trong một trạng thái nào đó (đang bận, đang nghỉ, đang mệt)</b>, rồi phía sau nói lời <b>cảm ơn hoặc xin lỗi</b>, đây là cách nói xã giao rất trang trọng. Ngoài ra nó còn có thể diễn đạt <b>「lẽ ra phải ～, vậy mà…」</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Xã giao: làm phiền đối phương</span>Phía trước đặt hoàn cảnh của đối phương, phía sau là lời 「cảm ơn」「xin lỗi」, hoặc việc đối phương đã làm cho bạn. Mẫu này xuất hiện rất nhiều trong điện thoại công việc, bài phát biểu và email.</div><div class='gd-ex-line'>・<span class='gd-jp'>お忙しいところをありがとうございます。</span>（Đang lúc bận rộn mà anh/chị vẫn dành thời gian, xin cảm ơn）</div><div class='gd-ex-line'>・<span class='gd-jp'>お休みのところ、申し訳ありません。</span>（Thật xin lỗi vì đã làm phiền lúc anh/chị đang nghỉ）</div><div class='gd-ex-line'>・<span class='gd-jp'>お疲れのところ、すみません。少しだけいいですか。</span>（Xin lỗi vì làm phiền lúc anh/chị đang mệt. Cho tôi xin một chút thời gian được không ạ）</div><div class='gd-sec'><span class='gd-tag'>Lẽ ra phải ～ vậy mà</span>Phía trước nói 「theo lẽ thường thì sẽ thế nào」, phía sau nói thực tế lại thành ra khác, thường là kết quả có lợi cho mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>本来ならこちらから伺うべきところを、わざわざお越しいただきました。</span>（Lẽ ra chúng tôi phải đến thăm, vậy mà anh/chị lại đích thân đến tận nơi）</div><div class='gd-ex-line'>・<span class='gd-jp'>普通なら罰金のところを、今回は注意だけで済んだ。</span>（Bình thường thì bị phạt tiền, lần này chỉ bị nhắc nhở là xong）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>休んでいる</span> → <span class='gd-jp'>休んでいるところを</span></span><br><span class='gd-pair'><span class='gd-jp'>伺うべき</span> → <span class='gd-jp'>伺うべきところを</span></span><br><b>Tính từ い</b>: nối trực tiếp, khi nói xã giao phía trước thường thêm お.<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>お忙しいところを</span></span><br><b>Tính từ な</b>: thêm な rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変なところを</span></span><br><b>Danh từ</b>: thêm の rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>お休み</span> → <span class='gd-jp'>お休みのところを</span></span><br><span class='gd-pair'><span class='gd-jp'>ご多忙</span> → <span class='gd-jp'>ご多忙のところを</span></span><br>Khi nói chuyện, 「を」 thường bị lược bỏ, nói <span class='gd-jp'>お忙しいところ</span> cũng hoàn toàn được.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ い không được thêm の: phải nói <span class='gd-jp'>お忙しいところ</span>, không phải お忙しいのところ. Chỉ danh từ mới cần thêm の.<br>・Đây là cách nói rất trang trọng, nếu nói 「お忙しいところを」 với bạn bè thì nghe rất xa cách. Giữa bạn bè chỉ cần nói <span class='gd-jp'>忙しいのにごめんね</span>.<br>・Ở cách dùng xã giao, phía trước là trạng thái của <b>đối phương</b>, không phải của mình. Nếu bản thân đang bận mà vẫn đến giúp, bạn sẽ không nói 「私の忙しいところを」.<br>・Việc ở vế sau thường <b>ảnh hưởng đến đối phương</b>: làm phiền, gây rắc rối, hoặc việc đối phương đã làm cho bạn. Không thể đi với việc chẳng liên quan gì đến đối phương.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>ところを＋見る／見つかる</b> = <b>cảnh bị bắt gặp</b>, đây là 「ところ」 của N3 cộng với を chỉ tân ngữ, không phải xã giao: <span class='gd-jp'>タバコを吸っているところを先生に見られた。</span>（Lúc đang hút thuốc thì bị thầy giáo nhìn thấy）<br><b>ところを（lẽ ra phải ～ vậy mà）</b> = theo lẽ thường sẽ như thế, nhưng thực tế lại có kết quả tốt: <span class='gd-jp'>普通なら怒られるところを、許してもらった。</span>（Bình thường thì bị mắng, vậy mà lại được tha thứ）<br><b>ものを</b> = 「rõ ràng chỉ cần ～ là được」, mang sắc thái trách móc, tiếc nuối, thường đặt cuối câu: <span class='gd-jp'>一言言ってくれればよかったものを。</span>（Chỉ cần nói một tiếng là xong rồi mà）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu phía sau là 「見られた、見つかった」 → cảnh bị bắt gặp; nếu phía sau là lời cảm ơn, xin lỗi hoặc được hưởng lợi → xã giao / lẽ ra phải ～ vậy mà; nếu cả câu mang giọng trách móc kiểu 「biết thế thì đã ～」 → ものを.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Một cách nói có nghĩa rất gần và cũng hay dùng trong xã giao là 「中」: <span class='gd-jp'>お足元の悪い中、お越しいただきありがとうございます。</span>（Trời xấu, đường trơn mà quý vị vẫn đến, xin chân thành cảm ơn）</div>","n1-45":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ときたら」giống như khi bạn than phiền: <b>«Nhắc đến ông/bà nhà tôi hả... trời ơi, thật hết nói nổi»</b>. Bạn nêu ra một người hoặc một thứ làm mình bực, rồi cứ thế kể tội nó. Trọng tâm của cả câu là <b>bất mãn, ngán ngẩm, không biết làm sao với nó</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ + ときたら, phía trước thường là người hoặc đồ vật.<br><span class='gd-pair'><span class='gd-jp'>うちの息子</span> → <span class='gd-jp'>うちの息子ときたら</span></span>(nhắc đến thằng con nhà tôi)<br><span class='gd-pair'><span class='gd-jp'>このパソコン</span> → <span class='gd-jp'>このパソコンときたら</span></span>(nhắc đến cái máy tính này)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Kể tội người xung quanh</span>Hay dùng nhất với người nhà, đồng nghiệp, sếp, tức là những người gần gũi và làm bạn đau đầu.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの息子ときたら、ゲームばかりしている。</span>(Nhắc đến thằng con nhà tôi, suốt ngày chỉ biết chơi game)</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの部長ときたら、会議のたびに話が長い。</span>(Nhắc đến trưởng phòng nhà tôi, họp lần nào cũng nói dài lê thê)</div><div class='gd-sec'><span class='gd-tag'>Phàn nàn về đồ vật</span>Đồ dùng không tốt cũng nói được.</div><div class='gd-ex-line'>・<span class='gd-jp'>このパソコンときたら、すぐ固まるんだから。</span>(Cái máy tính này thật là, hơi một tí là đơ)</div><div class='gd-sec'><span class='gd-tag'>Tự trách mình</span>Lôi chính mình ra «mổ xẻ» cũng rất tự nhiên.</div><div class='gd-ex-line'>・<span class='gd-jp'>私ときたら、また傘を電車に忘れてきた。</span>(Tôi thật là, lại để quên cái ô trên tàu rồi)</div><div class='gd-sec'><span class='gd-tag'>Bỏ lửng câu</span>Trong văn nói, người ta hay bỏ phần phàn nàn, chỉ nói đến ときたら rồi để giọng điệu cho người nghe tự hiểu là đang bất mãn.</div><div class='gd-ex-line'>・<span class='gd-jp'>まったく、うちの主人ときたら……</span>(Thật tình, ông chồng nhà tôi đúng là...)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này dùng để kể tội ai đó, cái gì đó <b>với người thứ ba</b>, không dùng để gọi thẳng vào mặt đối phương. Nói thẳng với mẹ mình「お母さんときたら!」là sai.<br>・Phía sau là miêu tả và phàn nàn, không đi với yêu cầu hay quyết định kiểu «hãy ~», «~ nhé/đi». Ví dụ <span class='gd-jp'>うちの部長ときたら、早く帰ってください</span> mà nối một lời yêu cầu như vậy là không đúng.<br>・Về cơ bản mang nghĩa tiêu cực, đừng dùng để khen người. <span class='gd-jp'>うちの息子ときたら、頭がいい</span> nghe sẽ rất lạ.<br>・Sắc thái khá khẩu ngữ, dùng khi tám chuyện, ít dùng trong văn bản trang trọng hay báo cáo.<br>・Đôi khi bạn sẽ nghe câu kiểu <span class='gd-jp'>夏ときたら、やっぱりビールでしょ。</span>(Nhắc đến mùa hè thì đúng là phải có bia rồi) theo kiểu «nhắc đến A là nghĩ ngay đến B». Đó là một cách dùng khác, không phải phàn nàn, nghe thấy thì đừng lẫn nhé.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>ったら</b>: cũng dùng để phàn nàn, nhưng nhẹ hơn, thường mang chút thân mật kiểu «thật hết nói nổi với bạn», và <b>có thể gọi thẳng đối phương</b>.<br><span class='gd-jp'>もう、お母さんったら!</span>(Trời ơi, mẹ thật là!): nói trực tiếp với mẹ, được<br><b>ときたら</b>: chê nặng hơn, chỉ dùng khi nói với người khác về người đó.<br><span class='gd-jp'>うちの母ときたら、人の話を全然聞かない。</span>(Nhắc đến mẹ tôi, chẳng bao giờ nghe người khác nói): than với bạn bè</div><div class='gd-sec'><b>に至っては</b>: nêu cả một nhóm người hay một loạt việc trước, rồi chọn ra <b>cái quá đáng nhất</b>.<br><span class='gd-jp'>みんな遅刻したが、田中さんに至っては来なかった。</span>(Ai cũng đến muộn, riêng Tanaka còn quá đáng hơn, chẳng thèm đến luôn)<br><b>ときたら</b> không cần so sánh với ai, cứ điểm danh thẳng một người hoặc một thứ để kể tội.</div><div class='gd-warn'>Mẹo phân biệt: muốn trách thẳng vào mặt «bạn thật là» thì dùng ったら; kể tội ai đó với người khác thì dùng ときたら; chọn ra cái quá đáng nhất trong một nhóm thì dùng に至っては.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu này hay đi cùng「<span class='gd-jp'>まったく</span>」và「<span class='gd-jp'>〜んだから</span>」, làm cảm giác phàn nàn mạnh hơn: <span class='gd-jp'>うちの夫ときたら、まったく何もしないんだから。</span>(Nhắc đến chồng tôi, đúng là chẳng làm gì cả)</div>","n1-46":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にあって」tương đương với <b>«trong hoàn cảnh ~», «với tư cách là ~»</b> của văn viết tiếng Việt. Phía trước đặt một thời đại, hoàn cảnh hoặc thân phận đặc biệt, phía sau nói về trạng thái, cách làm, hoặc điều nên làm trong bối cảnh đó. Mẫu này thường gặp trong tin tức, diễn văn, bài viết, còn trò chuyện hằng ngày gần như không dùng.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Chỉ ghép với danh từ: Danh từ + にあって<br><span class='gd-pair'><span class='gd-jp'>非常時</span> → <span class='gd-jp'>非常時にあって</span></span>(trong thời kỳ bất thường như thế này)<br><span class='gd-pair'><span class='gd-jp'>現代</span> → <span class='gd-jp'>現代にあって</span></span>(sống trong thời hiện đại)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thời đại, tình huống đặc biệt</span>Như thời kỳ khẩn cấp, lúc kinh tế suy thoái, thời đại bùng nổ thông tin.</div><div class='gd-ex-line'>・<span class='gd-jp'>この非常時にあって、リーダーは冷静であるべきだ。</span>(Trong thời kỳ bất thường này, người lãnh đạo phải bình tĩnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>情報があふれる現代にあって、正しい情報を選ぶ力が必要だ。</span>(Sống trong thời hiện đại tràn ngập thông tin, ta cần năng lực chọn lọc thông tin đúng)</div><div class='gd-sec'><span class='gd-tag'>Thân phận, lập trường</span>Thường viết thành「〜という立場にあって」.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>(Ở cương vị giám đốc, không được phép phát ngôn hấp tấp)</div><div class='gd-sec'><span class='gd-tag'>Đang ở một nơi nào đó</span>Phần lớn là nơi không bình thường như «nước ngoài», «chiến trường», mang sắc thái văn chương.</div><div class='gd-ex-line'>・<span class='gd-jp'>異国にあって、家族からの手紙が何よりの支えだった。</span>(Ở nơi đất khách quê người, thư của gia đình là chỗ dựa lớn nhất của tôi)</div><div class='gd-h'>Hai dạng biến thể hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>にあっても</span>Thêm「も」thành <b>«dù ở trong ~ thì vẫn…»</b>, phía sau thường là «vẫn không bỏ cuộc, vẫn kiên cường».</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな苦境にあっても、彼女は笑顔を忘れなかった。</span>(Dù ở trong hoàn cảnh khó khăn đến đâu, cô ấy vẫn không quên nụ cười)</div><div class='gd-sec'><span class='gd-tag'>にあっては</span>Thêm「は」để nhấn mạnh <b>«trong tình huống này thì (chỉ còn cách)…»</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>この不況下にあっては、どの会社も節約せざるを得ない。</span>(Trong thời kỳ suy thoái này, công ty nào cũng buộc phải tiết kiệm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chỉ ghép với danh từ. Muốn dùng với động từ thì phải biến nó thành danh từ trước, hoặc đổi sang「〜という状況にあって」.<br>・Phía trước phải là <b>môi trường hoặc thân phận đặc biệt, đáng để nhắc đến</b>. Những thời điểm bình thường như「月曜日にあって」「普通の日にあって」nghe rất kỳ.<br>・Đây là văn viết rất cứng. Nói chuyện với bạn bè thì dùng「忙しい中」「〜なのに」là đủ, nói にあって sẽ nghe như đang đọc thông cáo báo chí.<br>・Đừng nhầm với «ở đâu» thông thường: <span class='gd-jp'>その店は駅前にあって便利だ。</span>(Cửa hàng đó ở ngay trước ga, rất tiện) Ở đây あって chỉ có nghĩa «nằm ở», không phải mẫu ngữ pháp này.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>にあたって</b> (chỉ khác một chữ, dễ nhìn nhầm nhất) = <b>trước khi / vào dịp bắt đầu làm một việc gì</b>, có thể ghép với động từ.<br><span class='gd-jp'>社長に就任するにあたって、一言ご挨拶申し上げます。</span>(Nhân dịp nhậm chức giám đốc, tôi xin phép nói vài lời chào mọi người)<br><span class='gd-jp'>社長という立場にあって、軽率な発言は許されない。</span>(Ở cương vị giám đốc, không được phép phát ngôn hấp tấp)<br>Câu đầu nhấn vào «thời điểm nhậm chức», câu sau nhấn vào «đang luôn ở vị trí giám đốc».</div><div class='gd-sec'><b>とあって</b> = <b>vì là ~ nên</b> (nêu nguyên nhân).<br><span class='gd-jp'>不況とあって、就職が厳しい。</span>(Vì đang suy thoái nên tìm việc rất khó)<br><span class='gd-jp'>不況にあって、この会社は売り上げを伸ばしている。</span>(Dù đang trong suy thoái, công ty này vẫn tăng doanh thu)<br>とあって là «vì thế này nên thế kia»; にあって là «đang ở trong môi trường này thì thể hiện ra sao».</div><div class='gd-warn'>Mẹo phân biệt: «ở trong ~ / với tư cách ~» dùng にあって, «nhân dịp làm ~» dùng にあたって, «vì là ~» dùng とあって.</div>","n1-48":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「～ともなれば」nghĩa là <b>「đã đến mức/vị trí ～ rồi thì đương nhiên là…」</b>. Phía trước đặt một thân phận, độ tuổi hay thời điểm <b>cao hơn bình thường một bậc</b>, phía sau nói \"lên đến tầng này thì tự nhiên sẽ như vậy\". Giống như người Việt hay nói: \"Người ta làm đến giám đốc rồi, nghỉ lễ mà vẫn phải nghe điện thoại công việc là chuyện bình thường thôi\", chính là giọng điệu này.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Lên một bậc về thân phận, tuổi tác</span>Khi lên một chức vụ nào đó hay đến một độ tuổi nào đó, trách nhiệm và kỳ vọng của người khác cũng thay đổi theo.</div><div class='gd-ex-line'>・<span class='gd-jp'>プロともなれば、これくらいは当然できる。</span>（Đã là dân chuyên nghiệp rồi thì mức này đương nhiên làm được）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長ともなれば、休みの日も仕事の電話が来る。</span>（Làm đến giám đốc thì ngay cả ngày nghỉ cũng có điện thoại công việc gọi đến）</div><div class='gd-sec'><span class='gd-tag'>Khi thời điểm đến</span>Đến một mùa hay một ngày đặc biệt nào đó, mọi thứ xung quanh tự nhiên sẽ khác đi.</div><div class='gd-ex-line'>・<span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span>（Cứ đến tháng 12 là khắp phố ngập tràn không khí Giáng sinh）</div><div class='gd-sec'><span class='gd-tag'>Khi thật sự phải làm việc lớn</span>Đi sau động từ, mang nghĩa \"nếu thật sự phải làm đến mức này\", lúc này sắc thái \"giả sử\" rõ hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>海外に引っ越すともなれば、準備することが山ほどある。</span>（Nếu thật sự phải chuyển ra nước ngoài thì có cả núi việc cần chuẩn bị）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋ともなれば：<span class='gd-pair'><span class='gd-jp'>大学生</span> → <span class='gd-jp'>大学生ともなれば</span></span><br>Động từ thể từ điển＋ともなれば：<span class='gd-pair'><span class='gd-jp'>結婚する</span> → <span class='gd-jp'>結婚するともなれば</span></span><br>Phía sau thường đi với <span class='gd-jp'>当然</span>、<span class='gd-jp'>～なければならない</span>、<span class='gd-jp'>～ものだ</span>, tức là những cách nói mang nghĩa \"đương nhiên\", \"vốn dĩ phải thế\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải khiến người ta cảm thấy <b>đã lên một tầng khác</b>. <span class='gd-jp'>小学生ともなれば</span> dùng được, vì so với mẫu giáo thì đã lên một bậc; còn đặt bừa một từ bình thường vào thì câu sẽ rất kỳ.<br>・Phía sau nói về điều \"tự nhiên sẽ như vậy\", <b>không đặt ý chí hay lời nhờ vả của bản thân vào</b>. Muốn nói \"nếu làm giám đốc thì tôi muốn cố gắng hơn\", không được nói <span class='gd-jp'>社長ともなれば、もっと頑張りたい</span>, mà phải nói <span class='gd-jp'>社長になったら、もっと頑張りたい。</span><br>・Sắc thái khá trang trọng, thường gặp trong tin tức, bài viết, diễn thuyết. Khi trò chuyện hằng ngày thường nói <span class='gd-jp'>～になると</span> hoặc <span class='gd-jp'>～となると</span>.<br>・Đừng nhầm với <span class='gd-jp'>となれば</span>: thiếu chữ <span class='gd-jp'>も</span> thì chỉ đơn thuần là \"nếu là như vậy thì\", không có sự nhấn mạnh \"đã đến tầm này rồi\". Ví dụ: <span class='gd-jp'>明日も雨となれば、試合は中止だ。</span>（Nếu ngày mai trời cũng mưa thì trận đấu sẽ bị hủy）</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>ともなると</b>: nghĩa gần như y hệt, trong kỳ thi hầu hết có thể thay cho nhau.<br><span class='gd-jp'>12月ともなると、街はクリスマス一色になる。</span><br><span class='gd-jp'>12月ともなれば、街はクリスマス一色になる。</span><br>Cả hai câu đều đúng. Nếu cứ phải phân biệt thì <span class='gd-jp'>ともなれば</span> nhờ có <span class='gd-jp'>ば</span> nên sắc thái \"giả sử thật sự đến mức đó\" nhỉnh hơn một chút.</div><div class='gd-sec'><b>とあれば</b>: trông rất giống nhưng hướng nghĩa ngược lại. Nó là \"nếu là vì ～ / nếu là yêu cầu của ～\", phía sau thường là việc <b>bản thân sẵn lòng làm, hoặc đành phải làm</b>.<br><span class='gd-jp'>社長の命令とあれば、従うしかない。</span>（Đã là lệnh của giám đốc thì chỉ còn cách tuân theo）<br><span class='gd-jp'>社長ともなれば、責任も重くなる。</span>（Làm đến giám đốc thì trách nhiệm đương nhiên cũng nặng hơn）</div><div class='gd-warn'>Mẹo phán đoán nhanh: phía trước là \"lên một bậc\", phía sau nói \"tự nhiên sẽ như vậy\" thì dùng ともなれば／ともなると; phía trước là \"một lý do đặc biệt\", phía sau nói \"vậy thì tôi sẽ làm\" thì dùng とあれば.</div>","n1-49":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'><span class='gd-jp'>ともなく</span> có hai cách dùng, cốt lõi đều là <b>\"không rõ ràng\"</b>.<br>Một là <b>hành động không có mục đích</b>, kiểu \"xem lơ đãng, vừa xem vừa không xem\": TV mở sẵn, mắt bạn có nhìn, nhưng thật ra chẳng nhìn gì cụ thể.<br>Hai là <b>không nói rõ được nguồn gốc</b>: \"không biết từ đâu\", \"không biết ai là người bắt đầu trước\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Làm một cách vô thức</span>Không định làm, vậy mà tự nhiên lại đang làm. Đặc điểm lớn nhất là <b>đặt cùng một động từ ở trước và sau</b>, hoặc hai động từ có nghĩa rất gần nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなく窓の外を見ていた。</span>（Tôi không định nhìn gì cụ thể, cứ thế ngó ra ngoài cửa sổ）</div><div class='gd-ex-line'>・<span class='gd-jp'>聞くともなく隣の席の話を聞いていた。</span>（Tôi không cố ý nghe, nhưng chuyện của bàn bên cạnh vẫn lọt vào tai）</div><div class='gd-ex-line'>・<span class='gd-jp'>見るともなくテレビを眺めていたら、見覚えのある街が映った。</span>（Tôi đang xem TV một cách lơ đãng thì trên màn hình hiện ra một con phố quen quen）</div><div class='gd-sec'><span class='gd-tag'>Không nói được là ai, ở đâu</span>Phía trước đặt các từ dùng trong câu hỏi như 「どこ、誰、いつ」. Phía sau thường kèm <span class='gd-jp'>から</span>、<span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>どこからともなく、いい匂いがしてきた。</span>（Không biết từ đâu thoảng đến một mùi thơm）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰からともなく拍手が起こった。</span>（Không biết ai khởi đầu trước, mọi người đều vỗ tay）</div><div class='gd-ex-line'>・<span class='gd-jp'>男はどこへともなく歩いていった。</span>（Người đàn ông đó đi về đâu không rõ）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にともなく「ありがとう」とつぶやいた。</span>（Không nói với ai cả, chỉ lẩm bẩm một câu「ありがとう」）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: dùng dạng nguyên thể như trong từ điển (thể từ điển) rồi thêm <span class='gd-jp'>ともなく</span>, phía sau lại đặt chính động từ đó.<br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るともなく見る</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞くともなく聞く</span></span><br><b>Từ nghi vấn</b>: 「どこ、誰、いつ」 cộng trợ từ, rồi thêm <span class='gd-jp'>ともなく</span>.<br><span class='gd-pair'><span class='gd-jp'>どこから</span> → <span class='gd-jp'>どこからともなく</span></span><span class='gd-pair'><span class='gd-jp'>誰から</span> → <span class='gd-jp'>誰からともなく</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ phải ở thể từ điển: <span class='gd-jp'>見るともなく</span>. Không được bỏ ます rồi ghép thành 「見ともなく」, cũng không được dùng thể quá khứ 「見たともなく」.<br>・Số động từ dùng được kiểu này rất hạn chế, hầu như chỉ là <span class='gd-jp'>見る</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>言う</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>待つ</span>, những việc mắt, tai, miệng, đầu óc làm một cách tự nhiên. Đừng tùy tiện áp vào động từ khác.<br>・<span class='gd-jp'>どこからともなく</span> và <span class='gd-jp'>どことなく</span> chỉ khác nhau chút xíu nhưng nghĩa không giống nhau. <span class='gd-jp'>どことなく</span> là \"không hiểu sao cứ thấy hơi ～\", nói về cảm giác: <span class='gd-jp'>彼はどことなく父に似ている。</span>（Không nói rõ được ở chỗ nào, nhưng anh ấy hơi giống bố tôi）. Muốn nói \"từ đâu đến\" thì dùng <span class='gd-jp'>どこからともなく</span>.<br>・「Vô thức」không có nghĩa là \"không làm\". <span class='gd-jp'>見るともなく見る</span> vẫn là đang nhìn, chỉ là không có mục đích.<br>・Đây là cách nói thiên về văn viết, rất hay gặp trong tiểu thuyết, tản văn. Khi trò chuyện hằng ngày thường nói <span class='gd-jp'>なんとなく</span> hoặc <span class='gd-jp'>どこからか</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b><span class='gd-jp'>ともなると</span></b> cùng cấp độ (nghĩa giống <span class='gd-jp'>ともなれば</span>) chỉ khác vài chữ nhưng nghĩa hoàn toàn khác. Nghĩa của nó là: một khi đến mức độ hay lập trường nào đó thì <b>tự nhiên sẽ ～</b>. Phía trước phần lớn là danh từ, cũng có thể đi với động từ thể từ điển.<br>Thử so sánh trong cùng tình huống \"sống một mình\":<br><b><span class='gd-jp'>ともなく</span></b> (vô thức): <span class='gd-jp'>一人の部屋で、見るともなくテレビを見ていた。</span>（Một mình trong phòng, tôi xem TV một cách lơ đãng）<br><b><span class='gd-jp'>ともなく</span></b> (không rõ nguồn): <span class='gd-jp'>夜中、どこからともなく猫の鳴き声が聞こえてきた。</span>（Nửa đêm, không biết từ đâu vọng đến tiếng mèo kêu）<br><b><span class='gd-jp'>ともなると</span></b> (danh từ): <span class='gd-jp'>夜中ともなると、この辺りはすっかり静かになる。</span>（Cứ đến nửa đêm là khu này trở nên hoàn toàn yên tĩnh）<br><b><span class='gd-jp'>ともなると</span></b> (động từ): <span class='gd-jp'>一人暮らしをするともなると、家事も全部自分でやらなければならない。</span>（Một khi đã phải sống một mình thì việc nhà cũng phải tự làm hết）</div><div class='gd-warn'>Mẹo phán đoán nhanh:<br>・<span class='gd-jp'>ともなく</span> thường có dạng \"cùng một động từ＋ともなく＋cùng một động từ\" hoặc \"どこから／誰から＋ともなく\", nghĩa là vô thức, hoặc không nói rõ được là ai hay ở đâu.<br>・<span class='gd-jp'>ともなると</span> phía sau sẽ nối với \"thì sẽ ～, đương nhiên ～\", nghĩa là đến mức độ hay lập trường đó thì tự nhiên sẽ có tình trạng nào đó.<br>Đừng chỉ nhìn phía trước là danh từ hay động từ, hãy nhìn hình thức và ý nghĩa của cả câu.</div>","n1-60":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「Aかたがた」giống với cách nói <b>「nhân tiện gửi lời cảm ơn」「nhân tiện hỏi thăm」</b> trong tiếng Việt. Khi đến thăm hoặc viết thư cho ai đó, bạn kết hợp thêm một mục đích khác, ví dụ cảm ơn, báo tin gần đây, hỏi thăm. Đây là cách nói rất trang trọng, thường xuất hiện khi đến thăm bề trên, khách hàng hoặc trong thư từ công việc.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước là <b>danh từ</b>, và phần lớn là danh từ chỉ \"hành động\", ví dụ <span class='gd-jp'>お礼</span> (cảm ơn), <span class='gd-jp'>ご挨拶</span> (chào hỏi), <span class='gd-jp'>ご報告</span> (báo cáo), <span class='gd-jp'>お見舞い</span> (thăm bệnh), <span class='gd-jp'>散歩</span> (đi dạo).<br><span class='gd-pair'><span class='gd-jp'>お礼</span> → <span class='gd-jp'>お礼かたがた</span></span><span class='gd-pair'><span class='gd-jp'>ご報告</span> → <span class='gd-jp'>ご報告かたがた</span></span><br>Phía sau thường là hành động như \"đến thăm\" hoặc \"viết thư, phát biểu\", hay gặp nhất là <span class='gd-jp'>伺う</span>, <span class='gd-jp'>お邪魔する</span>, <span class='gd-jp'>申し上げる</span>.</div><div class='gd-h'>Mẫu câu hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Đến thăm nhà</span>Nói rõ mục đích hôm nay mình đến.</div><div class='gd-ex-line'>・<span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>(Hôm nay tôi đến chào hỏi, đồng thời cảm ơn chuyện hôm trước)</div><div class='gd-ex-line'>・<span class='gd-jp'>近くまで来ましたので、ご挨拶かたがたお邪魔しました。</span>(Tình cờ đi ngang gần đây nên tôi nhân tiện ghé qua chào bạn một tiếng)</div><div class='gd-sec'><span class='gd-tag'>Thư từ</span>Rất hay dùng ở phần kết của thư công việc, thư hỏi thăm, gần như là câu cố định.</div><div class='gd-ex-line'>・<span class='gd-jp'>略儀ながら書中をもちまして、お礼かたがたご挨拶申し上げます。</span>(Xin phép dùng thư này thay cho việc gặp trực tiếp, để gửi lời cảm ơn và hỏi thăm đến bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>転勤のご報告かたがた、お手紙を差し上げます。</span>(Tôi viết thư này cũng là để báo với bạn tin tôi chuyển công tác)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nối danh từ, không nối động từ thể từ điển: nói <span class='gd-jp'>お礼かたがた</span>, không nói <span class='gd-jp'>お礼を言うかたがた</span>.<br>・\"Nhân tiện\" trong tiếng Việt nghe có vẻ việc đó không quan trọng, nhưng かたがた trong tiếng Nhật không mang ý đó, cảm ơn và hỏi thăm đều là mục đích thật lòng. Dùng <span class='gd-jp'>お礼かたがた</span> không hề bất lịch sự, ngược lại còn rất chuẩn mực.<br>・Nó rất trang trọng, phía sau hay đi với các cách nói khiêm nhường như <span class='gd-jp'>伺う</span>, <span class='gd-jp'>申し上げる</span>. Với bạn bè, câu kiểu \"tôi nhân tiện ghé cửa hàng tiện lợi\" thì sẽ không dùng.<br>・「<span class='gd-jp'>方々</span>(かたがた)」trong <span class='gd-jp'>ご来場の方々</span>, <span class='gd-jp'>関係者の方々</span> nghĩa là \"các vị\", chỉ trùng cách đọc thôi, không liên quan đến mẫu ngữ pháp này.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'><b>かたがた</b> = dùng trong dịp trang trọng, khi đến thăm hoặc viết thư và <b>kết hợp thêm một mục đích khác</b>:<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺いました。</span>(Tôi đến thăm nhà thầy, cũng là để cảm ơn thầy)<br><b>がてら</b> = khẩu ngữ đời thường, <b>ra ngoài làm A, tiện đường làm B</b>:<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>(Đi dạo, tiện thể mua bánh mì về)<br><b>かたわら</b> = trong thời gian dài <b>vừa làm công việc chính, vừa làm thêm việc khác</b>, không liên quan đến \"nhân tiện\":<br><span class='gd-jp'>会社に勤めるかたわら、小説を書いている。</span>(Anh ấy vừa đi làm công ty, vừa viết tiểu thuyết)</div><div class='gd-warn'>Mẹo phân biệt: khi đến thăm hoặc viết thư trang trọng, \"kèm lời cảm ơn, nhân tiện hỏi thăm\" thì dùng かたがた; ra ngoài đời thường tiện đường làm thêm việc nhỏ thì dùng がてら; lâu dài đảm nhận hai việc cùng lúc thì dùng かたわら.</div>","n1-61":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AかたわらB」nghĩa là <b>「ngoài việc A (công việc chính), còn làm thêm B」</b>, hơi giống kiểu \"đa nhiệm, làm nhiều nghề\" bây giờ hay nói. <span class='gd-jp'>かたわら</span> vốn có nghĩa là \"bên cạnh\": việc chính đặt ở giữa, bên cạnh còn có một việc khác song song.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm thêm lâu dài</span>Nói về cuộc sống hoặc tình trạng công việc của một người: nghề chính là gì, ngoài ra còn lâu dài làm gì nữa. Thường xuất hiện trong bài giới thiệu nhân vật, bài báo, bài tự giới thiệu.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社に勤めるかたわら、週末は小説を書いている。</span>(Ngoài giờ đi làm ở công ty, cuối tuần tôi viết tiểu thuyết)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は大学で教えるかたわら、翻訳の仕事もしている。</span>(Ngoài việc dạy ở đại học, cô ấy còn làm cả công việc dịch thuật)</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のかたわら、日本語の勉強を続けている。</span>(Ngoài giờ làm việc, tôi vẫn tiếp tục học tiếng Nhật)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ: thể từ điển (dạng nguyên thể trong từ điển) ＋ かたわら<br><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働くかたわら</span></span><span class='gd-pair'><span class='gd-jp'>店を経営する</span> → <span class='gd-jp'>店を経営するかたわら</span></span><br>Danh từ: danh từ ＋ の ＋ かたわら<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のかたわら</span></span><span class='gd-pair'><span class='gd-jp'>育児</span> → <span class='gd-jp'>育児のかたわら</span></span><br>Danh từ thường là những từ như \"công việc, nghiên cứu, nuôi con\", tức là tự thân nó đã đại diện cho một hoạt động.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nó <b>không phải</b> là \"cùng một lúc tay làm việc này, tay làm việc kia\". <span class='gd-jp'>音楽を聞くかたわら勉強する</span> là sai, trường hợp này phải dùng <span class='gd-jp'>聞きながら</span>.<br>・Cả hai việc đều <b>kéo dài một khoảng thời gian</b>, nên phía sau rất hay đi với 「〜ている」. Việc chỉ xảy ra một lần thì không hợp.<br>・Phía trước đặt việc <b>chính</b>, phía sau đặt việc làm thêm, đừng đặt ngược.<br>・Phía trước không nối thể た: <span class='gd-jp'>勤めたかたわら</span> là sai, luôn dùng thể từ điển.<br>・Đây là văn viết, nói chuyện với bạn bè hiếm khi dùng, khẩu ngữ thường nói <span class='gd-jp'>仕事しながら</span> hoặc <span class='gd-jp'>本業のほかに</span>.<br>・Khi thấy dạng 「danh từ のかたわらで」 như <span class='gd-jp'>母のかたわらで</span>, phần lớn là nghĩa đen \"ở bên cạnh ～\", không phải mẫu ngữ pháp này.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'><b>ながら</b> = cùng một thời điểm, tay làm hai việc đồng thời:<br><span class='gd-jp'>音楽を聞きながら勉強する。</span>(Vừa nghe nhạc vừa học bài)<br><b>かたわら</b> = lâu dài có hai vai trò hoặc hai công việc:<br><span class='gd-jp'>会社で働くかたわら、夜間の大学に通っている。</span>(Ngoài giờ đi làm ban ngày, buổi tối tôi còn học đại học hệ tại chức)<br><b>がてら</b> = trong chuyến đi ra ngoài lần này, tiện thể làm thêm một việc khác, mang tính ngắn hạn, một lần:<br><span class='gd-jp'>散歩がてら、パンを買ってきた。</span>(Ra ngoài đi dạo một chút, tiện thể mua bánh mì về)<br><b>かたがた</b> = ý nghĩa gần với がてら nhưng trang trọng hơn, hay dùng khi đến thăm, cảm ơn, hỏi thăm. Phía sau là hành động thực tế, phía trước là mục đích kèm theo:<br><span class='gd-jp'>先日のお礼かたがた、ご挨拶に伺いました。</span>(Nhân dịp cảm ơn chuyện hôm trước, tôi đến thăm và chào hỏi bạn)</div><div class='gd-warn'>Mẹo phân biệt: nói về một người lâu dài làm hai việc thì dùng かたわら; trong một chuyến đi ra ngoài làm hai việc thì dùng がてら (dịp trang trọng dùng かたがた); cùng một lúc tay làm hai việc thì dùng ながら.</div>","n1-50":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AともBともつかない」nghĩa là <b>「chẳng ra A mà cũng chẳng ra B」</b>, giống cảm giác \"nửa cười nửa không\", \"xanh không ra xanh, lục không ra lục\". Thứ bạn đang nhìn nằm lửng lơ giữa hai bên, bạn không phân biệt được nó thuộc về bên nào.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>A và B là <b>danh từ</b> hoặc <b>động từ thể thông thường</b> (thể từ điển, thể ている, thể ない… tức các thể không có ます). Sau mỗi vế thêm một 「とも」, cuối cùng ghép với 「つかない」.<br><span class='gd-pair'><span class='gd-jp'>本気</span>＋<span class='gd-jp'>冗談</span> → <span class='gd-jp'>本気とも冗談ともつかない</span></span><br><span class='gd-pair'><span class='gd-jp'>笑っている</span>＋<span class='gd-jp'>泣いている</span> → <span class='gd-jp'>笑っているとも泣いているともつかない</span></span><br>「つかない」ở đây có nghĩa là \"không phán đoán được, không xác định được\", thường viết bằng hiragana. Phía sau hay nối thẳng với danh từ như: nét mặt, giọng nói, khẩu khí, câu trả lời, màu sắc.</div><div class='gd-h'>Hai dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ともつかない</span>Bản thân sự vật đã mơ hồ, nhìn hay nghe cũng không phân biệt được.</div><div class='gd-ex-line'>・<span class='gd-jp'>本気とも冗談ともつかない言い方だった。</span>（Cách nói đó khiến người ta không phân biệt được anh ấy nghiêm túc hay đang đùa）</div><div class='gd-ex-line'>・<span class='gd-jp'>ため息ともあくびともつかない声が聞こえた。</span>（Có tiếng gì đó vọng tới, không rõ là tiếng thở dài hay tiếng ngáp）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は笑っているとも泣いているともつかない顔をしていた。</span>（Cô ấy mang vẻ mặt nửa cười nửa mếu, không rõ là cười hay khóc）</div><div class='gd-sec'><span class='gd-tag'>とも言わない</span>A và B thường là một khẳng định, một phủ định, diễn tả việc đối phương <b>không bày tỏ thái độ</b>, kiểu \"không nói có cũng chẳng nói không\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行くとも行かないとも言わない。</span>（Anh ấy không nói là đi, cũng không nói là không đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はいいとも悪いとも言わなかった。</span>（Trưởng phòng không nói là được, cũng không nói là không được）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「つかない」chỉ việc <b>bản thân sự vật đó</b> không phân biệt được, dùng để miêu tả những thứ đang ở trước mắt như nét mặt, giọng nói, câu trả lời. Nếu chỉ là \"tôi không biết đáp án\" thì đừng dùng nó: muốn nói \"tôi không biết anh ấy có đến hay không\", hãy nói <span class='gd-jp'>彼が来るか来ないか分からない</span>.<br>・Sau cả A và B <b>đều phải</b> có とも. Chỉ viết một cái, hoặc viết thành 「AかBともつかない」 đều sai.<br>・Động từ nối thẳng với とも, không cần thêm 「の」: chỉ cần viết <span class='gd-jp'>笑っているとも</span>, không viết thành 笑っているのとも.<br>・Đây là cách viết thiên về văn viết, văn tiểu thuyết. Khi trò chuyện bình thường, nói <span class='gd-jp'>冗談か本気か分からない</span> là đủ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>AともBとも言わない</b>: cả hai đều <b>không nói</b>, thái độ không rõ ràng.<br><span class='gd-jp'>彼は賛成とも反対とも言わなかった。</span>（Anh ấy không nói là tán thành, cũng không nói là phản đối）<br><b>Aと言わずBと言わず</b>: dù là A hay B thì <b>tất cả đều</b> như vậy.<br><span class='gd-jp'>手と言わず足と言わず泥だらけになった。</span>（Tay cũng vậy, chân cũng vậy, cả người dính đầy bùn）<br>Cả hai đều có dạng 「A…B…」 cộng với 「言わ」 nên trông rất giống, nhưng nghĩa hoàn toàn khác: một bên là \"cả hai đều không nói\", một bên là \"chỗ nào cũng như nhau\".</div><div class='gd-sec'><b>〜ともなく</b> cũng có 「とも」, nhưng chỉ có <b>một vế</b>, phía trước thường là từ nghi vấn, nghĩa là \"không rõ là ở đâu, là ai\".<br><span class='gd-jp'>どこからともなく音楽が聞こえてきた。</span>（Không biết từ đâu vọng lại tiếng nhạc）</div><div class='gd-warn'>Mẹo phân biệt nhanh: có hai lựa chọn mà không phân biệt được là cái nào, dùng ともつかない; cả hai bên đều không bày tỏ thái độ, dùng とも言わない; bao gồm cả hai, tất cả đều như vậy, dùng と言わず; chỉ có một từ nghi vấn kiểu \"không biết từ đâu, không biết là ai\", dùng ともなく.</div>","n1-51":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てまで」nghĩa là <b>「bất chấp phải ～ cũng muốn…」「thậm chí ～ cũng làm…」</b>. Để đạt được một mục đích nào đó, người ta làm cả những việc bình thường sẽ không làm, cái giá phải trả rất lớn. Khi người Nhật dùng mẫu này, giọng điệu thường kèm ý \"có cần thiết phải làm đến mức đó không?\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Chuyển động từ sang thể て, thêm 「まで」, rồi nối với mục đích mà bạn thực sự muốn đạt được.<br><span class='gd-pair'><span class='gd-jp'>借金する</span> → <span class='gd-jp'>借金して</span> → <span class='gd-jp'>借金してまで</span></span><br><span class='gd-pair'><span class='gd-jp'>無理をする</span> → <span class='gd-jp'>無理をしてまで</span></span><br><span class='gd-pair'><span class='gd-jp'>嘘をつく</span> → <span class='gd-jp'>嘘をついてまで</span></span><br>Khung của cả câu là <b>「Aてまで、B」＝ vì B mà không ngại làm A</b>. A là cái giá bạn bỏ ra, B là thứ bạn muốn có.</div><div class='gd-h'>Những dạng hay gặp</div><div class='gd-sec'><span class='gd-tag'>Không đáng</span>Phía sau đi với 「〜必要はない」「〜たくない」, nghĩa là \"vì chuyện này mà làm đến mức đó thì không đáng\". Đây là cách dùng phổ biến nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>借金してまで、ブランド品を買う必要はない。</span>（Không cần thiết phải đi vay tiền để mua đồ hiệu）</div><div class='gd-ex-line'>・<span class='gd-jp'>体を壊してまで働きたくない。</span>（Tôi không muốn làm việc đến mức hỏng cả sức khỏe）</div><div class='gd-sec'><span class='gd-tag'>Ngán ngẩm, nghi ngờ</span>Thấy cái giá người khác bỏ ra quá đà, bạn dùng câu hỏi để thể hiện.</div><div class='gd-ex-line'>・<span class='gd-jp'>そこまでして行きたいの？</span>（Bạn muốn đi đến mức phải làm vậy luôn hả?）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を裏切ってまで、出世したかったのか。</span>（Bạn muốn thăng chức đến mức phản bội cả bạn bè sao?）</div><div class='gd-sec'><span class='gd-tag'>Chỉ nói ai đó nỗ lực đến đâu</span>Không nhất thiết là chê trách, cũng có thể chỉ miêu tả ai đó đã bỏ ra rất nhiều, đôi khi còn kèm chút nể phục.</div><div class='gd-ex-line'>・<span class='gd-jp'>徹夜してまで並んで、限定スイーツを手に入れた。</span>（Thức trắng đêm xếp hàng, cuối cùng cũng mua được món tráng miệng giới hạn）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は自分の給料を減らしてまで、社員を守った。</span>（Giám đốc thậm chí cắt cả lương của mình để bảo vệ nhân viên）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Đừng đảo thứ tự</b>: trước てまで là \"cái giá\", phía sau mới là \"mục đích\". <span class='gd-jp'>借金してまで買う</span> là \"vay tiền để mua\". Nếu viết thành 「買ってまで借金する」 thì thành \"mua để đi vay tiền\", nghĩa hoàn toàn không thông.<br>・Phía trước phải là việc <b>bất thường, hy sinh lớn</b>. Nếu đặt vào một việc nhẹ nhàng, vốn dĩ vẫn làm hằng ngày thì câu mất cảm giác \"bất chấp\", nghe rất lạ.<br>・<span class='gd-jp'>そこまでして</span> là cách nói cố định rất hay dùng trong khẩu ngữ, nghĩa là \"làm đến mức đó\", cùng cảm giác với てまで. Lưu ý nó nói về việc <b>cái giá quá lớn</b>, không phải \"tình hình đã đến mức này rồi\".<br>・Danh từ phải thêm 「する」 hoặc 「をする」 để thành động từ trước khi ghép với てまで: <span class='gd-jp'>借金してまで</span>、<span class='gd-jp'>無理をしてまで</span>、<span class='gd-jp'>家族を犠牲にしてまで</span>. Không thể viết thẳng 「借金まで」, vì đó sẽ thành \"đến cả vay tiền cũng…\", là một nghĩa khác.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Đều là động từ cộng 「まで」, chỉ khác ở thể của động từ, nhưng nghĩa hoàn toàn khác:<br><b>Thể từ điển＋まで</b>＝cho đến khi ～<br>・<span class='gd-jp'>彼が来るまで待った。</span>（Tôi đã đợi cho đến khi anh ấy đến）<br><b>Thể て＋まで</b>＝bất chấp ～ cũng muốn<br>・<span class='gd-jp'>3時間も待ってまで、彼に会いたかった。</span>（Tôi muốn gặp anh ấy đến mức chịu đợi cả ba tiếng）<br><b>Thể từ điển＋までだ（đặt cuối câu）</b>＝cùng lắm thì ～<br>・<span class='gd-jp'>彼が来ないなら、一人で行くまでだ。</span>（Nếu anh ấy không đến thì cùng lắm tôi đi một mình）</div><div class='gd-warn'>Mẹo phân biệt nhanh: trước まで là <b>thể て</b> thì là \"bất chấp\"; là <b>thể từ điển</b> và câu chưa kết thúc thì là \"cho đến khi\"; <b>までだ</b> đặt cuối câu thì là \"cùng lắm thì / chỉ là\".</div>","n1-54":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かろう」chính là <b>phiên bản văn viết kiểu cũ</b> của「〜いだろう」, nghĩa là \"chắc là ~ đấy\", \"hẳn là ~ nhỉ\". <span class='gd-jp'>難しいだろう</span> viết thành <span class='gd-jp'>難しかろう</span> thì nghĩa không đổi, chỉ là nghe giống văn xã luận, tiểu thuyết, hoặc giọng một ông cụ trong phim cổ trang.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><b>Chỉ đi với tính từ い</b>: bỏ「い」ở cuối, thêm「かろう」.<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → bỏ い → <span class='gd-jp'>難しかろう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒かろう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かろう</span></span><br><b>Có hai trường hợp bạn cần nhớ riêng</b>:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかろう</span></span> (biến từ <span class='gd-jp'>よい</span> mà ra)<br><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかろう</span></span><br>「〜たい」chia giống tính từ い nên cũng đi được: <span class='gd-pair'><span class='gd-jp'>帰りたい</span> → <span class='gd-jp'>帰りたかろう</span></span> (chắc là muốn về lắm đây)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Suy đoán trong văn viết</span>Dùng khi suy đoán tình hình trong bài viết, bài bình luận, thường đi cùng <span class='gd-jp'>さぞ</span> (hẳn là).</div><div class='gd-ex-line'>・<span class='gd-jp'>山の上はさぞ寒かろう。</span>(Trên núi hẳn là lạnh lắm nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>最初は苦しかろうが、すぐに慣れる。</span>(Lúc đầu có lẽ sẽ vất vả, nhưng chẳng mấy chốc sẽ quen)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ではなかろうか</span>= \"chẳng phải là ~ sao?\". Rất hay gặp trong luận văn, xã luận, là cách nêu quan điểm khá tế nhị.</div><div class='gd-ex-line'>・<span class='gd-jp'>この計画には無理があるのではなかろうか。</span>(Kế hoạch này có phải hơi gượng ép không nhỉ?)</div><div class='gd-sec'><span class='gd-tag'>よかろう</span>Người lớn tuổi hoặc cấp trên nói \"được rồi, đồng ý\", mang cảm giác kẻ trên nói với người dưới, miễn cưỡng chấp nhận.</div><div class='gd-ex-line'>・<span class='gd-jp'>まあ、よかろう。今回だけは許してやる。</span>(Ừm, được thôi. Lần này tha cho cậu)</div><div class='gd-sec'><span class='gd-tag'>Cách nói cố định</span><span class='gd-jp'>安かろう悪かろう</span> = tiền nào của nấy (rẻ thì chất lượng kém).</div><div class='gd-ex-line'>・<span class='gd-jp'>安かろう悪かろうの時代は終わった。</span>(Thời \"rẻ thì chất lượng kém\" đã qua rồi)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な và danh từ <b>không thể</b> đi với かろう: <span class='gd-jp'>静かかろう</span> là sai, phải nói <span class='gd-jp'>静かだろう</span> hoặc <span class='gd-jp'>静かであろう</span>; danh từ cũng vậy, dùng <span class='gd-jp'>学生だろう</span> hoặc <span class='gd-jp'>学生であろう</span>.<br>・Động từ cũng không đi được: phải nói <span class='gd-jp'>行くだろう</span> hoặc <span class='gd-jp'>行くであろう</span>.<br>・<span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よかろう</span>, không có cách nói「いかろう」.<br>・「ろう」đọc kéo dài thành ろー.<br>・Nói chuyện với bạn bè mà dùng <span class='gd-jp'>暑かろう</span> thì nghe như đang đóng phim cổ trang, bình thường cứ nói <span class='gd-jp'>暑いだろう</span> là đủ.<br>・<span class='gd-jp'>よかろう</span> là giọng bề trên nói với người dưới, nói với cấp trên hay thầy cô sẽ rất thất lễ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>「〜かろうが／〜かろうと」có hai nghĩa, cần nhìn cả câu để phân biệt:<br><b>Chắc là ~, nhưng…</b> (suy đoán rồi chuyển ý): <span class='gd-jp'>その試験は難しかろうが、準備すれば突破できる。</span> (Kỳ thi đó chắc là khó, nhưng chỉ cần chuẩn bị là vượt qua được)<br><b>Dù ~ thì cũng…</b> (chính là bản tính từ い của <span class='gd-jp'>〜ようが／〜ようと</span>): <span class='gd-jp'>高かろうが安かろうが、必要なものは買う。</span> (Dù đắt hay rẻ, thứ cần thì vẫn mua)<br><span class='gd-jp'>どんなに辛かろうと、最後までやり抜く。</span> (Dù vất vả đến đâu, cũng sẽ kiên trì đến cùng)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu phía trước có「どんなに」「いくら」, hoặc có hai vế đi thành cặp (高かろうが安かろうが) → nghĩa \"dù ~ thì cũng…\"; nếu chỉ có một vế và phía sau là \"nhưng…\" → nghĩa \"chắc là ~, nhưng\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bản \"dù ~ thì cũng…\" cho động từ và danh từ chính là <span class='gd-jp'>〜ようが／〜ようと</span>: <span class='gd-jp'>雨が降ろうが、試合は行われる。</span> (Dù có mưa, trận đấu vẫn diễn ra như thường)</div>","n1-58":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とばかりに」nghĩa là <b>\"làm ra vẻ như muốn nói '~'\"</b>. Đối phương không nói thành lời, nhưng động tác, nét mặt rõ ràng đang nói một câu nào đó. Bạn hãy đặt <b>câu thoại trong lòng</b> ấy ở phía trước, rồi nối với hành động của họ ở phía sau.<br>Ví dụ trưởng phòng cứ nhìn đồng hồ, không nói gì nhưng ai cũng hiểu ông ấy đang nói \"mau tan làm thôi\", lúc này bạn dùng mẫu này.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Miêu tả dáng vẻ của người khác</span>Viết ra \"câu thoại\" ẩn sau hành động của đối phương, hay gặp nhất trong tiểu thuyết, bài báo, văn miêu tả cảnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>「早く帰れ」とばかりに、課長は時計をちらちら見た。</span>(Trưởng phòng cứ liếc đồng hồ, như thể muốn nói \"về nhanh đi\")</div><div class='gd-ex-line'>・<span class='gd-jp'>「遊ぼう」とばかりに、犬がボールをくわえて走ってきた。</span>(Con chó ngậm quả bóng chạy tới, như thể muốn nói \"chơi đi mà\")</div><div class='gd-ex-line'>・<span class='gd-jp'>「待ってました」とばかりに、彼は勢いよく手を挙げた。</span>(Anh ấy giơ tay thật mạnh, như thể muốn nói \"chờ mãi mới tới lúc này\")</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước là <b>một câu thoại</b>, nên câu thoại có dạng nào cũng được: giọng ra lệnh (<span class='gd-jp'>帰れ</span>), giọng rủ rê (<span class='gd-jp'>遊ぼう</span>), thể ます (<span class='gd-jp'>待ってました</span>), một từ đơn hay một tiếng cảm thán cũng đều được. Thường đặt trong 「」 để người đọc nhìn là biết đó là lời thoại.<br>Khi phía sau cần nối với danh từ thì đổi thành <b>とばかりの</b>:<br>・<span class='gd-jp'>「もう帰れ」とばかりの冷たい態度だった。</span>(Một thái độ lạnh lùng như thể muốn nói \"cút đi\")</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ここぞとばかりに</span><span class='gd-jp'>ここぞ</span> = \"chính là chỗ này, chính là lúc này\", cả câu thành nghĩa \"như thể nắm được cơ hội, nhân dịp mà ra sức ~\". Rất thường gặp.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議で、彼はここぞとばかりに不満を言い始めた。</span>(Trong cuộc họp, anh ta như nắm được cơ hội, bắt đầu xả một tràng bức xúc)</div><div class='gd-sec'><span class='gd-tag'>今だとばかりに</span>\"Chính là bây giờ!\", thấy đúng thời điểm là hành động ngay.</div><div class='gd-ex-line'>・<span class='gd-jp'>相手が転んだ瞬間、今だとばかりに走り出した。</span>(Đối thủ vừa ngã, anh ấy liền lao ra chạy, như thể nói \"chính là bây giờ\")</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Đây là cách nói <b>nhìn người khác từ bên ngoài</b>, thường không dùng để nói về bản thân. Mình nghĩ gì trong lòng thì mình rõ nhất, đâu cần nói \"trông như đang nói\".<br>・Câu phía trước <b>thực ra chưa được nói ra</b>. Nếu đối phương thật sự đã nói thì dùng thẳng「〜と言って」.<br>・Ở đây ばかり không có nghĩa \"chỉ\", đừng hiểu thành \"chỉ là ~\".<br>・Mẫu này không chỉ đi với thể thường, phía trước có thể là câu mệnh lệnh, thể ます hay một từ đơn đều được, vì bản chất nó là trích dẫn một câu nói.<br>・Phần lớn dùng trong văn viết, văn miêu tả cảnh; trò chuyện hằng ngày ít khi nói như vậy.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>とばかりに</b> = phía trước là một <b>câu thoại</b>: \"làm ra vẻ như muốn nói '~'\"<br><b>んばかりに</b> = phía trước là một <b>hành động sắp xảy ra</b>: \"như thể sắp ~ đến nơi\"<br>Cùng một tình huống: đứa trẻ nhận được quà và vui sướng vô cùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>「やった」とばかりに、子どもは両手を上げた。</span>(Đứa trẻ giơ cả hai tay lên, như thể muốn nói \"tuyệt quá\")</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもは飛び上がらんばかりに喜んだ。</span>(Đứa trẻ vui đến mức như sắp nhảy cẫng lên)</div><div class='gd-sec'>Cách nối của んばかりに: chuyển sang thể ない, bỏ「ない」, thêm「ん」.<br><span class='gd-pair'><span class='gd-jp'>飛び上がる</span> → <span class='gd-jp'>飛び上がらない</span> → <span class='gd-jp'>飛び上がらんばかりに</span></span><br><span class='gd-pair'><span class='gd-jp'>泣き出す</span> → <span class='gd-jp'>泣き出さない</span> → <span class='gd-jp'>泣き出さんばかりに</span></span><br>※<b>する phải đổi thành「せん」</b>, không phải「しん」: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんばかりに</span></span> (ví dụ: <span class='gd-jp'>今にも爆発せんばかりに</span>)<br>Ngoài ra, <span class='gd-jp'>「帰れ」と言わんばかりに</span> (như thể sắp nói thẳng ra \"cút đi\") có nghĩa gần như giống <span class='gd-jp'>「帰れ」とばかりに</span>, có thể dùng thay nhau.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: phía trước là một \"câu thoại\" thì dùng とばかりに; phía trước là \"hành động suýt nữa thì xảy ra\" thì dùng んばかりに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là mẫu miêu tả \"dáng vẻ\", bạn có thể học tiếp <span class='gd-jp'>〜んばかりに</span> (như thể sắp ~), nhớ hai mẫu cùng lúc sẽ khó nhầm nhất.</div>","n1-65":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜いかん」tương đương với <b>「tùy thuộc vào ～」「phụ thuộc vào ～」</b> trong văn bản hành chính tiếng Việt. Chữ Hán là 如何 (Hán Việt: như hà), nhưng ngày nay phần lớn viết thẳng bằng hiragana <span class='gd-jp'>いかん</span>. Nghĩa là: kết quả ra sao còn tùy vào tình hình của việc đứng trước. Mẫu này rất cứng và trang trọng, chỉ xuất hiện trong tin tức, thông báo, hợp đồng hay lời huấn thị của cấp trên.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chỉ nối với <b>danh từ</b>, chữ「の」ở giữa có thể thêm hoặc không, không thêm thì phổ biến hơn.<br><span class='gd-pair'><span class='gd-jp'>努力</span> → <span class='gd-jp'>努力いかん</span></span>(tùy mức độ nỗ lực)<br><span class='gd-pair'><span class='gd-jp'>試験の結果</span> → <span class='gd-jp'>試験の結果いかん</span></span>(tùy kết quả thi)<br>Danh từ đứng trước phải là thứ <b>có tốt có xấu, có cao có thấp</b>, ví dụ: <span class='gd-jp'>結果</span>、<span class='gd-jp'>努力</span>、<span class='gd-jp'>態度</span>、<span class='gd-jp'>対応</span>、<span class='gd-jp'>天候</span>、<span class='gd-jp'>返答</span>、<span class='gd-jp'>内容</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>いかんだ／いかんにかかっている</span>Đặt ở cuối câu, nghĩa là「tất cả tùy vào ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できるかどうかは、本人の努力いかんだ。</span>(Có đỗ được hay không là tùy vào sự nỗ lực của chính người đó)</div><div class='gd-ex-line'>・<span class='gd-jp'>今期の業績は、チームの努力いかんにかかっている。</span>(Thành tích kỳ này phụ thuộc vào nỗ lực của cả đội)</div><div class='gd-sec'><span class='gd-tag'>いかんで／いかんによって</span>Đặt giữa câu, nghĩa là「quyết định theo ～, thay đổi theo ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>参加費は人数いかんで変わります。</span>(Phí tham gia sẽ thay đổi tùy theo số người)</div><div class='gd-sec'><span class='gd-tag'>いかんでは／いかんによっては</span>Thêm một chữ「は」thì nghĩa thành「tùy tình hình, <b>thậm chí có thể</b> ～」, phía sau thường là một kết quả đặc biệt, hay là kết quả không mấy tốt đẹp.</div><div class='gd-ex-line'>・<span class='gd-jp'>天候いかんでは、試合が中止になることもあります。</span>(Tùy tình hình thời tiết, trận đấu cũng có thể bị hủy)</div><div class='gd-ex-line'>・<span class='gd-jp'>会社の対応いかんでは、訴訟も考えています。</span>(Tùy cách công ty xử lý, chúng tôi cũng đang cân nhắc khởi kiện)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đọc là <b>いかん</b>. Cũng là hai chữ 如何, nhưng trong <span class='gd-jp'>如何ですか</span> thì đọc là いかが, đừng lẫn với nhau nhé.<br>・Không nối trực tiếp với động từ hay tính từ: muốn nói「tùy bạn có cố gắng hay không」phải viết <span class='gd-jp'>努力いかんで</span>, không được viết thành「頑張るいかんで」.<br>・Danh từ phía trước phải là thứ có biến số. Những từ như「明日」không có tốt xấu cao thấp gì để nói nên không dùng được.<br>・Mẫu này quá trang trọng, nói với bạn bè kiểu「天気いかんで決めよう」nghe sẽ rất kỳ. Trong văn nói hãy dùng <span class='gd-jp'>天気次第で決めよう</span> hoặc <span class='gd-jp'>天気によって決めよう</span>.<br>・Trong văn nói, câu đứng một mình <span class='gd-jp'>それはいかん</span> nghĩa là「thế thì không được đâu」, đó là một từ khác, không liên quan đến mẫu ngữ pháp này.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>次第</b>(N2) ＝ nghĩa gần như giống hệt, nhưng dùng được cả trong văn nói lẫn văn viết, nhẹ nhàng hơn:<br><span class='gd-jp'>結果次第で、計画を変えるかもしれない。</span>(Tùy kết quả, có thể kế hoạch sẽ thay đổi)<br><b>いかん</b>＝cùng nghĩa, nhưng mang giọng văn bản hành chính, báo cáo:<br><span class='gd-jp'>結果いかんでは、計画を変更することもあり得る。</span>(Tùy theo kết quả, kế hoạch cũng có thể được thay đổi)<br><b>いかんによらず／いかんにかかわらず</b>(n1-66) ＝ nghĩa ngược lại,「<b>dù</b> ～ thế nào thì cũng như nhau」:<br><span class='gd-jp'>理由のいかんにかかわらず、返金はいたしません。</span>(Dù lý do là gì, chúng tôi cũng không hoàn tiền)</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu sau いかん là「で・によって・だ・にかかっている」thì nghĩa là「<b>phải xem nó</b>」; nếu là「によらず・にかかわらず・を問わず」thì nghĩa là「<b>bất kể nó</b>」. Muốn nói nhẹ nhàng hơn thì đổi いかん thành 次第.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp bài n1-66 với <span class='gd-jp'>いかんによらず</span>、<span class='gd-jp'>いかんにかかわらず</span>, cùng cách nói rất hay gặp trên các thông báo là <span class='gd-jp'>理由のいかんを問わず</span> (không hỏi lý do).</div>","n1-66":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜いかんによらず／いかんにかかわらず」tương đương với <b>「bất kể ～ như thế nào, đều……」</b> trong văn bản hành chính tiếng Việt. Phía trước đặt một thứ có thể có nhiều tình huống khác nhau (lý do, kết quả, thời tiết), còn kết luận ở phía sau <b>sẽ không vì thế mà thay đổi</b>. Bạn hay gặp nó nhất trong thông báo, hợp đồng, quy định hoàn vé; trò chuyện hằng ngày gần như không dùng.</div><div class='gd-h'>Tách ra xem trước</div><div class='gd-sec'><span class='gd-jp'>いかん</span> viết bằng chữ Hán là <span class='gd-jp'>如何</span>, nghĩa là「nội dung, tình hình ra sao」.<br><span class='gd-jp'>によらず</span>＝không dựa theo, không phụ thuộc vào; <span class='gd-jp'>にかかわらず</span>＝không liên quan đến ～.<br>Hai cách nói này nghĩa giống nhau, đều là「bất kể ～ như thế nào」. Ngoài ra còn một cách nói cũng rất hay gặp: <span class='gd-jp'>いかんを問わず</span> (không hỏi ～ ra sao).</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋の＋いかんによらず／いかんにかかわらず<br><span class='gd-pair'><span class='gd-jp'>理由</span> → <span class='gd-jp'>理由のいかんによらず</span></span><span class='gd-pair'><span class='gd-jp'>天候</span> → <span class='gd-jp'>天候のいかんにかかわらず</span></span><br>Danh từ đứng trước phải là thứ <b>có nhiều khả năng khác nhau</b>, ví dụ <span class='gd-jp'>理由</span>、<span class='gd-jp'>結果</span>、<span class='gd-jp'>事情</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>天候</span>.<br>Trong văn bản chính thức đôi khi người ta bỏ「の」, viết thành <span class='gd-jp'>理由いかんにかかわらず</span>. Bạn chỉ cần đọc hiểu được là đủ, khi tự viết thì cứ dùng dạng có「の」trước đã.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Quy định・thông báo</span>Cửa hàng hoặc công ty dùng để nói「không có ngoại lệ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>理由のいかんを問わず、購入後のキャンセルはできません。</span>(Dù lý do là gì, sau khi mua cũng không thể hủy)</div><div class='gd-ex-line'>・<span class='gd-jp'>天候のいかんにかかわらず、イベントは予定通り開催されます。</span>(Dù thời tiết thế nào, sự kiện vẫn được tổ chức như dự kiến)</div><div class='gd-sec'><span class='gd-tag'>Tư cách・điều kiện</span>Thể hiện sự đối xử bình đẳng với mọi người.</div><div class='gd-ex-line'>・<span class='gd-jp'>国籍のいかんによらず、どなたでも応募できます。</span>(Bất kể quốc tịch, ai cũng có thể đăng ký)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước chỉ nối được với <b>danh từ</b>, không nối trực tiếp với động từ hay tính từ: <span class='gd-jp'>行くいかんによらず</span> là sai.<br>・Phía trước phải đặt từ「có nhiều tình huống」. <span class='gd-jp'>雨のいかんにかかわらず</span> nghe không ổn, vì「雨」không có chuyện「như thế nào」để nói, phải nói là <span class='gd-jp'>天候のいかん</span>.<br>・<span class='gd-jp'>如何</span> ở đây đọc là <b>いかん</b>. Cùng chữ Hán đó, trong <span class='gd-jp'>如何ですか</span> thì đọc là いかが, đừng nhầm nhé.<br>・Mẫu này rất cứng, nói với bạn bè sẽ nghe kỳ. Trong văn nói chỉ cần dùng <span class='gd-jp'>どんな理由でも</span> (dù lý do là gì) là được.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>〜いかんで／いかんによっては</b>(「〜いかん」của N1) có nghĩa hoàn toàn <b>ngược lại</b>: kết quả <b>còn tùy</b> vào việc phía trước ra sao.<br>・<span class='gd-jp'>面接の結果いかんで、採用が決まります。</span>(Có được nhận hay không là tùy kết quả phỏng vấn)<br>・<span class='gd-jp'>面接の結果のいかんにかかわらず、交通費は支給します。</span>(Dù kết quả phỏng vấn thế nào, chúng tôi vẫn chi trả phí đi lại cho bạn)</div><div class='gd-sec'><b>〜にかかわらず</b>(N2) là cách nói「bất kể」thông thường hơn, không cần thêm いかん, phía trước cũng có thể đặt những từ như <span class='gd-jp'>天気</span>、<span class='gd-jp'>年齢</span>: <span class='gd-jp'>天気にかかわらず、試合は行われます。</span>(Bất kể thời tiết, trận đấu vẫn diễn ra)<br>Thêm「のいかん」vào thì trang trọng hơn, mang giọng văn bản chính thức hơn.</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu sau いかん là「によらず／にかかわらず／を問わず」thì nghĩa là「bất kể」; nếu là「で／によっては」thì nghĩa là「còn tùy」.</div>","n1-68":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をもってしても」nghĩa là <b>「dù có dựa vào ～ đi nữa thì vẫn…」</b>. Phía trước là thứ rất mạnh, đáng lẽ phải hiệu quả (công nghệ mới nhất, thực lực của ai đó). Phía sau nói «vậy mà vẫn không được, vẫn rất khó». Điểm chính là <b>«ngay cả thứ mạnh đến thế cũng bó tay»</b>, dùng để nhấn mạnh việc đó khó đến mức nào.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Nối thẳng sau danh từ: danh từ＋をもってしても<br><span class='gd-pair'><span class='gd-jp'>最新の技術</span> → <span class='gd-jp'>最新の技術をもってしても</span></span> (dù có dựa vào công nghệ mới nhất)<br><span class='gd-pair'><span class='gd-jp'>彼の実力</span> → <span class='gd-jp'>彼の実力をもってしても</span></span> (dù với thực lực của anh ấy)<br>Phía trước cũng có thể đặt thẳng một người, nghĩa là «ngay cả người giỏi như anh ấy»: <span class='gd-jp'>彼をもってしても</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Kỹ thuật, khoa học, phương pháp</span>Ngay cả cách tốt nhất hiện nay cũng không làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>今の科学をもってしても、地震を正確に予知することはできない。</span>(Dù dựa vào khoa học hiện nay, vẫn không thể dự đoán chính xác động đất)</div><div class='gd-sec'><span class='gd-tag'>Năng lực của con người</span>Ngay cả người rất giỏi cũng thấy khó.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力をもってしても、優勝は難しいだろう。</span>(Dù với thực lực của anh ấy, chắc việc vô địch cũng khó)</div><div class='gd-ex-line'>・<span class='gd-jp'>天才と呼ばれた彼をもってしても、この問題は解けなかった。</span>(Ngay cả anh ấy, người được gọi là thiên tài, cũng không giải được bài này)</div><div class='gd-sec'><span class='gd-tag'>Ngôn từ, cách diễn đạt</span>Cách nói thường gặp trong diễn văn, lời phát biểu, diễn tả cảm xúc mạnh đến mức không nói nên lời.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな言葉をもってしても、この感謝の気持ちは伝えきれません。</span>(Dù dùng lời lẽ nào cũng không thể diễn tả hết lòng biết ơn này)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau hầu như luôn là kết quả kiểu <b>«không làm được, rất khó, vẫn chưa đủ»</b>, ví dụ <span class='gd-jp'>できない</span>, <span class='gd-jp'>難しい</span>, <span class='gd-jp'>無理だ</span>. Nếu nối với «thành công rồi» thì cả câu sẽ rất kỳ.<br>・Phía trước phải là thứ <b>vốn được kỳ vọng là rất hữu ích</b>. Nếu đặt thứ bình thường, ví dụ «dùng bút chì của tôi», thì sẽ không có cảm giác «đến cái này mà cũng không được».<br>・Đây là cách nói rất trang trọng, thiên về văn viết, thường gặp trong tin tức, luận văn, diễn văn. Khi nói chuyện hằng ngày chỉ cần nói <span class='gd-jp'>最新の技術でも</span> (dù là công nghệ mới nhất cũng…) là đủ.<br>・Trọng tâm là «dùng sức mạnh này để làm», không phải «xét từ góc độ ～». Đừng dịch thành «xét theo ～».</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là «công nghệ» nhưng ba cách nói cho kết quả hoàn toàn khác nhau:<br><b>をもって</b>＝dùng, nhờ vào (chỉ nói về phương tiện): <span class='gd-jp'>この技術をもって、問題を解決した。</span> (Đã giải quyết vấn đề nhờ công nghệ này)<br><b>をもってすれば</b>＝chỉ cần có ～ là làm được: <span class='gd-jp'>この技術をもってすれば、問題は解決できる。</span> (Chỉ cần có công nghệ này thì vấn đề có thể giải quyết)<br><b>をもってしても</b>＝dù có ～ cũng không làm được: <span class='gd-jp'>この技術をもってしても、問題は解決できない。</span> (Dù có công nghệ này, vấn đề cũng không giải quyết được)<br>Ngoài ra, <span class='gd-jp'>をもって</span> còn có cách dùng «lấy đó làm mốc», ví dụ <span class='gd-jp'>本日をもって閉店します。</span> (Cửa hàng đóng cửa kể từ hôm nay). Cách này không liên quan đến をもってしても, đừng nhầm lẫn.</div><div class='gd-warn'>Mẹo nhận biết: nhìn đoạn nhỏ ở giữa. 「すれば」 là có nó thì được, 「しても」 là có nó cũng không được.</div>","n1-71":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ずにはすまない」nghĩa là <b>«không ～ thì không thể cho qua được», «không ～ thì chuyện này không xong»</b>. <span class='gd-jp'>すむ</span>（済む）là «việc được giải quyết xong, êm xuôi», nên <span class='gd-jp'>すまない</span> là «không êm xuôi được». Cả câu có nghĩa: theo lẽ thường và tình hình hiện tại, không làm việc này thì không thể ăn nói được.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đạo lý buộc phải làm</span>Làm sai, gây ra chuyện mà không xin lỗi, không bồi thường, không chịu trách nhiệm thì về tình về lý đều không ổn.</div><div class='gd-ex-line'>・<span class='gd-jp'>人の車に傷をつけたのだから、弁償せずにはすまない。</span>(Đã làm xước xe người ta thì không bồi thường là không được)</div><div class='gd-sec'><span class='gd-tag'>Tình thế buộc phải làm</span>Chuyện đã bị làm lớn, không xử lý thì không thể kết thúc.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここまで問題が大きくなれば、社長も記者会見をせずにはすまないだろう。</span>(Vấn đề đã lớn đến mức này thì chắc giám đốc cũng buộc phải họp báo)</div><div class='gd-sec'>Phía trước thường nêu lý do trước, như <span class='gd-jp'>〜のだから</span>, <span class='gd-jp'>〜以上</span>, <span class='gd-jp'>〜たら</span>, và phía sau cũng hay thêm <span class='gd-jp'>だろう</span>, với ý «nhìn tình hình này thì chắc không tránh được».</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>ずにはすまない</b>: chuyển sang thể ない, bỏ 「ない」, rồi thêm 「ずにはすまない」.<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝らない</span> → <span class='gd-jp'>謝らずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>払う</span> → <span class='gd-jp'>払わない</span> → <span class='gd-jp'>払わずにはすまない</span></span><br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めずにはすまない</span></span><br><b>Động từ nhóm 3 cần nhớ riêng</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはすまない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはすまない</span>（こずに）</span></div><div class='gd-sec'><b>ないではすまない</b>: thể ない cộng thẳng 「ではすまない」, không phải bỏ gì cả, nghĩa giống nhau, giọng hơi bớt cứng hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議を無断で休んだのだから、部長に説明しないではすまない。</span>(Đã nghỉ họp không báo trước thì không giải thích với trưởng phòng là không xong)</div><div class='gd-sec'>Ngoài ra còn có <span class='gd-jp'>〜ではすまない</span> nối sau danh từ hoặc 「〜だけ」, nghĩa là «chỉ như vậy thì không giải quyết xong»:</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談ではすまない。</span>(Đây không phải chuyện đùa cho qua được)</div><div class='gd-ex-line'>・<span class='gd-jp'>謝るだけではすまない。</span>(Chỉ xin lỗi thôi thì không giải quyết được)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・する phải đổi thành <b>せずに</b>, không phải 「しずに」. <span class='gd-jp'>説明せずにはすまない</span> mới đúng.<br>・<span class='gd-jp'>すまない</span> ở đây không có nghĩa là «xin lỗi», mà là «việc không êm xuôi được».<br>・Đây là cách nói trang trọng, thiên về văn viết, thường gặp trong tin tức, bình luận, các dịp chính thức. Khi nói chuyện với bạn bè kiểu «chắc phải xin lỗi thôi», người Nhật thường nói <span class='gd-jp'>謝らないとまずいよ</span>, hoặc dùng <span class='gd-jp'>謝らないわけにはいかない</span>.<br>・Điểm chính là «lẽ thường hoặc hoàn cảnh bên ngoài buộc bạn phải làm», không phải bản thân bạn rất muốn làm, cũng không phải cảm xúc khiến bạn không kìm được.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là chuyện «xin lỗi», nhưng ba cách nói trông giống nhau lại khác nghĩa nhiều:<br><b>ずにはすまない</b>＝về tình về lý, không làm thì không ổn (bị hoàn cảnh buộc)<br>・<span class='gd-jp'>ミスをしたのは私だから、謝らずにはすまない。</span>(Lỗi là do tôi gây ra, nên không xin lỗi là không được)<br><b>ずにはいられない</b>＝không kìm được vì cảm xúc (đã học ở N2)<br>・<span class='gd-jp'>彼の涙を見て、謝らずにはいられなかった。</span>(Nhìn thấy nước mắt của anh ấy, tôi không kìm được mà xin lỗi)<br><b>ずにはおかない</b>＝nhất định phải làm cho bằng được, không thì không bỏ qua (ý chí mạnh)<br>・<span class='gd-jp'>今度こそ、彼に謝らせずにはおかない。</span>(Lần này tôi nhất định bắt anh ta xin lỗi)</div><div class='gd-warn'>Mẹo nhận biết: «không làm thì không ổn» là すまない, «không kìm được» là いられない, «không làm thì không bỏ qua» là おかない.</div>","n1-73":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ただ～のみ」nghĩa là <b>“duy chỉ ～”, “chỉ còn lại ～”</b>. Đây là phiên bản trang trọng, mang tính văn viết của「だけ」. Cách dùng hay gặp nhất là nói về quyết tâm: việc cần làm đã làm hết, trước mắt chỉ còn một con đường, ví dụ <span class='gd-jp'>あとはただ待つのみだ</span>（giờ chỉ còn biết chờ thôi）. Giọng điệu rất kiên định, kiểu “không nghĩ gì khác, chỉ tập trung làm việc này”.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chỉ có cái này</span>Nhấn mạnh phạm vi chỉ có một đối tượng này, không có gì khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格したのは、ただ一人のみだった。</span>（người đỗ chỉ có một người）</div><div class='gd-sec'><span class='gd-tag'>Chỉ còn việc này để làm</span>Đặt ở cuối câu thành「～のみだ」, nghĩa là không cần nghĩ gì khác nữa, cứ làm việc này thôi. Rất hay gặp trong diễn văn, phát biểu trước trận đấu và tin tức báo chí.</div><div class='gd-ex-line'>・<span class='gd-jp'>やるべきことはすべてやった。あとはただ結果を待つのみだ。</span>（việc cần làm đã làm hết, giờ chỉ còn chờ kết quả）</div><div class='gd-ex-line'>・<span class='gd-jp'>今はただ無事を祈るのみです。</span>（bây giờ chỉ còn biết cầu mong bình an）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>：ただ＋danh từ＋のみ　<span class='gd-pair'><span class='gd-jp'>一人</span> → <span class='gd-jp'>ただ一人のみ</span></span><br><b>Động từ</b>：ただ＋thể từ điển＋のみ　<span class='gd-pair'><span class='gd-jp'>前進する</span> → <span class='gd-jp'>ただ前進するのみだ</span></span><br>Muốn nói lịch sự hơn thì đổi だ ở cuối thành です：<span class='gd-jp'>祈るのみです</span>。<br>「ただ」có thể lược bỏ, chỉ dùng「のみ」nghĩa vẫn thông; thêm ただ là để nhấn mạnh hơn.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋あるのみ</span>Khi muốn nói “chỉ còn việc này phải làm”, sau danh từ thường thêm「ある」, gần như là cách nói cố định：<span class='gd-jp'>努力あるのみ</span>、<span class='gd-jp'>前進あるのみ</span>、<span class='gd-jp'>練習あるのみ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合まであと一週間。練習あるのみだ。</span>（còn một tuần nữa là thi đấu, chỉ còn biết luyện tập hết sức）</div><div class='gd-sec'><span class='gd-tag'>Biển báo</span>Trên đường phố Nhật bạn sẽ hay thấy「のみ」đứng riêng, nghĩa là “chỉ dành cho ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>この席は会員のみご利用いただけます。</span>（chỗ ngồi này chỉ dành cho hội viên）</div><div class='gd-ex-line'>・<span class='gd-jp'>関係者のみ</span>（người không phận sự xin đừng vào）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cách nói này rất trang trọng và đầy khí thế. Nói chuyện với bạn về bữa trưa mà bảo「ただ食べるのみ」thì nghe như đang đóng kịch; ngày thường cứ dùng <span class='gd-jp'>だけ</span> là được：<span class='gd-jp'>あとは待つだけだ</span>。<br>・Động từ phải dùng thể từ điển, không nối với thể ます: nói <span class='gd-jp'>前進するのみです</span>, không được nói「前進しますのみ」。<br>・<span class='gd-jp'>のみならず</span> trông rất giống nhưng nghĩa lại là <b>“không chỉ ～”</b>, hoàn toàn ngược lại：<span class='gd-jp'>ただ日本のみならず、世界中で人気がある。</span>（không chỉ ở Nhật, mà trên khắp thế giới đều được yêu thích）。Thấy sau のみ còn có「ならず」thì phải chuyển sang nghĩa “không chỉ”.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>～のみだ</b>＝trước mắt <b>chỉ có con đường này</b>, cứ tập trung tiến lên：<span class='gd-jp'>ここまで来たら、ただ前進するのみだ。</span>（đã đi đến bước này rồi thì chỉ còn cách tiến lên）<br><b>～まで（のこと）だ</b>＝<b>cùng lắm thì ～</b>, là đường lui đã nghĩ sẵn, phía trước thường có「だめなら」「失敗したら」：<span class='gd-jp'>だめなら、もう一度挑戦するまでだ。</span>（không được thì cùng lắm là thử thách lại một lần nữa）</div><div class='gd-warn'>Mẹo nhỏ: nếu tiếng Việt nói được “chỉ còn biết ～ / chỉ còn cách ～” thì dùng のみ; nếu là “cùng lắm thì ～”, phía trước còn có “nếu không được thì”, thì dùng までだ.</div>","n1-74":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ないものでもない」nghĩa là <b>“cũng không phải là không ～ đâu”</b>. Giống như khi bạn bè nhờ giúp chuyển nhà, bạn nói “còn tùy xem cậu có mời ăn cơm không, cũng không phải là không giúp được”. Ý là có khả năng, nhưng không mấy sẵn lòng và cũng không nhận lời một cách dứt khoát.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang dạng phủ định「ない」, rồi thêm trực tiếp <b>ものでもない</b> phía sau.<br><span class='gd-pair'><span class='gd-jp'>引き受ける</span> → <span class='gd-jp'>引き受けない</span> → <span class='gd-jp'>引き受けないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許さない</span> → <span class='gd-jp'>許さないものでもない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合う</span> → <span class='gd-jp'>間に合わない</span> → <span class='gd-jp'>間に合わないものでもない</span></span><br>Phủ định “không” cộng thêm “cũng không phải là”, hai phủ định triệt tiêu nhau, thành một lời “được” <b>có phần dè dặt</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nhận lời có điều kiện</span>Cách dùng phổ biến nhất. Phía trước thường có「〜ば」「〜なら」「〜次第では（tùy vào ～）」, nêu điều kiện trước rồi mới nói “cũng không phải là không được”.</div><div class='gd-ex-line'>・<span class='gd-jp'>条件次第では、引き受けないものでもない。</span>（tùy điều kiện, cũng không phải là không nhận được）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちゃんと謝るなら、許さないものでもない。</span>（nếu xin lỗi tử tế thì cũng không phải là không tha thứ được）</div><div class='gd-sec'><span class='gd-tag'>Vẫn còn khả năng</span>Đánh giá rằng một việc không phải hoàn toàn vô vọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>あと一週間あれば、間に合わないものでもない。</span>（nếu có thêm một tuần nữa thì cũng không phải là không kịp）</div><div class='gd-sec'><span class='gd-tag'>Tạm thông cảm được</span>Thể hiện “hiểu phần nào” suy nghĩ của người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の気持ちも分からないものでもない。</span>（tâm trạng của anh ấy tôi cũng không phải là không hiểu）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không được bỏ「ない」.</b>Nếu viết <span class='gd-jp'>引き受けるものでもない</span> thì nghĩa thành “cũng không phải việc nên nhận”, ngược hẳn lại. Còn <span class='gd-jp'>お金で買えるものでもない</span> nghĩa là “cũng không phải thứ mua được bằng tiền”, không liên quan đến mẫu ngữ pháp này.<br>・Nó chỉ biểu thị “<b>có khả năng</b>”, không phải “chắc chắn sẽ”, cũng không phải “rất muốn”. Dịch thành “tôi sẵn lòng” hay “không vấn đề gì” là dịch quá đà.<br>・Giọng điệu khá cứng, là cách nói văn viết, thường mang chút thái độ bề trên kiểu <b>“thôi thì miễn cưỡng nhận lời” “để tôi cân nhắc xem”</b>. Nói「手伝わないものでもないです」với cấp trên hay khách hàng sẽ rất thất lễ, khi cần lịch sự thì đừng dùng.<br>・Phía trước thường là hành động hoặc phán đoán của chính mình, như nhận hay không, có cân nhắc không, có hiểu được không; rất ít khi dùng để nói chuyện của người khác.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Những mẫu có nghĩa gần như giống còn có <b>ないこともない</b>、<b>ないでもない</b>、<b>なくもない</b>, khác nhau ở hoàn cảnh dùng:<br><b>ないものでもない</b>：văn viết, cứng, hay xuất hiện trong bài viết, đàm phán, phát biểu khá trang trọng.<br><span class='gd-jp'>条件が合えば、協力しないものでもない。</span>（nếu điều kiện phù hợp thì cũng không phải là không hợp tác được）<br><b>ないこともない／ないでもない</b>：dùng nhiều nhất trong hội thoại hằng ngày.<br><span class='gd-jp'>時間があれば、行けないこともないよ。</span>（nếu có thời gian thì cũng không phải là không đi được đâu）<br><b>なくもない</b>：khẩu ngữ hơn, thoải mái hơn.<br><span class='gd-jp'>まあ、分からなくもないけど。</span>（ừ thì, cũng không phải là không hiểu đâu）</div><div class='gd-warn'>Mẹo nhỏ: nghĩa đều là “cũng không phải là không ～”. Khi trò chuyện thì dùng「ないこともない」; chỉ khi viết văn, bàn điều kiện hoặc muốn tỏ ra “làm cao” một chút thì mới dùng「ないものでもない」.</div>","n1-79":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ともすると／ともすれば」nghĩa là <b>「hơi một chút là…」「chỉ cần sơ ý là…」「dễ có xu hướng…」</b>. Nó nói về một <b>xu hướng không tốt</b>: không phải lần nào cũng vậy, nhưng chỉ cần hơi lơ là là sẽ trượt về hướng đó. Giống như câu \"rảnh ra là dễ lướt điện thoại đến nửa đêm\" vậy.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đây là một <b>từ đứng độc lập</b>, không cần nối sau từ nào cả, chỉ cần đặt ở đầu câu hoặc ngay trước \"việc xấu muốn nói\".<br>Vế sau thường đi với những cách nói diễn tả \"dễ bị…\", đi cùng nhau là tự nhiên nhất:<br><span class='gd-tag'>Cách đi kèm thường gặp</span><span class='gd-jp'>〜がちだ</span> (thường hay ~), <span class='gd-jp'>〜やすい</span> (dễ ~), <span class='gd-jp'>〜てしまう</span> (lỡ ~ mất)</div><div class='gd-ex-line'>・<span class='gd-jp'>人はともすると、楽なほうへ流れがちだ。</span> (Con người thường dễ trôi theo hướng nhàn nhã)</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすれば食事を抜いてしまう。</span> (Hễ bận là dễ lỡ bỏ bữa)</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしだと、ともすると生活が不規則になりやすい。</span> (Ở một mình thì sinh hoạt rất dễ trở nên thất thường)</div><div class='gd-sec'>「ともすると」và「ともすれば」có nghĩa giống nhau, dùng thay thế được, bạn cứ chọn cái nào đọc thuận miệng hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đây không phải mẫu ngữ pháp nối sau từ khác, nên không thể viết thành「忙しいともすると」. Phải tách ra: <span class='gd-jp'>忙しいと、ともすると〜</span>.<br>・Nó nói về <b>xu hướng xấu</b>. Thói quen tốt thì không dùng, ví dụ muốn nói \"mình hay vô thức đi tập thể dục\" thì không dùng ともすると.<br>・Nó nói về \"xu hướng thường xuyên\", không phải một việc xảy ra một lần. \"Hôm qua lỡ đến trễ\" chỉ là sự cố một lần, không dùng ともすると, nói thẳng <span class='gd-jp'>うっかり遅刻した</span> là được.<br>・Sắc thái thiên về văn viết, trang trọng, rất hay gặp trong bài viết, diễn thuyết, bình luận. Khi trò chuyện với bạn bè thì hay nói <span class='gd-jp'>つい</span>, <span class='gd-jp'>すぐ</span> hơn, ví dụ <span class='gd-jp'>ついスマホを見ちゃう</span> (không nhịn được cứ xem điện thoại mãi).</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'><b>ともすると／ともすれば</b>: đứng độc lập trong câu, nói về <b>xu hướng xấu dễ sa vào</b>, phía sau hay đi với がち, やすい.<br><b>ともなると／ともなれば</b>: phía trước nối danh từ (phần lớn là thân phận, vị trí, thời gian, mức độ), cũng có thể nối động từ thể từ điển, nghĩa là <b>「một khi đã đến thân phận, thời kỳ, tình huống nào đó thì đương nhiên sẽ…」</b>.<br>Cùng nói về chuyện \"bận đến mức không ăn cơm\", hãy so sánh:</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、ともすると食事を抜きがちだ。</span> (Hễ bận là dễ bỏ bữa: nói về thói quen xấu)</div><div class='gd-ex-line'>・<span class='gd-jp'>年末ともなると、食事をする時間もない。</span> (Đã đến cuối năm thì đến thời gian ăn cơm cũng không có: nói về việc đến thời kỳ đó thì tự nhiên sẽ như vậy)</div><div class='gd-sec'>Ví dụ khác của ともなると: <span class='gd-jp'>社長ともなると、なかなか休めない。</span> (Đã làm đến giám đốc thì rất khó nghỉ ngơi)<br><span class='gd-jp'>海外に住むともなると、準備が大変だ。</span> (Nếu đã đến mức sống ở nước ngoài thì việc chuẩn bị vất vả lắm)</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước có danh từ hoặc động từ, nói \"đến giai đoạn đó thì sẽ…\" là ともなると; đứng một mình như một từ, nói \"hơi một chút là (chuyện xấu)\" là ともすると.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng nói về \"có xu hướng không tốt\", bạn có thể học tiếp <span class='gd-jp'>〜嫌いがある</span>, mẫu này đặt ở cuối câu: <span class='gd-jp'>彼は物事を悲観的に考える嫌いがある。</span> (Anh ấy có xu hướng nghĩ mọi chuyện theo hướng bi quan). Hai mẫu này cũng hay dùng chung: <span class='gd-jp'>人はともすると、自分に甘くなる嫌いがある。</span> (Con người thường có tật quá dễ dãi với bản thân)</div>","n1-82":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を限りに」nghĩa là <b>「đến hết ~ là dừng, từ đó về sau không ~ nữa」</b>. Giống như khi bạn nói \"hôm nay là ngày cuối cùng\", \"làm xong lần này là nghỉ\", vạch một đường: trước đường còn, sau đường là hết.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đặt thẳng danh từ chỉ thời điểm phía trước, rồi thêm「を限りに」:<br><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日を限りに</span></span><span class='gd-pair'><span class='gd-jp'>今回</span> → <span class='gd-jp'>今回を限りに</span></span><span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日を限りに</span></span><br>Thường gặp nhất là những từ chỉ \"thời điểm hiện tại\" như <span class='gd-jp'>今日・本日・今回・今月・今年度</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Quyết tâm không làm nữa</span>Cắt đứt với con người cũ của mình, thường mang chút quyết tâm.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日を限りに、お酒はやめる。</span> (Uống đến hết hôm nay thôi, từ nay mình bỏ rượu)</div><div class='gd-sec'><span class='gd-tag'>Thông báo kết thúc</span>Cửa hàng đóng cửa, vận động viên giải nghệ, chế độ bị bãi bỏ, thường mang chút bùi ngùi.</div><div class='gd-ex-line'>・<span class='gd-jp'>今回の試合を限りに、引退します。</span> (Sau trận đấu này tôi sẽ giải nghệ)</div><div class='gd-ex-line'>・<span class='gd-jp'>この路線は今年度を限りに廃止される。</span> (Tuyến này sẽ bị bãi bỏ sau khi hết năm tài chính này)</div><div class='gd-sec'><span class='gd-tag'>Một nghĩa khác</span>「<span class='gd-jp'>声を限りに</span>」là cách nói cố định, nghĩa là \"dốc hết sức, hét hết cỡ\", không liên quan đến thời gian, gặp thì nhớ nhận ra nhé.</div><div class='gd-ex-line'>・<span class='gd-jp'>声を限りに助けを呼んだ。</span> (Gào hết sức để kêu cứu)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nó không phải \"hạn chót\". Hạn nộp bài phải dùng までに: <span class='gd-jp'>金曜日までに出してください。</span> (Hãy nộp trước thứ Sáu), không thể nói「金曜日を限りに出してください」.<br>・Phía sau phần lớn là việc <b>kết thúc, dừng lại, không làm nữa</b>, như <span class='gd-jp'>やめる・引退する・閉店する・解散する</span>. Nếu chỉ muốn nói \"từ hôm nay bắt đầu cố gắng\", tiếng Nhật thường dùng <span class='gd-jp'>今日から</span>.<br>・Đây là cách nói thiên về trang trọng, văn viết. Bình thường nói với bạn bè thì dùng <span class='gd-jp'>今日でやめる</span> hoặc <span class='gd-jp'>今日限りでやめる</span> là đủ.<br>・Đừng nhầm với 「động từ＋限り」: <span class='gd-jp'>生きている限り</span> nghĩa là \"chừng nào còn sống\", ý nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'><b>をもって</b> cũng có thể diễn tả \"lấy ~ làm điểm kết thúc\", cùng một thông báo đóng cửa dùng cái nào cũng được, nhưng cảm giác khác nhau:<br><span class='gd-jp'>本日をもって閉店いたします。</span> (Cửa hàng chúng tôi mở cửa đến hết hôm nay)<br>→ Thông báo chính thức, công vụ, chỉ báo \"kết thúc vào ngày này\".<br><span class='gd-jp'>本日を限りに閉店いたします。</span> (Hôm nay là ngày bán cuối cùng)<br>→ Trọng tâm là \"đến hôm nay thôi, sau này không còn nữa\", có nhiều cảm xúc hơn, mang không khí hạ màn.<br>Ngoài ra, <b>をもって</b> còn có thể diễn tả <b>bắt đầu</b>: <span class='gd-jp'>4月1日をもって新制度を実施します。</span> (Thực hiện chế độ mới từ ngày 1 tháng 4); còn <b>を限りに</b> chỉ dùng cho \"cuối cùng\", không dùng để nói bắt đầu.</div><div class='gd-warn'>Mẹo phân biệt nhanh: muốn nhấn mạnh \"lần cuối cùng, từ nay không nữa\" thì dùng を限りに; thông báo chính thức một ngày bắt đầu hoặc kết thúc thì dùng をもって.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu có nghĩa vừa hay trái ngược là「<span class='gd-jp'>〜を皮切りに</span>」= lấy ~ làm khởi đầu, rồi lần lượt triển khai tiếp: <span class='gd-jp'>東京公演を皮切りに、全国ツアーが始まる。</span> (Bắt đầu từ buổi diễn ở Tokyo, tour toàn quốc sẽ triển khai)</div>","n1-76":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ではあるまいし」tương đương với <b>「có phải ～ đâu (mà…)」</b> trong tiếng Việt. Mẹ thấy bạn khóc và nói 「Có phải trẻ con đâu mà khóc lóc thế」, đó chính là sắc thái này: đưa ra một tình huống <b>rõ ràng không đúng sự thật</b>, rồi dùng nó để nhắc nhở, khuyên bảo đối phương.</div><div class='gd-h'>Nó từ đâu ra</div><div class='gd-sec'>Tách ra là hiểu ngay: <span class='gd-jp'>ではあるまい</span> là cách nói hơi văn viết của 「chắc không phải ～ đâu」, còn <span class='gd-jp'>し</span> là 「vì ～」. Ghép lại thành 「có phải ～ đâu, nên…」.<br>Khẩu ngữ hầu như đều nói <b><span class='gd-jp'>じゃあるまいし</span></b>, còn <span class='gd-jp'>ではあるまいし</span> thường xuất hiện trong văn viết hoặc những dịp trang trọng hơn.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供じゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供じゃあるまいし、自分のことは自分でやりなさい。</span>（Có phải trẻ con đâu, việc của mình thì tự làm đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>神様じゃあるまいし、明日のことなんて分からないよ。</span>（Tôi có phải thần thánh đâu mà biết ngày mai sẽ ra sao）</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>ở giữa phải đệm thêm <b><span class='gd-jp'>の</span>（khẩu ngữ là <span class='gd-jp'>ん</span>）hoặc <span class='gd-jp'>わけ</span></b>, không nối trực tiếp được.<br><span class='gd-pair'><span class='gd-jp'>遊びに行く</span> → <span class='gd-jp'>遊びに行くんじゃあるまいし</span></span><br><span class='gd-pair'><span class='gd-jp'>会えない</span> → <span class='gd-jp'>会えないわけじゃあるまいし</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>遊びに行くんじゃあるまいし、もっとちゃんとした服を着ていきなさい。</span>（Có phải đi chơi đâu, mặc đồ chỉnh tề hơn rồi hãy đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>一生会えないわけじゃあるまいし、そんなに泣かないで。</span>（Có phải cả đời không gặp lại đâu, đừng khóc như vậy nữa）</div><div class='gd-h'>Phía sau thường là gì</div><div class='gd-sec'>Vế sau mới là điều bạn thật sự muốn nói, hầu như luôn là <b>mệnh lệnh, cấm đoán, khuyên bảo, phê bình hoặc nhận định của bản thân</b>: 「đừng ～ nữa」「tự làm đi」「chuyện thế này không nên xảy ra」. Còn vế trước thường là những thứ rất phóng đại, nghe là biết ngay không phải, như <span class='gd-jp'>子供</span>, <span class='gd-jp'>神様</span>, <span class='gd-jp'>素人</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>素人じゃあるまいし、こんなミスは許されないよ。</span>（Có phải dân ngoại đạo đâu, lỗi thế này thì không thể châm chước được）</div><div class='gd-sec'><span class='gd-tag'>Đảo ngữ trong khẩu ngữ</span>Khi nói chuyện, người ta rất hay đặt nó ở cuối để nói thêm một câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>いちいち説明しなくても分かるよ。子供じゃあるまいし。</span>（Không cần giải thích từng việc đâu, tôi hiểu mà, có phải trẻ con đâu）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước động từ nhất định phải có <span class='gd-jp'>の／ん／わけ</span>: đúng là <span class='gd-jp'>死ぬわけじゃあるまいし</span>, chứ không phải 「死ぬじゃあるまいし」. Danh từ thì ngược lại, không thêm の, không nói 「子供のじゃあるまいし」.<br>・Vế trước phải là điều mà <b>ai cũng biết là 「rõ ràng không phải」</b>. Nếu chỉ đơn thuần nêu lý do, ví dụ 「tôi không phải học sinh nên phải mua vé đầy đủ」, thì dùng mẫu này sẽ rất kỳ, trường hợp đó chỉ cần dùng <span class='gd-jp'>〜ではないので</span> là được.<br>・Sắc thái của nó là <b>mắng, cằn nhằn</b>, có chút mất kiên nhẫn. Nói thẳng với cấp trên hay khách hàng sẽ rất thất lễ.<br>・Nó không phải câu phỏng đoán kiểu 「chắc không phải ～ đâu nhỉ」, trọng tâm nằm ở lời trách móc hay khuyên bảo ở câu sau.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>〜じゃないんだから</b>: nghĩa gần như giống hệt, 「có phải ～ đâu」, nhưng đời thường hơn, nghe nhiều hơn, người học dưới N1 cũng dùng được.<br>・<span class='gd-jp'>子供じゃないんだから、泣かないで。</span>（Có phải trẻ con đâu, đừng khóc nữa）<br>・<span class='gd-jp'>子供じゃあるまいし、泣かないで。</span>（Như trên, nhưng hơi cũ kiểu hơn, mang chút giọng cằn nhằn）</div><div class='gd-sec'><b>〜ではあるまいか</b>: chỉ khác một chữ cuối nhưng nghĩa hoàn toàn khác, là cách nói văn viết của 「chẳng lẽ là ～ à / có lẽ là ～ chăng」, dùng để phỏng đoán.<br>・<span class='gd-jp'>子供ではあるまいし、一人で行けるだろう。</span>（Có phải trẻ con đâu, chắc đi một mình được chứ）<br>・<span class='gd-jp'>彼は何か隠しているのではあるまいか。</span>（Chẳng lẽ anh ấy đang giấu điều gì chăng）</div><div class='gd-warn'>Mẹo nhận biết: phía sau có 「し」＋ một câu mắng thì là 「có phải ～ đâu」; còn cuối câu là 「か」 thì là đang đoán 「chẳng lẽ là ～」.</div>","n1-78":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AあってのB」tương đương với <b>「có A mới có B」「B là nhờ có A」</b>. A là tiền đề để B tồn tại, không có A thì không có B. Các cửa hàng ở Việt Nam hay nói 「khách hàng là thượng đế」, tiếng Nhật chính là: <span class='gd-jp'>お客様あっての商売だ。</span>（Có khách hàng thì mới có việc kinh doanh）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ＋あっての＋danh từ</b>. Phía trước đặt danh từ, phía sau cũng nhất định phải là danh từ.<br>「あって」là thể て của「ある（có）」, thêm「の」thành「cái ... có được nhờ có ～」.<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様あっての商売</span></span>（việc kinh doanh có được nhờ có khách hàng）</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>AあってのBだ</span>Nêu một đạo lý hay một giá trị: B được nâng đỡ nhờ A.</div><div class='gd-ex-line'>・<span class='gd-jp'>選手はファンあっての存在だ。</span>（Tuyển thủ tồn tại được là nhờ có người hâm mộ）</div><div class='gd-ex-line'>・<span class='gd-jp'>命あっての物種だ。無理はするな。</span>（Còn sống thì mới có tất cả, đừng cố quá sức）</div><div class='gd-sec'><span class='gd-tag'>〜あってのことだ</span>Danh từ phía sau đổi thành「こと」, nghĩa là「tất cả những điều này là nhờ có ～」. Hay dùng nhất trong lời phát biểu nhận giải và lời cảm ơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のご指導あってのことです。</span>（Em đậu được là hoàn toàn nhờ sự chỉ dạy của thầy cô）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの応援あっての優勝です。</span>（Có sự cổ vũ của mọi người mới có chức vô địch này）</div><div class='gd-sec'><span class='gd-tag'>あってこその</span>Thêm「こそ」ở giữa, sắc thái mạnh hơn: <span class='gd-jp'>家族あってこその私です。</span>（Chính vì có gia đình mới có tôi của ngày hôm nay）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau nhất định phải là danh từ (hoặc こと). Không thể nói 「お客様あっての売れる」, phải nói <span class='gd-jp'>お客様あっての商売</span>.<br>・Dạng cố định là 「あっての」, đừng viết thành 「あるの」.<br>・Nó không phải chỉ đơn thuần là「vì」. 「Vì trời mưa nên hủy」không thể nói 「雨あっての中止」, mà phải nói <span class='gd-jp'>雨で中止になった</span>. A phải là <b>nền tảng không thể thiếu</b> của B, thường là những thứ tích cực và quan trọng như khách hàng, sức khỏe, sự ủng hộ, nỗ lực.<br>・Sắc thái khá trang trọng, hơi giàu cảm xúc, hay dùng trong diễn thuyết, phỏng vấn, bài viết. Nói chuyện với bạn bè thì chỉ cần nói <span class='gd-jp'>お客さんがいるから</span> là đủ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng một ý, có thể nói từ mặt tích cực, cũng có thể nói từ mặt ngược lại:<br><b>あっての</b>＝nói từ mặt tích cực「có A mới có B」, phía sau là danh từ: <span class='gd-jp'>お客様あっての商売だ。</span>（Có khách hàng thì mới có việc kinh doanh）<br><b>なくしては</b>＝nói từ mặt ngược lại「không có A thì không thể B」, phía sau là phủ định: <span class='gd-jp'>お客様なくしては商売は成り立たない。</span>（Không có khách hàng thì việc kinh doanh không thể duy trì）<br><b>ばこそ</b>＝「chính vì ～ nên…」, giải thích lý do làm việc gì đó, phía trước là thể ば: <span class='gd-jp'>お客様のことを思えばこそ、品質にこだわるのだ。</span>（Chính vì nghĩ cho khách hàng nên mới khắt khe về chất lượng）</div><div class='gd-warn'>Mẹo nhận biết: muốn nói「B tồn tại là nhờ A」thì dùng あっての, phía sau đặt danh từ; muốn nói「thiếu A thì không làm được」thì dùng なくしては, phía sau đặt phủ định; muốn nói「chính vì nghĩ như vậy hoặc làm như vậy」thì dùng ばこそ.</div>","n1-83":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'><span class='gd-jp'>めく</span> nghĩa là <b>\"có chút hơi hướng ~\", \"toát ra vẻ ~\"</b>. Sự vật chưa hoàn toàn thành như vậy, nhưng bạn đã cảm nhận được rồi. Ví dụ cuối tháng Hai, một hôm trời bỗng ấm lên, bạn sẽ nói \"có cảm giác xuân về rồi nè\". Tiếng Nhật chính là <span class='gd-jp'>春めいてきた</span>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Mùa dần chuyển</span>Đây là cách dùng phổ biến nhất, thường đi với <span class='gd-jp'>〜めいてきた</span>, nghĩa là \"dần dần có cảm giác ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>一気に春めいてきた。</span>(Bỗng chốc đã có cảm giác xuân về rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>風が少し秋めいてきた。</span>(Gió đã bắt đầu mang chút hơi thu)</div><div class='gd-sec'><span class='gd-tag'>Miêu tả người hoặc cách nói</span>Dùng <span class='gd-jp'>〜めいた</span> đặt trước danh từ, nghĩa là \"mang chút vẻ ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はどこか謎めいた人だ。</span>(Cô ấy là người có chút bí ẩn)</div><div class='gd-ex-line'>・<span class='gd-jp'>皮肉めいた言い方はやめてよ。</span>(Đừng nói kiểu mỉa mai như vậy nữa mà)</div><div class='gd-ex-line'>・<span class='gd-jp'>言い訳めいたことは言いたくない。</span>(Mình không muốn nói những lời nghe như viện cớ)</div><div class='gd-h'>Cách nối và cách chia</div><div class='gd-sec'>Thêm <span class='gd-jp'>めく</span> thẳng vào sau danh từ, cả cụm trở thành một động từ, và là <b>động từ nhóm 1 (五段動詞)</b>, chia giống như <span class='gd-jp'>書く</span>.<br>Khi nối với て、た thì く đổi thành い:<br><span class='gd-pair'><span class='gd-jp'>春めく</span> → <span class='gd-jp'>春めいて</span></span> → <span class='gd-pair'><span class='gd-jp'>春めいてきた</span></span><br><span class='gd-pair'><span class='gd-jp'>謎めく</span> → <span class='gd-jp'>謎めいた</span></span> → <span class='gd-pair'><span class='gd-jp'>謎めいた事件</span></span> (vụ việc bí ẩn)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không phải danh từ nào cũng nối được.</b> <span class='gd-jp'>めく</span> chỉ đi với một nhóm nhỏ từ cố định, thường gặp là <span class='gd-jp'>春めく</span>、<span class='gd-jp'>秋めく</span>、<span class='gd-jp'>謎めく</span>、<span class='gd-jp'>皮肉めく</span>、<span class='gd-jp'>冗談めく</span>、<span class='gd-jp'>言い訳めく</span>、<span class='gd-jp'>説教めく</span>. Những từ như 「<span class='gd-jp'>学生めく</span>」「<span class='gd-jp'>先生めく</span>」 nghe không tự nhiên, bạn nên nói <span class='gd-jp'>学生らしい</span> hoặc <span class='gd-jp'>学生っぽい</span>.<br>・Khi đứng trước danh từ thì hầu như luôn dùng <b>めいた</b>: nói <span class='gd-jp'>謎めいた人</span>, chứ ít khi nói 謎めく人.<br>・Dạng て là <span class='gd-jp'>めいて</span>, không phải めくて, cũng không phải めきて.<br>・<span class='gd-jp'>春めいてきた</span> nghĩa là \"đã có cảm giác xuân về\", không đồng nghĩa với <span class='gd-jp'>春になった</span> (đã là mùa xuân rồi).<br>・Sắc thái thiên về văn viết, văn chương, rất hay gặp trong bản tin thời tiết và tiểu thuyết. Khi nói chuyện với bạn bè thì thường dùng <span class='gd-jp'>っぽい</span> hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng nói về \"mùa xuân\":<br><span class='gd-jp'>だんだん春めいてきた。</span> (Dần dần đã toát ra hơi thở mùa xuân): trọng tâm là <b>bắt đầu có dấu hiệu</b>.<br><span class='gd-jp'>今日は春らしい天気だ。</span> (Hôm nay thời tiết đúng kiểu mùa xuân): trọng tâm là <b>rất điển hình, đúng như tên gọi</b>.<br><span class='gd-jp'>春っぽい服を買った。</span> (Mình mua bộ đồ có cảm giác xuân xuân): <b>khẩu ngữ</b>, nói tùy hứng kiểu \"na ná ~\".</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"bắt đầu toát ra hơi hướng ~, mang chút vẻ ~\" thì dùng めく; \"rất đúng chất ~ nên có\" thì dùng らしい; nói chuyện tùy hứng kiểu \"cảm giác rất ~\" thì dùng っぽい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>めく</span> có một \"người anh em\" là <span class='gd-jp'>めかす</span>, nghĩa là \"cố ý làm ra vẻ ~\": <span class='gd-jp'>冗談めかして本音を言った。</span> (Nói ra lời thật lòng bằng giọng như đùa)</div>","n1-84":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Nhóm ngữ pháp này nghĩa là <b>\"tận ~\", \"lên tới ~ lận\"</b>. Phía trước đặt một con số, người nói muốn nhấn mạnh \"con số này lớn đó nha\", và <b>có khi còn hơn thế nữa</b>. Ví dụ bạn thấy một kiện hành lý 30 kg và nói \"cái này tận 30 ký luôn đó\", tiếng Nhật sẽ dùng mẫu này.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước nhất định là <b>số + đơn vị</b> (100キロ、1万人、50万円), phía sau nối thẳng với からある／からする／からの. Chọn trong ba cái này tùy vào bạn đang nói về thứ gì.</div><div class='gd-sec'><span class='gd-tag'>からある</span>Dùng cho trọng lượng, chiều dài, chiều cao, khoảng cách, kích cỡ.<br>Tiếng Nhật vốn nói 「重さが<b>ある</b>」「長さが<b>ある</b>」, nên khi nói \"nặng bao nhiêu, dài bao nhiêu\" thì dùng ある.</div><div class='gd-ex-line'>・<span class='gd-jp'>30キロからある荷物を一人で運んだ。</span>(Một mình mình khiêng kiện hành lý nặng tận 30 ký)</div><div class='gd-ex-line'>・<span class='gd-jp'>2メートルからある魚が釣れた。</span>(Câu được một con cá dài tận 2 mét)</div><div class='gd-ex-line'>・<span class='gd-jp'>片道100キロからある道のりを毎日車で通っている。</span>(Anh ấy ngày nào cũng lái xe đi làm, một chiều dài tận 100 km)</div><div class='gd-sec'><span class='gd-tag'>からする</span>Dùng cho giá tiền.<br>Tiếng Nhật khi nói \"giá bao nhiêu\" vốn dùng する: <span class='gd-jp'>この時計は100万円する。</span> (Chiếc đồng hồ này giá 1 triệu yên). Vì vậy giá tiền đi với からする.</div><div class='gd-ex-line'>・<span class='gd-jp'>一泊10万円からするホテルに泊まった。</span>(Mình đã ở một khách sạn giá tận 100 nghìn yên một đêm)</div><div class='gd-ex-line'>・<span class='gd-jp'>あのバッグは50万円からするらしい。</span>(Nghe nói cái túi đó giá lên tới 500 nghìn yên)</div><div class='gd-sec'><span class='gd-tag'>からの</span>Hay dùng nhất với số người, phía sau <b>nhất định phải có danh từ</b> (の ở đây nối với danh từ đứng sau). Các số lượng như tiền, nợ cũng có thể dùng からの + danh từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>会場には1万人からの人が集まった。</span>(Hội trường tụ tập tới 10 nghìn người)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼には1000万円からの借金がある。</span>(Anh ta mang khoản nợ lên tới 10 triệu yên)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chỉ dùng với <b>con số lớn</b>. <span class='gd-jp'>1キロからある荷物</span> nghe rất kỳ, vì 1 ký thì chẳng có gì đáng nhấn mạnh.<br>・からする chỉ dùng cho <b>giá tiền</b>. Trọng lượng phải nói <span class='gd-jp'>100キロからある</span>, không phải 100キロからする.<br>・Sau からの nhất định phải có danh từ: <span class='gd-jp'>1万人からの人</span> được, còn câu dừng ở 「1万人からの。」 thì không được.<br>・Nhóm ngữ pháp này hơi văn viết, trang trọng, rất hay gặp trong tin tức, bài báo, văn bản. Nói chuyện với bạn bè vẫn dùng được, nhưng cách nói khẩu ngữ hơn là dùng 「も」 (phần dưới sẽ nói).</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>「から」 thông thường</b> = <b>bắt đầu từ ~</b> (mức giá thấp nhất trong khoảng giá):<br><span class='gd-jp'>この店の時計は1万円からあります。</span> (Đồng hồ ở tiệm này giá từ 10 nghìn yên)<br><b>からする</b> = <b>tận ~ lận</b> (nhấn mạnh là rất đắt):<br><span class='gd-jp'>この時計は100万円からする。</span> (Chiếc đồng hồ này giá tận 1 triệu yên)<br>Cái trước là nói \"món rẻ nhất bắt đầu từ đâu\", cái sau là nói \"món này đắt kinh khủng\".</div><div class='gd-sec'><b>Số + も</b> = cách nói khẩu ngữ của \"tới tận ~ luôn\": <span class='gd-jp'>この荷物、30キロもあるよ。</span> (Kiện hành lý này tới 30 ký luôn đó)<br><b>からある</b> = thiên về văn viết, mang cảm giác \"ít nhất cũng chừng này, có khi còn hơn\": <span class='gd-jp'>30キロからある荷物</span> (kiện hành lý nặng tận 30 ký)</div><div class='gd-warn'>Mẹo phân biệt nhanh: cửa hàng ghi 「～円から」 là đang báo giá thấp nhất; còn sau con số mà nối với からある／からする／からの thì là người nói đang trầm trồ \"con số này lớn quá\". Trọng lượng, chiều dài dùng ある, giá tiền dùng する, phía sau cần danh từ thì dùng からの.</div>","n1-85":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようにも〜ない」nghĩa là <b>「muốn ~ cũng không ~ được」</b>, giống như \"muốn chạy cũng không chạy nổi\", \"muốn quên cũng không quên được\". Trong lòng bạn thật sự muốn làm, nhưng hoàn cảnh cản lại nên <b>hoàn toàn không làm được</b>, giọng điệu mang chút bất lực.</div><div class='gd-ex-line'>・<span class='gd-jp'>逃げようにも逃げられない状況だった。</span>(Lúc đó là tình huống muốn chạy cũng không chạy nổi)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bị hoàn cảnh bên ngoài cản trở</span>Bị thương, không có xe, không có cách liên lạc... Không phải bạn không muốn, mà là điều kiện không cho phép.</div><div class='gd-ex-line'>・<span class='gd-jp'>終電がなくて、帰ろうにも帰れない。</span>(Hết chuyến tàu cuối rồi, muốn về nhà cũng không về được)</div><div class='gd-ex-line'>・<span class='gd-jp'>足をけがしていて、歩こうにも歩けない。</span>(Chân bị thương, muốn đi cũng không đi nổi)</div><div class='gd-sec'><span class='gd-tag'>Tâm lý không vượt qua được</span>Có lúc thứ cản bạn là cảm xúc hoặc kỷ niệm.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れようにも忘れられない思い出だ。</span>(Đó là kỷ niệm muốn quên cũng không quên được)</div><div class='gd-ex-line'>・<span class='gd-jp'>状況が深刻すぎて、笑おうにも笑えなかった。</span>(Tình hình nghiêm trọng quá, muốn cười cũng không cười nổi)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Thể ý chí của động từ (「〜う／〜よう」, dạng dùng khi rủ \"cùng ~ nhé\") ＋にも＋dạng \"không làm được\" (phủ định của thể khả năng) của <b>chính động từ đó</b>.<br>Ở giữa thường chen thêm một vế nêu lý do: <span class='gd-jp'>帰ろうにも、終電がなくて帰れない。</span><br>Vế sau cũng có thể không lặp lại động từ mà nói thẳng lý do đang cản bạn:</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しようにも、番号が分からない。</span>(Muốn gọi điện nhưng lại không biết số)</div><div class='gd-h'>Cách biến đổi: xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ năm đoạn)</b>: ở vế trước, đổi âm cuối sang âm cột「お」cùng hàng rồi thêm「う」; ở vế sau, đổi âm cuối sang âm cột「え」cùng hàng rồi thêm「ない」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành こ → <span class='gd-jp'>書こう</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành け → <span class='gd-jp'>書けない</span></span><br>Ghép lại: <span class='gd-jp'>書こうにも書けない</span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろうにも帰れない</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そうにも話せない</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おうにも会えない</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ một đoạn)</b>: ở vế trước, bỏ「る」rồi thêm「よう」; ở vế sau, bỏ「る」rồi thêm「られない」.<br><span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げようにも逃げられない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れようにも忘れられない</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようにもできない</span></span>, ví dụ: <span class='gd-jp'>予約しようにも予約できない</span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようにも来られない</span>(こようにもこられない)</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế trước nhất định phải dùng thể ý chí: là <span class='gd-jp'>帰ろうにも</span>, không phải 帰るようにも. Mẫu này không liên quan gì đến「〜ように」(để ~) bạn học ở N4, đừng thấy「よう」là nối với thể từ điển.<br>・Vế sau phải là \"<b>không làm được</b>\", không phải \"không làm\": nếu viết thành 帰らない thì thành \"tự mình không muốn về\", mâu thuẫn với vế trước là \"muốn về\".<br>・Điều kiện là người nói <b>thật sự muốn làm</b>. Lười làm hay không hứng thú thì không dùng được mẫu này.<br>・Với nhóm 2, dạng \"không làm được\" trong văn bản trang trọng và bài thi phải viết là <span class='gd-jp'>逃げられない</span>; dạng「逃げれない」hay nghe trong khẩu ngữ thì nên tránh khi viết.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về \"chạy trốn\", hãy xem ba cách nói khác nhau thế nào:<br><b>ようにも</b> = muốn làm, nhưng <b>hoàn toàn không làm được</b>: <span class='gd-jp'>逃げようにも、ドアに鍵がかかっていて逃げられない。</span>(Muốn chạy nhưng cửa bị khóa, không chạy được)<br><b>たところで</b> = dù có làm cũng <b>vô ích</b>: <span class='gd-jp'>今さら逃げたところで、すぐに見つかるだろう。</span>(Bây giờ mới chạy thì cũng sẽ nhanh chóng bị tìm ra thôi)<br><b>ようと／ようが</b> = <b>dù làm thế nào</b> thì kết quả cũng như nhau: <span class='gd-jp'>どこへ逃げようと、必ず見つけ出す。</span>(Dù bạn trốn đến đâu, tôi nhất định sẽ tìm ra)</div><div class='gd-warn'>Mẹo nhận biết: \"muốn làm mà không làm được\" dùng ようにも, \"làm cũng như không\" dùng たところで, \"dù làm thế nào\" dùng ようと／ようが.</div>","n1-86":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とは言い条」nghĩa là <b>\"tuy nói là ~ nhưng...\", \"trên danh nghĩa là ~, thực ra...\"</b>. Trước tiên thừa nhận một cách nói, rồi ngay sau đó cho biết \"thực tế không đơn giản như vậy\". Ý nghĩa gần giống「とはいえ」, chỉ là cổ hơn, mang màu sắc văn viết hơn, và hầu như không dùng trong đời thường.</div><div class='gd-h'>Hiểu từ「言い条」trước</div><div class='gd-sec'><span class='gd-jp'>言い条</span> đọc là <b>いいじょう</b>, nghĩa gốc là \"cách nói, lời nói\". Vì vậy「Aとは言い条」theo nghĩa đen là \"nói là A, đó là một cách nói\". Hàm ý là: <b>nói thì nói vậy, nhưng thực tế lại là chuyện khác</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ nối trực tiếp: <span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロとは言い条</span></span><br>Động từ, tính từ nối bằng thể thường (tức là cách nói không có ます、です): <span class='gd-pair'><span class='gd-jp'>分かっている</span> → <span class='gd-jp'>分かっているとは言い条</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとは言い条</span></span><br>Thực tế gặp nhiều nhất là <b>danh từ nối trực tiếp</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Danh không xứng với thực</span>Vế trước là cách nói hay tên gọi ai cũng công nhận, vế sau chỉ ra thực tế không phải như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、朝晩はまだ冷える。</span>(Tuy nói là đã sang xuân, sáng tối vẫn còn lạnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>自由とは言い条、実際には多くの制約がある。</span>(Trên danh nghĩa là tự do, nhưng thực tế có rất nhiều ràng buộc)</div><div class='gd-sec'><span class='gd-tag'>Hiểu lý thì hiểu, nhưng làm không được</span>Thừa nhận điều ở vế trước không sai, nhưng kết quả vẫn không như ý.</div><div class='gd-ex-line'>・<span class='gd-jp'>頭では分かっているとは言い条、なかなか実行に移せない。</span>(Tuy trong đầu đã hiểu, mãi vẫn chưa bắt tay vào làm được)</div><div class='gd-ex-line'>・<span class='gd-jp'>プロとは言い条、ミスを犯すこともある。</span>(Tuy là dân chuyên nghiệp, cũng có lúc mắc lỗi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cách đọc là <b>いいじょう</b>. 「条」đọc là じょう (âm kéo dài), đừng đọc thành「いうじょう」hay「じょ」ngắn.<br>・Nó đứng <b>giữa câu</b>, phía sau nhất định phải có thêm một vế mang nghĩa \"nhưng...\", không thể đặt ở cuối câu rồi kết thúc.<br>・Đây là văn viết rất cứng, dùng trong bình luận, tiểu thuyết, bài viết. Nói chuyện với bạn bè mà dùng「春とは言い条」nghe sẽ như đang đọc sách cổ; trong khẩu ngữ chỉ cần nói「<span class='gd-jp'>春だけど</span>」là đủ.<br>・Gặp trong đề thi, bạn chỉ cần nhận ra nghĩa \"tuy nói ~ nhưng...\" là đủ; khi tự viết thì dùng「とはいえ」sẽ ít bị gượng hơn.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cả ba đều mang nghĩa \"tuy nói ~ nhưng...\", khác nhau ở <b>độ trang trọng và độ cổ</b>. So sánh trong cùng một tình huống:<br><b>とはいうものの</b>: dùng trong văn viết, nói chuyện ở những dịp trang trọng cũng dùng.<br></div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいうものの、まだ寒い。</span>(Tuy nói là mùa xuân, vẫn còn lạnh)</div><div class='gd-sec'><b>とはいえ</b>: chủ yếu là văn viết, rất hay gặp trong báo chí, bài viết, khẩu ngữ hơi trang trọng cũng nghe được.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、まだ寒い。</span>(Tuy nói là mùa xuân, vẫn còn lạnh)</div><div class='gd-sec'><b>とは言い条</b>: cổ nhất, ngày nay hầu như chỉ thấy trong bài viết, tác phẩm văn học.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とは言い条、まだ寒い。</span>(Tuy nói là mùa xuân, vẫn còn lạnh)</div><div class='gd-warn'>Mẹo nhận biết: ý nghĩa đều là \"tuy nói ~ nhưng...\". Càng giống sách cổ, càng văn vẻ thì là「とは言い条」; khi viết bài bình thường, chọn「とはいえ」là an toàn nhất.</div>","n1-90":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にかこつけて」nghĩa là <b>「mượn cớ ～」「lấy ～ làm cái cớ」</b>. Bề ngoài thì nói là vì A, nhưng thật ra điều bạn muốn làm là B. Ví dụ bạn nói \"mình đi công tác\", nhưng phần lớn thời gian lại đi dạo phố, ăn ngon. Kiểu \"treo đầu dê bán thịt chó\" đó chính là cảm giác của mẫu câu này.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋にかこつけて, phía sau là việc thật sự muốn làm.<br><span class='gd-pair'><span class='gd-jp'>出張</span> → <span class='gd-jp'>出張にかこつけて</span></span>（mượn danh đi công tác）<br><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事にかこつけて</span></span>（lấy công việc làm cái cớ）<br>Vế trước là \"lý do chính đáng nói ra được\", vế sau mới là \"việc thật sự muốn làm\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chê người khác</span>Đây là cách dùng phổ biến nhất. Bạn thấy ngứa mắt khi ai đó lấy lý do chính đáng làm bình phong, nên giọng hơi chê trách.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は視察にかこつけて、毎年ハワイに行っている。</span>（Trưởng phòng năm nào cũng mượn danh đi khảo sát để bay sang Hawaii）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事にかこつけて、毎晩飲みに行っている。</span>（Anh ta lấy công việc làm cớ, tối nào cũng đi nhậu）</div><div class='gd-sec'><span class='gd-tag'>Tự giễu</span>Bạn cũng có thể nói về chính mình. Khi đó giống như tự thú nhận \"thật ra mình muốn làm việc đó mà\", giọng hơi ngượng và hơi buồn cười.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの誕生日にかこつけて、自分が食べたいケーキを買った。</span>（Mượn cớ sinh nhật con, mình mua chiếc bánh mình muốn ăn）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にかこつけて、ジムをサボった。</span>（Lấy cớ trời mưa, mình đã trốn buổi tập gym）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ là <b>に</b>, không phải を. Cách nói đời thường có nghĩa gần giống là「〜を口実に」mới dùng を. Đừng trộn hai cái với nhau, viết「出張をかこつけて」là sai.<br>・Mẫu câu này luôn mang sắc thái <b>「lý do bề ngoài khác với mục đích thật」</b>. Nếu bạn thật sự đi công tác, chỉ tiện thể ngắm cảnh mà dùng nó, thì nghĩa sẽ thành \"đi công tác giả, đi chơi thật\".<br>・Vì mang giọng chê trách hoặc tự giễu, nó không hợp để giải thích lịch trình của mình trong hoàn cảnh trang trọng. Ví dụ khi báo cáo với sếp mà nói「出張にかこつけて…」, tức là bạn tự nhận mình đang lười biếng.<br>・Thường được viết bằng hiragana. Chữ Hán là「託けて」, ít gặp, chỉ cần nhận ra là đủ.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: đi công tác nhưng có đi tham quan Kyoto.<br><b>がてら</b>＝<b>nhân tiện</b>, cả hai việc đều thật, làm một cách đường hoàng:<br><span class='gd-jp'>出張がてら、京都を観光した。</span>（Nhân tiện đi công tác, mình tham quan Kyoto）<br><b>かたがた</b>＝cũng là \"nhân tiện, kết hợp\", nhưng trang trọng hơn, hay dùng khi đến thăm hoặc cảm ơn:<br><span class='gd-jp'>お礼かたがた、先生のお宅に伺った。</span>（Mình đến nhà thầy để thăm, nhân tiện bày tỏ lòng biết ơn）<br><b>にかこつけて</b>＝lý do phía trước chỉ là <b>bình phong</b>, mục đích thật là việc phía sau:<br><span class='gd-jp'>出張にかこつけて、京都を観光した。</span>（Mượn danh đi công tác, thật ra là đi chơi Kyoto）</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu cả hai việc đều là việc bạn thật lòng muốn làm thì dùng「がてら」, trong hoàn cảnh trang trọng thì dùng「かたがた」. Nếu lý do phía trước chỉ là cái cớ và việc phía sau mới là điều bạn thật sự muốn làm thì dùng「にかこつけて」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Trong hội thoại hằng ngày bạn sẽ nghe「〜を口実に」nhiều hơn. Nghĩa gần như giống nhau, giọng thì thẳng hơn: <span class='gd-jp'>風邪を口実に、会社を休んだ。</span>（Lấy cớ bị cảm để xin nghỉ ở công ty）</div>","n1-92":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AとBが相まって」nghĩa là <b>「hai yếu tố A và B cộng lại, hiệu quả tăng gấp bội」</b>. Giống như trong tiếng Việt ta nói \"thiên thời lại thêm địa lợi\", hay \"đã mệt lại còn thiếu ngủ\": nhìn riêng từng cái thì chưa sao, nhưng chồng hai cái lên nhau thì kết quả đặc biệt rõ. Chuyện tốt hay xấu đều dùng được, thường xuất hiện trong tin tức, bài bình luận, văn viết.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước ghép với <b>danh từ</b>. Thường có ba dạng:<br><span class='gd-tag'>AはBと相まって</span>Nhân vật chính A kết hợp với một yếu tố khác là B.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の才能は努力と相まって、大きな成果を生んだ。</span>（Tài năng của anh ấy kết hợp với nỗ lực đã tạo ra thành quả lớn）</div><div class='gd-sec'><span class='gd-tag'>AとBが相まって</span>Đặt hai yếu tố song song, cùng dẫn đến kết quả phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は料理の味と雰囲気の良さが相まって、いつも予約でいっぱいだ。</span>（Quán này đồ ăn ngon lại có không khí tốt, nên lúc nào cũng kín chỗ đặt trước）</div><div class='gd-sec'><span class='gd-tag'>Bも相まって</span>Hay gặp nhất trong tin tức. Dùng「も」để biểu thị \"vốn đã có nguyên nhân khác, <b>cộng thêm</b> B\".</div><div class='gd-ex-line'>・<span class='gd-jp'>円安も相まって、外国人観光客が急増している。</span>（Cộng thêm đồng yên mất giá, lượng khách du lịch nước ngoài tăng vọt）</div><div class='gd-sec'>Nếu phía trước là cả một câu, phải thêm「こと」để biến thành danh từ trước:<br><span class='gd-pair'><span class='gd-jp'>駅から近い</span> → <span class='gd-jp'>駅から近いことも相まって</span></span>（cộng thêm việc gần ga）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đọc là <b>あいまって</b>, không phải「そうまって」.<br>・Nhất định phải có <b>từ hai yếu tố trở lên</b>. Nếu chỉ có một nguyên nhân thì không dùng được: mưa làm trận đấu bị hủy thì nói thẳng <span class='gd-jp'>雨で試合が中止になった</span>, không thể nói「雨と相まって中止になった」.<br>・Không chỉ dùng cho chuyện tốt, chuyện xấu cũng dùng được: <span class='gd-jp'>寝不足と疲れが相まって、熱を出してしまった。</span>（Thiếu ngủ cộng với mệt mỏi, kết quả là bị sốt）Vì vậy đừng nghĩ nó chỉ là \"bổ trợ cho nhau\" theo nghĩa tích cực.<br>・Đây là cách nói thiên về trang trọng, văn viết. Khi nói chuyện với bạn bè, dùng <span class='gd-jp'>〜もあって</span>、<span class='gd-jp'>〜も重なって</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>に加えて</b>＝đơn giản là \"ngoài A ra còn có B\", chỉ liệt kê từng việc một:<br><span class='gd-jp'>円安に加えて、物価も上がっている。</span>（Ngoài đồng yên mất giá, vật giá cũng đang tăng）<br><b>と相まって</b>＝hai yếu tố <b>cùng phát huy tác dụng</b>, dẫn đến một kết quả:<br><span class='gd-jp'>円安と物価高が相まって、生活が苦しくなっている。</span>（Đồng yên mất giá cộng với vật giá leo thang, cuộc sống trở nên khó khăn）</div><div class='gd-sec'><b>とあって</b>（chỉ khác một chữ, rất dễ đọc nhầm）＝\"vì là tình huống đặc biệt như ～ nên…\", nguyên nhân chỉ có một:<br><span class='gd-jp'>連休とあって、どこも混んでいる。</span>（Vì là kỳ nghỉ dài, chỗ nào cũng đông nghịt）<br><b>と相まって</b>＝hai nguyên nhân chồng lên nhau:<br><span class='gd-jp'>連休と好天が相まって、どこも混んでいる。</span>（Kỳ nghỉ dài cộng với thời tiết đẹp, chỗ nào cũng đông nghịt）</div><div class='gd-warn'>Mẹo phân biệt nhanh: chỉ là \"còn có ～\" thì dùng に加えて; \"vì là ～\" thì dùng とあって; \"hai yếu tố chồng lên nhau, hiệu quả tăng gấp bội\" mới dùng と相まって.</div>","n1-87":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かれ〜かれ」tương đương với <b>“sớm muộn gì”, “dù ít dù nhiều”, “dù tốt hay xấu”</b> trong tiếng Việt. Đây không phải mẫu câu để bạn thoải mái thay từ vào, mà là <b>ba cụm cố định</b>. Bạn chỉ cần học thuộc cả cụm là xong.</div><div class='gd-h'>Nó từ đâu ra</div><div class='gd-sec'>「かれ」là thể mệnh lệnh của cổ văn, đại khái mang nghĩa “dù là ～ cũng được”.<br><span class='gd-jp'>多かれ少なかれ</span>ban đầu gần với nghĩa “nhiều cũng được, ít cũng được”. Về sau nó trở thành “dù nhiều hay ít, dù sao cũng có”.<br>Bạn không cần học cổ văn. Chỉ cần nhớ: đây là hai tính từ có <b>nghĩa trái ngược</b> đứng cạnh nhau, diễn tả “bên nào cũng như nhau, kết quả không đổi”.</div><div class='gd-h'>Ba cụm hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>遅かれ早かれ</span>đọc là「おそかれはやかれ」, nghĩa là sớm muộn gì, sớm hay muộn. Phía sau thường là chuyện “chắc chắn sẽ xảy ra”, mang cảm giác “không tránh được”. Trong hội thoại hằng ngày cũng hay nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>嘘は遅かれ早かればれるよ。</span>(Nói dối thì sớm muộn gì cũng bị lật tẩy thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、決めなきゃいけないことだ。</span>(Chuyện này sớm muộn gì cũng phải quyết định)</div><div class='gd-sec'><span class='gd-tag'>多かれ少なかれ</span>đọc là「おおかれすくなかれ」, nghĩa là dù ít dù nhiều, ít nhiều. Phía sau hay đi với「誰でも」「みんな」, cho thấy ai cũng có, chỉ khác nhau về mức độ.</div><div class='gd-ex-line'>・<span class='gd-jp'>多かれ少なかれ、誰にでも悩みはある。</span>(Ai cũng có phiền muộn, ít hay nhiều thôi)</div><div class='gd-sec'><span class='gd-tag'>善かれ悪しかれ</span>đọc là「よかれあしかれ」, nghĩa là dù tốt hay xấu. Cụm này trang trọng hơn hai cụm trên, hay dùng trong văn viết và bình luận.</div><div class='gd-ex-line'>・<span class='gd-jp'>善かれ悪しかれ、スマホは私たちの生活を大きく変えた。</span>(Dù tốt hay xấu, điện thoại thông minh cũng đã thay đổi cuộc sống của chúng ta rất nhiều)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không được tự chế</b>: thấy「tính từ + かれ」là muốn gắn vào <span class='gd-jp'>高い</span>、<span class='gd-jp'>大きい</span>, nhưng như vậy là sai. Thực tế chỉ có đúng ba cụm này.<br>・Phải là <b>悪しかれ</b>, không phải「悪かれ」. Ở đây dùng「悪し」của cổ văn, không phải「悪い」hiện đại.<br>・Thứ tự cố định: nói <span class='gd-jp'>遅かれ早かれ</span>、<span class='gd-jp'>多かれ少なかれ</span>, đừng đảo ngược.<br>・<span class='gd-jp'>よかれと思って</span>đứng riêng là một cách nói khác, nghĩa là “vì có ý tốt, nghĩ làm vậy là tốt cho đối phương”. Nó không liên quan đến “dù tốt hay xấu”.<br>　<span class='gd-jp'>よかれと思って言ったのに、怒られた。</span>(Mình nói vì có ý tốt, vậy mà bị mắng)</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng mang nghĩa “dù A hay B”, nhưng <span class='gd-jp'>〜にせよ〜にせよ</span> và <span class='gd-jp'>〜であれ〜であれ</span> thì thay từ thoải mái, còn <span class='gd-jp'>〜かれ〜かれ</span> thì không.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにせよ行かないにせよ、早めに連絡してね。</span>(Dù đi hay không đi, cũng báo mình sớm nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨であれ雪であれ、試合は行われる。</span>(Dù mưa hay tuyết, trận đấu vẫn diễn ra)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅かれ早かれ、ばれるよ。</span>(Sớm muộn gì cũng bị phát hiện thôi)</div><div class='gd-sec'>Ngược lại, “sớm muộn” cũng không nói thành <span class='gd-jp'>遅いにせよ早いにせよ</span>. Về ngữ pháp câu này không sai, nhưng nghe như đang bàn hai trường hợp “chậm hay nhanh”, chứ không phải cách nói cố định “sớm muộn”. Người Nhật cứ nói <span class='gd-jp'>遅かれ早かれ</span>.<br>Lưu ý thêm: trước <span class='gd-jp'>であれ</span> là danh từ hoặc tính từ đuôi な, <b>không đi với tính từ đuôi い</b>, nên「遅いであれ」tự nó đã sai.</div><div class='gd-warn'>Mẹo nhỏ: muốn nói “sớm muộn / ít nhiều / dù tốt hay xấu” thì dùng thẳng ba cụm かれ. Các kiểu “dù A hay B” khác thì dùng にせよ hoặc であれ.</div>","n1-88":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜始末だ」tương đương với <b>“rốt cuộc còn…”, “đến mức còn…”, “rồi ra nông nỗi…”</b> trong tiếng Việt. Bạn kể một loạt chuyện không ra gì, rồi tung ra một kết cục còn tệ hơn ở cuối. Giọng điệu mang cảm giác <b>cạn lời, chịu hết nổi, trách móc</b>. Giống như bạn than với bạn bè: “Anh ta đi muộn thì thôi, còn quên mang đồ. Rồi sao nữa? Cuối cùng còn bị sếp mắng.”</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trách móc người khác</span>Đây là cách dùng điển hình nhất. Bạn kể một người ngày càng quá đáng, cuối cùng đến mức khó tin.</div><div class='gd-ex-line'>・<span class='gd-jp'>息子は毎晩ゲームばかりして、ついには学校を休む始末だ。</span>(Con trai tối nào cũng chỉ chơi game, cuối cùng còn đến mức nghỉ học luôn)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は何度注意しても聞かず、最近は返事もしない始末だ。</span>(Nhắc bao nhiêu lần anh ta cũng không nghe, dạo này còn chẳng buồn trả lời nữa)</div><div class='gd-sec'><span class='gd-tag'>Tự giễu</span>Nói về chính mình cũng được, với giọng tự châm chọc kiểu “mình đúng là hết nói nổi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊して駅まで走ったのに、財布を家に忘れる始末だ。</span>(Ngủ quên, chạy hết tốc lực ra ga, vậy mà còn quên ví ở nhà)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ thể từ điển + 始末だ：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休む始末だ</span></span><br>Động từ thể ない + 始末だ：<span class='gd-pair'><span class='gd-jp'>しない</span> → <span class='gd-jp'>返事もしない始末だ</span></span><br>Từ chỉ thị + 始末だ：<span class='gd-jp'>この始末だ</span>、<span class='gd-jp'>あの始末だ</span>(“ra nông nỗi này”)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれほど言ったのに、この始末だ。</span>(Tôi đã nói đến thế rồi, vậy mà vẫn ra nông nỗi này)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Phía trước thường đi với những từ mang nghĩa “cuối cùng”, để tạo cảm giác “mọi chuyện ngày càng tệ”: <span class='gd-jp'>ついには</span>、<span class='gd-jp'>とうとう</span>、<span class='gd-jp'>最後には</span>、<span class='gd-jp'>挙句の果てには</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>借金を重ね、挙句の果てには夜逃げする始末だ。</span>(Nợ chồng thêm nợ, cuối cùng còn ra nông nỗi phải bỏ trốn trong đêm)</div><div class='gd-sec'>Khi nói chuyện đã xảy ra trong quá khứ, phía trước vẫn dùng thể từ điển, còn cuối câu có thể dùng <span class='gd-jp'>始末だった</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước dùng <b>thể từ điển hoặc thể ない</b>, đừng dùng thể た: đúng là <span class='gd-jp'>叱られる始末だ</span>, không phải 叱られた始末だ.<br>・<b>Chỉ dùng cho kết quả xấu</b>. Câu “chăm chỉ học, cuối cùng đỗ” thì không dùng được 始末だ.<br>・Cần có <b>phần dẫn dắt phía trước</b>. Chỉ ném ra một câu kiểu “Anh ấy đi trễ + 始末だ” thì rất kỳ, bạn phải kể trước việc mọi chuyện tệ dần từng bước thế nào.<br>・Giọng điệu là <b>trách móc, than phiền</b>. Nói như vậy về sếp hay khách ngay trước mặt họ là rất thiếu lịch sự. Mẫu này hay xuất hiện khi than phiền, trong văn viết và bình luận.<br>・<span class='gd-jp'>始末</span>đứng riêng còn có nghĩa “dọn dẹp, xử lý”, như <span class='gd-jp'>後始末</span>(giải quyết hậu quả) và <span class='gd-jp'>始末書</span>(bản kiểm điểm). Những từ này khác hẳn với mẫu câu đang học.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói “cuối cùng trở thành ～” còn có「末に」「羽目になる」mà bạn đã học ở N2. Khác nhau ở <b>kết quả tốt hay xấu, đang nói về ai, và tâm trạng người nói</b>.<br><b>末に</b>＝kết luận sau cả một quá trình, <b>trung tính</b>, kết quả tốt cũng dùng được:<br><span class='gd-jp'>何度も話し合った末に、ゲームは一日一時間と決めた。</span>(Sau nhiều lần bàn bạc, cuối cùng quyết định mỗi ngày chỉ chơi game một tiếng)<br><b>羽目になる</b>＝<b>chính mình</b> bị buộc phải làm một việc phiền phức, kèm cảm giác hối hận:<br><span class='gd-jp'>息子のゲームの課金を、私が払う羽目になった。</span>(Tiền nạp game của con trai, cuối cùng lại thành tôi phải trả)<br><b>始末だ</b>＝người nói <b>cạn lời, trách móc</b> ai đó “lại đến mức này”:<br><span class='gd-jp'>息子はゲームに夢中で、ついには学校を休む始末だ。</span>(Con trai mê game, cuối cùng còn đến mức nghỉ học luôn)</div><div class='gd-warn'>Mẹo nhỏ: “cuối cùng quyết định ～” một cách trung tính thì dùng 末に. “Hại mình phải ～” thì dùng 羽目になる. Còn muốn lườm một cái rồi nói “rốt cuộc còn ～” thì dùng 始末だ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hay đi cùng「〜あげく」: <span class='gd-jp'>さんざん迷ったあげく、何も買わずに帰ってくる始末だ。</span>(Phân vân mãi, rốt cuộc còn về tay không, chẳng mua gì cả)</div>","n1-67":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をよそに」nghĩa là <b>「mặc kệ ～」「bỏ ngoài tai ～」</b>. <span class='gd-jp'>よそ</span> là \"nhà người khác, nơi khác\", nên <span class='gd-jp'>〜をよそに</span> là coi sự lo lắng, phản đối của người xung quanh, hoặc tình hình xung quanh, như <b>chuyện của nhà người ta</b>, còn mình thì vẫn cứ làm theo ý mình.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Mặc kệ cảm xúc của người khác</span>Đây là cách dùng phổ biến nhất. Phía trước đặt sự lo lắng, phản đối, kỳ vọng hay chỉ trích của người khác, phía sau nói nhân vật chính vẫn làm việc của mình. Nhiều khi câu mang chút cảm giác \"sao lại thế được\", nhưng không nhất thiết là chê trách, cũng có thể chỉ là miêu tả khách quan.</div><div class='gd-ex-line'>・<span class='gd-jp'>親の心配をよそに、息子は毎晩遅くまで遊んでいる。</span>（Bố mẹ lo lắng như vậy mà con trai vẫn tối nào cũng chơi đến khuya）</div><div class='gd-ex-line'>・<span class='gd-jp'>周囲の反対をよそに、彼女は会社を辞めて留学した。</span>（Mặc kệ những người xung quanh phản đối, cô ấy vẫn nghỉ việc đi du học）</div><div class='gd-sec'><span class='gd-tag'>Không bị tình hình xung quanh ảnh hưởng</span>Phía trước đặt những tình hình mà \"lẽ ra phải bị ảnh hưởng\" như kinh tế suy thoái, xã hội xôn xao, phía sau nói nhân vật chính hoàn toàn không bị tác động.</div><div class='gd-ex-line'>・<span class='gd-jp'>不景気をよそに、この店はいつも行列ができている。</span>（Kinh tế ế ẩm như vậy mà quán này vẫn lúc nào cũng xếp hàng dài）</div><div class='gd-ex-line'>・<span class='gd-jp'>世間の騒ぎをよそに、本人はのんびり旅行を楽しんでいた。</span>（Bên ngoài ồn ào náo loạn, còn đương sự thì thong thả tận hưởng chuyến du lịch）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Nối trực tiếp sau <b>danh từ</b>: danh từ ＋ をよそに<br><span class='gd-pair'><span class='gd-jp'>家族の心配</span> → <span class='gd-jp'>家族の心配をよそに</span></span><span class='gd-pair'><span class='gd-jp'>ファンの期待</span> → <span class='gd-jp'>ファンの期待をよそに</span></span><br>Các danh từ hay đi cùng nhất: <span class='gd-jp'>心配</span>、<span class='gd-jp'>反対</span>、<span class='gd-jp'>期待</span>、<span class='gd-jp'>批判</span>、<span class='gd-jp'>不安</span>、<span class='gd-jp'>騒ぎ</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là danh từ. Đừng viết 「心配するをよそに」, hãy đổi sang danh từ <span class='gd-jp'>心配</span> trước.<br>・Phía trước là <b>phản ứng của người xung quanh hoặc tình hình xung quanh</b>, không phải việc bản thân lẽ ra phải làm. Với ý \"không làm bài tập mà chạy đi chơi\" đừng nói 「宿題をよそに」, dùng <span class='gd-jp'>宿題そっちのけで遊ぶ</span> sẽ tự nhiên hơn.<br>・Phần lớn dùng để miêu tả hành vi của <b>người khác</b>, là cách nói văn viết thường gặp trên báo chí, bài viết, còn nói chuyện với bạn bè thì rất ít dùng.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>をものともせず</b> ＝ không coi <b>khó khăn, nguy hiểm</b> ra gì, mang ý khen ngợi:<br><span class='gd-jp'>けがをものともせず、彼は最後まで走った。</span>（Bất chấp chấn thương, anh ấy đã chạy đến cùng: thật đáng nể）<br><b>をよそに</b> ＝ mặc kệ <b>tâm trạng của người xung quanh hoặc tình hình xung quanh</b>, cứ làm theo ý mình:<br><span class='gd-jp'>家族の心配をよそに、彼は最後まで走った。</span>（Gia đình lo lắng như vậy mà anh ấy vẫn chạy đến cùng: trọng tâm là anh ấy không để ý đến gia đình）</div><div class='gd-sec'><b>にもかかわらず</b> ＝ đơn thuần là \"tuy ～ nhưng ～\":<br><span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Tuy trời mưa nhưng vẫn có rất nhiều người đến）<br>Câu này chỉ đơn giản nêu \"tuy trời mưa nhưng vẫn có nhiều người đến\", nên dùng にもかかわらず là tự nhiên nhất. Trọng tâm của をよそに là \"nhân vật chính không coi chuyện lẽ ra phải để tâm, lẽ ra phải bị ảnh hưởng ra gì, vẫn cứ làm theo ý mình\", nên thường dùng với sự lo lắng, phản đối của người khác, hoặc tình hình xung quanh như kinh tế, những thứ lẽ ra phải gây ảnh hưởng.</div><div class='gd-warn'>Mẹo phân biệt nhanh: vượt qua khó khăn, đáng nể thì dùng をものともせず; mặc kệ người khác nghĩ gì, không bị xung quanh ảnh hưởng thì dùng をよそに; chỉ đơn thuần là \"tuy ～ nhưng ～\" thì dùng にもかかわらず.</div>","n1-70":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ずにはおかない」nghĩa là <b>「nhất định sẽ khiến người ta ～」「không ～ thì không bỏ qua」</b>. Mẫu này có hai cách dùng: một là sức mạnh của sự vật quá lớn, <b>chắc chắn sẽ</b> khiến người ta nảy sinh một cảm xúc nào đó; hai là người nói đã quyết tâm, <b>không làm được thì không dừng lại</b>. Đây là cách nói cứng của N1, thường xuất hiện trong bài bình phim, bình sách, tin tức, tiểu thuyết.</div><div class='gd-sec'>Tách ra thì dễ nhớ hơn: <span class='gd-jp'>おく</span> có nghĩa là \"để đó mặc kệ\". \"Không làm ～ thì sẽ không để yên\", tức là \"nhất định sẽ làm ～\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Sự vật tất yếu gây ra phản ứng</span>Đây là cách dùng phổ biến nhất. Chủ ngữ là bộ phim, tác phẩm, một câu nói, một sự việc, nói rằng nó <b>chắc chắn sẽ</b> khiến người ta cảm động, ngạc nhiên, suy ngẫm.<br>Người bị tác động được đánh dấu bằng <b>を</b> hoặc <b>に</b> (<span class='gd-jp'>人を～させる</span>／<span class='gd-jp'>人に～させる</span>), nên động từ phần lớn ở <b>thể sai khiến</b>, tức dạng \"khiến ai đó ～\": <span class='gd-pair'><span class='gd-jp'>感動する</span> → <span class='gd-jp'>感動させる</span></span>（làm cho người ta cảm động）.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画は、観客を感動させずにはおかない。</span>（Bộ phim này nhất định sẽ làm khán giả cảm động）</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説の結末は、読者を驚かせずにはおかないだろう。</span>（Cái kết của cuốn tiểu thuyết này chắc chắn sẽ khiến độc giả kinh ngạc）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の言葉は、聞く人の心を動かさずにはおかない。</span>（Lời của anh ấy nhất định sẽ lay động lòng người nghe）</div><div class='gd-sec'><span class='gd-tag'>Không làm được thì không bỏ qua</span>Chủ ngữ là người, thể hiện quyết tâm rất mạnh, mang cái quyết liệt kiểu \"tôi nhất định phải làm cho nó xảy ra\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今度こそ、真相を明らかにせずにはおかない。</span>（Lần này không làm rõ sự thật thì tôi quyết không bỏ qua）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな失礼なことを言われたんだ。必ず謝らせずにはおかない。</span>（Bị nói những lời vô lễ như thế. Tôi nhất định phải bắt hắn xin lỗi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước hết chuyển động từ sang thể ない, rồi <b>bỏ ない</b>, thêm <b>ずにはおかない</b>.<br><span class='gd-pair'><span class='gd-jp'>感動させる</span> → <span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させずにはおかない</span></span><br><span class='gd-pair'><span class='gd-jp'>動かす</span> → <span class='gd-jp'>動かさない</span> → <span class='gd-jp'>動かさずにはおかない</span></span><br>Nhóm 3 cần nhớ riêng: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはおかない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはおかない</span>（こず）</span></div><div class='gd-sec'>Còn một cách viết khác là thêm <b>ではおかない</b> <b>trực tiếp</b> vào thể ない, không cần bỏ ない, nghĩa vẫn như vậy:<br><span class='gd-pair'><span class='gd-jp'>感動させない</span> → <span class='gd-jp'>感動させないではおかない</span></span><br>「ずには」phổ biến hơn và mang tính văn viết hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・する phải đổi thành <b>せず</b>, không phải しず: <span class='gd-jp'>明らかにせずにはおかない</span>.<br>・Ở cách dùng thứ nhất, người bị tác động là đối tượng được đánh dấu bằng を／に, không phải chủ ngữ. <span class='gd-jp'>観客は感動せずにはおかない</span> là sai; muốn nói \"bộ phim làm khán giả cảm động\" phải nói: <span class='gd-jp'>映画は観客を感動させずにはおかない</span>.<br>・Sắc thái rất nặng và rất văn viết. Trong đời thường, muốn nói \"chắc chắn sẽ khóc\" chỉ cần nói <span class='gd-jp'>絶対泣けるよ</span>, dùng ずにはおかない nghe như đang đọc bài bình luận vậy.<br>・Cách dùng thứ hai là quyết tâm \"liều mạng cũng phải làm cho được\", đừng dùng cho chuyện nhỏ như \"ăn hết bát ramen này\".</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>ずにはいられない</b>（N2）＝ <b>bản thân không kìm được</b>: <span class='gd-jp'>この映画を見て、泣かずにはいられなかった。</span>（Xem bộ phim này, tôi không kìm được nước mắt）<br><b>ずにはおかない</b>＝ <b>sự vật nhất định sẽ khiến người ta</b> như vậy: <span class='gd-jp'>この映画は、見る人を泣かせずにはおかない。</span>（Bộ phim này nhất định sẽ khiến người xem rơi nước mắt）</div><div class='gd-sec'><b>ずにはすまない</b>（n1-71）＝ theo lẽ thường, theo tình huống, <b>không làm thì không xong</b>: <span class='gd-jp'>失礼なことを言ってしまったから、謝らずにはすまない。</span>（Tôi lỡ nói lời thất lễ, không xin lỗi thì không được）<br><b>ずにはおかない</b>＝ tôi <b>nhất định phải làm cho nó xảy ra</b>: <span class='gd-jp'>失礼なことを言われたから、謝らせずにはおかない。</span>（Bị nói lời thất lễ, tôi nhất định phải bắt họ xin lỗi）</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"bản thân không kìm được\" là ずにはいられない; \"thứ gì đó nhất định sẽ khiến người ta ～\" hoặc \"tôi nhất định phải làm cho bằng được\" là ずにはおかない; \"không làm thì không xong\" là ずにはすまない.</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>Hãy xem tiếp <span class='gd-jp'>〜ずにはすまない・ないではすまない</span>（n1-71）. Hai mẫu này thường được ra thi cùng nhau, học đối chiếu sẽ rõ nhất.</div>","n1-17":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜そばから」nghĩa là <b>“vừa mới ～ xong thì đã lại ～ ngay”</b>. Bạn đang làm bên này thì bên kia lập tức bị trả về nguyên trạng, mà <b>lần nào cũng vậy</b>, nên coi như làm công cốc. Hình dung bạn vừa lau nhà xong, bé con đã đi dép giẫm lên ngay. Lau một lần, giẫm một lần. Cảm giác bất lực đó chính là そばから.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ ở thể từ điển hoặc thể た, thêm そばから ngay phía sau.<br><span class='gd-pair'><span class='gd-jp'>片付ける</span> → <span class='gd-jp'>片付けるそばから</span></span>（vừa dọn dẹp bên này xong）<br><span class='gd-pair'><span class='gd-jp'>覚えた</span> → <span class='gd-jp'>覚えたそばから</span></span>（vừa mới học thuộc xong）<br>Hai cách có nghĩa gần như nhau. Nếu phải phân biệt thì thể từ điển giống “vừa làm vừa bị phá”, còn thể た giống “vừa làm xong là bị phá liền”.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Công sức bị xóa sạch</span>Bạn làm xong một việc, nhưng kết quả lập tức bị trả về nguyên trạng.</div><div class='gd-ex-line'>・<span class='gd-jp'>覚えたそばから忘れてしまう。</span>（Vừa học thuộc xong là quên mất）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪かきしたそばから、また積もっていく。</span>（Vừa xúc tuyết xong thì tuyết lại phủ dày lên）</div><div class='gd-sec'><span class='gd-tag'>Vào bao nhiêu ra bấy nhiêu</span>Thứ gì vừa đến đã biến mất ngay, không giữ lại được.</div><div class='gd-ex-line'>・<span class='gd-jp'>稼ぐそばから使ってしまうので、全然貯金できない。</span>（Kiếm được bao nhiêu tiêu hết bấy nhiêu, hoàn toàn không để dành được đồng nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>掃除するそばから、犬が毛を落としていく。</span>（Tôi vừa quét dọn bên này thì con chó bên kia cứ rụng lông liên tục）</div><div class='gd-sec'>Vế sau thường đi với <span class='gd-jp'>〜てしまう</span>、<span class='gd-jp'>〜ていく</span>, hoặc dùng bị động <span class='gd-jp'>〜される</span> (ví dụ: <span class='gd-jp'>子供に散らかされる</span>), để diễn tả cảm giác “sự việc ngoài tầm kiểm soát, mình bó tay”.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・そばから nói về việc <b>lặp đi lặp lại</b>. Việc chỉ xảy ra một lần thì không dùng được. Ví dụ câu “vừa về đến nhà thì trời mưa” không thể nói là 「家に着いたそばから雨が降り出した」. Trường hợp này phải dùng <span class='gd-jp'>とたん</span> hoặc <span class='gd-jp'>や否や</span>.<br>・Hầu như chỉ dùng khi <b>phàn nàn, bất lực, công sức đổ sông đổ bể</b>. Chuyện tốt cứ liên tục đến thì thường không dùng そばから.<br>・Vế sau mô tả “thực tế là như vậy”, nên không đi với các cách nói ý chí hoặc mệnh lệnh như “tôi sẽ ～” hay “hãy ～”.<br>・そば ở đây không phải 「蕎麦」 (mì soba) mà mang nghĩa “bên cạnh”. Bạn có thể hiểu là “vừa làm xong thì ngay bên cạnh đã ～ liền”.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><span class='gd-jp'>〜が早いか</span> và <span class='gd-jp'>〜や否や</span> cũng mang nghĩa “vừa ～ là ～ ngay”, nhưng chúng nói về <b>một lần cụ thể</b>, hai việc nối tiếp nhau, không có nghĩa “công cốc”.<br>Cùng là chuyện nhận lương:<br><b>そばから</b>：<span class='gd-jp'>給料が入るそばから使ってしまう。</span>（Lương vừa vào là tiêu hết ngay, tháng nào cũng vậy）<br><b>や否や</b>：<span class='gd-jp'>給料が入るや否や、新しいスマホを買った。</span>（Lần đó lương vừa vào tài khoản là tôi mua ngay chiếc điện thoại mới）</div><div class='gd-warn'>Mẹo phán đoán: “lần nào cũng vậy, làm cũng như không” thì dùng そばから. “Lần đó, việc trước vừa xảy ra thì việc sau liền theo ngay” thì dùng が早いか hoặc や否や.</div>","n1-21":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜んがため（に）」nghĩa là <b>“vì ～, bất chấp tất cả”</b>. Nghĩa “vì” giống 「ために」, nhưng giọng mạnh hơn nhiều, có cái quyết tâm “nhất định phải đạt được”. Mẫu này rất cổ, bình thường nói chuyện hầu như không dùng, thường gặp hơn trong tiểu thuyết, bài diễn thuyết, bài bình luận.</div><div class='gd-h'>Chữ 「ん」 này là gì</div><div class='gd-sec'>「ん」 ở đây <b>không phải phủ định</b>, mà là từ trong văn cổ biểu thị “muốn ～, định ～”, nghĩa gần với 「〜う／〜よう」 hiện đại. 「が」 tương đương với 「の」. Vì vậy <span class='gd-jp'>勝たんがため</span> đại khái là “mục đích muốn thắng”, tức là “để thắng”.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Trước hết chia động từ sang thể ない, <b>bỏ ない đi</b>, rồi thêm 「んがため（に）」.</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>勝つ</span> → <span class='gd-jp'>勝たない</span> → <span class='gd-jp'>勝たんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>売る</span> → <span class='gd-jp'>売らんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わんがため</span></span>（động từ đuôi う đổi thành わ, giống thể ない）</div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>生きる</span> → <span class='gd-jp'>生きない</span> → <span class='gd-jp'>生きんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>逃れる</span> → <span class='gd-jp'>逃れんがため</span></span></div><div class='gd-sec'><b>Nhóm 3</b>: <span class='gd-jp'>する</span> phải đổi thành <b>せ</b>, không phải し.<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せんがため</span></span><br><span class='gd-pair'><span class='gd-jp'>優勝する</span> → <span class='gd-jp'>優勝せんがため</span></span><br>「来る」 hầu như không xuất hiện trong mẫu này, bạn không cần cố nhớ.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>んがために</span>Đặt ở vế đầu câu, phía sau nói “vì thế đã làm gì”.</div><div class='gd-ex-line'>・<span class='gd-jp'>勝たんがために、彼は必死に練習した。</span>（Để thắng, anh ấy đã luyện tập hết mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>生きんがために、どんな仕事でもした。</span>（Để sống sót, việc gì tôi cũng từng làm）</div><div class='gd-sec'><span class='gd-tag'>んがための＋danh từ</span>Bổ nghĩa cho danh từ phía sau. <span class='gd-jp'>売らんがため</span> thường mang nghĩa tiêu cực, chỉ việc “chỉ chăm chăm bán lấy tiền”.</div><div class='gd-ex-line'>・<span class='gd-jp'>売らんがための広告には、もううんざりだ。</span>（Tôi chán ngấy những quảng cáo chỉ lo bán hàng rồi）</div><div class='gd-sec'><span class='gd-tag'>んがためだ</span>Đặt cuối câu, giải thích “làm vậy là để ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が嘘をついたのは、自分を守らんがためだった。</span>（Anh ấy nói dối là để tự bảo vệ mình）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・する là <b>せんがため</b>, viết 「しんがため」 là sai.<br>・「ん」 không phải phủ định: <span class='gd-jp'>勝たんがため</span> là “để thắng”, không phải “để không thắng”.<br>・Vế sau phải là <b>việc do con người chủ ý làm</b>, và thường là mục tiêu chính người đó muốn đạt được, nên không dùng để nói về thời tiết hay hiện tượng tự nhiên.<br>・Vế sau không đi với “xin bạn hãy ～” hay “hãy đi làm ～”: <span class='gd-jp'>合格せんがため、勉強しなさい</span> nghe không tự nhiên, phải nói <span class='gd-jp'>合格するために、勉強しなさい</span>.<br>・Dùng cho việc nhỏ thì nghe quá lố và buồn cười: đi cửa hàng tiện lợi mua bánh mì thì chỉ cần nói <span class='gd-jp'>パンを買うために</span> là đủ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một tình huống “để thi đậu, ngày nào cũng học đến khuya”:<br><b>ために</b> = “để” thông thường, dùng được trong mọi hoàn cảnh: <span class='gd-jp'>合格するために、毎晩遅くまで勉強した。</span><br><b>べく</b> = “để” dùng trong văn viết, gắn thẳng vào thể từ điển, する có thể đổi thành <span class='gd-jp'>すべく</span>: <span class='gd-jp'>合格すべく、毎晩遅くまで勉強した。</span><br><b>んがため</b> = cổ hơn nữa, mang cảm giác “có chết cũng phải làm”: <span class='gd-jp'>合格せんがため、毎晩遅くまで勉強した。</span></div><div class='gd-sec'>Một mẫu nữa cần cẩn thận là <b>んばかりに</b>. Cách chia phía trước giống hệt, nhưng nghĩa hoàn toàn khác, là “cứ như thể sắp ～ đến nơi”:<br><span class='gd-jp'>泣かんばかりに頼んだ。</span>（Tôi nhờ vả như thể sắp khóc đến nơi）</div><div class='gd-warn'>Mẹo phán đoán: sau 「ん」 là <b>がため</b> thì nghĩa là “để, vì”, còn sau 「ん」 là <b>ばかり</b> thì nghĩa là “như thể sắp”. Muốn nói “để”: bình thường dùng ために, văn viết dùng べく, chỉ khi muốn thể hiện khí thế “bất chấp tất cả” mới dùng んがため.</div>"});
